            <p className="text-[7px] text-zinc-700 mt-0.5">
              {Math.round(f.confidence * 100)}% conf
            </p>
          </div>
        ))}
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Loader2, PieChart } from 'lucide-react';
import { getCategoryColor } from '@/utils/categoryColors';
import { analyticsApi } from '@/api';
import type { CategoryBreakdownItem } from '../types';

const PERIODS = ['1m', '3m', '6m', '12m'] as const;

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
    maximumFractionDigits: 0,
  }).format(cents / 100);
}

// Color mapping from Tailwind class to hex
const COLOR_HEX: Record<string, string> = {
  'red-500': '#ef4444',
  'rose-500': '#f43f5e',
  'pink-500': '#ec4899',
  'fuchsia-500': '#d946ef',
  'purple-500': '#a855f7',
  'violet-500': '#8b5cf6',
  'indigo-500': '#6366f1',
  'blue-500': '#3b82f6',
  'sky-500': '#0ea5e9',
  'cyan-500': '#06b6d4',
  'teal-500': '#14b8a6',
  'emerald-500': '#10b981',
  'green-500': '#22c55e',
  'lime-500': '#84cc16',
  'yellow-500': '#eab308',
  'amber-500': '#f59e0b',
  'orange-500': '#f97316',
  'slate-500': '#64748b',
  'zinc-500': '#71717a',
  'stone-500': '#78716c',
};

function getHexColor(category: string): string {
  if (category === 'Other') return '#71717a';
  const catColor = getCategoryColor(category);
  if (!catColor) return '#FFCC00';
  const dotClass = catColor.dot.replace('bg-', '');
  return COLOR_HEX[dotClass] || '#FFCC00';
}

function polarToCartesian(
  cx: number,
  cy: number,
  r: number,
  angle: number,
): { x: number; y: number } {
  const rad = ((angle - 90) * Math.PI) / 180;
  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
}

function describeArc(
  cx: number,
  cy: number,
  r: number,
  startAngle: number,
  endAngle: number,
): string {
  const start = polarToCartesian(cx, cy, r, endAngle);
  const end = polarToCartesian(cx, cy, r, startAngle);
  const largeArcFlag = endAngle - startAngle > 180 ? 1 : 0;
  return `M ${start.x} ${start.y} A ${r} ${r} 0 ${largeArcFlag} 0 ${end.x} ${end.y}`;
}

export function CategoryBreakdown() {
  const [items, setItems] = useState<CategoryBreakdownItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState<string>('3m');
  const [mode, setMode] = useState<'expenses' | 'income'>('expenses');
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);

  useEffect(() => {
    loadData();
  }, [period, mode]);

  const loadData = async () => {
    setLoading(true);
    try {
      const data = await analyticsApi.fetchCategoryBreakdown(`${period}_${mode}`);
      setItems(data);
    } catch (err) {
      console.error('Failed to fetch category breakdown:', err);
    } finally {
      setLoading(false);
    }
  };

  const segments = useMemo(() => {
    if (items.length === 0) return [];
    const sorted = [...items].sort((a, b) => b.total - a.total);
    const top = sorted.slice(0, 5);
    const rest = sorted.slice(5);

    const displayItems: CategoryBreakdownItem[] = [...top];
    if (rest.length > 0) {
      displayItems.push({
        category: 'Other',
        total: rest.reduce((s, r) => s + r.total, 0),
        percentage: rest.reduce((s, r) => s + r.percentage, 0),
        color: '#71717a',
        transactionCount: rest.reduce((s, r) => s + r.transactionCount, 0),
      });
    }

    let currentAngle = 0;
    return displayItems.map((item) => {
      const angle = Math.max((item.percentage / 100) * 360, 1);
      const segment = {
        ...item,
        startAngle: currentAngle,
        endAngle: currentAngle + angle,
        hexColor: getHexColor(item.category),
      };
      currentAngle += angle;
      return segment;
    });
  }, [items]);

  const total = items.reduce((s, i) => s + i.total, 0);
  const CX = 100,
    CY = 100,
    R = 80,
    INNER_R = 50;

  if (loading) {
    return (
      <div className="neu-raised rounded-3xl p-8 border border-border/50 flex items-center justify-center min-h-[300px]">
        <Loader2 className="w-6 h-6 text-cba-gold animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <PieChart className="w-4 h-4 text-cba-gold" />
          <span className="text-[10px] font-black text-muted uppercase tracking-[0.2em]">
            Category Breakdown
          </span>
        </div>
        <div className="flex gap-2">
          <div className="flex gap-1 neu-inset rounded-xl p-1">
            <button
              type="button"
              onClick={() => setMode('expenses')}
              className={cn(
                'px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all',
                mode === 'expenses'
                  ? 'bg-cba-gold text-base'
                  : 'text-muted hover:text-primary',
              )}
            >
              Expenses
            </button>
            <button
              type="button"
              onClick={() => setMode('income')}
              className={cn(
                'px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all',
                mode === 'income'
                  ? 'bg-cba-gold text-base'
                  : 'text-muted hover:text-primary',
              )}
            >
              Income
            </button>
          </div>
          <div className="flex gap-1 neu-inset rounded-xl p-1">
            {PERIODS.map((p) => (
              <button
                key={p}
                type="button"
                onClick={() => setPeriod(p)}
                className={cn(
                  'px-2 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all',
                  period === p
                    ? 'bg-cba-gold text-base'
                    : 'text-muted hover:text-primary',
                )}
              >
                {p}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="neu-raised rounded-2xl border border-border/50 p-6">
        <div className="flex flex-col md:flex-row items-center gap-8">
          {/* Donut Chart */}
          <div className="relative shrink-0">
            <svg width="200" height="200" viewBox="0 0 200 200">
              {segments.map((seg, i) => {
                if (seg.percentage < 0.5) return null;
                const isSelected = selectedCategory === seg.category;
                return (
                  <path
                    key={i}
                    d={describeArc(CX, CY, isSelected ? R + 4 : R, seg.startAngle, seg.endAngle)}
                    fill="none"
                    stroke={seg.hexColor}
                    strokeWidth={isSelected ? INNER_R - 4 : INNER_R - 10}
                    strokeLinecap="butt"
                    className="cursor-pointer transition-all duration-200 hover:opacity-80"
                    onClick={() =>
                      setSelectedCategory(selectedCategory === seg.category ? null : seg.category)
                    }
                    opacity={selectedCategory && !isSelected ? 0.3 : 1}
                  />
                );
              })}
              {/* Center text */}
              <text
                x={CX}
                y={CY - 6}
                textAnchor="middle"
                fill="#f5f5f7"
                className="text-lg font-black"
              >
                {formatCurrency(total)}
              </text>
              <text
                x={CX}
                y={CY + 12}
                textAnchor="middle"
                fill="#71717a"
                className="text-[9px] font-bold uppercase"
              >
                Total
              </text>
            </svg>
          </div>

          {/* Legend */}
          <div className="flex-1 w-full space-y-2">
            {segments.map((seg, i) => (
              <button
                key={i}
                type="button"
                onClick={() =>
                  setSelectedCategory(selectedCategory === seg.category ? null : seg.category)
                }
                className={cn(
                  'w-full flex items-center gap-3 p-2.5 rounded-xl transition-all text-left',
                  selectedCategory === seg.category
                    ? 'neu-inset border border-border'
                    : 'hover:bg-overlay',
                )}
              >
                <div
                  className="w-3 h-3 rounded-full shrink-0"
                  style={{ backgroundColor: seg.hexColor }}
                />
                <span className="text-xs font-bold text-primary flex-1 truncate">
                  {seg.category}
                </span>
                <span className="text-xs font-black text-secondary tabular-nums">
                  {formatCurrency(seg.total)}
                </span>
                <span className="text-[9px] font-bold text-zinc-600 w-10 text-right tabular-nums">
                  {seg.percentage.toFixed(1)}%
                </span>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Loader2, TrendingUp, AlertTriangle } from 'lucide-react';
import { analyticsApi } from '@/api';
import type { ProjectionResult } from '@/api';
import type { CashFlowForecast } from '../types';
import {
  LineChart as GoldLineChart,
  ComposedChart as GoldComposedChart,
  ScatterPlot as GoldScatterPlot,
  CHART_COLORS,
} from '@/components/charts';

function formatDollars(value: number): string {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
    maximumFractionDigits: 0,
  }).format(value);
}

function ForecastDashboardInner() {
  const [revenueData, setRevenueData] = useState<ProjectionResult | null>(null);
  const [expenseData, setExpenseData] = useState<ProjectionResult | null>(null);
  const [cashFlowData, setCashFlowData] = useState<CashFlowForecast[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [months, setMonths] = useState(6);

  useEffect(() => {
    loadAllData();
  }, [months]);

  const loadAllData = async () => {
    setLoading(true);
    setError(null);
    try {
      const [revenue, expenses, cashFlow] = await Promise.allSettled([
        analyticsApi.projectRevenue('sole_trader', months),
        analyticsApi.projectExpenses('sole_trader', months),
        analyticsApi.fetchCashFlowForecast(months),
      ]);
      if (revenue.status === 'fulfilled') setRevenueData(revenue.value);
      if (expenses.status === 'fulfilled') setExpenseData(expenses.value);
      if (cashFlow.status === 'fulfilled') setCashFlowData(cashFlow.value);
    } catch (err) {
      setError('Failed to load forecast data');
      console.error('Forecast load error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Revenue forecast chart data
  const revenueChartData = useMemo(() => {
    if (!revenueData?.projections) return [];
    return revenueData.projections.map((p: Record<string, unknown>) => ({
      month: p.month,
      projected: Math.round(p.projected / 100),
      upper95: Math.round(p.upperBound / 100),
      lower95: Math.round(p.lowerBound / 100),
      upper80: Math.round(p.projected / 100 + (p.upperBound / 100 - p.projected / 100) * 0.6),
      lower80: Math.round(p.projected / 100 - (p.projected / 100 - p.lowerBound / 100) * 0.6),
    }));
  }, [revenueData]);

  // Expense forecast chart data
  const expenseChartData = useMemo(() => {
    if (!expenseData?.projections) return [];
    return expenseData.projections.map((p: Record<string, unknown>) => ({
      month: p.month,
      recurring: Math.round((p.projected / 100) * 0.7),
      variable: Math.round((p.projected / 100) * 0.3),
      total: Math.round(p.projected / 100),
    }));
  }, [expenseData]);

  // Cash flow projection chart data
  const cashFlowChartData = useMemo(() => {
    if (cashFlowData.length === 0) return [];
    return cashFlowData.map((cf) => ({
      month: cf.month,
      balance: Math.round(cf.projectedBalance / 100),
      upper: Math.round(cf.upperBound / 100),
      lower: Math.round(cf.lowerBound / 100),
      confidence: cf.confidence,
    }));
  }, [cashFlowData]);

  // Anomaly detection scatter data (derived from cash flow deviations)
  const anomalyData = useMemo(() => {
    if (cashFlowData.length === 0) return [];
    return cashFlowData.map((cf, i) => {
      const expected = cf.projectedBalance / 100;
      const deviation = Math.abs(cf.upperBound - cf.lowerBound) / (2 * 100);
      return {
        month: i + 1,
        expected: Math.round(expected),
        deviation: Math.round(deviation),
        confidence: cf.confidence,
      };
    });
  }, [cashFlowData]);

  if (loading) {
    return (
      <div className="neu-raised rounded-3xl p-8 border border-border/50 flex items-center justify-center min-h-[300px]">
        <Loader2 className="w-6 h-6 text-cba-gold animate-spin" />
      </div>
    );
  }

  const hasData =
    revenueChartData.length > 0 || expenseChartData.length > 0 || cashFlowChartData.length > 0;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <TrendingUp className="w-4 h-4 text-cba-gold" />
          <span className="text-[10px] font-black text-muted uppercase tracking-[0.2em]">
            Financial Forecast
          </span>
        </div>
        <div className="flex gap-1 neu-inset rounded-xl p-1">
          {([3, 6, 12] as const).map((m) => (
            <button
              key={m}
              type="button"
              onClick={() => setMonths(m)}
              className={cn(
                'px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all',
                months === m ? 'bg-cba-gold text-base' : 'text-muted hover:text-primary',
              )}
            >
              {m}mo
            </button>
          ))}
        </div>
      </div>

      {error && (
        <div className="neu-raised rounded-xl p-4 border border-red-500/20 flex items-center gap-2">
          <AlertTriangle className="w-4 h-4 text-red-400 shrink-0" />
          <span className="text-xs text-red-400">{error}</span>
        </div>
      )}

      {/* KPI Row */}
      {hasData && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <div className="neu-raised rounded-xl p-4 border border-border/50">
            <p className="text-[8px] font-black text-zinc-600 uppercase tracking-[0.2em]">
              Avg Monthly Revenue
            </p>
            <p className="text-lg font-black text-emerald-400 tabular-nums mt-1">
              {revenueData ? formatDollars(revenueData.averageMonthly / 100) : '—'}
            </p>
          </div>
          <div className="neu-raised rounded-xl p-4 border border-border/50">
            <p className="text-[8px] font-black text-zinc-600 uppercase tracking-[0.2em]">
              Revenue Growth
            </p>
            <p
              className={cn(
                'text-lg font-black tabular-nums mt-1',
                (revenueData?.growthRate ?? 0) >= 0 ? 'text-emerald-400' : 'text-red-400',
              )}
            >
              {revenueData ? `${(revenueData.growthRate * 100).toFixed(1)}%` : '—'}
            </p>
          </div>
          <div className="neu-raised rounded-xl p-4 border border-border/50">
            <p className="text-[8px] font-black text-zinc-600 uppercase tracking-[0.2em]">
              Avg Monthly Expenses
            </p>
            <p className="text-lg font-black text-red-400 tabular-nums mt-1">
              {expenseData ? formatDollars(expenseData.averageMonthly / 100) : '—'}
            </p>
          </div>
          <div className="neu-raised rounded-xl p-4 border border-border/50">
            <p className="text-[8px] font-black text-zinc-600 uppercase tracking-[0.2em]">
              Projected Cash Flow
            </p>
            <p className="text-lg font-black text-cba-gold tabular-nums mt-1">
              {cashFlowChartData.length > 0
                ? formatDollars(cashFlowChartData[cashFlowChartData.length - 1]!.balance)
                : '—'}
            </p>
          </div>
        </div>
      )}

      {!hasData ? (
        <div className="neu-raised rounded-2xl p-12 border border-border/50 text-center">
          <TrendingUp className="w-10 h-10 mx-auto text-zinc-600 mb-3" />
          <p className="text-sm text-muted">No forecast data available yet.</p>
          <p className="text-xs text-zinc-600 mt-1">
            Upload statements and categorize transactions to enable projections.
          </p>
        </div>
      ) : (
        <>
          {/* Revenue & Expense Forecasts */}
          <div className="grid gap-4 md:grid-cols-2">
            {/* Revenue Forecast */}
            <div className="neu-raised rounded-2xl p-4 border border-border/50">
              <GoldLineChart
                data={revenueChartData}
                dataKeys={['projected', 'upper95', 'lower95']}
                xAxisKey="month"
                showArea
                curved
                colors={[CHART_COLORS.primary, 'rgba(255,204,0,0.15)', 'rgba(255,204,0,0.08)']}
                title="Revenue Forecast"
                subtitle={`${months}-month projection with 95% confidence bands`}
                height={280}
              />
            </div>

            {/* Expense Forecast */}
            <div className="neu-raised rounded-2xl p-4 border border-border/50">
              <GoldLineChart
                data={expenseChartData}
                dataKeys={['recurring', 'variable', 'total']}
                xAxisKey="month"
                colors={[CHART_COLORS.expense, '#FF9500', '#DC2626']}
                title="Expense Forecast"
                subtitle="Recurring vs variable expense breakdown"
                height={280}
              />
            </div>
          </div>

          {/* Cash Flow & Anomaly Detection */}
          <div className="grid gap-4 md:grid-cols-2">
            {/* Cash Flow Projection */}
            <div className="neu-raised rounded-2xl p-4 border border-border/50">
              <GoldComposedChart
                data={cashFlowChartData}
                xAxisKey="month"
                areas={[
                  {
                    dataKey: 'balance',
                    color: CHART_COLORS.primary,
                    opacity: 0.3,
                    name: 'Projected Balance',
                  },
                ]}
                lines={[
                  {
                    dataKey: 'upper',
                    color: CHART_COLORS.revenue,
                    dashed: true,
                    name: 'Upper Bound',
                  },
                  {
                    dataKey: 'lower',
                    color: CHART_COLORS.expense,
                    dashed: true,
                    name: 'Lower Bound',
                  },
                ]}
                title="Cash Flow Projection"
                subtitle="Projected balance with upper/lower confidence range"
                height={280}
              />
            </div>

            {/* Anomaly Detection Scatter */}
            <div className="neu-raised rounded-2xl p-4 border border-border/50">
              <GoldScatterPlot
                data={anomalyData}
                xKey="expected"
                yKey="deviation"
                xLabel="Expected ($)"
                yLabel="Deviation ($)"
                color={CHART_COLORS.primary}
                title="Forecast Uncertainty Analysis"
                subtitle="Expected balance vs deviation range per period"
                height={280}
              />
            </div>
          </div>
        </>
      )}
    </div>
  );
}

