import { Loader2, TrendingUp, TrendingDown, Minus, LineChart } from 'lucide-react';
import { getCategoryColor } from '@/utils/categoryColors';
import { analyticsApi } from '@/api';
import type { SpendingTrend } from '../types';

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
    maximumFractionDigits: 0,
  }).format(cents / 100);
}

const COLOR_HEX: Record<string, string> = {
  'red-500': '#ef4444',
  'rose-500': '#f43f5e',
  'pink-500': '#ec4899',
  'fuchsia-500': '#d946ef',
  'purple-500': '#a855f7',
  'violet-500': '#8b5cf6',
  'indigo-500': '#6366f1',
  'blue-500': '#3b82f6',
  'sky-500': '#0ea5e9',
  'cyan-500': '#06b6d4',
  'teal-500': '#14b8a6',
  'emerald-500': '#10b981',
  'green-500': '#22c55e',
  'lime-500': '#84cc16',
  'yellow-500': '#eab308',
  'amber-500': '#f59e0b',
  'orange-500': '#f97316',
  'slate-500': '#64748b',
  'zinc-500': '#71717a',
  'stone-500': '#78716c',
};

function getHexColor(category: string): string {
  const catColor = getCategoryColor(category);
  if (!catColor) return '#FFCC00';
  const dotClass = catColor.dot.replace('bg-', '');
  return COLOR_HEX[dotClass] || '#FFCC00';
}

export function SpendingTrends() {
  const [trends, setTrends] = useState<SpendingTrend[]>([]);
  const [loading, setLoading] = useState(true);
  const [months, setMonths] = useState(6);
  const [selectedCategories, setSelectedCategories] = useState<Set<string>>(new Set());
  const [hoveredMonth, setHoveredMonth] = useState<number | null>(null);

  useEffect(() => {
    loadTrends();
  }, [months]);

  const loadTrends = async () => {
    setLoading(true);
    try {
      const data = await analyticsApi.fetchSpendingTrends(months);
      setTrends(data);
      // Auto-select top 5 categories
      const totals = new Map<string, number>();
      data.forEach((t) => {
        Object.entries(t.categories).forEach(([cat, amt]) => {
          totals.set(cat, (totals.get(cat) || 0) + amt);
        });
      });
      const top5 = [...totals.entries()]
        .sort((a, b) => b[1] - a[1])
        .slice(0, 5)
        .map(([c]) => c);
      setSelectedCategories(new Set(top5));
    } catch (err) {
      console.error('Failed to fetch spending trends:', err);
    } finally {
      setLoading(false);
    }
  };

  const allCategories = useMemo(() => {
    const cats = new Set<string>();
    trends.forEach((t) => Object.keys(t.categories).forEach((c) => cats.add(c)));
    return Array.from(cats).sort();
  }, [trends]);

  const toggleCategory = (cat: string) => {
    setSelectedCategories((prev) => {
      const n = new Set(prev);
      if (n.has(cat)) n.delete(cat);
      else n.add(cat);
      return n;
    });
  };

  // Chart dimensions
  const CHART_W = 600,
    CHART_H = 300;
  const PAD_L = 60,
    PAD_R = 20,
    PAD_T = 20,
    PAD_B = 40;
  const PLOT_W = CHART_W - PAD_L - PAD_R;
  const PLOT_H = CHART_H - PAD_T - PAD_B;

  const { maxValue, yTicks, lines } = useMemo(() => {
    if (trends.length === 0) return { maxValue: 0, yTicks: [], lines: [] };

    let max = 0;
    trends.forEach((t) => {
      selectedCategories.forEach((cat) => {
        const v = t.categories[cat] || 0;
        if (v > max) max = v;
      });
    });
    max = max * 1.1 || 1;

    const ticks = Array.from({ length: 5 }, (_, i) => (max / 4) * i);

    const lineData = Array.from(selectedCategories).map((cat) => {
      const color = getHexColor(cat);
      const points = trends.map((t, i) => {
        const x = PAD_L + (i / Math.max(trends.length - 1, 1)) * PLOT_W;
        const y = PAD_T + PLOT_H - ((t.categories[cat] || 0) / max) * PLOT_H;
        return { x, y, value: t.categories[cat] || 0, month: t.month };
      });
      return { category: cat, color, points };
    });

    return { maxValue: max, yTicks: ticks, lines: lineData };
  }, [trends, selectedCategories]);

  // Month-over-month change for selected categories
  const momChanges = useMemo(() => {
    if (trends.length < 2) return [];
    const last = trends[trends.length - 1];
    const prev = trends[trends.length - 2];
    if (!last || !prev) return [];

    return Array.from(selectedCategories).map((cat) => {
      const current = last.categories[cat] || 0;
      const previous = prev.categories[cat] || 0;
      const change = previous > 0 ? ((current - previous) / previous) * 100 : 0;
      return { category: cat, current, previous, change, color: getHexColor(cat) };
    });
  }, [trends, selectedCategories]);

  if (loading) {
    return (
      <div className="neu-raised rounded-3xl p-8 border border-border/50 flex items-center justify-center min-h-[300px]">
        <Loader2 className="w-6 h-6 text-cba-gold animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-2">
          <LineChart className="w-4 h-4 text-cba-gold" />
          <span className="text-[10px] font-black text-muted uppercase tracking-[0.2em]">
            Spending Trends
          </span>
        </div>
        <div className="flex gap-1 neu-inset rounded-xl p-1">
          {[6, 12].map((m) => (
            <button
              key={m}
              type="button"
              onClick={() => setMonths(m)}
              className={cn(
                'px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all',
                months === m ? 'bg-cba-gold text-base' : 'text-muted hover:text-primary',
              )}
            >
              {m}m
            </button>
          ))}
        </div>
      </div>

      {/* Chart */}
      <div className="neu-raised rounded-2xl border border-border/50 p-4">
        <svg
          viewBox={`0 0 ${CHART_W} ${CHART_H}`}
          className="w-full h-auto"
          style={{ maxHeight: 400 }}
        >
          {/* Y-axis grid lines + labels */}
          {yTicks.map((tick, i) => {
            const y = PAD_T + PLOT_H - (tick / maxValue) * PLOT_H;
            return (
              <g key={i}>
                <line
                  x1={PAD_L}
                  y1={y}
                  x2={CHART_W - PAD_R}
                  y2={y}
                  stroke="rgba(255,255,255,0.05)"
                />
                <text
                  x={PAD_L - 8}
                  y={y + 3}
                  textAnchor="end"
                  fill="#71717a"
                  className="text-[8px]"
                >
                  {formatCurrency(tick)}
                </text>
              </g>
            );
          })}

          {/* X-axis labels */}
          {trends.map((t, i) => {
            const x = PAD_L + (i / Math.max(trends.length - 1, 1)) * PLOT_W;
            return (
              <text
                key={i}
                x={x}
                y={CHART_H - 8}
                textAnchor="middle"
                fill="#71717a"
                className="text-[8px]"
              >
                {t.month}
              </text>
            );
          })}

          {/* Lines */}
          {lines.map((line) => (
            <g key={line.category}>
              <polyline
                points={line.points.map((p) => `${p.x},${p.y}`).join(' ')}
                fill="none"
                stroke={line.color}
                strokeWidth={2}
                strokeLinejoin="round"
                className="transition-opacity duration-200"
              />
              {/* Data points */}
              {line.points.map((p, i) => (
                <circle
                  key={i}
                  cx={p.x}
                  cy={p.y}
                  r={hoveredMonth === i ? 5 : 3}
                  fill={line.color}
                  stroke="#0a0a0f"
                  strokeWidth={2}
                  className="cursor-pointer transition-all"
                  onMouseEnter={() => setHoveredMonth(i)}
                  onMouseLeave={() => setHoveredMonth(null)}
                />
              ))}
            </g>
          ))}

          {/* Hover tooltip */}
          {hoveredMonth !== null && trends[hoveredMonth] && (
            <g>
              <line
                x1={PAD_L + (hoveredMonth / Math.max(trends.length - 1, 1)) * PLOT_W}
                y1={PAD_T}
                x2={PAD_L + (hoveredMonth / Math.max(trends.length - 1, 1)) * PLOT_W}
                y2={PAD_T + PLOT_H}
                stroke="rgba(255,204,0,0.2)"
                strokeDasharray="4,4"
              />
            </g>
          )}
        </svg>

        {/* Hover detail */}
        {hoveredMonth !== null && trends[hoveredMonth] && (
          <div className="mt-3 p-3 neu-inset rounded-xl border border-border/50">
            <p className="text-[9px] font-black text-secondary uppercase tracking-widest mb-2">
              {trends[hoveredMonth]?.month}
            </p>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
              {Array.from(selectedCategories).map((cat) => (
                <div key={cat} className="flex items-center gap-2">
                  <div
                    className="w-2 h-2 rounded-full"
                    style={{ backgroundColor: getHexColor(cat) }}
                  />
                  <span className="text-[9px] text-secondary truncate">{cat}</span>
                  <span className="text-[9px] font-bold text-primary ml-auto tabular-nums">
                    {formatCurrency(trends[hoveredMonth]?.categories[cat] || 0)}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* Category checkboxes */}
      <div className="flex flex-wrap gap-2">
        {allCategories.map((cat) => {
          const active = selectedCategories.has(cat);
          return (
            <button
              key={cat}
              type="button"
              onClick={() => toggleCategory(cat)}
              className={cn(
                'flex items-center gap-1.5 px-2.5 py-1 rounded-lg text-[9px] font-bold transition-all border',
                active
                  ? 'border-border bg-overlay text-primary'
                  : 'border-transparent text-zinc-600 hover:text-secondary',
              )}
            >
              <div
                className={cn(
                  'w-2.5 h-2.5 rounded-full transition-opacity',
                  active ? 'opacity-100' : 'opacity-30',
                )}
                style={{ backgroundColor: getHexColor(cat) }}
              />
              {cat}
            </button>
          );
        })}
      </div>

      {/* MoM Changes */}
      {momChanges.length > 0 && (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
          {momChanges.map((mc) => (
            <div key={mc.category} className="neu-inset rounded-xl p-3 border border-border/50">
              <div className="flex items-center gap-1.5 mb-1">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: mc.color }} />
                <span className="text-[8px] font-bold text-muted uppercase tracking-tight truncate">
                  {mc.category}
                </span>
              </div>
              <div className="flex items-center gap-1">
                {mc.change > 5 ? (
                  <TrendingUp className="w-3 h-3 text-red-400" />
                ) : mc.change < -5 ? (
                  <TrendingDown className="w-3 h-3 text-emerald-400" />
                ) : (
                  <Minus className="w-3 h-3 text-muted" />
                )}
                <span
                  className={cn(
                    'text-xs font-black tabular-nums',
                    mc.change > 5
                      ? 'text-red-400'
                      : mc.change < -5
                        ? 'text-emerald-400'
                        : 'text-muted',
                  )}
                >
                  {mc.change > 0 ? '+' : ''}
                  {mc.change.toFixed(1)}%
                </span>
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  FileText,
  ClipboardList,
  Users,
  Banknote,
  Plus,
  AlertTriangle,
  Clock,
  DollarSign,
  ShoppingCart,
} from 'lucide-react';
import { apApi } from '../../../api';
import type { APAgingReport } from '../../../api';
import { SupplierList } from './SupplierList';
import { SupplierDetail } from './SupplierDetail';
import { SupplierForm } from './SupplierForm';
import { BillEntry } from './BillEntry';
import { BillList } from './BillList';
import { BillApproval } from './BillApproval';
import { POList } from './POList';
import { PurchaseOrderEditor } from './PurchaseOrderEditor';
import { POReceiving } from './POReceiving';
import { SupplierPaymentRun } from './SupplierPaymentRun';

type APTab = 'bills' | 'purchase-orders' | 'suppliers' | 'payment-runs';
type View =
  | { type: 'list' }
  | { type: 'supplier-detail'; id: string }
  | { type: 'supplier-form'; id?: string }
  | { type: 'bill-entry'; id?: string }
  | { type: 'bill-approval'; id: string }
  | { type: 'po-editor'; id?: string }
  | { type: 'po-receiving'; id: string }
  | { type: 'payment-run' };

export function APDashboard() {
  const [activeTab, setActiveTab] = useState<APTab>('bills');
  const [view, setView] = useState<View>({ type: 'list' });
  const [aging, setAging] = useState<APAgingReport | null>(null);
  const [loading, setLoading] = useState(true);

  const loadAging = async () => {
    try {
      const data = await apApi.fetchAPAging();
      setAging(data);
    } catch (e) {
      console.error('Failed to fetch AP aging', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadAging();
  }, []);

  const handleTabChange = (tab: APTab) => {
    setActiveTab(tab);
    setView({ type: 'list' });
  };

  const tabs: { id: APTab; label: string; icon: typeof FileText }[] = [
    { id: 'bills', label: 'Bills', icon: FileText },
    { id: 'purchase-orders', label: 'Purchase Orders', icon: ClipboardList },
    { id: 'suppliers', label: 'Suppliers', icon: Users },
    { id: 'payment-runs', label: 'Payment Runs', icon: Banknote },
  ];

  const overdueBucket = aging?.buckets.find(
    (b) => b.label === '61-90 days' || b.label === '90+ days',
  );
  const totalOverdue = aging
    ? aging.buckets
        .filter((b) => b.label.includes('61') || b.label.includes('90'))
        .reduce((sum, b) => sum + b.amount, 0)
    : 0;

  const statCards = [
    {
      label: 'Total Outstanding',
      value: aging ? formatCurrency(aging.totalOutstanding) : '$0.00',
      icon: DollarSign,
      color: 'text-blue-400',
    },
    {
      label: 'Total Overdue',
      value: formatCurrency(totalOverdue),
      icon: AlertTriangle,
      color: 'text-red-400',
    },
    {
      label: 'Bills Due This Week',
      value: aging?.buckets.find((b) => b.label === 'Current')?.count?.toString() ?? '0',
      icon: Clock,
      color: 'text-amber-400',
    },
    {
      label: 'Open POs',
      value: '—',
      icon: ShoppingCart,
      color: 'text-emerald-400',
    },
  ];

  const quickActions = [
    {
      label: 'New Bill',
      icon: FileText,
      action: () => {
        setActiveTab('bills');
        setView({ type: 'bill-entry' });
      },
    },
    {
      label: 'New PO',
      icon: ClipboardList,
      action: () => {
        setActiveTab('purchase-orders');
        setView({ type: 'po-editor' });
      },
    },
    {
      label: 'New Supplier',
      icon: Users,
      action: () => {
        setActiveTab('suppliers');
        setView({ type: 'supplier-form' });
      },
    },
    {
      label: 'Payment Run',
      icon: Banknote,
      action: () => {
        setActiveTab('payment-runs');
        setView({ type: 'payment-run' });
      },
    },
  ];

  // Sub-view renders
  if (view.type === 'supplier-detail') {
    return (
      <SupplierDetail
        supplierId={view.id}
        onBack={() => setView({ type: 'list' })}
        onEdit={(id) => setView({ type: 'supplier-form', id })}
      />
    );
  }

  if (view.type === 'supplier-form') {
    return (
      <SupplierForm
        supplierId={view.id}
        onSave={() => {
          setView({ type: 'list' });
          loadAging();
        }}
        onCancel={() => setView({ type: 'list' })}
      />
    );
  }

  if (view.type === 'bill-entry') {
    return (
      <BillEntry
        billId={view.id}
        onSave={() => {
          setView({ type: 'list' });
          loadAging();
        }}
        onCancel={() => setView({ type: 'list' })}
      />
    );
  }

  if (view.type === 'bill-approval') {
    return (
      <BillApproval
        billId={view.id}
        onBack={() => setView({ type: 'list' })}
        onAction={() => {
          setView({ type: 'list' });
          loadAging();
        }}
      />
    );
  }

  if (view.type === 'po-editor') {
    return (
      <PurchaseOrderEditor
        poId={view.id}
        onSave={() => {
          setView({ type: 'list' });
          loadAging();
        }}
        onCancel={() => setView({ type: 'list' })}
      />
    );
  }

  if (view.type === 'po-receiving') {
    return (
      <POReceiving
        poId={view.id}
        onBack={() => setView({ type: 'list' })}
        onReceived={() => {
          setView({ type: 'list' });
          loadAging();
        }}
      />
    );
  }

  if (view.type === 'payment-run') {
    return (
      <SupplierPaymentRun
        onBack={() => setView({ type: 'list' })}
        onComplete={() => {
          setView({ type: 'list' });
          loadAging();
        }}
      />
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-primary">Accounts Payable</h1>
          <p className="text-sm text-secondary mt-1">
            Manage suppliers, bills, purchase orders, and payment runs
          </p>
        </div>
        <div className="flex gap-2">
          {quickActions.map((qa) => (
            <button
              key={qa.label}
              onClick={qa.action}
              className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium bg-overlay text-primary hover:bg-cba-gold/10 hover:text-cba-gold transition-all border border-border/50"
            >
              <qa.icon className="h-3.5 w-3.5" />
              {qa.label}
            </button>
          ))}
        </div>
      </div>

      {/* Stat Cards */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {loading
          ? Array.from({ length: 4 }).map((_, i) => (
              <div key={i} className="neu-raised rounded-2xl p-5 animate-pulse">
                <div className="h-4 w-20 bg-overlay rounded mb-3" />
                <div className="h-8 w-16 bg-overlay rounded" />
              </div>
            ))
          : statCards.map((card) => (
              <div key={card.label} className="neu-raised rounded-2xl p-5">
                <div className="flex items-center justify-between mb-2">
                  <span className="text-xs font-medium text-secondary uppercase tracking-wider">
                    {card.label}
                  </span>
                  <card.icon className={`h-4 w-4 ${card.color}`} />
                </div>
                <p className="text-2xl font-bold text-primary">{card.value}</p>
              </div>
            ))}
      </div>

      {/* AP Aging Mini-Chart */}
      {aging && aging.buckets.length > 0 && (
        <div className="neu-raised rounded-2xl p-5">
          <h3 className="text-sm font-semibold text-primary mb-3">AP Aging Distribution</h3>
          <div className="flex items-end gap-2 h-20">
            {aging.buckets.map((bucket) => {
              const maxAmount = Math.max(...aging.buckets.map((b) => b.amount));
              const height = maxAmount > 0 ? (bucket.amount / maxAmount) * 100 : 0;
              return (
                <div key={bucket.label} className="flex-1 flex flex-col items-center gap-1">
                  <div
                    className="w-full rounded-t bg-cba-gold/60 transition-all hover:bg-cba-gold/80"
                    style={{ height: `${Math.max(height, 4)}%` }}
                    title={`${bucket.label}: ${formatCurrency(bucket.amount)} (${bucket.count} bills)`}
                  />
                  <span className="text-[10px] text-muted truncate w-full text-center">
                    {bucket.label}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Tab Navigation */}
      <div className="flex gap-1 p-1 neu-inset rounded-xl w-fit">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => handleTabChange(tab.id)}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-all ${
              activeTab === tab.id
                ? 'bg-cba-gold/10 text-cba-gold shadow-sm'
                : 'text-secondary hover:text-primary'
            }`}
          >
            <tab.icon className="h-4 w-4" />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      {activeTab === 'bills' && (
        <BillList
          onNewBill={() => setView({ type: 'bill-entry' })}
          onEditBill={(id) => setView({ type: 'bill-entry', id })}
          onApproveBill={(id) => setView({ type: 'bill-approval', id })}
        />
      )}

      {activeTab === 'purchase-orders' && (
        <POList
          onNewPO={() => setView({ type: 'po-editor' })}
          onEditPO={(id) => setView({ type: 'po-editor', id })}
          onReceive={(id) => setView({ type: 'po-receiving', id })}
        />
      )}

      {activeTab === 'suppliers' && (
        <SupplierList
          onSelect={(id) => setView({ type: 'supplier-detail', id })}
          onNew={() => setView({ type: 'supplier-form' })}
        />
      )}

      {activeTab === 'payment-runs' && (
        <SupplierPaymentRun
          onBack={() => handleTabChange('bills')}
          onComplete={() => {
            handleTabChange('bills');
            loadAging();
          }}
        />
      )}
    </div>
  );
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
  }).format(cents / 100);
}

import { useState, useEffect, useCallback } from 'react';
import { ArrowLeft, Plus, Trash2, Save, Send, Search } from 'lucide-react';
import { apApi } from '../../../api';
import type { Supplier, BillLineItem } from '../../../api';

interface BillEntryProps {
  billId?: string;
  onSave: () => void;
  onCancel: () => void;
}

interface LineItem {
  description: string;
  quantity: number;
  unitPrice: number;
  gstRate: number;
}

const DEFAULT_GST_RATE = 10;

export function BillEntry({ billId, onSave, onCancel }: BillEntryProps) {
  const isEdit = !!billId;
  const [supplierId, setSupplierId] = useState('');
  const [supplierSearch, setSupplierSearch] = useState('');
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [showSupplierDropdown, setShowSupplierDropdown] = useState(false);
  const [selectedSupplier, setSelectedSupplier] = useState<Supplier | null>(null);

  const [billNumber, setBillNumber] = useState('');
  const [issueDate, setIssueDate] = useState(new Date().toISOString().split('T')[0]);
  const [dueDate, setDueDate] = useState('');
  const [notes, setNotes] = useState('');
  const [purchaseOrderId, setPurchaseOrderId] = useState('');

  const [lineItems, setLineItems] = useState<LineItem[]>([
    { description: '', quantity: 1, unitPrice: 0, gstRate: DEFAULT_GST_RATE },
  ]);

  const [saving, setSaving] = useState(false);
  const [loading, setLoading] = useState(isEdit);

  // Load existing bill for editing
  useEffect(() => {
    if (isEdit && billId) {
      apApi
        .fetchBill(billId)
        .then((bill) => {
          setSupplierId(bill.supplierId);
          setBillNumber(bill.billNumber);
          setIssueDate(bill.issueDate);
          setDueDate(bill.dueDate);
          setNotes(bill.notes ?? '');
          setPurchaseOrderId(bill.purchaseOrderId ?? '');
          if (bill.lineItems?.length) {
            setLineItems(
              bill.lineItems.map((li) => ({
                description: li.description,
                quantity: li.quantity,
                unitPrice: li.unitPrice,
                gstRate: li.gstRate,
              })),
            );
          }
          // Load selected supplier
          apApi
            .fetchSupplier(bill.supplierId)
            .then((s) => {
              setSelectedSupplier(s);
              setSupplierSearch(s.businessName);
            })
            .catch(() => {});
          setLoading(false);
        })
        .catch(() => setLoading(false));
    }
  }, [isEdit, billId]);

  // Supplier autocomplete search
  const searchSuppliers = useCallback(async (query: string) => {
    if (query.length < 2) {
      setSuppliers([]);
      return;
    }
    try {
      const result = await apApi.fetchSuppliers({ search: query, limit: 8, isActive: true });
      setSuppliers(result.suppliers);
    } catch {
      setSuppliers([]);
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => searchSuppliers(supplierSearch), 300);
    return () => clearTimeout(timer);
  }, [supplierSearch, searchSuppliers]);

  // Auto-calculate due date from supplier payment terms
  const selectSupplier = (s: Supplier) => {
    setSupplierId(s.id);
    setSelectedSupplier(s);
    setSupplierSearch(s.businessName);
    setShowSupplierDropdown(false);
    // Auto-calculate due date
    if (issueDate) {
      const due = new Date(issueDate);
      due.setDate(due.getDate() + s.paymentTermsDays);
      setDueDate(due.toISOString().split('T')[0]);
    }
  };

  // Line item calculations
  const calcLineAmount = (item: LineItem) => item.quantity * item.unitPrice;
  const calcLineGST = (item: LineItem) => (calcLineAmount(item) * item.gstRate) / 100;

  const subtotal = lineItems.reduce((sum, item) => sum + calcLineAmount(item), 0);
  const gstTotal = lineItems.reduce((sum, item) => sum + calcLineGST(item), 0);
  const total = subtotal + gstTotal;

  const updateLineItem = (index: number, field: keyof LineItem, value: string | number) => {
    setLineItems((prev) =>
      prev.map((item, i) => (i === index ? { ...item, [field]: value } : item)),
    );
  };

  const addLineItem = () => {
    setLineItems((prev) => [
      ...prev,
      { description: '', quantity: 1, unitPrice: 0, gstRate: DEFAULT_GST_RATE },
    ]);
  };

  const removeLineItem = (index: number) => {
    if (lineItems.length <= 1) return;
    setLineItems((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSave = async (asDraft: boolean) => {
    if (!supplierId || !billNumber.trim()) return;

    setSaving(true);
    try {
      const items: BillLineItem[] = lineItems
        .filter((li) => li.description.trim())
        .map((li) => ({
          description: li.description,
          quantity: li.quantity,
          unitPrice: Math.round(li.unitPrice * 100),
          gstRate: li.gstRate,
          amount: Math.round(calcLineAmount(li) * 100),
          gstAmount: Math.round(calcLineGST(li) * 100),
        }));

      const data = {
        supplierId,
        billNumber: billNumber.trim(),
        issueDate,
        dueDate,
        status: asDraft ? ('draft' as const) : ('awaiting_approval' as const),
        subtotal: Math.round(subtotal * 100),
        gstTotal: Math.round(gstTotal * 100),
        total: Math.round(total * 100),
        purchaseOrderId: purchaseOrderId || undefined,
        notes: notes.trim() || undefined,
        lineItems: items,
      };

      if (isEdit && billId) {
        await apApi.updateBill(billId, data);
      } else {
        await apApi.createBill(data);
      }
      onSave();
    } catch (e) {
      console.error('Failed to save bill', e);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="space-y-6 animate-in fade-in duration-300">
        <button
          onClick={onCancel}
          className="flex items-center gap-2 text-secondary hover:text-primary text-sm transition-colors"
        >
          <ArrowLeft className="h-4 w-4" /> Back
        </button>
        <div className="neu-raised rounded-2xl p-6 animate-pulse">
          <div className="h-6 w-48 bg-overlay rounded mb-4" />
          <div className="h-4 w-32 bg-overlay rounded" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      <button
        onClick={onCancel}
        className="flex items-center gap-2 text-secondary hover:text-primary text-sm transition-colors"
      >
        <ArrowLeft className="h-4 w-4" /> Back
      </button>

      <div>
        <h1 className="text-2xl font-bold text-primary">{isEdit ? 'Edit Bill' : 'New Bill'}</h1>
        <p className="text-sm text-secondary mt-1">Enter bill details and line items</p>
      </div>

      {/* Bill Header */}
      <div className="neu-raised rounded-2xl p-6 space-y-4">
        <h3 className="text-sm font-semibold text-primary">Bill Details</h3>

        {/* Supplier Autocomplete */}
        <div className="relative">
          <label htmlFor="ap-f1" className="block text-xs font-medium text-secondary mb-1.5">Supplier *</label>
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted" />
            <input id="ap-f1"
              type="text"
              value={supplierSearch}
              onChange={(e) => {
                setSupplierSearch(e.target.value);
                setShowSupplierDropdown(true);
                if (!e.target.value) {
                  setSupplierId('');
                  setSelectedSupplier(null);
                }
              }}
              onFocus={() => setShowSupplierDropdown(true)}
              placeholder="Search supplier..."
              className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all"
            />
          </div>
          {showSupplierDropdown && suppliers.length > 0 && (
            <div className="absolute z-20 w-full mt-1 rounded-xl bg-[#1a1a2e] border border-border shadow-xl max-h-48 overflow-y-auto">
              {suppliers.map((s) => (
                <button
                  key={s.id}
                  type="button"
                  onClick={() => selectSupplier(s)}
                  className="w-full px-4 py-2.5 text-left text-sm text-primary hover:bg-overlay hover:text-primary transition-colors"
                >
                  <span className="font-medium">{s.businessName}</span>
                  {s.abn && (
                    <span className="ml-2 text-xs text-muted font-mono">ABN: {s.abn}</span>
                  )}
                </button>
              ))}
            </div>
          )}
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label htmlFor="ap-f2" className="block text-xs font-medium text-secondary mb-1.5">Bill Number *</label>
            <input id="ap-f2"
              type="text"
              value={billNumber}
              onChange={(e) => setBillNumber(e.target.value)}
              className="w-full px-3 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all"
              placeholder="INV-001"
            />
          </div>
          <div>
            <label htmlFor="ap-f3" className="block text-xs font-medium text-secondary mb-1.5">Issue Date</label>
            <input id="ap-f3"
              type="date"
              value={issueDate}
              onChange={(e) => setIssueDate(e.target.value)}
              className="w-full px-3 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all"
            />
          </div>
          <div>
            <label htmlFor="ap-f4" className="block text-xs font-medium text-secondary mb-1.5">Due Date</label>
            <input id="ap-f4"
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              className="w-full px-3 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all"
            />
          </div>
        </div>

        <div>
          <label htmlFor="ap-f5" className="block text-xs font-medium text-secondary mb-1.5">
            Link to Purchase Order (optional)
          </label>
          <input id="ap-f5"
            type="text"
            value={purchaseOrderId}
            onChange={(e) => setPurchaseOrderId(e.target.value)}
            className="w-full px-3 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all"
            placeholder="PO number or leave blank"
          />
        </div>
      </div>

      {/* Line Items */}
      <div className="neu-raised rounded-2xl p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-sm font-semibold text-primary">Line Items</h3>
          <button
            type="button"
            onClick={addLineItem}
            className="flex items-center gap-1 px-3 py-1.5 rounded-lg text-xs font-medium bg-overlay text-primary hover:bg-cba-gold/10 hover:text-cba-gold transition-all"
          >
            <Plus className="h-3 w-3" />
            Add Row
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full min-w-[640px]">
            <thead>
              <tr className="border-b border-border/50">
                <th className="text-left px-2 py-2 text-xs font-semibold text-secondary w-[35%]">
                  Description
                </th>
                <th className="text-right px-2 py-2 text-xs font-semibold text-secondary w-[10%]">
                  Qty
                </th>
                <th className="text-right px-2 py-2 text-xs font-semibold text-secondary w-[15%]">
                  Unit Price
                </th>
                <th className="text-right px-2 py-2 text-xs font-semibold text-secondary w-[10%]">
                  GST %
                </th>
                <th className="text-right px-2 py-2 text-xs font-semibold text-secondary w-[12%]">
                  Amount
                </th>
                <th className="text-right px-2 py-2 text-xs font-semibold text-secondary w-[12%]">
                  GST
                </th>
                <th className="w-[6%]"></th>
              </tr>
            </thead>
            <tbody>
              {lineItems.map((item, index) => (
                <tr key={`item-${index}`} className="border-b border-border/50">
                  <td className="px-1 py-2">
                    <input
                      type="text"
                      value={item.description}
                      onChange={(e) => updateLineItem(index, 'description', e.target.value)}
                      className="w-full px-2 py-1.5 rounded-lg bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 transition-all"
                      placeholder="Item description"
                    />
                  </td>
                  <td className="px-1 py-2">
                    <input
                      type="number"
                      value={item.quantity}
                      onChange={(e) => updateLineItem(index, 'quantity', Number(e.target.value))}
                      className="w-full px-2 py-1.5 rounded-lg bg-overlay border border-border text-sm text-primary text-right focus:outline-none focus:border-cba-gold/30 transition-all"
                      min="1"
                      step="1"
                    />
                  </td>
                  <td className="px-1 py-2">
                    <input
                      type="number"
                      value={item.unitPrice}
                      onChange={(e) => updateLineItem(index, 'unitPrice', Number(e.target.value))}
                      className="w-full px-2 py-1.5 rounded-lg bg-overlay border border-border text-sm text-primary text-right focus:outline-none focus:border-cba-gold/30 transition-all"
                      min="0"
                      step="0.01"
                    />
                  </td>
                  <td className="px-1 py-2">
                    <input
                      type="number"
                      value={item.gstRate}
                      onChange={(e) => updateLineItem(index, 'gstRate', Number(e.target.value))}
                      className="w-full px-2 py-1.5 rounded-lg bg-overlay border border-border text-sm text-primary text-right focus:outline-none focus:border-cba-gold/30 transition-all"
                      min="0"
                      max="100"
                      step="1"
                    />
                  </td>
                  <td className="px-2 py-2 text-right text-sm text-primary font-mono">
                    ${calcLineAmount(item).toFixed(2)}
                  </td>
                  <td className="px-2 py-2 text-right text-sm text-secondary font-mono">
                    ${calcLineGST(item).toFixed(2)}
                  </td>
                  <td className="px-1 py-2 text-center">
                    <button
                      type="button"
                      onClick={() => removeLineItem(index)}
                      disabled={lineItems.length <= 1}
                      className="p-1 rounded-lg text-muted hover:text-red-400 hover:bg-red-400/10 transition-all disabled:opacity-20"
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {/* Totals */}
        <div className="flex justify-end mt-4">
          <div className="w-64 space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-secondary">Subtotal</span>
              <span className="text-primary font-mono">${subtotal.toFixed(2)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-secondary">GST</span>
              <span className="text-primary font-mono">${gstTotal.toFixed(2)}</span>
            </div>
            <div className="border-t border-border pt-2 flex justify-between text-sm font-semibold">
              <span className="text-cba-gold">Total</span>
              <span className="text-cba-gold font-mono">${total.toFixed(2)}</span>
            </div>
          </div>
        </div>
      </div>

      {/* Notes */}
      <div className="neu-raised rounded-2xl p-6">
        <label htmlFor="ap-f6" className="block text-xs font-medium text-secondary mb-1.5">Notes</label>
        <textarea id="ap-f6"
          value={notes}
          onChange={(e) => setNotes(e.target.value)}
          className="w-full px-3 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all resize-none"
          rows={3}
          placeholder="Additional notes..."
        />
      </div>

      {/* Actions */}
      <div className="flex items-center justify-end gap-3">
        <button
          type="button"
          onClick={onCancel}
          className="px-5 py-2.5 rounded-xl bg-overlay text-primary text-sm font-medium hover:bg-overlay-hover transition-all"
        >
          Cancel
        </button>
        <button
          type="button"
          onClick={() => handleSave(true)}
          disabled={saving || !supplierId || !billNumber.trim()}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-overlay-hover text-primary font-medium text-sm hover:bg-white/15 transition-all disabled:opacity-50"
        >
          <Save className="h-4 w-4" />
          Save Draft
        </button>
        <button
          type="button"
          onClick={() => handleSave(false)}
          disabled={saving || !supplierId || !billNumber.trim()}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-cba-gold text-black font-semibold text-sm hover:bg-cba-gold/90 transition-all shadow-[0_0_20px_rgba(255,204,0,0.2)] disabled:opacity-50"
        >
          <Send className="h-4 w-4" />
          {saving ? 'Saving...' : 'Submit for Approval'}
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  FileText,
  ChevronLeft,
  ChevronRight,
  Plus,
  Eye,
  CheckCircle,
  Ban,
  DollarSign,
} from 'lucide-react';
import { apApi } from '../../../api';
import type { Bill } from '../../../api';

type StatusFilter = 'all' | 'draft' | 'awaiting_approval' | 'approved' | 'overdue' | 'paid';

interface BillListProps {
  onNewBill: () => void;
  onEditBill: (id: string) => void;
  onApproveBill: (id: string) => void;
}

export function BillList({ onNewBill, onEditBill, onApproveBill }: BillListProps) {
  const [bills, setBills] = useState<Bill[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<StatusFilter>('all');
  const [page, setPage] = useState(1);
  const limit = 20;

  const loadBills = async () => {
    setLoading(true);
    try {
      const result = await apApi.fetchBills({
        page,
        limit,
        status: statusFilter === 'all' ? undefined : statusFilter,
      });
      setBills(result.bills);
      setTotal(result.total);
    } catch (e) {
      console.error('Failed to fetch bills', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadBills();
  }, [page, statusFilter]);

  const totalPages = Math.ceil(total / limit);

  const statusTabs: { id: StatusFilter; label: string }[] = [
    { id: 'all', label: 'All' },
    { id: 'draft', label: 'Draft' },
    { id: 'awaiting_approval', label: 'Awaiting' },
    { id: 'approved', label: 'Approved' },
    { id: 'overdue', label: 'Overdue' },
    { id: 'paid', label: 'Paid' },
  ];

  const handleQuickAction = async (action: string, bill: Bill) => {
    switch (action) {
      case 'view':
        onEditBill(bill.id);
        break;
      case 'approve':
        onApproveBill(bill.id);
        break;
      case 'pay':
        try {
          await apApi.payBill(bill.id, { paymentDate: new Date().toISOString().split('T')[0] });
          loadBills();
        } catch (e) {
          console.error('Failed to pay bill', e);
        }
        break;
      case 'void':
        try {
          await apApi.voidBill(bill.id);
          loadBills();
        } catch (e) {
          console.error('Failed to void bill', e);
        }
        break;
    }
  };

  return (
    <div className="space-y-4">
      {/* Status Filter + New */}
      <div className="flex items-center justify-between">
        <div className="flex gap-1 p-1 neu-inset rounded-xl">
          {statusTabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => {
                setStatusFilter(tab.id);
                setPage(1);
              }}
              className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-all ${
                statusFilter === tab.id
                  ? 'bg-cba-gold/10 text-cba-gold'
                  : 'text-secondary hover:text-primary'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <button
          onClick={onNewBill}
          className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-cba-gold text-black font-semibold text-sm hover:bg-cba-gold/90 transition-all shadow-[0_0_20px_rgba(255,204,0,0.2)]"
        >
          <Plus className="h-4 w-4" />
          New Bill
        </button>
      </div>

      {/* Table */}
      <div className="neu-raised rounded-2xl overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border/50">
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Bill #
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Supplier
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider hidden md:table-cell">
                Issue Date
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider hidden md:table-cell">
                Due Date
              </th>
              <th className="text-right px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Total
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Status
              </th>
              <th className="text-right px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Actions
              </th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="border-b border-border/50">
                  <td colSpan={7} className="px-4 py-4">
                    <div className="h-4 w-full bg-overlay rounded animate-pulse" />
                  </td>
                </tr>
              ))
            ) : bills.length === 0 ? (
              <tr>
                <td colSpan={7} className="px-4 py-12 text-center">
                  <FileText className="h-10 w-10 text-zinc-600 mx-auto mb-2" />
                  <p className="text-secondary text-sm">No bills found</p>
                </td>
              </tr>
            ) : (
              bills.map((bill) => (
                <tr
                  key={bill.id}
                  className="border-b border-border/50 hover:bg-white/[0.02] transition-colors"
                >
                  <td className="px-4 py-3 text-sm text-primary font-mono">{bill.billNumber}</td>
                  <td className="px-4 py-3 text-sm text-primary">{bill.supplierName ?? '—'}</td>
                  <td className="px-4 py-3 text-sm text-secondary hidden md:table-cell">
                    {bill.issueDate}
                  </td>
                  <td className="px-4 py-3 text-sm text-secondary hidden md:table-cell">
                    {bill.dueDate}
                  </td>
                  <td className="px-4 py-3 text-right text-sm font-medium text-primary">
                    {formatCurrency(bill.total)}
                  </td>
                  <td className="px-4 py-3">
                    <StatusBadge status={bill.status} />
                  </td>
                  <td className="px-4 py-3">
                    <div className="flex items-center justify-end gap-1">
                      <ActionButton
                        icon={Eye}
                        tooltip="View"
                        onClick={() => handleQuickAction('view', bill)}
                      />
                      {bill.status === 'awaiting_approval' && (
                        <ActionButton
                          icon={CheckCircle}
                          tooltip="Approve"
                          onClick={() => handleQuickAction('approve', bill)}
                          accent
                        />
                      )}
                      {bill.status === 'approved' && (
                        <ActionButton
                          icon={DollarSign}
                          tooltip="Pay"
                          onClick={() => handleQuickAction('pay', bill)}
                          accent
                        />
                      )}
                      {(bill.status === 'draft' || bill.status === 'awaiting_approval') && (
                        <ActionButton
                          icon={Ban}
                          tooltip="Void"
                          onClick={() => handleQuickAction('void', bill)}
                          danger
                        />
                      )}
                    </div>
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-xs text-muted">
            Showing {(page - 1) * limit + 1}–{Math.min(page * limit, total)} of {total}
          </p>
          <div className="flex gap-1">
            <button
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page === 1}
              className="p-2 rounded-lg bg-overlay text-secondary hover:text-primary disabled:opacity-30 transition-all"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="p-2 rounded-lg bg-overlay text-secondary hover:text-primary disabled:opacity-30 transition-all"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function StatusBadge({ status }: { status: string }) {
  const styles: Record<string, string> = {
    draft: 'bg-zinc-400/10 text-secondary',
    awaiting_approval: 'bg-amber-400/10 text-amber-400',
    approved: 'bg-emerald-400/10 text-emerald-400',
    overdue: 'bg-red-400/10 text-red-400',
    paid: 'bg-blue-400/10 text-blue-400',
    void: 'bg-zinc-500/10 text-muted',
  };
  const labels: Record<string, string> = {
    draft: 'Draft',
    awaiting_approval: 'Awaiting',
    approved: 'Approved',
    overdue: 'Overdue',
    paid: 'Paid',
    void: 'Void',
  };
  return (
    <span
      className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${styles[status] ?? styles.draft}`}
    >
      {labels[status] ?? status}
    </span>
  );
}

function ActionButton({
  icon: Icon,
  tooltip,
  onClick,
  accent,
  danger,
}: {
  icon: typeof Eye;
  tooltip: string;
  onClick: () => void;
  accent?: boolean;
  danger?: boolean;
}) {
  return (
    <button
      onClick={(e) => {
        e.stopPropagation();
        onClick();
      }}
      title={tooltip}
      className={`p-1.5 rounded-lg transition-all ${
        danger
          ? 'text-muted hover:text-red-400 hover:bg-red-400/10'
          : accent
            ? 'text-cba-gold/60 hover:text-cba-gold hover:bg-cba-gold/10'
            : 'text-muted hover:text-primary hover:bg-overlay'
      }`}
    >
      <Icon className="h-3.5 w-3.5" />
    </button>
  );
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);
}

import { useState, useEffect } from 'react';
import {
  Search,
  Plus,
  ChevronLeft,
  ChevronRight,
  ClipboardList,
