                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-xs text-muted">
            Showing {(page - 1) * limit + 1}–{Math.min(page * limit, total)} of {total}
          </p>
          <div className="flex gap-1">
            <button
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page === 1}
              className="p-2 rounded-lg bg-overlay text-secondary hover:text-primary disabled:opacity-30 transition-all"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="p-2 rounded-lg bg-overlay text-secondary hover:text-primary disabled:opacity-30 transition-all"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);
}

import { useState, useEffect } from 'react';
import {
  ArrowLeft,
  PackageCheck,
  Calendar,
  CheckCircle2,
  AlertTriangle,
  FileText,
  Minus,
} from 'lucide-react';
import { apApi } from '../../../api';
import type { PurchaseOrder } from '../../../api';

interface ReceivingLine {
  lineId: string;
  description: string;
  orderedQty: number;
  previouslyReceived: number;
  receivingNow: number;
  unitPrice: number;
  maxReceivable: number;
}

interface ReceiptHistoryItem {
  id: string;
  receiptDate: string;
  receivedBy?: string;
  lines: Array<{ lineId: string; quantity: number }>;
}

interface ThreeWayMatch {
  poTotal: number;
  receiptTotal: number;
  billTotal: number;
  lines: Array<{
    description: string;
    poQty: number;
    receivedQty: number;
    billedQty: number;
    poAmount: number;
    receivedAmount: number;
    billedAmount: number;
    matched: boolean;
  }>;
  status: 'matched' | 'partial' | 'discrepancy';
}

interface POReceivingProps {
  poId: string;
  onBack: () => void;
  onReceived: () => void;
}

export function POReceiving({ poId, onBack, onReceived }: POReceivingProps) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [po, setPO] = useState<PurchaseOrder | null>(null);
  const [lines, setLines] = useState<ReceivingLine[]>([]);
  const [receiptDate, setReceiptDate] = useState(new Date().toISOString().split('T')[0]);
  const [notes, setNotes] = useState('');
  const [receipts, setReceipts] = useState<ReceiptHistoryItem[]>([]);
  const [threeWay, setThreeWay] = useState<ThreeWayMatch | null>(null);
  const [error, setError] = useState('');

  useEffect(() => {
    loadPO();
  }, [poId]);

  const loadPO = async () => {
    try {
      const poData = await apApi.fetchPurchaseOrder(poId);
      setPO(poData);

      // Build receiving lines from PO line items
      const receivingLines: ReceivingLine[] = (poData.lineItems ?? []).map((li: Record<string, unknown>) => {
        const prevReceived = li.receivedQuantity ?? 0;
        return {
          lineId: li.id ?? li.lineId ?? '',
          description: li.description,
          orderedQty: li.quantity,
          previouslyReceived: prevReceived,
          receivingNow: 0,
          unitPrice: li.unitPrice,
          maxReceivable: li.quantity - prevReceived,
        };
      });
      setLines(receivingLines);

      // Load receipt history if available
      if (poData.receipts) {
        setReceipts(poData.receipts);
      }

      // Load three-way match if bill linked
      if (poData.purchaseOrderId || poData.billId) {
        try {
          const matchData = await apApi.fetchThreeWayMatch(poId);
          setThreeWay(matchData);
        } catch {
          // No three-way match available
        }
      }
    } catch (e) {
      console.error('Failed to load PO for receiving', e);
      setError('Failed to load purchase order');
    } finally {
      setLoading(false);
    }
  };

  const updateReceivingQty = (lineId: string, qty: number) => {
    setLines((prev) =>
      prev.map((l) => {
        if (l.lineId !== lineId) return l;
        const clamped = Math.max(0, Math.min(qty, l.maxReceivable));
        return { ...l, receivingNow: clamped };
      }),
    );
  };

  const totalReceivingNow = lines.reduce((sum, l) => sum + l.receivingNow, 0);
  const linesFullyReceived = lines.filter(
    (l) => l.previouslyReceived + l.receivingNow >= l.orderedQty,
  ).length;
  const linesPartial = lines.filter((l) => {
    const total = l.previouslyReceived + l.receivingNow;
    return total > 0 && total < l.orderedQty;
  }).length;
  const linesOutstanding = lines.filter(
    (l) => l.previouslyReceived + l.receivingNow === 0 && l.orderedQty > 0,
  ).length;

  const handleRecordReceipt = async () => {
    if (totalReceivingNow === 0) {
      setError('Enter quantities to receive');
      return;
    }
    setError('');
    setSaving(true);

    try {
      await apApi.receivePurchaseOrder(poId, {
        receiptDate,
        notes: notes || undefined,
        lines: lines
          .filter((l) => l.receivingNow > 0)
          .map((l) => ({
            lineId: l.lineId,
            quantity: l.receivingNow,
          })),
      });
      onReceived();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to record receipt');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="neu-raised rounded-2xl p-8 animate-pulse">
        <div className="h-6 w-48 bg-overlay rounded mb-6" />
        <div className="space-y-4">
          <div className="h-10 w-full bg-overlay rounded" />
          <div className="h-40 w-full bg-overlay rounded" />
        </div>
      </div>
    );
  }

  if (!po) {
    return (
      <div className="neu-raised rounded-2xl p-8 text-center">
        <AlertTriangle className="h-10 w-10 text-red-400 mx-auto mb-3" />
        <p className="text-secondary">Purchase order not found</p>
      </div>
    );
  }

  const isReceivable = po.status === 'sent' || po.status === 'partially_received';

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={onBack}
          className="p-2 rounded-xl bg-overlay text-secondary hover:text-primary transition-all"
        >
          <ArrowLeft className="h-4 w-4" />
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-bold text-primary">Goods Receiving</h2>
          <p className="text-xs text-muted mt-0.5 font-mono">{po.poNumber}</p>
        </div>
        <span
          className={`px-3 py-1 rounded-full text-xs font-medium ${
            po.status === 'received'
              ? 'bg-emerald-400/10 text-emerald-400'
              : po.status === 'partially_received'
                ? 'bg-amber-400/10 text-amber-400'
                : 'bg-blue-400/10 text-blue-400'
          }`}
        >
          {po.status.replace('_', ' ')}
        </span>
      </div>

      {/* PO Header Info */}
      <div className="neu-raised rounded-2xl p-5">
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
          <div>
            <span className="text-muted text-xs">Supplier</span>
            <p className="text-primary font-medium">{po.supplierName ?? '—'}</p>
          </div>
          <div>
            <span className="text-muted text-xs">Issue Date</span>
            <p className="text-primary">
              {po.issueDate ? new Date(po.issueDate).toLocaleDateString('en-AU') : '—'}
            </p>
          </div>
          <div>
            <span className="text-muted text-xs">Expected Delivery</span>
            <p className="text-primary">
              {po.expectedDate ? new Date(po.expectedDate).toLocaleDateString('en-AU') : '—'}
            </p>
          </div>
          <div>
            <span className="text-muted text-xs">PO Total</span>
            <p className="text-cba-gold font-semibold">{formatCurrency(po.total)}</p>
          </div>
        </div>
      </div>

      {error && (
        <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm">
          {error}
        </div>
      )}

      {/* Receiving Lines Table */}
      {isReceivable && (
        <div className="neu-raised rounded-2xl overflow-hidden">
          <div className="p-4 border-b border-border/50 flex items-center justify-between">
            <h3 className="text-sm font-semibold text-primary">Receive Items</h3>
            <div className="flex items-center gap-2">
              <Calendar className="h-4 w-4 text-muted" />
              <input
                type="date"
                value={receiptDate}
                onChange={(e) => setReceiptDate(e.target.value)}
                className="px-3 py-1.5 rounded-lg bg-overlay border border-border text-sm text-primary focus:outline-none focus:border-cba-gold/30 transition-all"
              />
            </div>
          </div>
          <table className="w-full">
            <thead>
              <tr className="border-b border-border/50 bg-white/[0.02]">
                <th className="text-left px-4 py-2 text-xs font-semibold text-secondary">
                  Description
                </th>
                <th className="text-right px-3 py-2 text-xs font-semibold text-secondary">
                  Ordered
                </th>
                <th className="text-right px-3 py-2 text-xs font-semibold text-secondary">
                  Prev Recv
                </th>
                <th className="text-right px-3 py-2 text-xs font-semibold text-secondary w-28">
                  Receiving Now
                </th>
                <th className="text-right px-3 py-2 text-xs font-semibold text-secondary">
                  Unit Price
                </th>
                <th className="text-right px-4 py-2 text-xs font-semibold text-secondary">Amount</th>
              </tr>
            </thead>
            <tbody>
              {lines.map((line) => {
                const willComplete = line.previouslyReceived + line.receivingNow >= line.orderedQty;
                return (
                  <tr
                    key={line.lineId}
                    className={`border-b border-border/50 transition-colors ${
                      willComplete && line.receivingNow > 0 ? 'bg-emerald-400/[0.03]' : ''
                    }`}
                  >
                    <td className="px-4 py-3 text-sm text-primary">{line.description}</td>
                    <td className="px-3 py-3 text-sm text-secondary text-right">
                      {line.orderedQty}
                    </td>
                    <td className="px-3 py-3 text-sm text-secondary text-right">
                      {line.previouslyReceived}
                    </td>
                    <td className="px-3 py-3">
                      <input
                        type="number"
                        min={0}
                        max={line.maxReceivable}
                        value={line.receivingNow}
                        onChange={(e) => updateReceivingQty(line.lineId, Number(e.target.value))}
                        className={`w-full px-2 py-1.5 rounded-lg text-sm text-right text-primary bg-overlay border focus:outline-none focus:ring-1 transition-all ${
                          line.receivingNow > 0
                            ? 'border-cba-gold/30 focus:ring-[#FFCC00]/20'
                            : 'border-border focus:ring-white/10'
                        }`}
                      />
                    </td>
                    <td className="px-3 py-3 text-sm text-secondary text-right">
                      {formatCurrency(line.unitPrice)}
                    </td>
                    <td className="px-4 py-3 text-sm font-medium text-right">
                      <span className={line.receivingNow > 0 ? 'text-cba-gold' : 'text-muted'}>
                        {formatCurrency(line.receivingNow * line.unitPrice)}
                      </span>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Receiving Summary */}
      <div className="grid grid-cols-3 gap-4">
        <div className="neu-raised rounded-2xl p-4 text-center">
          <CheckCircle2 className="h-5 w-5 text-emerald-400 mx-auto mb-1" />
          <p className="text-lg font-bold text-primary">{linesFullyReceived}</p>
          <p className="text-xs text-muted">Fully Received</p>
        </div>
        <div className="neu-raised rounded-2xl p-4 text-center">
          <Minus className="h-5 w-5 text-amber-400 mx-auto mb-1" />
          <p className="text-lg font-bold text-primary">{linesPartial}</p>
          <p className="text-xs text-muted">Partial</p>
        </div>
        <div className="neu-raised rounded-2xl p-4 text-center">
          <AlertTriangle className="h-5 w-5 text-muted mx-auto mb-1" />
          <p className="text-lg font-bold text-primary">{linesOutstanding}</p>
          <p className="text-xs text-muted">Outstanding</p>
        </div>
      </div>

      {/* Notes + Record Button */}
      {isReceivable && (
        <div className="neu-raised rounded-2xl p-5 space-y-4">
          <div>
            <label htmlFor="porece-f1" className="block text-xs font-medium text-secondary mb-1.5">Receipt Notes</label>
            <textarea id="porece-f1"
              value={notes}
              onChange={(e) => setNotes(e.target.value)}
              rows={2}
              placeholder="Optional notes for this receipt..."
              className="w-full px-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all resize-none"
            />
          </div>
          <div className="flex justify-end">
            <button
              onClick={handleRecordReceipt}
              disabled={saving || totalReceivingNow === 0}
              className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-cba-gold text-black text-sm font-semibold hover:bg-cba-gold/90 transition-all shadow-[0_0_20px_rgba(255,204,0,0.2)] disabled:opacity-50"
            >
              <PackageCheck className="h-4 w-4" />
              {saving ? 'Recording...' : `Record Receipt (${totalReceivingNow} items)`}
            </button>
          </div>
        </div>
      )}

      {/* Receipt History */}
      {receipts.length > 0 && (
        <div className="neu-raised rounded-2xl p-5">
          <h3 className="text-sm font-semibold text-primary mb-3">Receipt History</h3>
          <div className="space-y-2">
            {receipts.map((r, idx) => (
              <div
                key={r.id ?? idx}
                className="flex items-center justify-between px-4 py-3 rounded-xl bg-white/[0.02] border border-border/50"
              >
                <div className="flex items-center gap-3">
                  <PackageCheck className="h-4 w-4 text-emerald-400" />
                  <div>
                    <p className="text-sm text-primary font-medium">
                      {new Date(r.receiptDate).toLocaleDateString('en-AU')}
                    </p>
                    <p className="text-xs text-muted">
                      {r.lines.reduce((sum, l) => sum + l.quantity, 0)} items received
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Three-Way Match Panel */}
      {threeWay && (
        <div className="neu-raised rounded-2xl p-5">
          <div className="flex items-center gap-2 mb-4">
            <FileText className="h-4 w-4 text-cba-gold" />
            <h3 className="text-sm font-semibold text-primary">Three-Way Match</h3>
            <span
              className={`ml-auto px-2 py-0.5 rounded-full text-xs font-medium ${
                threeWay.status === 'matched'
                  ? 'bg-emerald-400/10 text-emerald-400'
                  : threeWay.status === 'partial'
                    ? 'bg-amber-400/10 text-amber-400'
                    : 'bg-red-400/10 text-red-400'
              }`}
            >
              {threeWay.status === 'matched'
                ? 'Matched'
                : threeWay.status === 'partial'
                  ? 'Partial Match'
                  : 'Discrepancy'}
            </span>
          </div>

          {/* Summary Comparison */}
          <div className="grid grid-cols-3 gap-4 mb-4">
            <div className="text-center p-3 rounded-xl bg-white/[0.02] border border-border/50">
              <p className="text-xs text-muted mb-1">PO Total</p>
              <p className="text-sm font-semibold text-primary">{formatCurrency(threeWay.poTotal)}</p>
            </div>
            <div className="text-center p-3 rounded-xl bg-white/[0.02] border border-border/50">
              <p className="text-xs text-muted mb-1">Receipt Total</p>
              <p className="text-sm font-semibold text-primary">
                {formatCurrency(threeWay.receiptTotal)}
              </p>
            </div>
            <div className="text-center p-3 rounded-xl bg-white/[0.02] border border-border/50">
              <p className="text-xs text-muted mb-1">Bill Total</p>
              <p className="text-sm font-semibold text-primary">
                {formatCurrency(threeWay.billTotal)}
              </p>
            </div>
          </div>

          {/* Per-Line Comparison */}
          <div className="rounded-xl border border-border/50 overflow-hidden">
            <table className="w-full text-xs">
              <thead>
                <tr className="border-b border-border/50 bg-white/[0.02]">
                  <th className="text-left px-3 py-2 text-secondary">Item</th>
                  <th className="text-right px-3 py-2 text-secondary">PO Qty</th>
                  <th className="text-right px-3 py-2 text-secondary">Recv Qty</th>
                  <th className="text-right px-3 py-2 text-secondary">Bill Qty</th>
                  <th className="text-center px-3 py-2 text-secondary">Match</th>
                </tr>
              </thead>
              <tbody>
                {threeWay.lines.map((l, idx) => (
                  <tr
                    key={`item-${idx}`}
                    className={`border-b border-border/50 ${!l.matched ? 'bg-red-500/[0.03]' : ''}`}
                  >
                    <td className="px-3 py-2 text-primary">{l.description}</td>
                    <td className="px-3 py-2 text-right text-secondary">{l.poQty}</td>
                    <td className="px-3 py-2 text-right text-secondary">{l.receivedQty}</td>
                    <td className="px-3 py-2 text-right text-secondary">{l.billedQty}</td>
                    <td className="px-3 py-2 text-center">
                      {l.matched ? (
                        <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400 inline" />
                      ) : (
                        <AlertTriangle className="h-3.5 w-3.5 text-red-400 inline" />
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function formatCurrency(value: number): string {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(value / 100);
}

import { useState, useEffect, useRef } from 'react';
import { ArrowLeft, Plus, Trash2, Save, Send, Package, Search } from 'lucide-react';
import { apApi } from '../../../api';
import type { Supplier } from '../../../api';

interface POLineItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number;
  amount: number;
}

interface PurchaseOrderEditorProps {
  poId?: string;
  onSave: () => void;
  onCancel: () => void;
}

let lineCounter = 0;
function nextLineId() {
  return `line-${++lineCounter}-${Date.now()}`;
}

export function PurchaseOrderEditor({ poId, onSave, onCancel }: PurchaseOrderEditorProps) {
  const [loading, setLoading] = useState(!!poId);
  const [saving, setSaving] = useState(false);
  const [sending, setSending] = useState(false);
  const [poNumber, setPONumber] = useState('');
  const [supplierId, setSupplierId] = useState('');
  const [supplierSearch, setSupplierSearch] = useState('');
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [showSupplierDropdown, setShowSupplierDropdown] = useState(false);
  const [expectedDate, setExpectedDate] = useState('');
  const [notes, setNotes] = useState('');
  const [lineItems, setLineItems] = useState<POLineItem[]>([
    { id: nextLineId(), description: '', quantity: 1, unitPrice: 0, amount: 0 },
  ]);
  const [status, setStatus] = useState<string>('draft');
  const [error, setError] = useState('');
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (poId) {
      loadPO();
    }
  }, [poId]);

  useEffect(() => {
    const timer = setTimeout(() => {
      if (supplierSearch.length >= 2) {
        loadSuppliers(supplierSearch);
      }
    }, 300);
    return () => clearTimeout(timer);
  }, [supplierSearch]);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target as Node)) {
        setShowSupplierDropdown(false);
      }
    }
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const loadPO = async () => {
    try {
      const po = await apApi.fetchPurchaseOrder(poId!);
      setPONumber(po.poNumber);
      setSupplierId(po.supplierId);
      setSupplierSearch(po.supplierName ?? '');
      setExpectedDate(po.expectedDate ?? '');
      setNotes(po.notes ?? '');
      setStatus(po.status);
      if (po.lineItems?.length) {
        setLineItems(
          po.lineItems.map((li: { id?: string; description: string; quantity: number; unitPrice: number }) => ({
            id: li.id ?? nextLineId(),
            description: li.description,
            quantity: li.quantity,
            unitPrice: li.unitPrice,
            amount: li.quantity * li.unitPrice,
          })),
        );
      }
    } catch (e) {
      console.error('Failed to load PO', e);
      setError('Failed to load purchase order');
    } finally {
      setLoading(false);
    }
  };

  const loadSuppliers = async (search: string) => {
    try {
      const result = await apApi.fetchSuppliers({ search, limit: 10, isActive: true });
      setSuppliers(result.suppliers);
      setShowSupplierDropdown(true);
    } catch {
      // ignore
    }
  };

  const selectSupplier = (s: Supplier) => {
    setSupplierId(s.id);
    setSupplierSearch(s.businessName);
    setShowSupplierDropdown(false);
  };

  const updateLine = (id: string, field: keyof POLineItem, value: string | number) => {
    setLineItems((prev) =>
      prev.map((li) => {
        if (li.id !== id) return li;
        const updated = { ...li, [field]: value };
        updated.amount = updated.quantity * updated.unitPrice;
        return updated;
      }),
    );
  };

  const addLine = () => {
    setLineItems((prev) => [
      ...prev,
      { id: nextLineId(), description: '', quantity: 1, unitPrice: 0, amount: 0 },
    ]);
  };

  const removeLine = (id: string) => {
    if (lineItems.length <= 1) return;
    setLineItems((prev) => prev.filter((li) => li.id !== id));
  };

  const subtotal = lineItems.reduce((sum, li) => sum + li.amount, 0);
  const gst = Math.round(subtotal * 0.1 * 100) / 100;
  const total = subtotal + gst;
  const isEditable = !poId || status === 'draft';

  const handleSave = async (sendAfter = false) => {
    if (!supplierId) {
      setError('Please select a supplier');
      return;
    }
    if (lineItems.every((li) => !li.description.trim())) {
      setError('Add at least one line item');
      return;
    }

    setError('');
    sendAfter ? setSending(true) : setSaving(true);

    try {
      const payload = {
        supplierId,
        expectedDate: expectedDate || undefined,
        notes: notes || undefined,
        lineItems: lineItems
          .filter((li) => li.description.trim())
          .map((li) => ({
            description: li.description,
            quantity: li.quantity,
            unitPrice: li.unitPrice,
            amount: li.quantity * li.unitPrice,
          })),
      };

      if (poId) {
        await apApi.updatePurchaseOrder(poId, payload);
        if (sendAfter) await apApi.sendPurchaseOrder(poId);
      } else {
        const result = await apApi.createPurchaseOrder(payload);
        if (sendAfter) await apApi.sendPurchaseOrder(result.id);
      }
      onSave();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to save purchase order');
    } finally {
      setSaving(false);
      setSending(false);
    }
  };

  if (loading) {
    return (
      <div className="neu-raised rounded-2xl p-8 animate-pulse">
        <div className="h-6 w-48 bg-overlay rounded mb-6" />
        <div className="space-y-4">
          <div className="h-10 w-full bg-overlay rounded" />
          <div className="h-10 w-full bg-overlay rounded" />
          <div className="h-40 w-full bg-overlay rounded" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
      {/* Header */}
      <div className="flex items-center gap-4">
        <button
          onClick={onCancel}
          className="p-2 rounded-xl bg-overlay text-secondary hover:text-primary transition-all"
        >
          <ArrowLeft className="h-4 w-4" />
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-bold text-primary">
            {poId ? `Edit PO ${poNumber}` : 'New Purchase Order'}
          </h2>
          {poNumber && <p className="text-xs text-muted mt-0.5 font-mono">{poNumber}</p>}
        </div>
        {!isEditable && (
          <span className="px-3 py-1 rounded-full text-xs font-medium bg-blue-400/10 text-blue-400">
            {status}
          </span>
        )}
      </div>

      {error && (
        <div className="p-3 rounded-xl bg-red-500/10 border border-red-500/20 text-red-400 text-sm">
          {error}
        </div>
      )}

      {/* Form */}
      <div className="neu-raised rounded-2xl p-6 space-y-5">
        {/* Supplier + Expected Date Row */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div className="relative" ref={dropdownRef}>
            <label htmlFor="purcha-f1" className="block text-xs font-medium text-secondary mb-1.5">Supplier *</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted" />
              <input id="purcha-f1"
                type="text"
                value={supplierSearch}
                onChange={(e) => {
                  setSupplierSearch(e.target.value);
                  setSupplierId('');
                }}
                disabled={!isEditable}
                placeholder="Search supplier..."
                className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all disabled:opacity-50"
              />
            </div>
            {showSupplierDropdown && suppliers.length > 0 && (
              <div className="absolute z-20 mt-1 w-full rounded-xl bg-zinc-800 border border-border shadow-xl max-h-48 overflow-y-auto">
                {suppliers.map((s) => (
                  <button
                    key={s.id}
                    onClick={() => selectSupplier(s)}
                    className="w-full text-left px-4 py-2.5 text-sm text-primary hover:bg-overlay transition-colors first:rounded-t-xl last:rounded-b-xl"
                  >
                    <span className="font-medium">{s.businessName}</span>
                    {s.abn && <span className="text-muted ml-2 text-xs">ABN: {s.abn}</span>}
                  </button>
                ))}
              </div>
            )}
          </div>

          <div>
            <label htmlFor="purcha-f2" className="block text-xs font-medium text-secondary mb-1.5">
              Expected Delivery Date
            </label>
            <input id="purcha-f2"
              type="date"
              value={expectedDate}
              onChange={(e) => setExpectedDate(e.target.value)}
              disabled={!isEditable}
              className="w-full px-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all disabled:opacity-50"
            />
          </div>
        </div>

        {/* Line Items */}
        <div>
          <div className="flex items-center justify-between mb-3">
            <label htmlFor="purcha-f3" className="text-xs font-medium text-secondary uppercase tracking-wider">
              Line Items
            </label>
            {isEditable && (
              <button
                onClick={addLine}
                className="flex items-center gap-1 text-xs text-cba-gold hover:text-cba-gold/80 transition-colors"
              >
                <Plus className="h-3.5 w-3.5" />
                Add Row
              </button>
            )}
          </div>

          <div className="rounded-xl border border-border/50 overflow-hidden">
            <table className="w-full">
              <thead>
                <tr className="border-b border-border/50 bg-white/[0.02]">
                  <th className="text-left px-3 py-2 text-xs font-semibold text-secondary w-[45%]">
                    Description
                  </th>
                  <th className="text-right px-3 py-2 text-xs font-semibold text-secondary w-[15%]">
                    Qty
                  </th>
                  <th className="text-right px-3 py-2 text-xs font-semibold text-secondary w-[18%]">
                    Unit Price
                  </th>
                  <th className="text-right px-3 py-2 text-xs font-semibold text-secondary w-[17%]">
                    Amount
                  </th>
                  <th className="w-[5%]" />
                </tr>
              </thead>
              <tbody>
                {lineItems.map((li) => (
                  <tr key={li.id} className="border-b border-border/50">
                    <td className="px-2 py-1.5">
                      <input
                        type="text"
                        value={li.description}
                        onChange={(e) => updateLine(li.id, 'description', e.target.value)}
                        disabled={!isEditable}
                        placeholder="Item description"
                        className="w-full px-2 py-1.5 rounded-lg bg-transparent border border-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none focus:border-cba-gold/20 transition-all disabled:opacity-50"
                      />
                    </td>
                    <td className="px-2 py-1.5">
                      <input
                        type="number"
                        min={0}
                        step={1}
                        value={li.quantity}
                        onChange={(e) => updateLine(li.id, 'quantity', Number(e.target.value))}
                        disabled={!isEditable}
                        className="w-full px-2 py-1.5 rounded-lg bg-transparent border border-transparent text-sm text-primary text-right focus:outline-none focus:border-cba-gold/20 transition-all disabled:opacity-50"
                      />
                    </td>
                    <td className="px-2 py-1.5">
                      <input
                        type="number"
                        min={0}
                        step={0.01}
                        value={li.unitPrice}
                        onChange={(e) => updateLine(li.id, 'unitPrice', Number(e.target.value))}
                        disabled={!isEditable}
                        className="w-full px-2 py-1.5 rounded-lg bg-transparent border border-transparent text-sm text-primary text-right focus:outline-none focus:border-cba-gold/20 transition-all disabled:opacity-50"
                      />
                    </td>
                    <td className="px-3 py-1.5 text-right text-sm font-medium text-primary">
                      {formatCurrency(li.amount)}
                    </td>
                    <td className="px-1 py-1.5">
                      {isEditable && lineItems.length > 1 && (
                        <button
                          onClick={() => removeLine(li.id)}
                          className="p-1 rounded-lg text-zinc-600 hover:text-red-400 transition-colors"
                        >
                          <Trash2 className="h-3.5 w-3.5" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* Totals */}
        <div className="flex justify-end">
          <div className="w-64 space-y-2">
            <div className="flex justify-between text-sm">
              <span className="text-secondary">Subtotal</span>
              <span className="text-primary font-medium">{formatCurrency(subtotal)}</span>
            </div>
            <div className="flex justify-between text-sm">
              <span className="text-secondary">GST (10%)</span>
              <span className="text-primary font-medium">{formatCurrency(gst)}</span>
            </div>
            <div className="flex justify-between text-sm border-t border-border pt-2">
              <span className="text-primary font-semibold">Total</span>
              <span className="text-cba-gold font-bold text-lg">{formatCurrency(total)}</span>
            </div>
          </div>
        </div>

        {/* Notes */}
        <div>
          <label htmlFor="purcha-f4" className="block text-xs font-medium text-secondary mb-1.5">Notes</label>
          <textarea id="purcha-f4"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            disabled={!isEditable}
            rows={3}
            placeholder="Internal notes..."
            className="w-full px-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all resize-none disabled:opacity-50"
          />
        </div>
      </div>

      {/* Actions */}
      {isEditable && (
        <div className="flex justify-end gap-3">
          <button
            onClick={onCancel}
            className="px-4 py-2.5 rounded-xl bg-overlay text-secondary text-sm font-medium hover:text-primary transition-all"
          >
            Cancel
          </button>
          <button
            onClick={() => handleSave(false)}
            disabled={saving || sending}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-overlay-hover text-primary text-sm font-medium hover:bg-white/15 transition-all disabled:opacity-50"
          >
            <Save className="h-4 w-4" />
            {saving ? 'Saving...' : 'Save Draft'}
          </button>
          <button
            onClick={() => handleSave(true)}
            disabled={saving || sending}
            className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-cba-gold text-black text-sm font-semibold hover:bg-cba-gold/90 transition-all shadow-[0_0_20px_rgba(255,204,0,0.2)] disabled:opacity-50"
          >
            <Send className="h-4 w-4" />
            {sending ? 'Sending...' : 'Send to Supplier'}
          </button>
        </div>
      )}
    </div>
  );
}

function formatCurrency(value: number): string {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(value);
}

import { useState, useEffect } from 'react';
import { Search, Plus, Building2, ChevronLeft, ChevronRight } from 'lucide-react';
import { apApi } from '../../../api';
import type { Supplier } from '../../../api';

interface SupplierListProps {
  onSelect: (id: string) => void;
  onNew: () => void;
}

export function SupplierList({ onSelect, onNew }: SupplierListProps) {
  const [suppliers, setSuppliers] = useState<Supplier[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [page, setPage] = useState(1);
  const limit = 20;

  const loadSuppliers = async () => {
    setLoading(true);
    try {
      const result = await apApi.fetchSuppliers({
        page,
        limit,
        search: search || undefined,
        isActive: showArchived ? undefined : true,
      });
      setSuppliers(result.suppliers);
      setTotal(result.total);
    } catch (e) {
      console.error('Failed to fetch suppliers', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadSuppliers();
  }, [page, search, showArchived]);

  const totalPages = Math.ceil(total / limit);

  return (
    <div className="space-y-4">
      {/* Controls */}
      <div className="flex items-center gap-3">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted" />
          <input
            type="text"
            placeholder="Search name, contact, or ABN..."
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPage(1);
            }}
            className="w-full pl-10 pr-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder-zinc-500 focus:outline-none focus:border-cba-gold/30 focus:ring-1 focus:ring-[#FFCC00]/20 transition-all"
          />
        </div>

        <button
          onClick={() => {
            setShowArchived(!showArchived);
            setPage(1);
          }}
          className={`px-3 py-2.5 rounded-xl text-xs font-medium border transition-all ${
            showArchived
              ? 'bg-cba-gold/10 text-cba-gold border-cba-gold/30'
              : 'bg-overlay text-secondary border-border hover:text-primary'
          }`}
        >
          {showArchived ? 'Show All' : 'Active Only'}
        </button>

        <button
          onClick={onNew}
          className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-cba-gold text-black font-semibold text-sm hover:bg-cba-gold/90 transition-all shadow-[0_0_20px_rgba(255,204,0,0.2)]"
        >
          <Plus className="h-4 w-4" />
          New Supplier
        </button>
      </div>

      {/* Table */}
      <div className="neu-raised rounded-2xl overflow-hidden">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border/50">
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Business Name
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider hidden md:table-cell">
                Contact
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider hidden lg:table-cell">
                ABN
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider hidden md:table-cell">
                Terms
              </th>
              <th className="text-left px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Status
              </th>
              <th className="text-right px-4 py-3 text-xs font-semibold text-secondary uppercase tracking-wider">
                Outstanding
              </th>
            </tr>
          </thead>
          <tbody>
            {loading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <tr key={i} className="border-b border-border/50">
                  <td colSpan={6} className="px-4 py-4">
                    <div className="h-4 w-48 bg-overlay rounded animate-pulse" />
                  </td>
                </tr>
              ))
            ) : suppliers.length === 0 ? (
              <tr>
                <td colSpan={6} className="px-4 py-12 text-center">
                  <Building2 className="h-10 w-10 text-zinc-600 mx-auto mb-2" />
                  <p className="text-secondary text-sm">No suppliers found</p>
                </td>
              </tr>
            ) : (
              suppliers.map((s) => (
                <tr
                  key={s.id}
                  onClick={() => onSelect(s.id)}
                  className="border-b border-border/50 hover:bg-white/[0.02] cursor-pointer transition-colors"
                >
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-3">
                      <div className="h-8 w-8 rounded-lg bg-cba-gold/10 flex items-center justify-center">
                        <Building2 className="h-4 w-4 text-cba-gold" />
                      </div>
                      <span className="text-sm font-medium text-primary">{s.businessName}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-sm text-secondary hidden md:table-cell">
                    {s.contactName ?? '—'}
                  </td>
                  <td className="px-4 py-3 text-sm text-secondary font-mono hidden lg:table-cell">
                    {s.abn ? formatABN(s.abn) : '—'}
                  </td>
                  <td className="px-4 py-3 text-sm text-secondary hidden md:table-cell">
                    {s.paymentTermsDays} days
                  </td>
                  <td className="px-4 py-3">
                    <span
                      className={`inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium ${
                        s.isActive
                          ? 'bg-emerald-400/10 text-emerald-400'
                          : 'bg-zinc-400/10 text-secondary'
                      }`}
                    >
                      {s.isActive ? 'Active' : 'Archived'}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right text-sm font-medium text-primary">
                    {formatCurrency(s.outstandingAmount)}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-xs text-muted">
            Showing {(page - 1) * limit + 1}–{Math.min(page * limit, total)} of {total}
          </p>
          <div className="flex gap-1">
            <button
              onClick={() => setPage((p) => Math.max(1, p - 1))}
              disabled={page === 1}
              className="p-2 rounded-lg bg-overlay text-secondary hover:text-primary disabled:opacity-30 transition-all"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button
              onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
              disabled={page === totalPages}
              className="p-2 rounded-lg bg-overlay text-secondary hover:text-primary disabled:opacity-30 transition-all"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);
}

function formatABN(abn: string): string {
  const digits = abn.replace(/\D/g, '');
  if (digits.length === 11) {
    return `${digits.slice(0, 2)} ${digits.slice(2, 5)} ${digits.slice(5, 8)} ${digits.slice(8)}`;
  }
  return abn;
}

import { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Loader2, Trash2, AlertTriangle } from 'lucide-react';
import { assetApi } from '@/api';
import type { FixedAssetData } from '@/api';

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const DISPOSAL_METHODS = [
  { value: 'sale', label: 'Sale' },
  { value: 'scrapped', label: 'Scrapped' },
  { value: 'trade_in', label: 'Trade-In' },
  { value: 'theft', label: 'Theft / Loss' },
  { value: 'insurance_claim', label: 'Insurance Claim' },
];

interface AssetDisposalFormProps {
  assets: FixedAssetData[];
  onSuccess: () => void;
}

export function AssetDisposalForm({ assets, onSuccess }: AssetDisposalFormProps) {
  const [selectedAssetId, setSelectedAssetId] = useState('');
  const [disposalDate, setDisposalDate] = useState('');
  const [disposalMethod, setDisposalMethod] = useState('');
  const [proceeds, setProceeds] = useState('');
  const [buyerDetails, setBuyerDetails] = useState('');
  const [invoiceRef, setInvoiceRef] = useState('');
  const [notes, setNotes] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const activeAssets = useMemo(() => assets.filter((a) => a.status === 'active'), [assets]);
  const selectedAsset = useMemo(
    () => activeAssets.find((a) => a.id === selectedAssetId),
    [activeAssets, selectedAssetId],
  );

  const proceedsCents = Math.round((parseFloat(proceeds) || 0) * 100);
  const wdvAtDisposal = selectedAsset?.currentWrittenDownValue ?? 0;
  const gainLoss = proceedsCents - wdvAtDisposal;
  const isCgtApplicable = gainLoss > 0 && selectedAsset && selectedAsset.purchasePrice >= 1000000;

  const handleSubmit = async () => {
    if (!selectedAssetId || !disposalDate || !disposalMethod) return;
    setSubmitting(true);
    setError(null);
    try {
      await assetApi.disposeAsset(selectedAssetId, {
        disposalDate,
        disposalMethod,
        proceedsCents,
        buyerDetails: buyerDetails || undefined,
        invoiceReference: invoiceRef || undefined,
        notes: notes || undefined,
      });
      setSelectedAssetId('');
      setDisposalDate('');
      setDisposalMethod('');
      setProceeds('');
      setBuyerDetails('');
      setInvoiceRef('');
      setNotes('');
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to dispose asset');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Card className="neu-raised border-border/50">
      <CardHeader>
        <CardTitle className="text-lg font-bold text-zinc-100 flex items-center gap-2">
          <Trash2 className="w-5 h-5 text-red-400" />
          Record Asset Disposal
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        {activeAssets.length === 0 ? (
          <p className="text-muted text-center py-8">No active assets available for disposal</p>
        ) : (
          <>
            <div className="grid gap-4 md:grid-cols-2">
              <div className="space-y-2">
                <Label>Select Asset</Label>
                <Select value={selectedAssetId} onValueChange={setSelectedAssetId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Choose asset to dispose..." />
                  </SelectTrigger>
                  <SelectContent>
                    {activeAssets.map((a) => (
                      <SelectItem key={a.id} value={a.id}>
                        {a.assetNumber} — {a.assetName}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Disposal Date</Label>
                <Input
                  type="date"
                  value={disposalDate}
                  onChange={(e) => setDisposalDate(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Disposal Method</Label>
                <Select value={disposalMethod} onValueChange={setDisposalMethod}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select method..." />
                  </SelectTrigger>
                  <SelectContent>
                    {DISPOSAL_METHODS.map((m) => (
                      <SelectItem key={m.value} value={m.value}>
                        {m.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-2">
                <Label>Disposal Proceeds ($)</Label>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  placeholder="0.00"
                  value={proceeds}
                  onChange={(e) => setProceeds(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Buyer Details</Label>
                <Input
                  placeholder="Optional"
                  value={buyerDetails}
                  onChange={(e) => setBuyerDetails(e.target.value)}
                />
              </div>
              <div className="space-y-2">
                <Label>Invoice Reference</Label>
                <Input
                  placeholder="Optional"
                  value={invoiceRef}
                  onChange={(e) => setInvoiceRef(e.target.value)}
                />
              </div>
            </div>
            <div className="space-y-2">
              <Label>Notes</Label>
              <Input
                placeholder="Additional notes..."
                value={notes}
                onChange={(e) => setNotes(e.target.value)}
              />
            </div>

            {selectedAsset && (
              <div className="neu-inset rounded-xl p-4 space-y-3">
                <p className="text-sm font-bold text-primary">Disposal Summary</p>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                  <div>
                    <p className="text-muted text-xs">Purchase Price</p>
                    <p className="font-mono text-primary">
                      {formatCurrency(selectedAsset.purchasePrice)}
                    </p>
                  </div>
                  <div>
                    <p className="text-muted text-xs">WDV at Disposal</p>
                    <p className="font-mono text-cba-gold">{formatCurrency(wdvAtDisposal)}</p>
                  </div>
                  <div>
                    <p className="text-muted text-xs">Proceeds</p>
                    <p className="font-mono text-primary">{formatCurrency(proceedsCents)}</p>
                  </div>
                  <div>
                    <p className="text-muted text-xs">
                      {gainLoss >= 0 ? 'Profit' : 'Loss'} on Disposal
                    </p>
                    <p
                      className={`font-mono font-bold ${gainLoss >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                    >
                      {gainLoss >= 0 ? '+' : ''}
                      {formatCurrency(gainLoss)}
                    </p>
                  </div>
                </div>
                {isCgtApplicable && (
                  <div className="flex items-center gap-2 mt-2">
                    <AlertTriangle className="w-4 h-4 text-amber-400" />
                    <span className="text-xs text-amber-400">
                      CGT may apply — original cost exceeds $10,000
                    </span>
                  </div>
                )}
              </div>
            )}

            {error && <p className="text-red-400 text-sm">{error}</p>}

            <Button
              onClick={handleSubmit}
              disabled={submitting || !selectedAssetId || !disposalDate || !disposalMethod}
              className="bg-red-500/80 hover:bg-red-500 text-primary font-bold"
            >
              {submitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
              Confirm Disposal
            </Button>
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Search, ChevronUp, ChevronDown, Trash2, Calculator, Edit } from 'lucide-react';
import type { FixedAssetData } from '@/api';

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const STATUS_COLORS: Record<string, string> = {
  active: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  disposed: 'bg-red-500/20 text-red-400 border-red-500/30',
  fully_depreciated: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
  written_off: 'bg-zinc-500/20 text-secondary border-zinc-500/30',
};

const CATEGORY_COLORS: Record<string, string> = {
  'Motor Vehicles': 'bg-blue-500/20 text-blue-400',
  'Plant & Equipment': 'bg-purple-500/20 text-purple-400',
  'Office Equipment': 'bg-cyan-500/20 text-cyan-400',
  'Furniture & Fittings': 'bg-orange-500/20 text-orange-400',
  'Computer Equipment': 'bg-indigo-500/20 text-indigo-400',
  'Building Improvements': 'bg-teal-500/20 text-teal-400',
  'Low Value Pool': 'bg-pink-500/20 text-pink-400',
  Software: 'bg-violet-500/20 text-violet-400',
  Tooling: 'bg-yellow-500/20 text-yellow-400',
  Other: 'bg-zinc-500/20 text-secondary',
};

type SortKey =
  | 'assetNumber'
  | 'assetName'
  | 'category'
  | 'purchaseDate'
  | 'purchasePrice'
  | 'currentWrittenDownValue'
  | 'status';

interface AssetRegisterTableProps {
  assets: FixedAssetData[];
  onDispose?: (asset: FixedAssetData) => void;
  onEdit?: (asset: FixedAssetData) => void;
}

function SortIcon({ col, sortKey, sortDir }: { col: SortKey; sortKey: SortKey; sortDir: 'asc' | 'desc' }) {
  if (sortKey !== col) return null;
  return sortDir === 'asc' ? (
    <ChevronUp className="w-3 h-3 inline ml-1" />
  ) : (
    <ChevronDown className="w-3 h-3 inline ml-1" />
  );
}

export function AssetRegisterTable({ assets, onDispose, onEdit }: AssetRegisterTableProps) {
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState<string>('all');
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [sortKey, setSortKey] = useState<SortKey>('assetNumber');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');
  const [expandedId, setExpandedId] = useState<string | null>(null);

  const categories = useMemo(() => {
    const cats = new Set(assets.map((a) => a.category));
    return Array.from(cats).sort();
  }, [assets]);

  const filtered = useMemo(() => {
    let result = [...assets];

    if (search) {
      const q = search.toLowerCase();
      result = result.filter(
        (a) =>
          a.assetName.toLowerCase().includes(q) ||
          a.assetNumber.toLowerCase().includes(q) ||
          a.supplier?.toLowerCase().includes(q),
      );
    }

    if (categoryFilter !== 'all') {
      result = result.filter((a) => a.category === categoryFilter);
    }

    if (statusFilter !== 'all') {
      result = result.filter((a) => a.status === statusFilter);
    }

    result.sort((a, b) => {
      let cmp = 0;
      const aVal = a[sortKey];
      const bVal = b[sortKey];
      if (typeof aVal === 'string' && typeof bVal === 'string') {
        cmp = aVal.localeCompare(bVal);
      } else if (typeof aVal === 'number' && typeof bVal === 'number') {
        cmp = aVal - bVal;
      }
      return sortDir === 'asc' ? cmp : -cmp;
    });

    return result;
  }, [assets, search, categoryFilter, statusFilter, sortKey, sortDir]);

  const handleSort = (key: SortKey) => {
    if (sortKey === key) {
      setSortDir((d) => (d === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  return (
    <Card className="neu-raised border-border/50">
      <CardHeader>
        <CardTitle className="text-lg font-bold text-zinc-100">Asset Register</CardTitle>
        <div className="flex flex-wrap gap-3 mt-3">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted" />
            <Input
              placeholder="Search assets..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9"
            />
          </div>
          <Select value={categoryFilter} onValueChange={setCategoryFilter}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="Category" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Categories</SelectItem>
              {categories.map((c) => (
                <SelectItem key={c} value={c}>
                  {c}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-[160px]">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="active">Active</SelectItem>
              <SelectItem value="disposed">Disposed</SelectItem>
              <SelectItem value="fully_depreciated">Fully Depreciated</SelectItem>
              <SelectItem value="written_off">Written Off</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </CardHeader>
      <CardContent>
        {filtered.length === 0 ? (
          <p className="text-muted text-center py-8">No assets found</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border text-muted text-xs uppercase tracking-wider">
                  <th
                    className="text-left py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('assetNumber')}
                  >
                    Asset # <SortIcon col="assetNumber" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th
                    className="text-left py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('assetName')}
                  >
                    Name <SortIcon col="assetName" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th
                    className="text-left py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('category')}
                  >
                    Category <SortIcon col="category" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th
                    className="text-left py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('purchaseDate')}
                  >
                    Purchase <SortIcon col="purchaseDate" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th
                    className="text-right py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('purchasePrice')}
                  >
                    Cost <SortIcon col="purchasePrice" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th
                    className="text-right py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('currentWrittenDownValue')}
                  >
                    WDV <SortIcon col="currentWrittenDownValue" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th
                    className="text-left py-3 px-2 cursor-pointer hover:text-primary"
                    onClick={() => handleSort('status')}
                  >
                    Status <SortIcon col="status" sortKey={sortKey} sortDir={sortDir} />
                  </th>
                  <th className="text-right py-3 px-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((asset) => (
                  <>
                    <tr
                      key={asset.id}
                      className="border-b border-border/50 hover:bg-white/[0.02] transition-colors cursor-pointer"
                      onClick={() => setExpandedId(expandedId === asset.id ? null : asset.id)}
                    >
                      <td className="py-3 px-2 font-mono text-secondary">{asset.assetNumber}</td>
                      <td className="py-3 px-2 font-medium text-zinc-100">{asset.assetName}</td>
                      <td className="py-3 px-2">
                        <Badge
                          variant="outline"
                          className={CATEGORY_COLORS[asset.category] ?? CATEGORY_COLORS['Other']}
                        >
                          {asset.category}
                        </Badge>
                      </td>
                      <td className="py-3 px-2 text-secondary">{asset.purchaseDate}</td>
                      <td className="py-3 px-2 text-right font-mono text-primary">
                        {formatCurrency(asset.purchasePrice)}
                      </td>
                      <td className="py-3 px-2 text-right font-mono text-cba-gold">
                        {formatCurrency(asset.currentWrittenDownValue)}
                      </td>
                      <td className="py-3 px-2">
                        <Badge variant="outline" className={STATUS_COLORS[asset.status] ?? ''}>
                          {asset.status.replace('_', ' ')}
                        </Badge>
                      </td>
                      <td className="py-3 px-2 text-right">
                        <div
                          className="flex justify-end gap-1"
                          role="presentation"
                          onClick={(e) => e.stopPropagation()}
                        >
                          {onEdit && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-7 w-7 p-0 text-muted hover:text-cba-gold"
                              onClick={() => onEdit(asset)}
                            >
                              <Edit className="w-3.5 h-3.5" />
                            </Button>
                          )}
                          {onDispose && asset.status === 'active' && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-7 w-7 p-0 text-muted hover:text-red-400"
                              onClick={() => onDispose(asset)}
                            >
                              <Trash2 className="w-3.5 h-3.5" />
                            </Button>
                          )}
                        </div>
                      </td>
                    </tr>
                    {expandedId === asset.id && (
                      <tr key={`${asset.id}-detail`} className="bg-white/[0.01]">
                        <td colSpan={8} className="p-4">
                          <div className="grid grid-cols-2 md:grid-cols-4 gap-4 text-sm">
                            <div>
                              <p className="text-muted text-xs">Method</p>
                              <p className="text-primary font-medium">
                                {asset.depreciationMethod}
                              </p>
                            </div>
                            <div>
                              <p className="text-muted text-xs">Effective Life</p>
                              <p className="text-primary font-medium">
                                {asset.effectiveLifeYears} years
                              </p>
                            </div>
                            <div>
                              <p className="text-muted text-xs">Residual Value</p>
                              <p className="text-primary font-medium">
                                {formatCurrency(asset.residualValue)}
                              </p>
                            </div>
                            {asset.location && (
                              <div>
                                <p className="text-muted text-xs">Location</p>
                                <p className="text-primary font-medium">{asset.location}</p>
                              </div>
                            )}
                            {asset.serialNumber && (
                              <div>
                                <p className="text-muted text-xs">Serial Number</p>
                                <p className="text-primary font-medium">{asset.serialNumber}</p>
                              </div>
                            )}
                            {asset.supplier && (
                              <div>
                                <p className="text-muted text-xs">Supplier</p>
                                <p className="text-primary font-medium">{asset.supplier}</p>
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    )}
                  </>
                ))}
              </tbody>
            </table>
          </div>
        )}
        <div className="mt-3 text-xs text-zinc-600 text-right">
          {filtered.length} of {assets.length} assets shown
        </div>
      </CardContent>
    </Card>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import { Loader2, Plus, Lightbulb } from 'lucide-react';
import { assetApi } from '@/api';
import { toast } from 'sonner';

const ASSET_CATEGORIES = [
  { value: 'Motor Vehicles', life: 8 },
  { value: 'Plant & Equipment', life: 15 },
  { value: 'Office Equipment', life: 10 },
  { value: 'Furniture & Fittings', life: 13 },
  { value: 'Computer Equipment', life: 4 },
  { value: 'Building Improvements', life: 40 },
  { value: 'Low Value Pool', life: 0 },
  { value: 'Software', life: 5 },
  { value: 'Tooling', life: 5 },
  { value: 'Other', life: 10 },
];

const DEPRECIATION_METHODS = [
  { value: 'diminishing_value', label: 'Diminishing Value' },
  { value: 'prime_cost', label: 'Prime Cost (Straight Line)' },
  { value: 'instant_write_off', label: 'Instant Asset Write-Off' },
  { value: 'low_value_pool', label: 'Low Value Pool' },
];

const INSTANT_WRITE_OFF_THRESHOLD = 2000000; // $20,000 in cents

interface RegisterAssetFormProps {
  onSuccess: () => void;
}

export function RegisterAssetForm({ onSuccess }: RegisterAssetFormProps) {
  const [assetName, setAssetName] = useState('');
  const [category, setCategory] = useState('');
  const [purchaseDate, setPurchaseDate] = useState('');
  const [purchasePrice, setPurchasePrice] = useState('');
  const [residualValue, setResidualValue] = useState('0');
  const [depreciationMethod, setDepreciationMethod] = useState('diminishing_value');
  const [effectiveLife, setEffectiveLife] = useState('');
  const [location, setLocation] = useState('');
  const [serialNumber, setSerialNumber] = useState('');
  const [supplier, setSupplier] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const priceCents = Math.round((parseFloat(purchasePrice) || 0) * 100);
  const isWriteOffEligible = priceCents > 0 && priceCents < INSTANT_WRITE_OFF_THRESHOLD;

  const handleCategoryChange = (val: string) => {
    setCategory(val);
    const catDef = ASSET_CATEGORIES.find((c) => c.value === val);
    if (catDef && catDef.life > 0) {
      setEffectiveLife(String(catDef.life));
    }
    if (val === 'Low Value Pool') {
      setDepreciationMethod('low_value_pool');
    }
  };

  const handleSubmit = async () => {
    if (!assetName || !category || !purchaseDate || !purchasePrice) return;

    const today = new Date().toISOString().split('T')[0];
    if (purchaseDate > today) {
      setError('Purchase date cannot be in the future');
      return;
    }

    if (priceCents <= 0) {
      setError('Purchase price must be positive');
      return;
    }

    setSubmitting(true);
    setError(null);
    try {
      await assetApi.registerAsset({
        assetName,
        category,
        purchaseDate,
        purchasePrice: priceCents,
        residualValue: Math.round((parseFloat(residualValue) || 0) * 100),
        depreciationMethod,
        effectiveLifeYears: parseFloat(effectiveLife) || 10,
        location: location || undefined,
        serialNumber: serialNumber || undefined,
        supplier: supplier || undefined,
      });
      toast.success('Asset registered successfully');
      setAssetName('');
      setCategory('');
      setPurchaseDate('');
      setPurchasePrice('');
      setResidualValue('0');
      setDepreciationMethod('diminishing_value');
      setEffectiveLife('');
      setLocation('');
      setSerialNumber('');
      setSupplier('');
      onSuccess();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to register asset');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Card className="neu-raised border-border/50">
      <CardHeader>
        <CardTitle className="text-lg font-bold text-zinc-100 flex items-center gap-2">
          <Plus className="w-5 h-5 text-cba-gold" />
          Register New Asset
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-6">
        <div className="grid gap-4 md:grid-cols-2">
          <div className="space-y-2">
            <Label>Asset Name *</Label>
            <Input
              placeholder="e.g., MacBook Pro 16-inch"
              value={assetName}
              onChange={(e) => setAssetName(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Category *</Label>
            <Select value={category} onValueChange={handleCategoryChange}>
              <SelectTrigger>
                <SelectValue placeholder="Select category..." />
              </SelectTrigger>
              <SelectContent>
                {ASSET_CATEGORIES.map((c) => (
                  <SelectItem key={c.value} value={c.value}>
                    {c.value} {c.life > 0 ? `(${c.life}y)` : ''}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Purchase Date *</Label>
            <Input
              type="date"
              value={purchaseDate}
              onChange={(e) => setPurchaseDate(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Purchase Price ($) *</Label>
            <Input
              type="number"
              min="0"
              step="0.01"
              placeholder="0.00"
              value={purchasePrice}
              onChange={(e) => setPurchasePrice(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Residual Value ($)</Label>
            <Input
              type="number"
              min="0"
              step="0.01"
              placeholder="0.00"
              value={residualValue}
              onChange={(e) => setResidualValue(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Depreciation Method</Label>
            <Select value={depreciationMethod} onValueChange={setDepreciationMethod}>
              <SelectTrigger>
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {DEPRECIATION_METHODS.map((m) => (
                  <SelectItem key={m.value} value={m.value}>
                    {m.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
          <div className="space-y-2">
            <Label>Effective Life (years)</Label>
            <Input
              type="number"
              min="1"
              max="100"
              placeholder="e.g., 10"
              value={effectiveLife}
              onChange={(e) => setEffectiveLife(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Location</Label>
            <Input
              placeholder="Optional"
              value={location}
              onChange={(e) => setLocation(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Serial Number</Label>
            <Input
              placeholder="Optional"
              value={serialNumber}
              onChange={(e) => setSerialNumber(e.target.value)}
            />
          </div>
          <div className="space-y-2">
            <Label>Supplier</Label>
            <Input
              placeholder="Optional"
              value={supplier}
              onChange={(e) => setSupplier(e.target.value)}
            />
          </div>
        </div>

        {isWriteOffEligible && (
          <div className="neu-inset rounded-xl p-4 flex items-start gap-3">
            <Lightbulb className="w-5 h-5 text-cba-gold shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-bold text-cba-gold">Instant Write-Off Eligible</p>
              <p className="text-xs text-secondary mt-1">
                This asset costs under $20,000 and may be eligible for the instant asset write-off
                under the ATO small business rules. Consider selecting "Instant Asset Write-Off" as
                the depreciation method.
              </p>
            </div>
          </div>
        )}

        {category === 'Low Value Pool' && (
          <div className="neu-inset rounded-xl p-4 flex items-start gap-3">
            <Lightbulb className="w-5 h-5 text-blue-400 shrink-0 mt-0.5" />
            <div>
              <p className="text-sm font-bold text-blue-400">Low Value Pool</p>
              <p className="text-xs text-secondary mt-1">
                Assets under $1,000 (or with WDV under $1,000) can be allocated to the low value
                pool. Depreciation rate: 37.5% first year, 30% subsequent years.
              </p>
            </div>
          </div>
        )}

        {error && <p className="text-red-400 text-sm">{error}</p>}

        <Button
          onClick={handleSubmit}
          disabled={submitting || !assetName || !category || !purchaseDate || !purchasePrice}
          className="bg-cba-gold text-base hover:bg-cba-gold/90 font-bold"
        >
          {submitting && <Loader2 className="w-4 h-4 mr-2 animate-spin" />}
          Register Asset
        </Button>
      </CardContent>
    </Card>
  );
}

