import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { formatCurrency } from '@/lib/format';
import { Loader2, TrendingUp, TrendingDown, Minus } from 'lucide-react';
import { gstApi } from '@/api';
import type { BASComparisonData } from '@/features/gst/types';

const BAS_LABELS: Record<string, string> = {
  G1: 'Total Sales',
  G2: 'Export Sales',
  G3: 'GST-Free Sales',
  G4: 'Input Taxed Sales',
  G9: 'GST on Sales',
  G10: 'Capital Purchases',
  G11: 'Non-Capital Purchases',
  G19: 'GST Credits',
  G20: 'Net GST',
  '1A': 'GST on Sales',
  '1B': 'GST on Purchases',
  W1: 'Gross Wages',
  W2: 'Amounts Withheld',
};

const generateQuarters = (): { value: string; label: string }[] => {
  const options = [];
  const currentYear = new Date().getFullYear();
  for (let year = currentYear; year >= currentYear - 4; year--) {
    for (let q = 4; q >= 1; q--) {
      options.push({
        value: `${year}-Q${q}`,
        label: `Q${q} FY ${year}-${(year + 1).toString().slice(2)}`,
      });
    }
  }
  return options;
};

function VarianceCell({ change, variance }: { change: number; variance: number }) {
  const absVariance = Math.abs(variance);
  let color = 'text-primary';
  if (absVariance > 50) color = 'text-red-400';
  else if (absVariance > 20) color = 'text-amber-400';

  return (
    <div className="flex items-center gap-1.5 justify-end">
      {change > 0 ? (
        <TrendingUp className={`w-3 h-3 ${color}`} />
      ) : change < 0 ? (
        <TrendingDown className={`w-3 h-3 ${color}`} />
      ) : (
        <Minus className="w-3 h-3 text-zinc-600" />
      )}
      <span className={`text-xs font-medium ${color}`}>
        {variance === 0 ? '-' : `${variance > 0 ? '+' : ''}${variance.toFixed(1)}%`}
      </span>
    </div>
  );
}

export function BASComparison() {
  const [quarterA, setQuarterA] = useState('');
  const [quarterB, setQuarterB] = useState('');
  const [data, setData] = useState<BASComparisonData | null>(null);
  const [loading, setLoading] = useState(false);
  const quarters = generateQuarters();

  useEffect(() => {
    const first = quarters[0];
    const second = quarters[1];
    if (first && second) {
      setQuarterA(first.value);
      setQuarterB(second.value);
    }
  }, []);

  useEffect(() => {
    if (quarterA && quarterB && quarterA !== quarterB) {
      loadComparison();
    }
  }, [quarterA, quarterB]);

  const loadComparison = async () => {
    setLoading(true);
    try {
      const result = await gstApi.fetchBASComparison(quarterA, quarterB);
      setData(result);
    } catch (err) {
      console.error('Failed to load comparison:', err);
    } finally {
      setLoading(false);
    }
  };

  const getVariance = (a: number, b: number): { change: number; variance: number } => {
    const change = a - b;
    const variance = b === 0 ? (a === 0 ? 0 : 100) : ((a - b) / Math.abs(b)) * 100;
    return { change, variance };
  };

  const allLabels = data
    ? Array.from(
      new Set([...Object.keys(data.periodA.labels), ...Object.keys(data.periodB.labels)]),
    ).sort()
    : [];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold">BAS Comparison</h3>
      </div>

      <div className="flex items-center gap-3 flex-wrap">
        <Select value={quarterA} onValueChange={setQuarterA}>
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Period A" />
          </SelectTrigger>
          <SelectContent>
            {quarters.map((q) => (
              <SelectItem key={q.value} value={q.value}>
                {q.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        <span className="text-muted text-sm">vs</span>

        <Select value={quarterB} onValueChange={setQuarterB}>
          <SelectTrigger className="w-[180px]">
            <SelectValue placeholder="Period B" />
          </SelectTrigger>
          <SelectContent>
            {quarters.map((q) => (
              <SelectItem key={q.value} value={q.value}>
                {q.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {loading ? (
        <Card className="neu-raised rounded-xl">
          <CardContent className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
          </CardContent>
        </Card>
      ) : data ? (
        <Card className="neu-raised rounded-xl">
          <CardHeader className="pb-3">
            <CardTitle className="text-sm">Label Comparison</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-0.5">
              {/* Header */}
              <div className="grid grid-cols-5 gap-2 text-xs text-muted pb-2 border-b border-border/50">
                <span>Label</span>
                <span className="text-right">{data.periodA.quarter}</span>
                <span className="text-right">{data.periodB.quarter}</span>
                <span className="text-right">Change</span>
                <span className="text-right">Variance</span>
              </div>

              {allLabels.map((label) => {
                const valA = data.periodA.labels[label] || 0;
                const valB = data.periodB.labels[label] || 0;
                const { change, variance } = getVariance(valA, valB);
                const absVariance = Math.abs(variance);

                return (
                  <div
                    key={label}
                    className={`grid grid-cols-5 gap-2 py-2 px-2 rounded-lg text-sm items-center ${absVariance > 50 ? 'bg-red-500/5' : absVariance > 20 ? 'bg-amber-500/5' : ''
                      }`}
                  >
                    <div>
                      <span className="font-mono text-xs text-cba-gold mr-2">{label}</span>
                      <span className="text-xs text-muted">{BAS_LABELS[label] || ''}</span>
                    </div>
                    <span className="text-right font-medium">{formatCurrency(valA)}</span>
                    <span className="text-right font-medium">{formatCurrency(valB)}</span>
                    <span
                      className={`text-right text-xs ${change > 0 ? 'text-emerald-400' : change < 0 ? 'text-red-400' : 'text-muted'}`}
                    >
                      {change === 0 ? '-' : formatCurrency(change)}
                    </span>
                    <VarianceCell change={change} variance={variance} />
                  </div>
                );
              })}
            </div>

            {/* Legend */}
            <div className="mt-4 pt-3 border-t border-border/50 flex items-center gap-4 text-[10px] text-zinc-600">
              <span className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-amber-500/30" /> &gt;20% variance
              </span>
              <span className="flex items-center gap-1">
                <span className="w-2 h-2 rounded-full bg-red-500/30" /> &gt;50% variance
              </span>
            </div>
          </CardContent>
        </Card>
      ) : (
        <Card className="neu-raised rounded-xl">
          <CardContent className="text-center py-12 text-muted">
            Select two periods to compare
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { basApi } from '@/api';
import type { BASCalculation, BASQuarter } from '@/types/tax';
import { getCurrentQuarter, getQuarterDates } from '../utils.js';

export interface QuarterOption {
  value: string;
  label: string;
  sublabel: string;
}

function apiQuarterToOption(fy: string, q: number): QuarterOption {
  const fyStartYear = parseInt(fy.split('-')[0], 10);
  const value = `${fyStartYear}-Q${q}`;
  const label = `Q${q} ${fy}`;
  const sublabel = getQuarterDates(fyStartYear, q as 1 | 2 | 3 | 4);
  return { value, label, sublabel };
}

export function useBASDashboard() {
  const [loading, setLoading] = useState(false);
  const [calculating, setCalculating] = useState(false);
  const [selectedQuarter, setSelectedQuarter] = useState<string>('');
  const [method, setMethod] = useState<'accrual' | 'cash'>('accrual');
  const [basData, setBASData] = useState<BASCalculation | null>(null);
  const [history, setHistory] = useState<BASQuarter[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'calculate' | 'breakdown' | 'history'>('calculate');
  const [availableQuarters, setAvailableQuarters] = useState<QuarterOption[]>([]);

  useEffect(() => {
    loadHistory();
    loadAvailableQuarters();
    const { year, quarter } = getCurrentQuarter();
    setSelectedQuarter(`${year}-Q${quarter}`);
  }, []);

  // Auto-calculate when quarter or method changes
  useEffect(() => {
    if (selectedQuarter) {
      autoCalculate();
    }
  }, [selectedQuarter, method]);

  const autoCalculate = async () => {
    if (!selectedQuarter) return;
    setCalculating(true);
    setError(null);
    try {
      const data = await basApi.calculateBAS(selectedQuarter, method);
      setBASData(data);
    } catch (err) {
      console.error('Auto-calculate BAS failed:', err);
      setError(err instanceof Error ? err.message : 'Failed to calculate BAS');
    } finally {
      setCalculating(false);
    }
  };

  const loadAvailableQuarters = async () => {
    try {
      const apiQuarters = await basApi.fetchQuarters();
      const options = apiQuarters.map((q) => apiQuarterToOption(q.financialYear, q.quarter));
      // Always include current quarter
      const { year, quarter } = getCurrentQuarter();
      const currentFy = `${year}-${(year + 1).toString().slice(2)}`;
      const currentValue = `${year}-Q${quarter}`;
      if (!options.some((o) => o.value === currentValue)) {
        options.push(apiQuarterToOption(currentFy, quarter));
      }
      // Sort descending by value (newest first)
      options.sort((a, b) => b.value.localeCompare(a.value));
      setAvailableQuarters(options);
    } catch (err) {
      console.error('Failed to load available quarters:', err);
      // Fallback: show current quarter only
      const { year, quarter } = getCurrentQuarter();
      const currentFy = `${year}-${(year + 1).toString().slice(2)}`;
      setAvailableQuarters([apiQuarterToOption(currentFy, quarter)]);
    }
  };

  const loadHistory = async () => {
    try {
      const data = await basApi.fetchHistory();
      setHistory(data);
    } catch (err) {
      console.error('Failed to load BAS history:', err);
    }
  };

  const calculateBAS = async () => {
    if (!selectedQuarter) return;
    setCalculating(true);
    setError(null);
    try {
      const data = await basApi.calculateBAS(selectedQuarter, method);
      setBASData(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to calculate BAS');
    } finally {
      setCalculating(false);
    }
  };

  const saveBAS = async () => {
    if (!selectedQuarter || !basData) return;
    setLoading(true);
    try {
      await basApi.saveBAS(selectedQuarter, basData);
      await loadHistory();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save BAS');
    } finally {
      setLoading(false);
    }
  };

  const barChartData = useMemo(() => {
    if (!basData) return null;
    const sales = basData.g1_total_sales;
    const purchases = basData.g12_g10_plus_g11;
    const max = Math.max(sales, purchases, 1);
    return { sales, purchases, max };
  }, [basData]);

  const isRefund = basData ? basData.net_amount_payable <= 0 : false;
  const netAmount = basData ? Math.abs(basData.net_amount_payable || basData.net_refund) : 0;

  return {
    loading,
    calculating,
    selectedQuarter,
    setSelectedQuarter,
    method,
    setMethod,
    basData,
    setBASData,
    history,
    error,
    activeTab,
    setActiveTab,
    calculateBAS,
    saveBAS,
    barChartData,
    isRefund,
    netAmount,
    availableQuarters,
  };
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { BASPeriodSelector } from './BASPeriodSelector';
import { formatCurrency } from '@/lib/format';
import { Loader2, ChevronRight, AlertTriangle, Save, CheckCircle, FileText } from 'lucide-react';
import { gstApi, basApi } from '@/api';
import type { BASCalculationEnhanced } from '@/features/gst/types';

type BASStatus = 'draft' | 'review' | 'ready' | 'lodged' | 'amended';

const getCurrentFinancialYear = () => {
  const now = new Date();
  return now.getMonth() >= 6 ? now.getFullYear() : now.getFullYear() - 1;
};

function LabelRow({
  label,
  description,
  amount,
  count,
}: {
  label: string;
  description: string;
  amount: number;
  count?: number;
}) {
  return (
    <div className="flex items-center justify-between py-2.5 px-3 rounded-lg hover:bg-white/[0.02] cursor-pointer group transition-colors">
      <div className="flex items-center gap-3">
        <span className="text-xs font-mono text-cba-gold w-8">{label}</span>
        <span className="text-sm text-primary">{description}</span>
        {count !== undefined && <span className="text-[10px] text-zinc-600">({count} txns)</span>}
      </div>
      <div className="flex items-center gap-2">
        <span className="text-sm font-medium">{formatCurrency(amount)}</span>
        <ChevronRight className="w-4 h-4 text-zinc-600 group-hover:text-secondary transition-colors" />
      </div>
    </div>
  );
}

const getCurrentQuarter = (): number => {
  const month = new Date().getMonth();
  if (month >= 6 && month <= 8) return 1;
  if (month >= 9 && month <= 11) return 2;
  if (month >= 0 && month <= 2) return 3;
  return 4;
};

export function BASPreFillReport() {
  const [loading, setLoading] = useState(false);
  const [basData, setBASData] = useState<BASCalculationEnhanced | null>(null);
  const [selectedYear, setSelectedYear] = useState(() => getCurrentFinancialYear());
  const [selectedQuarter, setSelectedQuarter] = useState(() => getCurrentQuarter());
  const [periodType, setPeriodType] = useState<'monthly' | 'quarterly' | 'annual'>('quarterly');
  const [basMethod, setBASMethod] = useState<'simpler' | 'full'>('simpler');
  const [status, setStatus] = useState<BASStatus>('draft');
  const [error, setError] = useState<string | null>(null);
  const [availableYears, setAvailableYears] = useState<number[]>([]);

  const quarterKey = `${selectedYear}-Q${selectedQuarter}`;

  useEffect(() => {
    loadAvailableYears();
  }, []);

  useEffect(() => {
    loadBAS();
  }, [quarterKey, basMethod]);

  const loadAvailableYears = async () => {
    try {
      const quarters = await basApi.fetchQuarters();
      const yearSet = new Set<number>();
      for (const q of quarters) {
        yearSet.add(parseInt(q.financialYear.split('-')[0], 10));
      }
      // Always include current FY
      yearSet.add(getCurrentFinancialYear());
      const sorted = Array.from(yearSet).sort((a, b) => b - a);
      setAvailableYears(sorted);
    } catch {
      // Fallback: just current year
      setAvailableYears([getCurrentFinancialYear()]);
    }
  };

  const loadBAS = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await gstApi.fetchBASCalculation(quarterKey, basMethod);
      setBASData(data);
      setStatus(data.status);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load BAS data');
    } finally {
      setLoading(false);
    }
  };

  const handleStatusChange = async (newStatus: string) => {
    const s = newStatus as BASStatus;
    setStatus(s);
    try {
      await gstApi.updateBASStatus(quarterKey, s);
    } catch (err) {
      console.error('Failed to update status:', err);
    }
  };

  const handleSaveDraft = async () => {
    if (!basData) return;
    try {
      await gstApi.saveBASdraft(quarterKey, basData);
    } catch (err) {
      console.error('Failed to save draft:', err);
    }
  };

  return (
    <div className="space-y-4">
      {/* Period Selector */}
      <BASPeriodSelector
        selectedYear={selectedYear}
        selectedQuarter={selectedQuarter}
        periodType={periodType}
        onYearChange={setSelectedYear}
        onQuarterChange={setSelectedQuarter}
        onPeriodTypeChange={setPeriodType}
        availableYears={availableYears.length > 0 ? availableYears : undefined}
      />

      {/* BAS Method & Status */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <Tabs value={basMethod} onValueChange={(v) => setBASMethod(v as 'simpler' | 'full')}>
          <TabsList>
            <TabsTrigger value="simpler">Simpler BAS</TabsTrigger>
            <TabsTrigger value="full">Full BAS</TabsTrigger>
          </TabsList>
        </Tabs>

        <div className="flex items-center gap-2">
          <span className="text-xs text-muted">Status:</span>
          <Select value={status} onValueChange={handleStatusChange}>
            <SelectTrigger className="w-[130px] h-8">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="draft">Draft</SelectItem>
              <SelectItem value="review">Review</SelectItem>
              <SelectItem value="ready">Ready</SelectItem>
              <SelectItem value="lodged">Lodged</SelectItem>
              <SelectItem value="amended">Amended</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {error && (
        <Card className="border-red-500/20 bg-red-500/5 rounded-xl">
          <CardContent className="p-4 text-sm text-red-400">{error}</CardContent>
        </Card>
      )}

      {loading ? (
        <Card className="neu-raised rounded-xl">
          <CardContent className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
            <span className="ml-2 text-secondary">Calculating BAS...</span>
          </CardContent>
        </Card>
      ) : (
        basData && (
          <>
            {/* Warnings */}
            {basData.warnings.length > 0 && (
              <div className="space-y-1">
                {basData.warnings.map((warning, i) => (
                  <div
                    key={`warning-${i}-${warning.slice(0, 20)}`}
                    className="flex items-center gap-2 text-xs text-amber-400 bg-amber-500/5 px-3 py-2 rounded-lg border border-amber-500/10"
                  >
                    <AlertTriangle className="w-3 h-3 shrink-0" />
                    {warning}
                  </div>
                ))}
              </div>
            )}

            {/* Sales Section */}
            <Card className="neu-raised rounded-xl border-l-2 border-l-[#FFCC00]/30">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm">Sales</CardTitle>
              </CardHeader>
              <CardContent className="space-y-0.5">
                <LabelRow
                  label="G1"
                  description="Total Sales"
                  amount={basData.labels.G1}
                  count={basData.transactionCounts?.G1}
                />
                {basMethod === 'full' && (
                  <>
                    {basData.labels.G2 !== undefined && (
                      <LabelRow label="G2" description="Export Sales" amount={basData.labels.G2} />
                    )}
                    {basData.labels.G3 !== undefined && (
                      <LabelRow
                        label="G3"
                        description="GST-Free Sales"
                        amount={basData.labels.G3}
                      />
                    )}
                    {basData.labels.G4 !== undefined && (
                      <LabelRow
                        label="G4"
                        description="Input Taxed Sales"
                        amount={basData.labels.G4}
                      />
                    )}
                  </>
                )}
                <div className="border-t border-border/50 mt-2 pt-1">
                  <LabelRow label="1A" description="GST on Sales" amount={basData.labels['1A']} />
                </div>
              </CardContent>
            </Card>

            {/* Purchases Section */}
            <Card className="neu-raised rounded-xl border-l-2 border-l-blue-500/30">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm">Purchases</CardTitle>
              </CardHeader>
              <CardContent className="space-y-0.5">
                {basMethod === 'full' && (
                  <>
                    {basData.labels.G10 !== undefined && (
                      <LabelRow
                        label="G10"
                        description="Capital Purchases"
                        amount={basData.labels.G10}
                      />
                    )}
                    {basData.labels.G11 !== undefined && (
                      <LabelRow
                        label="G11"
                        description="Non-Capital Purchases"
                        amount={basData.labels.G11}
                      />
                    )}
                  </>
                )}
                <div className={basMethod === 'full' ? 'border-t border-border/50 mt-2 pt-1' : ''}>
                  <LabelRow
                    label="1B"
                    description="GST on Purchases"
                    amount={basData.labels['1B']}
                  />
                </div>
              </CardContent>
            </Card>

            {/* PAYG Section */}
            {(basData.labels.W1 !== undefined || basData.labels.W2 !== undefined) && (
              <Card className="neu-raised rounded-xl border-l-2 border-l-purple-500/30">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm">PAYG Withholding</CardTitle>
                </CardHeader>
                <CardContent className="space-y-0.5">
                  {basData.labels.W1 !== undefined && (
                    <LabelRow label="W1" description="Gross Wages" amount={basData.labels.W1} />
                  )}
                  {basData.labels.W2 !== undefined && (
                    <LabelRow
                      label="W2"
                      description="Amounts Withheld"
                      amount={basData.labels.W2}
                    />
                  )}
                  {basData.labels['5A'] !== undefined && (
                    <LabelRow
                      label="5A"
                      description="PAYG Instalment"
                      amount={basData.labels['5A']}
                    />
                  )}
                </CardContent>
              </Card>
            )}

            {/* Summary */}
            <Card className="neu-raised rounded-xl border-cba-gold/20">
              <CardHeader className="pb-2">
                <CardTitle className="text-sm">Summary</CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2 text-sm">
                  <div className="flex justify-between">
                    <span className="text-secondary">Net GST (1A - 1B)</span>
                    <span className="font-medium">{formatCurrency(basData.netGST)}</span>
                  </div>
                  {basData.labels.W2 !== undefined && basData.labels.W2 > 0 && (
                    <div className="flex justify-between">
                      <span className="text-secondary">PAYG Withheld</span>
                      <span className="font-medium">{formatCurrency(basData.labels.W2)}</span>
                    </div>
                  )}
                  <div className="border-t border-border pt-2 flex justify-between text-base font-bold">
                    <span>{basData.totalPayable > 0 ? 'Total Payable' : 'Total Refundable'}</span>
                    <span
                      className={basData.totalPayable > 0 ? 'text-red-400' : 'text-emerald-400'}
                    >
                      {formatCurrency(Math.abs(basData.totalPayable))}
                    </span>
                  </div>
                  <div className="flex justify-between text-xs text-muted">
                    <span>Due Date</span>
                    <span>{basData.dueDate}</span>
                  </div>
                </div>
              </CardContent>
            </Card>

            {/* Actions */}
            <div className="flex justify-end gap-2">
              <Button variant="outline" size="sm">
                <FileText className="w-4 h-4 mr-1" />
                Review Transactions
              </Button>
              <Button variant="outline" size="sm" onClick={handleSaveDraft}>
                <Save className="w-4 h-4 mr-1" />
                Save Draft
              </Button>
              <Button size="sm" onClick={() => handleStatusChange('ready')}>
                <CheckCircle className="w-4 h-4 mr-1" />
                Mark Ready
              </Button>
            </div>
          </>
        )
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { ArrowLeft, Plus, Trash2, Sparkles, Save, ChevronRight } from 'lucide-react';
import { budgetsApi } from '../../../api';
import type { Budget, BudgetLine } from '../../../api';
import { CATEGORY_NAMES } from '../../transactions/constants/categories';

interface BudgetEditorProps {
  budgetId: string;
  onBack: () => void;
}

export function BudgetEditor({ budgetId, onBack }: BudgetEditorProps) {
  const [budget, setBudget] = useState<Budget | null>(null);
  const [lines, setLines] = useState<BudgetLine[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [editingCell, setEditingCell] = useState<string | null>(null);
  const [editValue, setEditValue] = useState('');

  // New line form
  const [newCategory, setNewCategory] = useState('');
  const [newPeriod, setNewPeriod] = useState('');
  const [newAmount, setNewAmount] = useState('');
  const [newNotes, setNewNotes] = useState('');

  useEffect(() => {
    loadBudget();
  }, [budgetId]);

  const loadBudget = async () => {
    setLoading(true);
    try {
      const data = await budgetsApi.get(budgetId);
      setBudget(data.budget ?? data);
      setLines(data.lines ?? []);
    } catch (e) {
      console.error('Failed to load budget', e);
    } finally {
      setLoading(false);
    }
  };

  const handleAddLine = async () => {
    if (!newCategory || !newAmount) return;
    try {
      const result = await budgetsApi.addLine(budgetId, {
        category: newCategory,
        period: newPeriod || budget?.periodStart || '',
        budgetedAmount: parseFloat(newAmount) * 100,
        notes: newNotes || undefined,
      });
      setLines((prev) => [...prev, result]);
      setNewCategory('');
      setNewPeriod('');
      setNewAmount('');
      setNewNotes('');
      loadBudget();
    } catch (e) {
      console.error('Failed to add line', e);
    }
  };

  const handleSaveCell = async (lineId: string, field: string) => {
    const value = field === 'budgetedAmount' ? parseFloat(editValue) * 100 : editValue;
    try {
      await budgetsApi.update(budgetId, {
        lineUpdate: { lineId, [field]: value },
      });
      setLines((prev) => prev.map((l) => (l.id === lineId ? { ...l, [field]: value } : l)));
    } catch (e) {
      console.error('Failed to save cell', e);
    }
    setEditingCell(null);
  };

  const handleStatusChange = async (newStatus: 'draft' | 'active' | 'closed') => {
    setSaving(true);
    try {
      await budgetsApi.update(budgetId, { status: newStatus });
      setBudget((prev: Budget | null) => (prev ? { ...prev, status: newStatus } : prev));
    } catch (e) {
      console.error('Failed to update status', e);
    } finally {
      setSaving(false);
    }
  };

  const handleAutoGenerate = async () => {
    setSaving(true);
    try {
      await budgetsApi.update(budgetId, { autoGenerate: true });
      await loadBudget();
    } catch (e) {
      console.error('Failed to auto-generate', e);
    } finally {
      setSaving(false);
    }
  };

  const totalBudgeted = lines.reduce((sum, l) => sum + (l.budgetedAmount ?? 0), 0);

  const statusFlow: Array<'draft' | 'active' | 'closed'> = ['draft', 'active', 'closed'];
  const currentIndex = statusFlow.indexOf(budget?.status as 'draft' | 'active' | 'closed');

  if (loading) {
    return (
      <div className="space-y-4">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-secondary hover:text-cba-gold transition-colors"
        >
          <ArrowLeft className="w-4 h-4" /> Back to Budgets
        </button>
        <div className="neu-raised rounded-2xl p-8 animate-pulse">
          <div className="h-6 bg-zinc-800 rounded w-1/3 mb-4" />
          <div className="h-4 bg-zinc-800 rounded w-2/3" />
        </div>
      </div>
    );
  }

  if (!budget) {
    return (
      <div className="space-y-4">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-secondary hover:text-cba-gold transition-colors"
        >
          <ArrowLeft className="w-4 h-4" /> Back to Budgets
        </button>
        <div className="neu-raised rounded-2xl p-8 text-center text-muted">Budget not found</div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-4">
        <div className="flex items-center gap-3">
          <button
            onClick={onBack}
            className="neu-raised-sm p-2 rounded-xl text-secondary hover:text-cba-gold transition-colors"
          >
            <ArrowLeft className="w-4 h-4" />
          </button>
          <div>
            <h2 className="text-xl font-bold text-gradient-gold">{budget.name}</h2>
            <p className="text-sm text-muted">
              {budget.budgetType} &middot; {budget.periodStart} to {budget.periodEnd}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
          <button
            onClick={handleAutoGenerate}
            disabled={saving}
            className="neu-raised-sm px-3 py-2 rounded-xl text-sm font-medium text-purple-400 hover:text-purple-300 transition-colors flex items-center gap-2"
          >
            <Sparkles className="w-4 h-4" />
            Auto-Generate
          </button>

          {/* Status Controls */}
          <div className="flex items-center gap-1 neu-inset px-2 py-1 rounded-xl">
            {statusFlow.map((s, i) => (
              <span key={s} className="flex items-center">
                <button
                  onClick={() => handleStatusChange(s)}
                  disabled={saving}
                  className={`px-3 py-1.5 rounded-lg text-xs font-bold uppercase tracking-wider transition-all ${
                    budget.status === s
                      ? s === 'draft'
                        ? 'bg-zinc-700 text-primary'
                        : s === 'active'
                          ? 'bg-emerald-500/20 text-emerald-400'
                          : 'bg-amber-500/20 text-amber-400'
                      : 'text-zinc-600 hover:text-secondary'
                  }`}
                >
                  {s}
                </button>
                {i < statusFlow.length - 1 && (
                  <ChevronRight className="w-3 h-3 text-zinc-600 mx-0.5" />
                )}
              </span>
            ))}
          </div>
        </div>
      </div>

      {/* Add New Line */}
      <div className="neu-raised rounded-2xl p-4">
        <h3 className="text-sm font-bold text-primary mb-3">Add Budget Line</h3>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-3">
          <select
            value={newCategory}
            onChange={(e) => setNewCategory(e.target.value)}
            className="neu-inset rounded-xl px-3 py-2 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
          >
            <option value="">Select Category</option>
            {CATEGORY_NAMES.map((c) => (
              <option key={c} value={c}>
                {c}
              </option>
            ))}
          </select>
          <input
            type="month"
            value={newPeriod}
            onChange={(e) => setNewPeriod(e.target.value)}
            placeholder="Period"
            className="neu-inset rounded-xl px-3 py-2 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
          />
          <input
            type="number"
            step="0.01"
            value={newAmount}
            onChange={(e) => setNewAmount(e.target.value)}
            placeholder="Amount ($)"
            className="neu-inset rounded-xl px-3 py-2 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
          />
          <input
            type="text"
            value={newNotes}
            onChange={(e) => setNewNotes(e.target.value)}
            placeholder="Notes"
            className="neu-inset rounded-xl px-3 py-2 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
          />
          <button
            onClick={handleAddLine}
            disabled={!newCategory || !newAmount}
            className="neu-raised-sm px-4 py-2 rounded-xl text-sm font-bold text-cba-gold hover:bg-cba-gold/10 transition-colors flex items-center justify-center gap-2 disabled:opacity-40"
          >
            <Plus className="w-4 h-4" />
            Add
          </button>
        </div>
      </div>

      {/* Lines Table */}
      <div className="neu-raised rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border/50">
                <th className="text-left px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Category
                </th>
                <th className="text-left px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Period
                </th>
                <th className="text-right px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Budgeted
                </th>
                <th className="text-left px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Notes
                </th>
                <th className="text-center px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider w-16">
                  Actions
                </th>
              </tr>
            </thead>
            <tbody>
              {lines.map((line) => (
                <tr
                  key={line.id}
                  className="border-b border-border/50 hover:bg-white/[0.02] transition-colors"
                >
                  <td className="px-4 py-3 text-primary font-medium">{line.category}</td>
                  <td className="px-4 py-3 text-secondary">{line.period}</td>
                  <td className="px-4 py-3 text-right">
                    {editingCell === `${line.id}-amount` ? (
                      <input
                        type="number"
                        step="0.01"
                        value={editValue}
                        onChange={(e) => setEditValue(e.target.value)}
                        onBlur={() => handleSaveCell(line.id, 'budgetedAmount')}
                        onKeyDown={(e) =>
                          e.key === 'Enter' && handleSaveCell(line.id, 'budgetedAmount')
                        }
                        className="neu-inset rounded-lg px-2 py-1 text-sm bg-transparent text-primary w-28 text-right focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
                      />
                    ) : (
                      <button
                        onClick={() => {
                          setEditingCell(`${line.id}-amount`);
                          setEditValue(((line.budgetedAmount ?? 0) / 100).toFixed(2));
                        }}
                        className="text-cba-gold font-mono hover:underline"
                      >
                        $
                        {((line.budgetedAmount ?? 0) / 100).toLocaleString('en-AU', {
                          minimumFractionDigits: 2,
                        })}
                      </button>
                    )}
                  </td>
                  <td className="px-4 py-3 text-muted text-xs">{line.notes || '—'}</td>
                  <td className="px-4 py-3 text-center">
                    <button className="text-red-400/60 hover:text-red-400 transition-colors p-1">
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </td>
                </tr>
              ))}
              {lines.length === 0 && (
                <tr>
                  <td colSpan={5} className="px-4 py-8 text-center text-zinc-600">
                    No budget lines yet. Add one above or use Auto-Generate.
                  </td>
                </tr>
              )}
            </tbody>
            <tfoot>
              <tr className="border-t border-cba-gold/20 bg-cba-gold/5">
                <td colSpan={2} className="px-4 py-3 text-primary font-bold">
                  Total
                </td>
                <td className="px-4 py-3 text-right text-cba-gold font-bold font-mono">
                  ${(totalBudgeted / 100).toLocaleString('en-AU', { minimumFractionDigits: 2 })}
                </td>
                <td colSpan={2} />
              </tr>
            </tfoot>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Wallet, Target, TrendingUp, Plus, BarChart3, Filter } from 'lucide-react';
import { budgetsApi } from '../../../api';
import type { Budget } from '../../../api';
import { BudgetEditor } from './BudgetEditor';
import { VarianceView } from './VarianceView';
import { ForecastScenarios } from './ForecastScenarios';
import { ScenarioComparison } from './ScenarioComparison';
import { CATEGORY_NAMES } from '../../transactions/constants/categories';

type Tab = 'budgets' | 'create' | 'forecasts';

const statusColors: Record<string, string> = {
  draft: 'text-secondary bg-zinc-700/50',
  active: 'text-emerald-400 bg-emerald-500/20',
  closed: 'text-amber-400 bg-amber-500/20',
  archived: 'text-muted bg-zinc-800',
};

const typeLabels: Record<string, string> = {
  annual: 'Annual',
  quarterly: 'Quarterly',
  monthly: 'Monthly',
  project: 'Project',
};

export function BudgetsDashboard() {
  const [tab, setTab] = useState<Tab>('budgets');
  const [budgets, setBudgets] = useState<Budget[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<string>('');

  // Sub-views
  const [editingBudgetId, setEditingBudgetId] = useState<string | null>(null);
  const [viewingVarianceId, setViewingVarianceId] = useState<string | null>(null);
  const [comparisonIds, setComparisonIds] = useState<string[] | null>(null);

  // Create form
  const [createName, setCreateName] = useState('');
  const [createType, setCreateType] = useState<'annual' | 'quarterly' | 'monthly' | 'project'>(
    'monthly',
  );
  const [createStart, setCreateStart] = useState('');
  const [createEnd, setCreateEnd] = useState('');
  const [createAutoGenerate, setCreateAutoGenerate] = useState(false);
  const [creating, setCreating] = useState(false);

  useEffect(() => {
    if (tab === 'budgets') loadBudgets();
  }, [tab, statusFilter]);

  const loadBudgets = async () => {
    setLoading(true);
    try {
      const data = await budgetsApi.list(statusFilter || undefined);
      setBudgets(Array.isArray(data) ? data : (data.budgets ?? []));
    } catch (e) {
      console.error('Failed to load budgets', e);
    } finally {
      setLoading(false);
    }
  };

  const handleCreate = async () => {
    if (!createName || !createStart || !createEnd) return;
    setCreating(true);
    try {
      await budgetsApi.create({
        userId: 'default',
        name: createName,
        budgetType: createType,
        periodStart: createStart,
        periodEnd: createEnd,
        autoGenerate: createAutoGenerate,
      });
      setCreateName('');
      setCreateType('monthly');
      setCreateStart('');
      setCreateEnd('');
      setCreateAutoGenerate(false);
      setTab('budgets');
      loadBudgets();
    } catch (e) {
      console.error('Failed to create budget', e);
    } finally {
      setCreating(false);
    }
  };

  const fmt = (cents: number) =>
    '$' + (cents / 100).toLocaleString('en-AU', { minimumFractionDigits: 2 });

  // Sub-view routing
  if (editingBudgetId) {
    return <BudgetEditor budgetId={editingBudgetId} onBack={() => setEditingBudgetId(null)} />;
  }
  if (viewingVarianceId) {
    return <VarianceView budgetId={viewingVarianceId} onBack={() => setViewingVarianceId(null)} />;
  }
  if (comparisonIds) {
    return (
      <div className="space-y-4">
        <button
          onClick={() => setComparisonIds(null)}
          className="text-sm text-secondary hover:text-cba-gold transition-colors"
        >
          &larr; Back to Forecasts
        </button>
        <ScenarioComparison scenarioIds={comparisonIds} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold tracking-tight text-gradient-gold">
          Budgets & Forecasts
        </h2>
        <p className="text-sm text-muted">
          Plan, track, and forecast your financial performance
        </p>
      </div>

      {/* Tabs */}
      <div className="flex items-center gap-1 neu-inset p-1 rounded-xl w-fit">
        {[
          { id: 'budgets' as Tab, label: 'My Budgets', icon: Wallet },
          { id: 'create' as Tab, label: 'Create Budget', icon: Plus },
          { id: 'forecasts' as Tab, label: 'Forecasts', icon: TrendingUp },
        ].map((t) => (
          <button
            key={t.id}
            onClick={() => setTab(t.id)}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
              tab === t.id
                ? 'bg-cba-gold text-base shadow-[0_0_15px_rgba(255,204,0,0.15)]'
                : 'text-secondary hover:text-primary'
            }`}
          >
            <t.icon className="w-4 h-4" />
            {t.label}
          </button>
        ))}
      </div>

      {/* My Budgets Tab */}
      {tab === 'budgets' && (
        <div className="space-y-4">
          {/* Status Filter */}
          <div className="flex items-center gap-3">
            <Filter className="w-4 h-4 text-muted" />
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="neu-inset rounded-xl px-3 py-2 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
            >
              <option value="">All Statuses</option>
              <option value="draft">Draft</option>
              <option value="active">Active</option>
              <option value="closed">Closed</option>
              <option value="archived">Archived</option>
            </select>
          </div>

          {/* Budget Cards */}
          {loading ? (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {[1, 2, 3].map((i) => (
                <div key={`item-${i}`} className="neu-raised rounded-2xl p-5 animate-pulse">
                  <div className="h-5 bg-zinc-800 rounded w-2/3 mb-3" />
                  <div className="h-4 bg-zinc-800 rounded w-1/2 mb-2" />
                  <div className="h-4 bg-zinc-800 rounded w-1/3" />
                </div>
              ))}
            </div>
          ) : budgets.length === 0 ? (
            <div className="neu-inset rounded-2xl p-8 text-center text-muted">
              <Wallet className="w-10 h-10 mx-auto mb-3 text-zinc-600" />
              <p>No budgets found.</p>
              <p className="text-xs mt-1">Create a new budget to get started.</p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
              {budgets.map((b) => (
                <div
                  key={b.id}
                  className="neu-raised rounded-2xl p-5 hover:border-cba-gold/20 border border-transparent transition-all group cursor-pointer"
                >
                  <div className="flex items-start justify-between mb-3">
                    <h4 className="text-sm font-bold text-primary group-hover:text-cba-gold transition-colors truncate">
                      {b.name}
                    </h4>
                    <span
                      className={`px-2 py-0.5 rounded-full text-[10px] font-bold uppercase ${statusColors[b.status] ?? statusColors.draft}`}
                    >
                      {b.status}
                    </span>
                  </div>

                  <div className="space-y-1 mb-4">
                    <p className="text-xs text-muted">
                      {typeLabels[b.budgetType] ?? b.budgetType} &middot; {b.periodStart} to{' '}
                      {b.periodEnd}
                    </p>
                    {b.autoGenerated && (
                      <span className="inline-block text-[10px] text-purple-400 bg-purple-500/10 px-2 py-0.5 rounded-full font-medium">
                        Auto-Generated
                      </span>
                    )}
                  </div>

                  <div className="flex items-end justify-between">
                    <p className="text-lg font-bold text-cba-gold font-mono">
                      {fmt(b.totalAmount)}
                    </p>
                    <div className="flex gap-1">
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setEditingBudgetId(b.id);
                        }}
                        className="neu-raised-sm px-3 py-1.5 rounded-lg text-xs font-bold text-secondary hover:text-cba-gold transition-colors"
                      >
                        Edit
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setViewingVarianceId(b.id);
                        }}
                        className="neu-raised-sm px-3 py-1.5 rounded-lg text-xs font-bold text-secondary hover:text-emerald-400 transition-colors flex items-center gap-1"
                      >
                        <Target className="w-3 h-3" />
                        Variance
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}

      {/* Create Budget Tab */}
      {tab === 'create' && (
        <div className="neu-raised rounded-2xl p-6 max-w-2xl space-y-5">
          <h3 className="text-lg font-bold text-primary">Create New Budget</h3>

          <div className="space-y-4">
            <div>
              <label htmlFor="budget-f1" className="block text-xs text-muted mb-1">Budget Name</label>
              <input id="budget-f1"
                value={createName}
                onChange={(e) => setCreateName(e.target.value)}
                placeholder="e.g. Q1 2026 Operating Budget"
                className="w-full neu-inset rounded-xl px-4 py-3 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
              <div>
                <label htmlFor="budget-f2" className="block text-xs text-muted mb-1">Budget Type</label>
                <select id="budget-f2"
                  value={createType}
                  onChange={(e) => setCreateType(e.target.value as 'annual' | 'quarterly' | 'monthly' | 'project')}
                  className="w-full neu-inset rounded-xl px-3 py-3 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
                >
                  <option value="annual">Annual</option>
                  <option value="quarterly">Quarterly</option>
                  <option value="monthly">Monthly</option>
                  <option value="project">Project</option>
                </select>
              </div>
              <div>
                <label htmlFor="budget-f3" className="block text-xs text-muted mb-1">Period Start</label>
                <input id="budget-f3"
                  type="date"
                  value={createStart}
                  onChange={(e) => setCreateStart(e.target.value)}
                  className="w-full neu-inset rounded-xl px-3 py-3 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
                />
              </div>
              <div>
                <label htmlFor="budget-create-end" className="block text-xs text-muted mb-1">Period End</label>
                <input
                  id="budget-create-end"
                  type="date"
                  value={createEnd}
                  onChange={(e) => setCreateEnd(e.target.value)}
                  className="w-full neu-inset rounded-xl px-3 py-3 text-sm bg-transparent text-primary focus:ring-1 focus:ring-[#FFCC00]/50 outline-none"
                />
              </div>
            </div>

            {/* Auto-Generate Toggle */}
            <div className="flex items-center gap-3 neu-inset rounded-xl px-4 py-3">
              <button
                onClick={() => setCreateAutoGenerate(!createAutoGenerate)}
                className={`w-10 h-6 rounded-full transition-colors relative ${
                  createAutoGenerate ? 'bg-cba-gold' : 'bg-zinc-700'
                }`}
              >
                <span
                  className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-transform ${
                    createAutoGenerate ? 'translate-x-5' : 'translate-x-1'
                  }`}
                />
              </button>
              <div>
                <p className="text-sm font-medium text-primary">Auto-Generate from History</p>
                <p className="text-xs text-muted">
                  AI will analyze your past transactions to pre-fill budget lines
                </p>
              </div>
            </div>

            <div className="flex justify-end gap-3 pt-2">
              <button
                onClick={() => setTab('budgets')}
                className="px-4 py-2.5 rounded-xl text-sm text-secondary hover:text-primary transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleCreate}
                disabled={!createName || !createStart || !createEnd || creating}
                className="px-6 py-2.5 rounded-xl text-sm font-bold bg-cba-gold text-base hover:bg-cba-gold/90 transition-colors disabled:opacity-40"
              >
                {creating ? 'Creating...' : 'Create Budget'}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* Forecasts Tab */}
      {tab === 'forecasts' && <ForecastScenarios onCompare={(ids) => setComparisonIds(ids)} />}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { BarChart3 } from 'lucide-react';
import { forecastsApi } from '../../../api';

interface ScenarioComparisonProps {
  scenarioIds: string[];
}

interface ComparisonData {
  scenarios: Array<{
    id: string;
    name: string;
    scenarioType: string;
  }>;
  periods: Array<{
    period: string;
    values: Record<string, number>;
  }>;
  totals: Record<string, number>;
}

const typeColors: Record<string, { bar: string; text: string }> = {
  optimistic: { bar: 'bg-emerald-500', text: 'text-emerald-400' },
  realistic: { bar: 'bg-blue-500', text: 'text-blue-400' },
  pessimistic: { bar: 'bg-red-500', text: 'text-red-400' },
  custom: { bar: 'bg-purple-500', text: 'text-purple-400' },
};

export function ScenarioComparison({ scenarioIds }: ScenarioComparisonProps) {
  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<ComparisonData | null>(null);

  useEffect(() => {
    loadComparison();
  }, [scenarioIds.join(',')]);

  const loadComparison = async () => {
    setLoading(true);
    try {
      const result = await forecastsApi.compareScenarios(scenarioIds);
      setData(result);
    } catch (e) {
      console.error('Failed to compare scenarios', e);
    } finally {
      setLoading(false);
    }
  };

  const fmt = (cents: number) =>
    '$' + (cents / 100).toLocaleString('en-AU', { minimumFractionDigits: 2 });

  if (loading) {
    return (
      <div className="neu-raised rounded-2xl p-8 animate-pulse">
        <div className="h-6 bg-zinc-800 rounded w-1/3 mb-4" />
        <div className="h-4 bg-zinc-800 rounded w-2/3 mb-8" />
        <div className="space-y-3">
          {[1, 2, 3, 4, 5].map((i) => (
            <div key={i} className="h-10 bg-zinc-800 rounded" />
          ))}
        </div>
      </div>
    );
  }

  if (!data || !data.scenarios?.length) {
    return (
      <div className="neu-inset rounded-2xl p-8 text-center text-muted">
        <BarChart3 className="w-10 h-10 mx-auto mb-3 text-zinc-600" />
        <p>No comparison data available.</p>
      </div>
    );
  }

  // Find max value across all periods for bar chart scaling
  const allValues = (data.periods ?? []).flatMap((p) =>
    Object.values(p.values).map((v) => Math.abs(v)),
  );
  const maxValue = Math.max(...allValues, 1);

  return (
    <div className="space-y-6">
      <div>
        <h3 className="text-lg font-bold text-gradient-gold">Scenario Comparison</h3>
        <p className="text-sm text-muted">
          Comparing {data.scenarios.length} scenarios side-by-side
        </p>
      </div>

      {/* Legend */}
      <div className="flex flex-wrap gap-3">
        {data.scenarios.map((s) => {
          const colors = typeColors[s.scenarioType] ?? typeColors.custom;
          return (
            <div key={s.id} className="flex items-center gap-2 neu-inset px-3 py-1.5 rounded-xl">
              <div className={`w-3 h-3 rounded-sm ${colors.bar}`} />
              <span className={`text-xs font-bold ${colors.text}`}>{s.name}</span>
              <span className="text-[10px] text-zinc-600 uppercase">{s.scenarioType}</span>
            </div>
          );
        })}
      </div>

      {/* Comparison Table */}
      <div className="neu-raised rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border/50">
                <th className="text-left px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Period
                </th>
                {data.scenarios.map((s) => {
                  const colors = typeColors[s.scenarioType] ?? typeColors.custom;
                  return (
                    <th
                      key={s.id}
                      className={`text-right px-4 py-3 font-bold uppercase text-xs tracking-wider ${colors.text}`}
                    >
                      {s.name}
                    </th>
                  );
                })}
                <th className="text-right px-4 py-3 text-cba-gold font-bold uppercase text-xs tracking-wider">
                  Spread
                </th>
              </tr>
            </thead>
            <tbody>
              {(data.periods ?? []).map((p, i) => {
                const vals = data.scenarios.map((s) => p.values[s.id] ?? 0);
                const spread = Math.max(...vals) - Math.min(...vals);

                return (
                  <tr key={i} className="border-b border-border/50 hover:bg-white/[0.02]">
                    <td className="px-4 py-3 text-primary font-medium">{p.period}</td>
                    {data.scenarios.map((s) => (
                      <td key={s.id} className="px-4 py-3 text-right font-mono text-primary">
                        {fmt(p.values[s.id] ?? 0)}
                      </td>
                    ))}
                    <td className="px-4 py-3 text-right font-mono text-cba-gold">{fmt(spread)}</td>
                  </tr>
                );
              })}
            </tbody>
            {/* Summary row */}
            <tfoot>
              <tr className="border-t border-cba-gold/20 bg-cba-gold/5">
                <td className="px-4 py-3 text-primary font-bold">Total</td>
                {data.scenarios.map((s) => (
                  <td key={s.id} className="px-4 py-3 text-right font-mono font-bold text-primary">
                    {fmt(data.totals?.[s.id] ?? 0)}
                  </td>
                ))}
                <td className="px-4 py-3 text-right font-mono font-bold text-cba-gold">
                  {fmt(
                    Math.max(...data.scenarios.map((s) => data.totals?.[s.id] ?? 0)) -
                      Math.min(...data.scenarios.map((s) => data.totals?.[s.id] ?? 0)),
                  )}
                </td>
              </tr>
            </tfoot>
          </table>
        </div>
      </div>

      {/* CSS Bar Chart */}
      <div className="neu-raised rounded-2xl p-5">
        <h4 className="text-sm font-bold text-primary mb-4">Visual Comparison</h4>
        <div className="space-y-4">
          {(data.periods ?? []).map((p, i) => (
            <div key={i}>
              <p className="text-xs text-muted mb-1.5">{p.period}</p>
              <div className="flex gap-1 h-6">
                {data.scenarios.map((s) => {
                  const value = Math.abs(p.values[s.id] ?? 0);
                  const width = (value / maxValue) * 100;
                  const colors = typeColors[s.scenarioType] ?? typeColors.custom;
                  return (
                    <div
                      key={s.id}
                      className={`${colors.bar} rounded-sm transition-all relative group`}
                      style={{ width: `${width}%`, minWidth: value > 0 ? '4px' : '0' }}
                      title={`${s.name}: ${fmt(p.values[s.id] ?? 0)}`}
                    >
                      <span className="absolute inset-0 flex items-center justify-center text-[9px] font-bold text-primary/80 opacity-0 group-hover:opacity-100 truncate px-1">
                        {fmt(p.values[s.id] ?? 0)}
                      </span>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { ArrowLeft, AlertTriangle, TrendingUp, TrendingDown, Target } from 'lucide-react';
import { budgetsApi } from '../../../api';
import type { BudgetVariance, VarianceSummary } from '../../../api';

interface VarianceViewProps {
  budgetId: string;
  onBack: () => void;
}

export function VarianceView({ budgetId, onBack }: VarianceViewProps) {
  const [loading, setLoading] = useState(true);
  const [variance, setVariance] = useState<BudgetVariance[]>([]);
  const [summary, setSummary] = useState<VarianceSummary | null>(null);

  useEffect(() => {
    loadData();
  }, [budgetId]);

  const loadData = async () => {
    setLoading(true);
    try {
      const [vData, sData] = await Promise.all([
        budgetsApi.getVariance(budgetId),
        budgetsApi.getVarianceSummary(budgetId),
      ]);
      setVariance(Array.isArray(vData) ? vData : (vData.variances ?? []));
      setSummary(sData);
    } catch (e) {
      console.error('Failed to load variance data', e);
    } finally {
      setLoading(false);
    }
  };

  const fmt = (cents: number) =>
    '$' + (cents / 100).toLocaleString('en-AU', { minimumFractionDigits: 2 });

  const healthConfig: Record<string, { label: string; color: string; icon: typeof Target }> = {
    on_track: { label: 'On Track', color: 'text-emerald-400 bg-emerald-500/20', icon: Target },
    over_budget: { label: 'Over Budget', color: 'text-red-400 bg-red-500/20', icon: TrendingUp },
    under_budget: {
      label: 'Under Budget',
      color: 'text-blue-400 bg-blue-500/20',
      icon: TrendingDown,
    },
  };

  if (loading) {
    return (
      <div className="space-y-4">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-secondary hover:text-cba-gold transition-colors"
        >
          <ArrowLeft className="w-4 h-4" /> Back to Budgets
        </button>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="neu-raised rounded-2xl p-6 animate-pulse">
              <div className="h-4 bg-zinc-800 rounded w-1/2 mb-3" />
              <div className="h-6 bg-zinc-800 rounded w-2/3" />
            </div>
          ))}
        </div>
      </div>
    );
  }

  const health = summary
    ? (healthConfig[summary.health] ?? healthConfig.on_track)
    : healthConfig.on_track;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center gap-3">
        <button
          onClick={onBack}
          className="neu-raised-sm p-2 rounded-xl text-secondary hover:text-cba-gold transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
        </button>
        <div>
          <h2 className="text-xl font-bold text-gradient-gold">Budget vs Actual</h2>
          <p className="text-sm text-muted">Variance analysis for budget</p>
        </div>
      </div>

      {/* Summary Cards */}
      {summary && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="neu-raised rounded-2xl p-5">
            <p className="text-xs font-bold text-muted uppercase tracking-wider mb-1">
              Total Budgeted
            </p>
            <p className="text-xl font-bold text-primary font-mono">
              {fmt(summary.totalBudgeted)}
            </p>
          </div>
          <div className="neu-raised rounded-2xl p-5">
            <p className="text-xs font-bold text-muted uppercase tracking-wider mb-1">
              Total Actual
            </p>
            <p className="text-xl font-bold text-primary font-mono">{fmt(summary.totalActual)}</p>
          </div>
          <div className="neu-raised rounded-2xl p-5">
            <p className="text-xs font-bold text-muted uppercase tracking-wider mb-1">
              Total Variance
            </p>
            <p
              className={`text-xl font-bold font-mono ${summary.totalVariance >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
            >
              {fmt(summary.totalVariance)}
            </p>
          </div>
          <div className="neu-raised rounded-2xl p-5">
            <p className="text-xs font-bold text-muted uppercase tracking-wider mb-1">Health</p>
            <span
              className={`inline-flex items-center gap-2 px-3 py-1 rounded-full text-sm font-bold ${health.color}`}
            >
              <health.icon className="w-4 h-4" />
              {health.label}
            </span>
          </div>
        </div>
      )}

      {/* Top Variances Alert */}
      {summary && summary.topVariances.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {(summary.topVariances as Array<Record<string, unknown>>).slice(0, 5).map((tv, i: number) => (
            <div key={i} className="neu-inset rounded-xl p-3 flex items-center gap-3">
              <div
                className={`p-2 rounded-lg ${tv.variance < 0 ? 'bg-red-500/20 text-red-400' : 'bg-amber-500/20 text-amber-400'}`}
              >
                <AlertTriangle className="w-4 h-4" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-medium text-primary truncate">{tv.category}</p>
                <p className="text-xs text-muted">
                  Budget: {fmt(tv.budgeted)} &middot; Actual: {fmt(tv.actual)}
                </p>
              </div>
              <p
                className={`text-sm font-bold font-mono ${tv.variance < 0 ? 'text-red-400' : 'text-amber-400'}`}
              >
                {fmt(tv.variance)}
              </p>
            </div>
          ))}
        </div>
      )}

      {/* Variance Table */}
      <div className="neu-raised rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border/50">
                <th className="text-left px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Category
                </th>
                <th className="text-left px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Period
                </th>
                <th className="text-right px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Budgeted
                </th>
                <th className="text-right px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Actual
                </th>
                <th className="text-right px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Variance $
                </th>
                <th className="text-right px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider">
                  Variance %
                </th>
                <th className="px-4 py-3 text-muted font-bold uppercase text-xs tracking-wider w-40">
                  Progress
                </th>
              </tr>
            </thead>
            <tbody>
              {variance.map((v, i) => {
                const ratio = v.budgetedAmount > 0 ? (v.actualAmount / v.budgetedAmount) * 100 : 0;
                const isOver = ratio > 100;
                const isSignificantlyUnder = ratio < 50;

                return (
                  <tr
                    key={i}
                    className={`border-b border-border/50 transition-colors ${
                      isOver
                        ? 'bg-red-500/5'
                        : isSignificantlyUnder
                          ? 'bg-amber-500/5'
                          : 'hover:bg-white/[0.02]'
                    }`}
                  >
                    <td className="px-4 py-3 text-primary font-medium">{v.category}</td>
                    <td className="px-4 py-3 text-secondary">{v.period}</td>
                    <td className="px-4 py-3 text-right text-primary font-mono">
                      {fmt(v.budgetedAmount)}
                    </td>
                    <td className="px-4 py-3 text-right text-primary font-mono">
                      {fmt(v.actualAmount)}
                    </td>
                    <td
                      className={`px-4 py-3 text-right font-mono font-medium ${v.varianceAmount >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                    >
                      {fmt(v.varianceAmount)}
                    </td>
                    <td
                      className={`px-4 py-3 text-right font-mono ${v.variancePercent >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                    >
                      {v.variancePercent >= 0 ? '+' : ''}
                      {v.variancePercent.toFixed(1)}%
                    </td>
                    <td className="px-4 py-3">
                      <div className="w-full h-2 rounded-full bg-zinc-800 overflow-hidden">
                        <div
                          className={`h-full rounded-full transition-all ${
                            isOver ? 'bg-red-500' : ratio > 80 ? 'bg-amber-500' : 'bg-emerald-500'
                          }`}
                          style={{ width: `${Math.min(ratio, 100)}%` }}
                        />
                      </div>
                      <p className="text-[10px] text-zinc-600 mt-1 text-center">
                        {ratio.toFixed(0)}%
                      </p>
                    </td>
                  </tr>
                );
              })}
              {variance.length === 0 && (
                <tr>
                  <td colSpan={7} className="px-4 py-8 text-center text-zinc-600">
                    No variance data available. Ensure budget lines are created and transactions
                    exist for the period.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import { cn } from '@/lib/utils';

interface StreamingMessageProps {
  tokens: string[];
  isComplete: boolean;
  agentType?: string;
}

/**
 * Progressive text rendering with typing animation for SSE-streamed responses.
 * Displays tokens as they arrive via SSE, with a blinking cursor until complete.
 */
export function StreamingMessage({ tokens, isComplete, agentType }: StreamingMessageProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (containerRef.current) {
      containerRef.current.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  }, [tokens.length]);

  const displayText = tokens.join('');

  return (
    <div
      ref={containerRef}
      className="neu-raised rounded-2xl rounded-bl-none px-4 py-3 border border-border/50 max-w-[85%]"
    >
      {/* Agent type badge */}
      {agentType && (
        <div className="flex items-center gap-1.5 mb-1.5">
          <div className="w-1.5 h-1.5 rounded-full bg-cba-gold animate-pulse" />
          <span className="text-[8px] font-black uppercase tracking-widest text-cba-gold/70">
            {agentType.replace(/_/g, ' ')}
          </span>
        </div>
      )}

      {/* Streaming text with cursor */}
      <div className="text-xs font-medium text-primary leading-relaxed whitespace-pre-wrap">
        {displayText}
        {!isComplete && (
          <span className="inline-block w-0.5 h-3.5 bg-cba-gold ml-0.5 align-middle animate-blink" />
        )}
      </div>

      {/* Streaming indicator */}
      {!isComplete && (
        <div className="flex items-center gap-1.5 mt-2">
          <div className="flex gap-0.5">
            <span
              className="w-1 h-1 rounded-full bg-cba-gold/50 animate-bounce"
              style={{ animationDelay: '0ms' }}
            />
            <span
              className="w-1 h-1 rounded-full bg-cba-gold/50 animate-bounce"
              style={{ animationDelay: '150ms' }}
            />
            <span
              className="w-1 h-1 rounded-full bg-cba-gold/50 animate-bounce"
              style={{ animationDelay: '300ms' }}
            />
          </div>
          <span className="text-[7px] font-black text-zinc-600 uppercase tracking-widest">
            Streaming
          </span>
        </div>
      )}

      <style>{`
        @keyframes blink {
          0%, 50% { opacity: 1; }
          51%, 100% { opacity: 0; }
        }
        .animate-blink {
          animation: blink 1s step-end infinite;
        }
      `}</style>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { anomalyApi } from '../../../api';
import {
  AlertTriangle,
  CheckCircle,
  XCircle,
  Eye,
  Loader2,
  Search,
  AlertOctagon,
  Info,
} from 'lucide-react';
import { cn } from '../../../lib/utils';

interface AnomalyAlert {
  id: string;
  type: string;
  severity: 'critical' | 'high' | 'medium' | 'low';
  title: string;
  description: string;
  transactionId?: string;
  status: 'open' | 'acknowledged' | 'resolved' | 'dismissed';
  detectedAt: string;
}

interface AnomalyStats {
  open: number;
  acknowledged: number;
  resolved: number;
  total: number;
}

interface AnomalyAlertPanelProps {
  userId: string;
}

const severityConfig: Record<
  string,
  { icon: typeof AlertTriangle; color: string; bg: string; order: number }
> = {
  critical: {
    icon: AlertOctagon,
    color: 'text-red-400',
    bg: 'bg-red-400/10 border-red-500/30',
    order: 0,
  },
  high: {
    icon: AlertTriangle,
    color: 'text-orange-400',
    bg: 'bg-orange-400/10 border-orange-500/30',
    order: 1,
  },
  medium: {
    icon: Info,
    color: 'text-yellow-400',
    bg: 'bg-yellow-400/10 border-yellow-500/30',
    order: 2,
  },
  low: { icon: Info, color: 'text-secondary', bg: 'bg-zinc-400/10 border-zinc-500/30', order: 3 },
};

export function AnomalyAlertPanel({ userId }: AnomalyAlertPanelProps) {
  const [alerts, setAlerts] = useState<AnomalyAlert[]>([]);
  const [stats, setStats] = useState<AnomalyStats>({
    open: 0,
    acknowledged: 0,
    resolved: 0,
    total: 0,
  });
  const [loading, setLoading] = useState(true);
  const [scanning, setScanning] = useState(false);

  useEffect(() => {
    loadAlerts();
  }, [userId]);

  const loadAlerts = async () => {
    try {
      setLoading(true);
      const [alertData, statsData] = await Promise.all([
        anomalyApi.list(userId),
        anomalyApi.stats(userId),
      ]);
      const list = alertData.alerts ?? alertData ?? [];
      setAlerts(
        list.sort(
          (a: AnomalyAlert, b: AnomalyAlert) =>
            (severityConfig[a.severity]?.order ?? 9) - (severityConfig[b.severity]?.order ?? 9),
        ),
      );
      setStats(statsData);
    } catch (e) {
      console.error('Failed to load anomaly alerts', e);
    } finally {
      setLoading(false);
    }
  };

  const handleScan = async () => {
    try {
      setScanning(true);
      await anomalyApi.scan({ userId, detectors: ['all'] });
      await loadAlerts();
    } catch (e) {
      console.error('Failed to scan', e);
    } finally {
      setScanning(false);
    }
  };

  const handleAction = async (alertId: string, action: 'acknowledge' | 'resolve' | 'dismiss') => {
    try {
      if (action === 'acknowledge') await anomalyApi.acknowledge(alertId);
      else if (action === 'resolve') await anomalyApi.resolve(alertId, userId);
      else await anomalyApi.dismiss(alertId, 'User dismissed');
      await loadAlerts();
    } catch (e) {
      console.error(`Failed to ${action} alert`, e);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-8 w-8 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Stats Bar */}
      <div className="flex flex-wrap items-center gap-4">
        <div className="flex items-center gap-6 neu-inset px-4 py-2 rounded-xl">
          <span className="text-xs font-bold text-red-400">Open: {stats.open}</span>
          <span className="text-xs font-bold text-yellow-400">Ack: {stats.acknowledged}</span>
          <span className="text-xs font-bold text-emerald-400">Resolved: {stats.resolved}</span>
        </div>

        <button
          onClick={handleScan}
          disabled={scanning}
          className="ml-auto flex items-center gap-2 px-4 py-2 rounded-xl bg-cba-gold text-base font-bold text-sm hover:bg-[#FFD633] transition-colors disabled:opacity-50"
        >
          {scanning ? <Loader2 className="h-4 w-4 animate-spin" /> : <Search className="h-4 w-4" />}
          Run Scan
        </button>
      </div>

      {/* Alert Cards */}
      <div className="space-y-3">
        {alerts.length === 0 ? (
          <div className="neu-raised rounded-2xl p-8 text-center">
            <CheckCircle className="h-12 w-12 text-emerald-400 mx-auto mb-3" />
            <p className="text-primary font-medium">No anomalies detected</p>
            <p className="text-muted text-sm mt-1">Run a scan to check for issues</p>
          </div>
        ) : (
          alerts.map((alert) => {
            const sc = severityConfig[alert.severity] ?? severityConfig.low;
            const Icon = sc.icon;
            return (
              <div key={alert.id} className={cn('neu-raised rounded-2xl p-4 border', sc.bg)}>
                <div className="flex items-start gap-3">
                  <div className={cn('p-2 rounded-xl neu-inset', sc.color)}>
                    <Icon className="h-5 w-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <h4 className="text-primary font-bold text-sm">{alert.title}</h4>
                      <span
                        className={cn(
                          'px-2 py-0.5 rounded text-[10px] font-bold uppercase',
                          sc.color,
                          sc.bg,
                        )}
                      >
                        {alert.severity}
                      </span>
                      {alert.status !== 'open' && (
                        <span className="px-2 py-0.5 rounded text-[10px] font-bold uppercase text-secondary bg-zinc-400/10">
                          {alert.status}
                        </span>
                      )}
                    </div>
                    <p className="text-secondary text-xs">{alert.description}</p>
                    <p className="text-zinc-600 text-[10px] mt-1">
                      Detected: {new Date(alert.detectedAt).toLocaleString('en-AU')}
                    </p>
                  </div>
                  {alert.status === 'open' && (
                    <div className="flex items-center gap-1 shrink-0">
                      <button
                        onClick={() => handleAction(alert.id, 'acknowledge')}
                        title="Acknowledge"
                        className="p-1.5 rounded-lg text-yellow-400 hover:bg-yellow-400/10 transition-colors"
                      >
                        <Eye className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => handleAction(alert.id, 'resolve')}
                        title="Resolve"
                        className="p-1.5 rounded-lg text-emerald-400 hover:bg-emerald-400/10 transition-colors"
                      >
                        <CheckCircle className="h-4 w-4" />
                      </button>
                      <button
                        onClick={() => handleAction(alert.id, 'dismiss')}
                        title="Dismiss"
                        className="p-1.5 rounded-lg text-secondary hover:bg-zinc-400/10 transition-colors"
                      >
                        <XCircle className="h-4 w-4" />
                      </button>
                    </div>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { complianceApi } from '../../../api';
import { ChevronLeft, ChevronRight, Loader2, Calendar as CalIcon } from 'lucide-react';
import { cn } from '../../../lib/utils';

interface CalendarObligation {
  id: string;
  type: string;
  dueDate: string;
  status: 'compliant' | 'pending' | 'overdue' | 'lodged' | 'in_progress';
  description?: string;
}

interface ComplianceCalendarProps {
  userId: string;
}

const statusDotColors: Record<string, string> = {
  compliant: 'bg-emerald-400',
  pending: 'bg-yellow-400',
  overdue: 'bg-red-400',
  lodged: 'bg-blue-400',
  in_progress: 'bg-cba-gold',
};

const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

export function ComplianceCalendar({ userId }: ComplianceCalendarProps) {
  const [obligations, setObligations] = useState<CalendarObligation[]>([]);
  const [loading, setLoading] = useState(true);
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);

  useEffect(() => {
    loadCalendar();
  }, [userId]);

  const loadCalendar = async () => {
    try {
      setLoading(true);
      const data = await complianceApi.calendar(userId);
      setObligations(data.obligations ?? data ?? []);
    } catch (e) {
      console.error('Failed to load calendar', e);
    } finally {
      setLoading(false);
    }
  };

  const year = currentMonth.getFullYear();
  const month = currentMonth.getMonth();

  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDay = new Date(year, month, 1).getDay();
  // Convert Sun=0 to Mon=0 format
  const startOffset = firstDay === 0 ? 6 : firstDay - 1;

  const obligationsByDate = useMemo(() => {
    const map: Record<string, CalendarObligation[]> = {};
    for (const ob of obligations) {
      const d = ob.dueDate.split('T')[0];
      if (!map[d]) map[d] = [];
      map[d].push(ob);
    }
    return map;
  }, [obligations]);

  const upcomingObligations = useMemo(() => {
    const now = new Date();
    const in30 = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
    return obligations
      .filter((o) => {
        const d = new Date(o.dueDate);
        return d >= now && d <= in30;
      })
      .sort((a, b) => new Date(a.dueDate).getTime() - new Date(b.dueDate).getTime());
  }, [obligations]);

  const selectedObligations = selectedDate ? (obligationsByDate[selectedDate] ?? []) : [];

  const prevMonth = () => setCurrentMonth(new Date(year, month - 1, 1));
  const nextMonth = () => setCurrentMonth(new Date(year, month + 1, 1));

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-8 w-8 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
      {/* Calendar Grid */}
      <div className="lg:col-span-2 neu-raised rounded-2xl p-4">
        {/* Month Navigation */}
        <div className="flex items-center justify-between mb-4">
          <button
            onClick={prevMonth}
            className="p-2 rounded-xl neu-raised-sm text-secondary hover:text-primary transition-colors"
          >
            <ChevronLeft className="h-5 w-5" />
          </button>
          <h3 className="text-primary font-bold">
            {currentMonth.toLocaleString('en-AU', { month: 'long', year: 'numeric' })}
          </h3>
          <button
            onClick={nextMonth}
            className="p-2 rounded-xl neu-raised-sm text-secondary hover:text-primary transition-colors"
          >
            <ChevronRight className="h-5 w-5" />
          </button>
        </div>

        {/* Day Headers */}
        <div className="grid grid-cols-7 gap-1 mb-1">
          {DAYS.map((d) => (
            <div key={d} className="text-center text-[10px] font-bold text-muted uppercase py-1">
              {d}
            </div>
          ))}
        </div>

        {/* Day Cells */}
        <div className="grid grid-cols-7 gap-1">
          {/* Empty cells for offset */}
          {Array.from({ length: startOffset }).map((_, i) => (
            <div key={`empty-${i}`} className="h-16" />
          ))}

          {Array.from({ length: daysInMonth }).map((_, i) => {
            const day = i + 1;
            const dateStr = `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
            const dayObs = obligationsByDate[dateStr] ?? [];
            const isSelected = selectedDate === dateStr;
            const isToday = new Date().toISOString().split('T')[0] === dateStr;

            return (
              <button
                key={day}
                onClick={() => setSelectedDate(isSelected ? null : dateStr)}
                className={cn(
                  'h-16 rounded-xl p-1 text-left transition-all duration-200 relative',
                  isSelected ? 'ring-2 ring-[#FFCC00] bg-cba-gold/5' : 'hover:bg-overlay',
                  isToday && 'border border-cba-gold/30',
                )}
              >
                <span
                  className={cn('text-xs font-bold', isToday ? 'text-cba-gold' : 'text-secondary')}
                >
                  {day}
                </span>
                {dayObs.length > 0 && (
                  <div className="flex flex-wrap gap-0.5 mt-1">
                    {dayObs.slice(0, 3).map((ob, j) => (
                      <span
                        key={j}
                        className={cn(
                          'w-2 h-2 rounded-full',
                          statusDotColors[ob.status] ?? 'bg-zinc-400',
                        )}
                      />
                    ))}
                    {dayObs.length > 3 && (
                      <span className="text-[8px] text-muted font-bold">
                        +{dayObs.length - 3}
                      </span>
                    )}
                  </div>
                )}
              </button>
            );
          })}
        </div>

        {/* Selected Day Details */}
        {selectedDate && selectedObligations.length > 0 && (
          <div className="mt-4 space-y-2 border-t border-border/50 pt-4">
            <h4 className="text-primary text-sm font-bold">
              {new Date(selectedDate + 'T00:00:00').toLocaleDateString('en-AU', {
                weekday: 'long',
                day: 'numeric',
                month: 'long',
                year: 'numeric',
              })}
            </h4>
            {selectedObligations.map((ob) => (
              <div key={ob.id} className="flex items-center gap-2 text-sm">
                <span
                  className={cn(
                    'w-2 h-2 rounded-full shrink-0',
                    statusDotColors[ob.status] ?? 'bg-zinc-400',
                  )}
                />
                <span className="text-primary font-medium">{ob.type}</span>
                <span className="text-muted text-xs capitalize">
                  ({ob.status.replace('_', ' ')})
                </span>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Upcoming 30 Days Sidebar */}
      <div className="neu-raised rounded-2xl p-4">
        <div className="flex items-center gap-2 mb-4">
          <CalIcon className="h-4 w-4 text-cba-gold" />
          <h4 className="text-primary font-bold text-sm">Next 30 Days</h4>
        </div>
        {upcomingObligations.length === 0 ? (
          <p className="text-muted text-sm">No upcoming obligations</p>
        ) : (
          <div className="space-y-3">
            {upcomingObligations.map((ob) => (
              <div key={ob.id} className="flex items-start gap-2">
                <span
                  className={cn(
                    'w-2 h-2 rounded-full mt-1.5 shrink-0',
                    statusDotColors[ob.status] ?? 'bg-zinc-400',
                  )}
                />
                <div className="min-w-0">
                  <p className="text-primary text-sm font-medium truncate">{ob.type}</p>
                  <p className="text-muted text-xs">
                    Due: {new Date(ob.dueDate).toLocaleDateString('en-AU')}
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { complianceApi } from '../../../api';
import { FileText, Copy, Check, Loader2, Download } from 'lucide-react';
import { cn } from '../../../lib/utils';

interface ReportData {
  title: string;
  period: string;
  generatedAt: string;
  summary: {
    totalObligations: number;
    compliant: number;
    overdue: number;
    pending: number;
    complianceRate: number;
  };
  obligations: Array<{
    type: string;
    period: string;
    dueDate: string;
    status: string;
    riskLevel: string;
  }>;
  anomalySummary: {
    totalAlerts: number;
    critical: number;
    high: number;
    resolved: number;
  };
  recommendations: string[];
}

interface ComplianceReportProps {
  userId: string;
}

const ragColors: Record<string, string> = {
  compliant: 'text-emerald-400',
  lodged: 'text-blue-400',
  pending: 'text-yellow-400',
  in_progress: 'text-cba-gold',
  overdue: 'text-red-400',
};

export function ComplianceReport({ userId }: ComplianceReportProps) {
  const [report, setReport] = useState<ReportData | null>(null);
  const [loading, setLoading] = useState(false);
  const [copied, setCopied] = useState(false);
  const [periodType, setPeriodType] = useState<'quarter' | 'year'>('quarter');
  const [includeRecommendations, setIncludeRecommendations] = useState(true);

