              <option value="year">Full Financial Year</option>
            </select>
          </div>

          <label htmlFor="compli-f2" className="flex items-center gap-2 cursor-pointer">
            <input id="compli-f2"
              type="checkbox"
              checked={includeRecommendations}
              onChange={(e) => setIncludeRecommendations(e.target.checked)}
