          </div>

          {/* Recommendations */}
          {report.recommendations && report.recommendations.length > 0 && (
            <div>
              <h4 className="text-primary font-bold text-sm mb-3">Recommendations</h4>
              <ul className="space-y-2">
                {report.recommendations.map((rec, i) => (
                  <li key={`item-${i}`} className="flex items-start gap-2 text-sm text-secondary">
                    <span className="text-cba-gold font-bold mt-0.5">{i + 1}.</span>
                    <span>{rec}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function formatReportText(report: ReportData): string {
  const lines: string[] = [
    report.title || 'Compliance Report',
    `Period: ${report.period}`,
    `Generated: ${new Date(report.generatedAt).toLocaleString('en-AU')}`,
    '',
    '== Summary ==',
    `Total: ${report.summary.totalObligations} | Compliant: ${report.summary.compliant} | Overdue: ${report.summary.overdue} | Rate: ${Math.round(report.summary.complianceRate)}%`,
    '',
    '== Obligations ==',
    ...report.obligations.map(
      (o) =>
        `${o.type} | ${o.period} | Due: ${new Date(o.dueDate).toLocaleDateString('en-AU')} | ${o.status} | ${o.riskLevel}`,
    ),
    '',
    '== Anomalies ==',
    `Total: ${report.anomalySummary.totalAlerts} | Critical: ${report.anomalySummary.critical} | High: ${report.anomalySummary.high} | Resolved: ${report.anomalySummary.resolved}`,
  ];
  if (report.recommendations?.length) {
    lines.push('', '== Recommendations ==');
    report.recommendations.forEach((r, i) => lines.push(`${i + 1}. ${r}`));
  }
  return lines.join('\n');
}

import { useState, useEffect } from 'react';
import { complianceApi } from '../../../api';
import { CheckCircle, Clock, AlertTriangle, Filter, Plus, Loader2 } from 'lucide-react';
import { cn } from '../../../lib/utils';

interface Obligation {
  id: string;
  type: string;
  period: string;
  dueDate: string;
  status: 'compliant' | 'pending' | 'overdue' | 'lodged' | 'in_progress';
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  description?: string;
}

interface ObligationTrackerProps {
  userId: string;
}

const statusConfig: Record<string, { label: string; color: string; bg: string }> = {
  compliant: {
    label: 'Compliant',
    color: 'text-emerald-400',
    bg: 'bg-emerald-400/10 border-emerald-400/30',
  },
  pending: {
    label: 'Pending',
    color: 'text-yellow-400',
    bg: 'bg-yellow-400/10 border-yellow-400/30',
  },
  overdue: { label: 'Overdue', color: 'text-red-400', bg: 'bg-red-400/10 border-red-400/30' },
  lodged: { label: 'Lodged', color: 'text-blue-400', bg: 'bg-blue-400/10 border-blue-400/30' },
  in_progress: {
    label: 'In Progress',
    color: 'text-cba-gold',
    bg: 'bg-cba-gold/10 border-cba-gold/30',
  },
};

const riskColors: Record<string, string> = {
  low: 'text-emerald-400',
  medium: 'text-yellow-400',
  high: 'text-orange-400',
  critical: 'text-red-400',
};

export function ObligationTracker({ userId }: ObligationTrackerProps) {
  const [obligations, setObligations] = useState<Obligation[]>([]);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilter] = useState<string>('all');
  const [generating, setGenerating] = useState(false);

  useEffect(() => {
    loadObligations();
  }, [userId]);

  const loadObligations = async () => {
    try {
      setLoading(true);
      const data = await complianceApi.obligations(userId);
      setObligations(data.obligations ?? data ?? []);
    } catch (e) {
      console.error('Failed to load obligations', e);
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateSchedule = async () => {
    try {
      setGenerating(true);
      await complianceApi.generateSchedule(userId, { financialYear: '2025-2026' });
      await loadObligations();
    } catch (e) {
      console.error('Failed to generate schedule', e);
    } finally {
      setGenerating(false);
    }
  };

  const handleLodge = async (checkId: string) => {
    try {
      await complianceApi.lodge(checkId, {
        lodgedDate: new Date().toISOString(),
        lodgedBy: userId,
      });
      await loadObligations();
    } catch (e) {
      console.error('Failed to lodge', e);
    }
  };

  const filtered =
    statusFilter === 'all' ? obligations : obligations.filter((o) => o.status === statusFilter);

  const isOverdue = (o: Obligation) =>
    o.status === 'overdue' || (o.status === 'pending' && new Date(o.dueDate) < new Date());

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-8 w-8 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Controls */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="flex items-center gap-2 neu-inset px-3 py-2 rounded-xl">
          <Filter className="h-4 w-4 text-secondary" />
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="bg-transparent text-sm text-primary outline-none"
          >
            <option value="all">All Statuses</option>
            <option value="overdue">Overdue</option>
            <option value="pending">Pending</option>
            <option value="in_progress">In Progress</option>
            <option value="lodged">Lodged</option>
            <option value="compliant">Compliant</option>
          </select>
        </div>

        <button
          onClick={handleGenerateSchedule}
          disabled={generating}
          className="ml-auto flex items-center gap-2 px-4 py-2 rounded-xl bg-cba-gold text-base font-bold text-sm hover:bg-[#FFD633] transition-colors disabled:opacity-50"
        >
          {generating ? <Loader2 className="h-4 w-4 animate-spin" /> : <Plus className="h-4 w-4" />}
          Generate Schedule
        </button>
      </div>

      {/* Table */}
      <div className="neu-raised rounded-2xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-sm">
            <thead>
              <tr className="border-b border-border/50">
                <th className="text-left px-4 py-3 text-secondary font-semibold">Type</th>
                <th className="text-left px-4 py-3 text-secondary font-semibold">Period</th>
                <th className="text-left px-4 py-3 text-secondary font-semibold">Due Date</th>
                <th className="text-left px-4 py-3 text-secondary font-semibold">Status</th>
                <th className="text-left px-4 py-3 text-secondary font-semibold">Risk</th>
                <th className="text-right px-4 py-3 text-secondary font-semibold">Actions</th>
              </tr>
            </thead>
            <tbody>
              {filtered.length === 0 ? (
                <tr>
                  <td colSpan={6} className="px-4 py-8 text-center text-muted">
                    No obligations found. Generate a schedule to get started.
                  </td>
                </tr>
              ) : (
                filtered.map((ob) => {
                  const sc = statusConfig[ob.status] ?? statusConfig.pending;
                  return (
                    <tr
                      key={ob.id}
                      className={cn(
                        'border-b border-border/50 hover:bg-white/[0.02] transition-colors',
                        isOverdue(ob) && 'border-l-2 border-l-red-500',
                      )}
                    >
                      <td className="px-4 py-3 text-primary font-medium">{ob.type}</td>
                      <td className="px-4 py-3 text-secondary">{ob.period}</td>
                      <td className="px-4 py-3 text-secondary">
                        {new Date(ob.dueDate).toLocaleDateString('en-AU')}
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={cn(
                            'px-2 py-1 rounded-lg text-xs font-bold border',
                            sc.bg,
                            sc.color,
                          )}
                        >
                          {sc.label}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <span
                          className={cn(
                            'text-xs font-bold uppercase',
                            riskColors[ob.riskLevel] ?? 'text-secondary',
                          )}
                        >
                          {ob.riskLevel}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-right">
                        <div className="flex items-center justify-end gap-2">
                          {ob.status !== 'lodged' && ob.status !== 'compliant' && (
                            <button
                              onClick={() => handleLodge(ob.id)}
                              className="px-2 py-1 text-xs font-bold rounded-lg text-blue-400 hover:bg-blue-400/10 transition-colors"
                            >
                              Mark Lodged
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { complianceApi } from '../../../api';
import { RefreshCw, Loader2, TrendingDown, AlertTriangle, Clock, FileX } from 'lucide-react';
import { cn } from '../../../lib/utils';

interface RiskAssessment {
  overallScore: number;
  factors: {
    overdueObligations: { score: number; weight: number; details: string };
    lateHistory: { score: number; weight: number; details: string };
    anomalyCount: { score: number; weight: number; details: string };
    outstandingActions: { score: number; weight: number; details: string };
  };
  recommendations: string[];
}

interface RiskAssessmentPanelProps {
  userId: string;
}

function scoreColor(score: number): string {
  if (score <= 30) return '#4ade80'; // green
  if (score <= 60) return '#facc15'; // yellow
  if (score <= 80) return '#fb923c'; // orange
  return '#f87171'; // red
}

function scoreLabel(score: number): string {
  if (score <= 30) return 'Low Risk';
  if (score <= 60) return 'Moderate Risk';
  if (score <= 80) return 'High Risk';
  return 'Critical Risk';
}

const factorIcons: Record<string, typeof AlertTriangle> = {
  overdueObligations: FileX,
  lateHistory: Clock,
  anomalyCount: AlertTriangle,
  outstandingActions: TrendingDown,
};

const factorLabels: Record<string, string> = {
  overdueObligations: 'Overdue Obligations',
  lateHistory: 'Late History',
  anomalyCount: 'Anomalies',
  outstandingActions: 'Outstanding Actions',
};

export function RiskAssessmentPanel({ userId }: RiskAssessmentPanelProps) {
  const [risk, setRisk] = useState<RiskAssessment | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadRisk();
  }, [userId]);

  const loadRisk = async () => {
    try {
      setLoading(true);
      const data = await complianceApi.risk(userId);
      setRisk(data);
    } catch (e) {
      console.error('Failed to load risk assessment', e);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-8 w-8 animate-spin text-cba-gold" />
      </div>
    );
  }

  const score = risk?.overallScore ?? 0;
  const color = scoreColor(score);
  const circumference = 2 * Math.PI * 70;
  const dashoffset = circumference - (score / 100) * circumference;

  return (
    <div className="space-y-6">
      {/* Header with refresh */}
      <div className="flex items-center justify-end">
        <button
          onClick={loadRisk}
          className="flex items-center gap-2 px-4 py-2 rounded-xl neu-raised-sm text-secondary hover:text-cba-gold text-sm font-bold transition-colors"
        >
          <RefreshCw className="h-4 w-4" />
          Refresh
        </button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Gauge */}
        <div className="neu-raised rounded-2xl p-6 flex flex-col items-center justify-center">
          <svg width="180" height="180" viewBox="0 0 180 180" className="mb-4">
            {/* Background ring */}
            <circle
              cx="90"
              cy="90"
              r="70"
              fill="none"
              stroke="rgba(255,255,255,0.05)"
              strokeWidth="12"
            />
            {/* Score ring */}
            <circle
              cx="90"
              cy="90"
              r="70"
              fill="none"
              stroke={color}
              strokeWidth="12"
              strokeLinecap="round"
              strokeDasharray={circumference}
              strokeDashoffset={dashoffset}
              transform="rotate(-90 90 90)"
              style={{ transition: 'stroke-dashoffset 1s ease-in-out, stroke 0.5s' }}
            />
            {/* Score text */}
            <text x="90" y="82" textAnchor="middle" fill={color} fontSize="36" fontWeight="bold">
              {score}
            </text>
            <text x="90" y="105" textAnchor="middle" fill="rgb(161,161,170)" fontSize="12">
              {scoreLabel(score)}
            </text>
          </svg>
          <p className="text-muted text-xs text-center">
            Risk score: 0 (safest) to 100 (critical)
          </p>
        </div>

        {/* Factor Cards */}
        <div className="space-y-3">
          {risk?.factors &&
            Object.entries(risk.factors).map(([key, factor]) => {
              const Icon = factorIcons[key] ?? AlertTriangle;
              const factorColor = scoreColor(factor.score);
              return (
                <div key={key} className="neu-raised rounded-xl p-4 flex items-center gap-4">
                  <div className="neu-inset p-2 rounded-xl" style={{ color: factorColor }}>
                    <Icon className="h-5 w-5" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center justify-between mb-1">
                      <span className="text-primary text-sm font-bold">
                        {factorLabels[key] ?? key}
                      </span>
                      <span className="text-xs text-muted font-medium">
                        Weight: {Math.round(factor.weight * 100)}%
                      </span>
                    </div>
                    <div className="w-full h-2 rounded-full bg-overlay overflow-hidden">
                      <div
                        className="h-full rounded-full transition-all duration-700"
                        style={{ width: `${factor.score}%`, backgroundColor: factorColor }}
                      />
                    </div>
                    <p className="text-muted text-[11px] mt-1">{factor.details}</p>
                  </div>
                  <span className="text-lg font-bold tabular-nums" style={{ color: factorColor }}>
                    {factor.score}
                  </span>
                </div>
              );
            })}
        </div>
      </div>

      {/* Recommendations */}
      {risk?.recommendations && risk.recommendations.length > 0 && (
        <div className="neu-raised rounded-2xl p-4">
          <h4 className="text-primary font-bold text-sm mb-3">Recommendations</h4>
          <ul className="space-y-2">
            {risk.recommendations.map((rec, i) => (
              <li key={i} className="flex items-start gap-2 text-sm text-secondary">
                <span className="text-cba-gold font-bold mt-0.5">{i + 1}.</span>
                <span>{rec}</span>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}

