interface WidgetPickerProps {
  open: boolean;
  onClose: () => void;
  onSelect: (widget: WidgetConfig) => void;
}

export function WidgetPicker({ open, onClose, onSelect }: WidgetPickerProps) {
  if (!open) return null;

  const handleSelect = (wt: WidgetType) => {
    const widget: WidgetConfig = {
      id: `widget-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      chartType: wt.chartType,
      title: wt.name,
      position: { col: 0, row: 0, width: 6, height: 4 },
      config: { ...wt.defaultConfig },
    };
    onSelect(widget);
    onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative neu-raised rounded-2xl w-full max-w-2xl mx-4 max-h-[80vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="flex items-center justify-between p-5 border-b border-cba-gold/20 shrink-0">
          <h3 className="text-lg font-bold text-gradient-gold">Add Widget</h3>
          <button
            onClick={onClose}
            className="p-1.5 rounded-lg text-secondary hover:text-primary hover:bg-overlay-hover transition-colors"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        {/* Widget Types Grid */}
        <div className="p-5 overflow-y-auto">
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {WIDGET_TYPES.map((wt) => (
              <button
                key={wt.chartType}
                onClick={() => handleSelect(wt)}
                className={cn(
                  'neu-raised-sm rounded-xl p-4 text-left border border-transparent',
                  'hover:border-cba-gold/30 hover:shadow-[0_0_15px_rgba(255,204,0,0.08)]',
                  'transition-all duration-200 group',
                )}
              >
                <div className="flex items-center gap-3 mb-2">
                  <div className="neu-inset p-2 rounded-lg text-cba-gold group-hover:shadow-[0_0_10px_rgba(255,204,0,0.15)] transition-shadow">
                    <wt.icon className="w-5 h-5" />
                  </div>
                  <h4 className="font-bold text-zinc-100 text-sm">{wt.name}</h4>
                </div>
                <p className="text-xs text-muted leading-relaxed">{wt.description}</p>
              </button>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  ArrowLeft,
  RefreshCw,
  Search,
  Trash2,
  Loader2,
  ExternalLink,
  CheckCircle,
  XCircle,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { documentsApi } from '@/api';
import type { OCRDocument } from '@/api';
import { LineItemEditor } from './LineItemEditor';

interface DocumentViewerProps {
  documentId: string;
  onBack: () => void;
}

function statusBadge(status: string) {
  switch (status) {
    case 'extracted':
    case 'verified':
      return <Badge variant="success">{status}</Badge>;
    case 'processing':
      return (
        <Badge variant="warning" className="animate-pulse">
          {status}
        </Badge>
      );
    case 'pending':
      return <Badge variant="secondary">{status}</Badge>;
    case 'matched':
      return <Badge>{status}</Badge>;
    case 'failed':
      return <Badge variant="destructive">{status}</Badge>;
    default:
      return <Badge variant="secondary">{status}</Badge>;
  }
}

function confidenceColor(score: number) {
  if (score > 80) return 'text-green-400';
  if (score > 50) return 'text-amber-400';
  return 'text-red-400';
}

function confidenceBarColor(score: number) {
  if (score > 80) return '[&_[role=progressbar]>div]:bg-green-500';
  if (score > 50) return '[&_[role=progressbar]>div]:bg-amber-500';
  return '[&_[role=progressbar]>div]:bg-red-500';
}

function formatCurrency(amount: number | undefined | null) {
  if (amount == null) return '-';
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(
    amount / 100,
  );
}

export function DocumentViewer({ documentId, onBack }: DocumentViewerProps) {
  const [doc, setDoc] = useState<OCRDocument | null>(null);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [showRawData, setShowRawData] = useState(false);

  const loadDocument = async () => {
    setLoading(true);
    try {
      const data = await documentsApi.get(documentId);
      setDoc(data);
    } catch (err) {
      console.error('Failed to load document', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadDocument();
  }, [documentId]);

  const handleReprocess = async () => {
    setProcessing(true);
    try {
      await documentsApi.process(documentId);
      await loadDocument();
    } catch (err) {
      console.error('Failed to reprocess', err);
    } finally {
      setProcessing(false);
    }
  };

  const handleClassify = async () => {
    setProcessing(true);
    try {
      await documentsApi.classify(documentId);
      await loadDocument();
    } catch (err) {
      console.error('Failed to classify', err);
    } finally {
      setProcessing(false);
    }
  };

  const handleDelete = async () => {
    try {
      await documentsApi.delete(documentId);
      onBack();
    } catch (err) {
      console.error('Failed to delete', err);
    }
  };

  if (loading) {
    return (
      <div className="neu-raised rounded-xl p-12 flex items-center justify-center">
        <Loader2 className="h-8 w-8 text-cba-gold animate-spin" />
      </div>
    );
  }

  if (!doc) {
    return (
      <div className="neu-raised rounded-xl p-8 text-center">
        <XCircle className="h-12 w-12 text-red-400 mx-auto mb-3" />
        <p className="text-secondary">Document not found</p>
        <button
          onClick={onBack}
          className="mt-4 px-4 py-2 rounded-lg bg-overlay text-primary hover:bg-overlay-hover text-sm"
        >
          Go back
        </button>
      </div>
    );
  }

  const gstValid =
    doc.subtotal != null && doc.gstAmount != null && doc.totalAmount != null
      ? Math.abs(doc.subtotal + doc.gstAmount - doc.totalAmount) < 2
      : null;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button
            onClick={onBack}
            className="neu-raised p-2 rounded-xl text-secondary hover:text-primary transition-colors"
          >
            <ArrowLeft className="h-5 w-5" />
          </button>
          <div>
            <h2 className="text-lg font-bold text-zinc-100">{doc.fileName}</h2>
            <div className="flex items-center gap-2 mt-0.5">
              {statusBadge(doc.status)}
              <span className="text-xs text-muted">{doc.mimeType}</span>
              <span className="text-xs text-muted">
                {new Date(doc.createdAt).toLocaleDateString()}
              </span>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={handleReprocess}
            disabled={processing}
            className="flex items-center gap-1.5 px-3 py-2 rounded-lg neu-raised text-sm font-semibold text-primary hover:text-cba-gold transition-colors disabled:opacity-50"
          >
            <RefreshCw className={`h-4 w-4 ${processing ? 'animate-spin' : ''}`} />
            Re-process
          </button>
          <button
            onClick={handleClassify}
            disabled={processing}
            className="flex items-center gap-1.5 px-3 py-2 rounded-lg neu-raised text-sm font-semibold text-primary hover:text-blue-400 transition-colors disabled:opacity-50"
          >
            <Search className="h-4 w-4" />
            Classify
          </button>
          <button
            onClick={handleDelete}
            className="flex items-center gap-1.5 px-3 py-2 rounded-lg neu-raised text-sm font-semibold text-primary hover:text-red-400 transition-colors"
          >
            <Trash2 className="h-4 w-4" />
            Delete
          </button>
        </div>
      </div>

      {/* Two Column Layout */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Left: Metadata */}
        <div className="space-y-4">
          {/* Document Info */}
          <div className="neu-raised rounded-xl p-5">
            <h3 className="text-sm font-bold text-cba-gold uppercase tracking-wide mb-3">
              Document Info
            </h3>
            <div className="grid grid-cols-2 gap-3 text-sm">
              <div>
                <p className="text-muted text-xs">Type</p>
                <p className="text-primary font-medium capitalize">
                  {doc.documentType || 'Unknown'}
                </p>
              </div>
              <div>
                <p className="text-muted text-xs">Document Number</p>
                <p className="text-primary font-medium">{doc.documentNumber || '-'}</p>
              </div>
              <div>
                <p className="text-muted text-xs">Document Date</p>
                <p className="text-primary font-medium">{doc.documentDate || '-'}</p>
              </div>
              <div>
                <p className="text-muted text-xs">Due Date</p>
                <p className="text-primary font-medium">{doc.dueDate || '-'}</p>
              </div>
            </div>
          </div>

          {/* Vendor Info */}
          <div className="neu-raised rounded-xl p-5">
            <h3 className="text-sm font-bold text-cba-gold uppercase tracking-wide mb-3">
              Vendor
            </h3>
            <div className="space-y-2 text-sm">
              <div>
                <p className="text-muted text-xs">Name</p>
                <p className="text-primary font-medium">{doc.vendorName || '-'}</p>
              </div>
              <div>
                <p className="text-muted text-xs">ABN</p>
                <div className="flex items-center gap-2">
                  <p className="text-primary font-medium">{doc.vendorAbn || '-'}</p>
                  {doc.vendorAbn && (
                    <a
                      href={`https://abr.business.gov.au/ABN/View?abn=${doc.vendorAbn}`}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="text-cba-gold hover:text-cba-gold/80"
                    >
                      <ExternalLink className="h-3 w-3" />
                    </a>
                  )}
                </div>
              </div>
            </div>
          </div>

          {/* GST Summary */}
          <div className="neu-raised rounded-xl p-5">
            <h3 className="text-sm font-bold text-cba-gold uppercase tracking-wide mb-3">
              Amounts
            </h3>
            <div className="space-y-2">
              <div className="flex justify-between text-sm">
                <span className="text-muted">Subtotal</span>
                <span className="text-primary font-medium">{formatCurrency(doc.subtotal)}</span>
              </div>
              <div className="flex justify-between text-sm">
                <span className="text-muted">GST</span>
                <span className="text-primary font-medium">{formatCurrency(doc.gstAmount)}</span>
              </div>
              <div className="border-t border-border/50 pt-2 flex justify-between text-sm">
                <span className="text-primary font-semibold">Total</span>
                <div className="flex items-center gap-2">
                  <span className="text-zinc-100 font-bold">{formatCurrency(doc.totalAmount)}</span>
                  {gstValid !== null &&
                    (gstValid ? (
                      <CheckCircle className="h-4 w-4 text-green-400" />
                    ) : (
                      <XCircle className="h-4 w-4 text-red-400" />
                    ))}
                </div>
              </div>
            </div>
          </div>

          {/* Confidence */}
          <div className="neu-raised rounded-xl p-5">
            <h3 className="text-sm font-bold text-cba-gold uppercase tracking-wide mb-3">
              Confidence
            </h3>
            <div className="flex items-center gap-3">
              <Progress value={doc.confidenceScore} className="flex-1 h-2.5" />
              <span className={`text-sm font-bold ${confidenceColor(doc.confidenceScore)}`}>
                {doc.confidenceScore}%
              </span>
            </div>
          </div>

          {doc.errorMessage && (
            <div className="neu-raised rounded-xl p-5 border border-red-500/20">
              <h3 className="text-sm font-bold text-red-400 uppercase tracking-wide mb-2">Error</h3>
              <p className="text-sm text-red-300">{doc.errorMessage}</p>
            </div>
          )}
        </div>

        {/* Right: Extracted Data */}
        <div className="space-y-4">
          <div className="neu-raised rounded-xl p-5">
            <div className="flex items-center justify-between mb-3">
              <h3 className="text-sm font-bold text-cba-gold uppercase tracking-wide">
                Extracted Data
              </h3>
              <button
                onClick={() => setShowRawData(!showRawData)}
                className="text-xs px-2 py-1 rounded-md bg-overlay text-secondary hover:text-primary transition-colors"
              >
                {showRawData ? 'Hide JSON' : 'Show JSON'}
              </button>
            </div>
            {showRawData && doc.extractedData ? (
              <div className="neu-inset rounded-lg p-4 overflow-auto max-h-96">
                <pre className="text-xs text-primary whitespace-pre-wrap font-mono">
                  {JSON.stringify(doc.extractedData, null, 2)}
                </pre>
              </div>
            ) : !doc.extractedData ? (
              <div className="neu-inset rounded-lg p-6 text-center">
                <p className="text-muted text-sm">No extracted data available</p>
                <p className="text-zinc-600 text-xs mt-1">Process the document to extract data</p>
              </div>
            ) : (
              <div className="neu-inset rounded-lg p-4">
                <p className="text-secondary text-sm">
                  Data extracted successfully. Click &quot;Show JSON&quot; to view raw data.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Line Items */}
      <div className="neu-raised rounded-xl p-5">
        <h3 className="text-sm font-bold text-cba-gold uppercase tracking-wide mb-4">
          Line Items
        </h3>
        <LineItemEditor documentId={documentId} />
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  FileText,
  FileUp,
  Clock,
  CheckCircle,
  XCircle,
  AlertTriangle,
  Loader2,
  FileScan,
  Eye,
  Trash2,
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { documentsApi } from '@/api';
import type { OCRDocument } from '@/api';
import { DocumentUpload } from './DocumentUpload';
import { DocumentViewer } from './DocumentViewer';
import { ProcessingQueue } from './ProcessingQueue';

type SubTab = 'all' | 'upload' | 'queue';

const STATUS_FILTERS = [
  '',
  'pending',
  'processing',
  'extracted',
  'verified',
  'matched',
  'failed',
] as const;
const DOC_TYPE_FILTERS = ['', 'invoice', 'receipt', 'bill', 'credit_note', 'statement'] as const;

function statusBadge(status: string) {
  switch (status) {
    case 'extracted':
    case 'verified':
      return (
        <span className="px-2 py-1 rounded-full text-xs bg-green-500/20 text-green-400">
          {status}
        </span>
      );
    case 'processing':
      return (
        <span className="px-2 py-1 rounded-full text-xs bg-blue-500/20 text-blue-400 animate-pulse">
          {status}
        </span>
      );
    case 'pending':
      return (
        <span className="px-2 py-1 rounded-full text-xs bg-zinc-500/20 text-secondary">
          {status}
        </span>
      );
    case 'matched':
      return (
        <span className="px-2 py-1 rounded-full text-xs bg-cba-gold/20 text-cba-gold">
          {status}
        </span>
      );
    case 'failed':
      return (
        <span className="px-2 py-1 rounded-full text-xs bg-red-500/20 text-red-400">{status}</span>
      );
    default:
      return (
        <span className="px-2 py-1 rounded-full text-xs bg-zinc-500/20 text-secondary">
          {status}
        </span>
      );
  }
}

function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function formatCurrency(amount: number | undefined | null) {
  if (amount == null) return '-';
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(
    amount / 100,
  );
}

export function DocumentsDashboard() {
  const [documents, setDocuments] = useState<OCRDocument[]>([]);
  const [loading, setLoading] = useState(false);
  const [subTab, setSubTab] = useState<SubTab>('all');
  const [statusFilter, setStatusFilter] = useState('');
  const [docTypeFilter, setDocTypeFilter] = useState('');
  const [selectedDocId, setSelectedDocId] = useState<string | null>(null);

  const loadDocuments = useCallback(async () => {
    setLoading(true);
    try {
      const data = await documentsApi.list(statusFilter || undefined, docTypeFilter || undefined);
      setDocuments(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('Failed to load documents', err);
      setDocuments([]);
    } finally {
      setLoading(false);
    }
  }, [statusFilter, docTypeFilter]);

  useEffect(() => {
    loadDocuments();
  }, [loadDocuments]);

  const handleDelete = async (id: string) => {
    try {
      await documentsApi.delete(id);
      loadDocuments();
    } catch (err) {
      console.error('Failed to delete document', err);
    }
  };

  if (selectedDocId) {
    return (
      <DocumentViewer
        documentId={selectedDocId}
        onBack={() => {
          setSelectedDocId(null);
          loadDocuments();
        }}
      />
    );
  }

  const totalDocs = documents.length;
  const pendingCount = documents.filter((d) => d.status === 'pending').length;
  const extractedCount = documents.filter(
    (d) => d.status === 'extracted' || d.status === 'verified',
  ).length;
  const matchedCount = documents.filter((d) => d.status === 'matched').length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="neu-inset p-2 rounded-xl text-rose-400">
            <FileScan className="h-6 w-6" />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-gradient-gold">Documents</h1>
            <p className="text-sm text-muted">OCR processing, invoices & receipts</p>
          </div>
        </div>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Total Documents', value: totalDocs, icon: FileText, color: 'text-primary' },
          { label: 'Pending OCR', value: pendingCount, icon: Clock, color: 'text-amber-400' },
          { label: 'Extracted', value: extractedCount, icon: CheckCircle, color: 'text-green-400' },
          { label: 'Matched', value: matchedCount, icon: CheckCircle, color: 'text-cba-gold' },
        ].map((stat) => (
          <div key={stat.label} className="neu-raised rounded-xl p-4">
            <div className="flex items-center gap-2 mb-1">
              <stat.icon className={`h-4 w-4 ${stat.color}`} />
              <span className="text-xs text-muted uppercase tracking-wide">{stat.label}</span>
            </div>
            <p className={`text-2xl font-bold ${stat.color}`}>{stat.value}</p>
          </div>
        ))}
      </div>

      {/* Sub-tabs */}
      <div className="flex gap-2">
        {[
          { id: 'all' as SubTab, label: 'All Documents', icon: FileText },
          { id: 'upload' as SubTab, label: 'Upload', icon: FileUp },
          { id: 'queue' as SubTab, label: 'Queue', icon: Clock },
        ].map((tab) => (
          <button
            key={tab.id}
            onClick={() => setSubTab(tab.id)}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all ${
              subTab === tab.id
                ? 'bg-cba-gold text-base'
                : 'neu-raised text-secondary hover:text-zinc-100'
            }`}
          >
            <tab.icon className="h-4 w-4" />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Sub-tab content */}
      {subTab === 'upload' && <DocumentUpload onUploadComplete={loadDocuments} />}

      {subTab === 'queue' && <ProcessingQueue />}

      {subTab === 'all' && (
        <div className="space-y-4">
          {/* Filters */}
          <div className="neu-raised rounded-xl p-4 flex flex-wrap gap-3 items-center">
            <span className="text-xs font-bold text-muted uppercase tracking-wide">Status:</span>
            <div className="flex gap-1 flex-wrap">
              {STATUS_FILTERS.map((s) => (
                <button
                  key={s}
                  onClick={() => setStatusFilter(s)}
                  className={`px-3 py-1 rounded-full text-xs font-semibold transition-all ${
                    statusFilter === s
                      ? 'bg-cba-gold text-base'
                      : 'bg-overlay text-secondary hover:bg-overlay-hover'
                  }`}
                >
                  {s || 'All'}
                </button>
              ))}
            </div>
            <span className="text-xs font-bold text-muted uppercase tracking-wide ml-4">
              Type:
            </span>
            <div className="flex gap-1 flex-wrap">
              {DOC_TYPE_FILTERS.map((t) => (
                <button
                  key={t}
                  onClick={() => setDocTypeFilter(t)}
                  className={`px-3 py-1 rounded-full text-xs font-semibold transition-all ${
                    docTypeFilter === t
                      ? 'bg-cba-gold text-base'
                      : 'bg-overlay text-secondary hover:bg-overlay-hover'
                  }`}
                >
                  {t || 'All'}
                </button>
              ))}
            </div>
          </div>

          {/* Document List */}
          {loading ? (
            <div className="neu-raised rounded-xl p-12 flex items-center justify-center">
              <Loader2 className="h-8 w-8 text-cba-gold animate-spin" />
            </div>
          ) : documents.length === 0 ? (
            <div className="neu-raised rounded-xl p-12 text-center">
              <FileText className="h-12 w-12 text-zinc-600 mx-auto mb-3" />
              <p className="text-secondary font-medium">No documents found</p>
              <p className="text-zinc-600 text-sm mt-1">
                Upload invoices, receipts, or bills to get started
              </p>
            </div>
          ) : (
            <div className="space-y-2">
              {documents.map((doc) => (
                <div
                  key={doc.id}
                  className="neu-raised rounded-xl p-4 hover:border-cba-gold/20 border border-transparent transition-colors cursor-pointer"
                  onClick={() => setSelectedDocId(doc.id)}
                >
                  <div className="flex items-center justify-between gap-4">
                    <div className="flex items-center gap-3 min-w-0">
                      <div className="neu-inset p-2 rounded-lg shrink-0">
                        <FileText className="h-5 w-5 text-secondary" />
                      </div>
                      <div className="min-w-0">
                        <p className="font-semibold text-zinc-100 truncate">{doc.fileName}</p>
                        <div className="flex items-center gap-2 text-xs text-muted mt-0.5">
                          <span>{formatBytes(doc.fileSize)}</span>
                          <span>-</span>
                          <span>{doc.documentType || 'Unknown'}</span>
                          {doc.vendorName && (
                            <>
                              <span>-</span>
                              <span className="text-primary">{doc.vendorName}</span>
                            </>
                          )}
                        </div>
                      </div>
                    </div>
                    <div className="flex items-center gap-3 shrink-0">
                      {doc.totalAmount != null && (
                        <span className="text-sm font-bold text-primary">
                          {formatCurrency(doc.totalAmount)}
                        </span>
                      )}
                      {statusBadge(doc.status)}
                      {doc.confidenceScore > 0 && (
                        <Badge
                          variant={
                            doc.confidenceScore > 80
                              ? 'success'
                              : doc.confidenceScore > 50
                                ? 'warning'
                                : 'destructive'
                          }
                        >
                          {doc.confidenceScore}%
                        </Badge>
                      )}
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedDocId(doc.id);
                        }}
                        className="p-1.5 rounded-lg hover:bg-overlay-hover text-secondary hover:text-primary transition-colors"
                        title="View"
                      >
                        <Eye className="h-4 w-4" />
                      </button>
                      <button
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDelete(doc.id);
                        }}
                        className="p-1.5 rounded-lg hover:bg-red-500/10 text-secondary hover:text-red-400 transition-colors"
                        title="Delete"
                      >
                        <Trash2 className="h-4 w-4" />
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useState, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Skeleton } from '@/components/ui/skeleton';
import { Layers, Play, Lock, TrendingUp, TrendingDown, Minus, Loader2 } from 'lucide-react';
import { consolidationApi } from '@/api';
import type {
  EntityWithDetails,
  ConsolidationDetailResponse,
  ConsolidationSnapshotData,
} from '@/api';
import { toast } from 'sonner';

function formatMoney(cents: number): string {
  return new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);
}

const SNAPSHOT_STATUS_COLORS: Record<string, string> = {
  draft: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
  reviewed: 'bg-blue-500/20 text-blue-400 border-blue-500/30',
  finalized: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
};

interface ConsolidationViewProps {
  entities: EntityWithDetails[];
  financialYear: string;
}

export function ConsolidationView({ entities, financialYear }: ConsolidationViewProps) {
  const [generating, setGenerating] = useState(false);
  const [detail, setDetail] = useState<ConsolidationDetailResponse | null>(null);
  const [snapshots, setSnapshots] = useState<ConsolidationSnapshotData[]>([]);
  const [snapshotsLoaded, setSnapshotsLoaded] = useState(false);
  const [selectedParentId, setSelectedParentId] = useState<string>('');
  const [finalizing, setFinalizing] = useState<string | null>(null);

  const consolidatedParents = entities.filter((e) => e.isConsolidatedParent);

  const handleGenerate = useCallback(async () => {
    if (!selectedParentId) {
      toast.error('Select a parent entity first');
      return;
    }
    setGenerating(true);
    try {
      const result = await consolidationApi.generate(selectedParentId, financialYear);
      setDetail(result);
      toast.success('Consolidation generated successfully');
      // Refresh snapshots
      const snaps = await consolidationApi.getSnapshots(selectedParentId, financialYear);
      setSnapshots(snaps);
      setSnapshotsLoaded(true);
    } catch (err) {
      console.error('Failed to generate consolidation:', err);
      toast.error('Failed to generate consolidation');
    } finally {
      setGenerating(false);
    }
  }, [selectedParentId, financialYear]);

  const loadSnapshots = useCallback(async () => {
    if (!selectedParentId) return;
    try {
      const snaps = await consolidationApi.getSnapshots(selectedParentId, financialYear);
      setSnapshots(snaps);
      setSnapshotsLoaded(true);
    } catch (err) {
      console.error('Failed to load snapshots:', err);
    }
  }, [selectedParentId, financialYear]);

  const handleParentChange = (id: string) => {
    setSelectedParentId(id);
    setDetail(null);
    setSnapshotsLoaded(false);
  };

  const handleViewSnapshot = async (id: string) => {
    try {
      const result = await consolidationApi.getSnapshotDetail(id);
      setDetail(result);
    } catch (err) {
      console.error('Failed to load snapshot detail:', err);
      toast.error('Failed to load snapshot');
    }
  };

  const handleFinalize = async (id: string) => {
    setFinalizing(id);
    try {
      await consolidationApi.finalizeSnapshot(id);
      toast.success('Snapshot finalized');
      loadSnapshots();
    } catch (err) {
      console.error('Failed to finalize snapshot:', err);
      toast.error('Failed to finalize snapshot');
    } finally {
      setFinalizing(null);
    }
  };

  return (
    <div className="space-y-6">
      {/* Controls */}
      <div className="flex flex-wrap items-center gap-3">
        <Select value={selectedParentId} onValueChange={handleParentChange}>
          <SelectTrigger className="w-[220px]">
            <SelectValue placeholder="Select parent entity" />
          </SelectTrigger>
          <SelectContent>
            {consolidatedParents.length === 0 ? (
              <SelectItem value="__none" disabled>
                No consolidated parents
              </SelectItem>
            ) : (
              consolidatedParents.map((e) => (
                <SelectItem key={e.id} value={e.id}>
                  {e.name}
                </SelectItem>
              ))
            )}
          </SelectContent>
        </Select>
        <Button
          onClick={handleGenerate}
          disabled={generating || !selectedParentId}
          className="bg-cba-gold text-base hover:bg-cba-gold/90 font-bold"
        >
          {generating ? (
            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
          ) : (
            <Play className="w-4 h-4 mr-2" />
          )}
          {generating ? 'Generating...' : 'Generate Consolidation'}
        </Button>
        {selectedParentId && !snapshotsLoaded && (
          <Button variant="outline" onClick={loadSnapshots}>
            Load History
          </Button>
        )}
      </div>

      {consolidatedParents.length === 0 && (
        <Card className="neu-raised border-0">
          <CardContent className="p-8 text-center">
            <Layers className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
            <h3 className="text-lg font-bold text-primary mb-1">No Consolidated Parents</h3>
            <p className="text-sm text-muted">
              Mark an entity as "Consolidated Parent" to enable group consolidation
            </p>
          </CardContent>
        </Card>
      )}

      {/* Consolidation Detail */}
      {detail && (
        <div className="space-y-4">
          {/* Consolidated Totals */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <TrendingUp className="w-4 h-4 text-emerald-400" />
                  Total Revenue
                </div>
                <p className="text-xl font-bold text-emerald-400">
                  {formatMoney(detail.consolidatedTotals.revenue)}
                </p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <TrendingDown className="w-4 h-4 text-red-400" />
                  Total Expenses
                </div>
                <p className="text-xl font-bold text-red-400">
                  {formatMoney(detail.consolidatedTotals.expenses)}
                </p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <Minus className="w-4 h-4 text-cba-gold" />
                  Net Profit
                </div>
                <p
                  className={`text-xl font-bold ${detail.consolidatedTotals.netProfit >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                >
                  {formatMoney(detail.consolidatedTotals.netProfit)}
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Balance Sheet Summary */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <p className="text-xs text-muted mb-1">Total Assets</p>
                <p className="text-lg font-bold text-zinc-100">
                  {formatMoney(detail.consolidatedTotals.assets)}
                </p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <p className="text-xs text-muted mb-1">Total Liabilities</p>
                <p className="text-lg font-bold text-zinc-100">
                  {formatMoney(detail.consolidatedTotals.liabilities)}
                </p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <p className="text-xs text-muted mb-1">Total Equity</p>
                <p className="text-lg font-bold text-zinc-100">
                  {formatMoney(detail.consolidatedTotals.equity)}
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Per-Entity Breakdown */}
          <Card className="neu-raised border-0">
            <CardHeader>
              <CardTitle className="text-sm font-bold text-primary">
                Per-Entity P&L Breakdown
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="border-b border-border/50 text-xs text-muted uppercase tracking-wide">
                      <th className="text-left py-2 pr-4">Entity</th>
                      <th className="text-right py-2 px-2">Revenue</th>
                      <th className="text-right py-2 px-2">Expenses</th>
                      <th className="text-right py-2 pl-2">Net</th>
                    </tr>
                  </thead>
                  <tbody>
                    {Object.entries(detail.byEntity).map(([entityId, rawData]) => {
                      const data = rawData as Record<string, unknown>;
                      const net = data.revenue - data.expenses;
                      return (
                        <tr key={entityId} className="border-b border-border/50">
                          <td className="py-2 pr-4 font-medium text-primary">{data.entityName}</td>
                          <td className="py-2 px-2 text-right text-emerald-400">
                            {formatMoney(data.revenue)}
                          </td>
                          <td className="py-2 px-2 text-right text-red-400">
                            {formatMoney(data.expenses)}
                          </td>
                          <td
                            className={`py-2 pl-2 text-right font-bold ${net >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                          >
                            {formatMoney(net)}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>

          {/* Eliminations */}
          {detail.eliminations.length > 0 && (
            <Card className="neu-raised border-0">
              <CardHeader>
                <CardTitle className="text-sm font-bold text-primary">
                  Elimination Entries
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-2">
                  {(detail.eliminations as Array<Record<string, unknown>>).map((elim, idx: number) => (
                    <div
                      key={idx}
                      className="flex items-center justify-between py-2 border-b border-border/50 last:border-0"
                    >
                      <span className="text-sm text-secondary">{elim.description}</span>
                      <span className="text-sm font-bold text-blue-400">
                        {formatMoney(elim.amount)}
                      </span>
                    </div>
                  ))}
                </div>
              </CardContent>
            </Card>
          )}
        </div>
      )}

      {/* Snapshot History */}
      {snapshotsLoaded && snapshots.length > 0 && (
        <Card className="neu-raised border-0">
          <CardHeader>
            <CardTitle className="text-sm font-bold text-primary">Snapshot History</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2">
              {snapshots.map((snap) => (
                <div
                  key={snap.id}
                  className="flex items-center justify-between py-2 border-b border-border/50 last:border-0"
                >
                  <div className="flex items-center gap-3">
                    <span className="text-sm text-secondary">
                      {new Date(snap.snapshotDate).toLocaleDateString('en-AU')}
                    </span>
                    <Badge variant="outline" className={SNAPSHOT_STATUS_COLORS[snap.status] ?? ''}>
                      {snap.status}
                    </Badge>
                    <span className="text-xs text-muted">FY {snap.financialYear}</span>
                  </div>
                  <div className="flex items-center gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleViewSnapshot(snap.id)}
                      className="h-7 text-xs"
                    >
                      View
                    </Button>
                    {snap.status === 'draft' && (
                      <Button
                        size="sm"
                        variant="outline"
                        onClick={() => handleFinalize(snap.id)}
                        disabled={finalizing === snap.id}
                        className="h-7 text-xs text-cba-gold border-cba-gold/30 hover:bg-cba-gold/10"
                      >
                        {finalizing === snap.id ? (
                          <Loader2 className="w-3 h-3 animate-spin" />
                        ) : (
                          <Lock className="w-3 h-3 mr-1" />
                        )}
                        Finalize
                      </Button>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Card, CardContent } from '@/components/ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Skeleton } from '@/components/ui/skeleton';
import { Building2, ArrowLeftRight, Layers, Settings, GitBranch, AlertCircle } from 'lucide-react';
import { entityApi } from '@/api';
import type { EntityHierarchyResponse, EntityData } from '@/api';
import { EntityHierarchyView } from './EntityHierarchyView';
import { InterEntityTransactionsView } from './InterEntityTransactionsView';
import { ConsolidationView } from './ConsolidationView';
import { EntitySettingsPanel } from './EntitySettingsPanel';

const FINANCIAL_YEARS = ['2023-24', '2024-25', '2025-26'];

export function EntitiesDashboard() {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [hierarchy, setHierarchy] = useState<EntityHierarchyResponse | null>(null);
  const [financialYear, setFinancialYear] = useState('2024-25');
  const [selectedEntityId, setSelectedEntityId] = useState<string>('all');

  const loadHierarchy = useCallback(async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await entityApi.getHierarchy();
      setHierarchy(result);
    } catch (err) {
      console.error('Failed to load entity hierarchy:', err);
      setError('Failed to load entities');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadHierarchy();
  }, [loadHierarchy]);

  const entities = hierarchy?.entities ?? [];
  const totalEntities = hierarchy?.totalEntities ?? 0;
  const linkedAccounts = entities.reduce((sum: number, e: Record<string, unknown>) => sum + ((e.accounts as unknown[])?.length ?? 0), 0);
  const consolidatedParents = entities.filter((e: Record<string, unknown>) => e.isConsolidatedParent).length;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
        <div>
          <h2 className="text-2xl font-bold tracking-tight text-gradient-gold">Entities</h2>
          <p className="text-sm text-muted">
            Multi-entity management, inter-entity transactions & consolidation
          </p>
        </div>
        <div className="flex items-center gap-3">
          <Select value={selectedEntityId} onValueChange={setSelectedEntityId}>
            <SelectTrigger className="w-[180px]">
              <SelectValue placeholder="All Entities" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Entities</SelectItem>
              {entities.map((e: Record<string, unknown>) => (
                <SelectItem key={e.id} value={e.id}>
                  {e.name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
          <Select value={financialYear} onValueChange={setFinancialYear}>
            <SelectTrigger className="w-[140px]">
              <SelectValue placeholder="FY" />
            </SelectTrigger>
            <SelectContent>
              {FINANCIAL_YEARS.map((fy) => (
                <SelectItem key={fy} value={fy}>
                  FY {fy}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {loading ? (
          <>
            {[1, 2, 3, 4].map((i) => (
              <Card key={i} className="neu-raised border-0">
                <CardContent className="p-4">
                  <Skeleton className="h-4 w-24 mb-2" />
                  <Skeleton className="h-8 w-16" />
                </CardContent>
              </Card>
            ))}
          </>
        ) : (
          <>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <Building2 className="w-4 h-4" />
                  Total Entities
                </div>
                <p className="text-2xl font-bold text-zinc-100">{totalEntities}</p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <GitBranch className="w-4 h-4" />
                  Linked Accounts
                </div>
                <p className="text-2xl font-bold text-zinc-100">{linkedAccounts}</p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <Layers className="w-4 h-4" />
                  Consolidated Groups
                </div>
                <p className="text-2xl font-bold text-zinc-100">{consolidatedParents}</p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-0">
              <CardContent className="p-4">
                <div className="flex items-center gap-2 text-muted text-sm mb-1">
                  <ArrowLeftRight className="w-4 h-4" />
                  FY Period
                </div>
                <p className="text-2xl font-bold text-cba-gold">{financialYear}</p>
              </CardContent>
            </Card>
          </>
        )}
      </div>

      {error && (
        <div className="neu-raised border border-red-500/20 rounded-xl p-4 flex items-center gap-3">
          <AlertCircle className="w-5 h-5 text-red-400 shrink-0" />
          <p className="text-sm text-red-400">{error}</p>
        </div>
      )}

      {/* Tabbed Content */}
      <Tabs defaultValue="hierarchy" className="space-y-4">
        <TabsList className="flex-wrap h-auto gap-1">
          <TabsTrigger value="hierarchy">
            <GitBranch className="w-4 h-4 mr-2" />
            Entity Hierarchy
          </TabsTrigger>
          <TabsTrigger value="inter-entity">
            <ArrowLeftRight className="w-4 h-4 mr-2" />
            Inter-Entity Txns
          </TabsTrigger>
          <TabsTrigger value="consolidation">
            <Layers className="w-4 h-4 mr-2" />
            Consolidation
          </TabsTrigger>
          <TabsTrigger value="settings">
            <Settings className="w-4 h-4 mr-2" />
            Settings
          </TabsTrigger>
        </TabsList>

        <TabsContent value="hierarchy">
          <EntityHierarchyView hierarchy={hierarchy} loading={loading} onRefresh={loadHierarchy} />
        </TabsContent>

        <TabsContent value="inter-entity">
          <InterEntityTransactionsView entities={entities} selectedEntityId={selectedEntityId} />
        </TabsContent>

        <TabsContent value="consolidation">
          <ConsolidationView entities={entities} financialYear={financialYear} />
        </TabsContent>

        <TabsContent value="settings">
          <EntitySettingsPanel entities={entities} />
        </TabsContent>
      </Tabs>
    </div>
  );
}

import { useState, useEffect, useRef, useCallback } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Switch } from '@/components/ui/switch';
import { Skeleton } from '@/components/ui/skeleton';
import { Settings, Loader2, Check } from 'lucide-react';
import { entityApi } from '@/api';
import type { EntityWithDetails, EntitySettingData } from '@/api';
import { toast } from 'sonner';

interface EntitySettingsPanelProps {
  entities: EntityWithDetails[];
}

export function EntitySettingsPanel({ entities }: EntitySettingsPanelProps) {
  const [selectedEntityId, setSelectedEntityId] = useState<string>(entities[0]?.id ?? '');
  const [settings, setSettings] = useState<EntitySettingData | null>(null);
  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [saved, setSaved] = useState(false);
  const saveTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const selectedEntity = entities.find((e) => e.id === selectedEntityId);

  useEffect(() => {
    if (selectedEntity?.settings) {
      setSettings({ ...selectedEntity.settings });
    } else {
      setSettings({
        basReportingFrequency: 'quarterly',
        gstRegistered: false,
        gstMethod: 'cash',
        taxRate: 25,
        defaultDepreciationMethod: 'diminishing_value',
        instantWriteOffThreshold: 2000000,
      });
    }
  }, [selectedEntityId, selectedEntity]);

  const debouncedSave = useCallback(
    (updated: EntitySettingData) => {
      if (saveTimeoutRef.current) {
        clearTimeout(saveTimeoutRef.current);
      }
      saveTimeoutRef.current = setTimeout(async () => {
        if (!selectedEntityId) return;
        setSaving(true);
        setSaved(false);
        try {
          await entityApi.updateSettings(selectedEntityId, updated);
          setSaved(true);
          setTimeout(() => setSaved(false), 2000);
        } catch (err) {
          console.error('Failed to save settings:', err);
          toast.error('Failed to save settings');
        } finally {
          setSaving(false);
        }
      }, 800);
    },
    [selectedEntityId],
  );

  const updateSetting = <K extends keyof EntitySettingData>(
    key: K,
    value: EntitySettingData[K],
  ) => {
    if (!settings) return;
    const updated = { ...settings, [key]: value };
    setSettings(updated);
    debouncedSave(updated);
  };

  if (entities.length === 0) {
    return (
      <Card className="neu-raised border-0">
        <CardContent className="p-8 text-center">
          <Settings className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
          <h3 className="text-lg font-bold text-primary mb-1">No Entities</h3>
          <p className="text-sm text-muted">Create an entity first to configure settings</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-6">
      {/* Entity Selector */}
      <div className="flex items-center gap-3">
        <Select value={selectedEntityId} onValueChange={setSelectedEntityId}>
          <SelectTrigger className="w-[250px]">
            <SelectValue placeholder="Select entity" />
          </SelectTrigger>
          <SelectContent>
            {entities.map((e) => (
              <SelectItem key={e.id} value={e.id}>
                {e.name}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {saving && (
          <span className="flex items-center gap-1.5 text-xs text-muted">
            <Loader2 className="w-3 h-3 animate-spin" />
            Saving...
          </span>
        )}
        {saved && (
          <span className="flex items-center gap-1.5 text-xs text-emerald-400">
            <Check className="w-3 h-3" />
            Saved
          </span>
        )}
      </div>

      {!settings ? (
        <div className="space-y-4">
          <Skeleton className="h-20 w-full rounded-xl" />
          <Skeleton className="h-20 w-full rounded-xl" />
        </div>
      ) : (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {/* BAS Reporting Frequency */}
          <Card className="neu-raised border-0">
            <CardContent className="p-4 space-y-3">
              <div>
                <Label className="text-sm font-bold text-primary">BAS Reporting Frequency</Label>
                <p className="text-xs text-muted mt-0.5">
                  How often you lodge your Business Activity Statement
                </p>
              </div>
              <Select
                value={settings.basReportingFrequency}
                onValueChange={(v) => updateSetting('basReportingFrequency', v)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="monthly">Monthly</SelectItem>
                  <SelectItem value="quarterly">Quarterly</SelectItem>
                  <SelectItem value="annually">Annually</SelectItem>
                </SelectContent>
              </Select>
            </CardContent>
          </Card>

          {/* GST Registered */}
          <Card className="neu-raised border-0">
            <CardContent className="p-4 space-y-3">
              <div>
                <Label className="text-sm font-bold text-primary">GST Registered</Label>
                <p className="text-xs text-muted mt-0.5">
                  Required if annual turnover exceeds $75,000 ($150,000 for non-profits)
                </p>
              </div>
              <div className="flex items-center gap-3">
                <Switch
                  checked={settings.gstRegistered}
                  onCheckedChange={(v) => updateSetting('gstRegistered', v)}
                />
                <span className="text-sm text-secondary">
                  {settings.gstRegistered ? 'Registered' : 'Not registered'}
                </span>
              </div>
            </CardContent>
          </Card>

          {/* GST Method — only shown if registered */}
          {settings.gstRegistered && (
            <Card className="neu-raised border-0">
              <CardContent className="p-4 space-y-3">
                <div>
                  <Label className="text-sm font-bold text-primary">GST Method</Label>
                  <p className="text-xs text-muted mt-0.5">
                    Cash: report when paid. Accrual: report when invoiced.
                  </p>
                </div>
                <Select
                  value={settings.gstMethod}
                  onValueChange={(v) => updateSetting('gstMethod', v)}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="cash">Cash</SelectItem>
                    <SelectItem value="accrual">Accrual</SelectItem>
                  </SelectContent>
                </Select>
              </CardContent>
            </Card>
          )}

          {/* Tax Rate */}
          <Card className="neu-raised border-0">
            <CardContent className="p-4 space-y-3">
              <div>
                <Label className="text-sm font-bold text-primary">Tax Rate (%)</Label>
                <p className="text-xs text-muted mt-0.5">
                  Company: 25% (base rate) or 30%. Trusts: distributed to beneficiaries.
                </p>
              </div>
              <Input
                type="number"
                min={0}
                max={100}
                step={0.5}
                value={settings.taxRate}
                onChange={(e) => updateSetting('taxRate', parseFloat(e.target.value) || 0)}
              />
            </CardContent>
          </Card>

          {/* Depreciation Method */}
          <Card className="neu-raised border-0">
            <CardContent className="p-4 space-y-3">
              <div>
                <Label className="text-sm font-bold text-primary">
                  Default Depreciation Method
                </Label>
                <p className="text-xs text-muted mt-0.5">
                  Method used for new assets unless overridden per asset
                </p>
              </div>
              <Select
                value={settings.defaultDepreciationMethod}
                onValueChange={(v) => updateSetting('defaultDepreciationMethod', v)}
              >
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="straight_line">Straight Line</SelectItem>
                  <SelectItem value="diminishing_value">Diminishing Value</SelectItem>
                </SelectContent>
              </Select>
            </CardContent>
          </Card>

          {/* Instant Write-Off Threshold */}
          <Card className="neu-raised border-0">
            <CardContent className="p-4 space-y-3">
              <div>
                <Label className="text-sm font-bold text-primary">
                  Instant Write-Off Threshold ($)
                </Label>
                <p className="text-xs text-muted mt-0.5">
                  Assets under this value can be immediately deducted. Default: $20,000
                </p>
              </div>
              <Input
                type="number"
                min={0}
                step={1000}
                value={settings.instantWriteOffThreshold / 100}
                onChange={(e) =>
                  updateSetting(
                    'instantWriteOffThreshold',
                    Math.round((parseFloat(e.target.value) || 0) * 100),
                  )
                }
              />
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { forecastApi } from '../../../api';
import { RefreshCw, TrendingUp, Target, AlertTriangle, Compass } from 'lucide-react';

interface AccuracyMetrics {
  mae: number;
  rmse: number;
  mape: number;
  directionAccuracy: number;
}

interface AccuracyPanelProps {
  forecastId: string;
}

function ratingColor(metric: string, value: number): string {
  if (metric === 'directionAccuracy') {
    if (value >= 80) return 'text-emerald-400';
    if (value >= 60) return 'text-yellow-400';
    return 'text-red-400';
  }
  if (metric === 'mape') {
    if (value <= 10) return 'text-emerald-400';
    if (value <= 25) return 'text-yellow-400';
    return 'text-red-400';
  }
  // MAE / RMSE — lower is better, thresholds are domain-specific
  return 'text-zinc-100';
}

function ratingBg(metric: string, value: number): string {
  if (metric === 'directionAccuracy') {
    if (value >= 80) return 'border-emerald-500/20';
    if (value >= 60) return 'border-yellow-500/20';
    return 'border-red-500/20';
  }
  if (metric === 'mape') {
    if (value <= 10) return 'border-emerald-500/20';
    if (value <= 25) return 'border-yellow-500/20';
    return 'border-red-500/20';
  }
  return 'border-border';
}

const formatDollar = (cents: number) =>
  new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
    maximumFractionDigits: 0,
  }).format(cents / 100);

export function AccuracyPanel({ forecastId }: AccuracyPanelProps) {
  const [metrics, setMetrics] = useState<AccuracyMetrics | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loadAccuracy = async () => {
    setLoading(true);
    setError(null);
    try {
      const result = await forecastApi.calculateAccuracy(forecastId);
      setMetrics(result);
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to calculate accuracy');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (forecastId) loadAccuracy();
  }, [forecastId]);

  const updateActuals = async () => {
    setLoading(true);
    try {
      await forecastApi.updateActuals(forecastId);
      await loadAccuracy();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to update actuals');
    } finally {
      setLoading(false);
    }
  };

  if (!forecastId) {
    return (
      <div className="neu-inset rounded-2xl p-8 text-center text-muted">
        Select a forecast to view accuracy metrics
      </div>
    );
  }

  if (error) {
    return (
      <div className="neu-inset rounded-2xl p-8 text-center">
        <AlertTriangle className="w-8 h-8 text-yellow-400 mx-auto mb-2" />
        <p className="text-secondary text-sm">{error}</p>
        <button onClick={loadAccuracy} className="mt-3 text-xs text-cba-gold hover:underline">
          Retry
        </button>
      </div>
    );
  }

  const cards = metrics
    ? [
        {
          label: 'MAE',
          value: formatDollar(metrics.mae),
          raw: metrics.mae,
          metric: 'mae',
          icon: Target,
          desc: 'Mean Absolute Error',
        },
        {
          label: 'RMSE',
          value: formatDollar(metrics.rmse),
          raw: metrics.rmse,
          metric: 'rmse',
          icon: TrendingUp,
          desc: 'Root Mean Square Error',
        },
        {
          label: 'MAPE',
          value: `${metrics.mape.toFixed(1)}%`,
          raw: metrics.mape,
          metric: 'mape',
          icon: AlertTriangle,
          desc: 'Mean Abs % Error',
        },
        {
          label: 'Direction',
          value: `${metrics.directionAccuracy.toFixed(1)}%`,
          raw: metrics.directionAccuracy,
          metric: 'directionAccuracy',
          icon: Compass,
          desc: 'Direction Accuracy',
        },
      ]
    : [];

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-bold text-zinc-100">Forecast Accuracy</h3>
        <button
          onClick={updateActuals}
          disabled={loading}
          className="neu-raised-sm px-3 py-1.5 rounded-xl text-xs font-bold text-cba-gold hover:bg-overlay transition-colors disabled:opacity-50 flex items-center gap-1.5"
        >
          <RefreshCw className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
          Update Actuals
        </button>
      </div>

      {loading && !metrics ? (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {[1, 2, 3, 4].map((i) => (
            <div key={i} className="neu-raised rounded-2xl p-5 animate-pulse">
              <div className="h-4 w-16 bg-overlay-hover rounded mb-3" />
              <div className="h-8 w-24 bg-overlay-hover rounded mb-2" />
              <div className="h-3 w-20 bg-overlay rounded" />
            </div>
          ))}
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
          {cards.map((card) => {
            const Icon = card.icon;
            return (
              <div
                key={card.label}
                className={`neu-raised rounded-2xl p-5 border ${ratingBg(card.metric, card.raw)} transition-colors`}
              >
                <div className="flex items-center gap-2 mb-3">
                  <div className="neu-inset p-1.5 rounded-lg">
                    <Icon className={`w-4 h-4 ${ratingColor(card.metric, card.raw)}`} />
                  </div>
                  <span className="text-xs font-bold text-secondary uppercase tracking-wider">
                    {card.label}
                  </span>
                </div>
                <p className={`text-2xl font-bold ${ratingColor(card.metric, card.raw)}`}>
                  {card.value}
                </p>
                <p className="text-[11px] text-muted mt-1">{card.desc}</p>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { formatCurrency } from '@/lib/format';
import { Loader2, TrendingUp, TrendingDown, Download, FileText, ArrowRight } from 'lucide-react';
import { gstApi } from '@/api';
import type { GSTSummaryData } from '@/features/gst/types';

interface GSTSummaryProps {
  period?: string;
  businessOnly?: boolean;
}

export function GSTSummary({ period = 'current', businessOnly: _businessOnly }: GSTSummaryProps) {
  const [data, setData] = useState<GSTSummaryData | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadSummary();
  }, [period]);

  const loadSummary = async () => {
    setLoading(true);
    try {
      const result = await gstApi.fetchSummary(period);
      setData(result);
    } catch (err) {
      console.error('Failed to load GST summary:', err);
    } finally {
      setLoading(false);
    }
  };

  const getChangePercent = (current: number, previous?: number): number | null => {
    if (previous === undefined || previous === 0) return null;
    return ((current - previous) / Math.abs(previous)) * 100;
  };

  if (loading) {
    return (
      <Card className="neu-raised rounded-xl">
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        </CardContent>
      </Card>
    );
  }

  if (!data) return null;

  const netChange = getChangePercent(data.netGST, data.previousPeriodNetGST);

  return (
    <div className="space-y-4">
      {/* Stat Cards */}
      <div className="grid gap-4 md:grid-cols-3">
        {/* GST Collected (1A) */}
        <Card className="neu-inset rounded-xl">
          <CardContent className="p-4">
            <p className="text-xs text-muted mb-1">GST Collected (1A)</p>
            <p className="text-2xl font-bold text-emerald-400">
              {formatCurrency(data.gstCollected)}
            </p>
          </CardContent>
        </Card>

        {/* GST Credits (1B) */}
        <Card className="neu-inset rounded-xl">
          <CardContent className="p-4">
            <p className="text-xs text-muted mb-1">GST Credits (1B)</p>
            <p className="text-2xl font-bold text-blue-400">{formatCurrency(data.gstCredits)}</p>
          </CardContent>
        </Card>

        {/* Net GST Position */}
        <Card className="neu-inset rounded-xl border-cba-gold/20">
          <CardContent className="p-4">
            <p className="text-xs text-muted mb-1">Net GST Position</p>
            <div className="flex items-center gap-2">
              <p className="text-2xl font-bold text-cba-gold">{formatCurrency(data.netGST)}</p>
              {netChange !== null && (
                <span
                  className={`flex items-center text-xs ${netChange > 0 ? 'text-red-400' : 'text-emerald-400'}`}
                >
                  {netChange > 0 ? (
                    <TrendingUp className="w-3 h-3 mr-0.5" />
                  ) : (
                    <TrendingDown className="w-3 h-3 mr-0.5" />
                  )}
                  {Math.abs(netChange).toFixed(1)}%
                </span>
              )}
            </div>
            <p className="text-[10px] text-zinc-600 mt-1">
              {data.netGST > 0 ? 'Amount payable to ATO' : 'Refund from ATO'}
            </p>
          </CardContent>
        </Card>
      </div>

      {/* Breakdown */}
      <Card className="neu-raised rounded-xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-medium">GST Breakdown</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3 text-sm">
            <div className="flex justify-between items-center">
              <span className="text-secondary">Taxable Sales</span>
              <span className="font-medium">{formatCurrency(data.breakdown.taxable.sales)}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-secondary">Taxable Purchases</span>
              <span className="font-medium">
                {formatCurrency(data.breakdown.taxable.purchases)}
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-secondary">GST-Free Sales</span>
              <span className="font-medium">{formatCurrency(data.breakdown.gstFree.sales)}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-secondary">GST-Free Purchases</span>
              <span className="font-medium">
                {formatCurrency(data.breakdown.gstFree.purchases)}
              </span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-secondary">Input Taxed</span>
              <span className="font-medium">{formatCurrency(data.breakdown.inputTaxed)}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-secondary">Capital Acquisitions</span>
              <span className="font-medium">{formatCurrency(data.breakdown.capital)}</span>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-secondary">Private/Non-Deductible</span>
              <span className="font-medium">{formatCurrency(data.breakdown.private)}</span>
            </div>
          </div>

          <div className="mt-4 pt-3 border-t border-border/50 flex items-center justify-between text-xs text-muted">
            <span>
              {data.transactionsClassified} classified | {data.transactionsNeedReview} need review
            </span>
          </div>
        </CardContent>
      </Card>

      {/* Actions */}
      <div className="flex gap-2">
        <Button variant="outline" size="sm">
          <ArrowRight className="w-4 h-4 mr-1" />
          View Details
        </Button>
        <Button variant="outline" size="sm">
          <Download className="w-4 h-4 mr-1" />
          Export CSV
        </Button>
        <Button size="sm">
          <FileText className="w-4 h-4 mr-1" />
          Generate BAS Draft
        </Button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { formatCurrency } from '@/lib/format';
import { Loader2, CheckCircle, AlertTriangle } from 'lucide-react';
import { gstApi } from '@/api';
import type { InputTaxCredit } from '@/features/gst/types';

interface InputTaxCreditsProps {
  period?: string;
  businessOnly?: boolean;
}

export function InputTaxCredits({
  period = 'current',
  businessOnly: _businessOnly,
}: InputTaxCreditsProps) {
  const [credits, setCredits] = useState<InputTaxCredit[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadCredits();
  }, [period]);

  const loadCredits = async () => {
    setLoading(true);
    try {
      const data = await gstApi.fetchInputTaxCredits(period);
      setCredits(data.sort((a, b) => b.gstCredits - a.gstCredits));
    } catch (err) {
      console.error('Failed to load input tax credits:', err);
    } finally {
      setLoading(false);
    }
  };

  const totalClaimable = credits.reduce((sum, c) => sum + c.gstCredits, 0);
  const missingInvoices = credits.filter((c) => !c.hasInvoice && c.gstCredits > 8250); // >$82.50 threshold in cents

  if (loading) {
    return (
      <Card className="neu-raised rounded-xl">
        <CardContent className="flex items-center justify-center py-12">
          <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Summary Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold">Input Tax Credits</h3>
          <p className="text-sm text-muted">
            Total Claimable:{' '}
            <span className="text-emerald-400 font-medium">{formatCurrency(totalClaimable)}</span>
          </p>
        </div>
        {missingInvoices.length > 0 && (
          <Badge variant="warning">
            {missingInvoices.length} missing invoice{missingInvoices.length !== 1 ? 's' : ''}
          </Badge>
        )}
      </div>

      {missingInvoices.length > 0 && (
        <Card className="rounded-xl border-amber-500/20 bg-amber-500/5">
          <CardContent className="p-3 flex items-start gap-2">
            <AlertTriangle className="w-4 h-4 text-amber-400 mt-0.5 shrink-0" />
            <p className="text-xs text-amber-400">
              GST credits over $82.50 without a valid tax invoice may be disallowed. Ensure you have
              invoices for all claimable credits.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Credits Table */}
      <Card className="neu-raised rounded-xl">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm">Credit Breakdown by Category</CardTitle>
          <CardDescription>Claimable GST credits with invoice status</CardDescription>
        </CardHeader>
        <CardContent>
          {credits.length === 0 ? (
            <p className="text-muted text-center py-8">No input tax credits for this period</p>
          ) : (
            <div className="space-y-1">
              {/* Header */}
              <div className="grid grid-cols-4 gap-4 text-xs text-muted pb-2 border-b border-border/50">
                <span>Category</span>
                <span className="text-right">GST Credits</span>
                <span className="text-center">Invoice</span>
                <span className="text-right">Transactions</span>
              </div>
              {/* Rows */}
              {credits.map((credit, idx) => {
                const needsInvoice = !credit.hasInvoice && credit.gstCredits > 8250;
                return (
                  <div
                    key={idx}
                    className="grid grid-cols-4 gap-4 py-2 text-sm items-center border-b border-white/[0.02] last:border-0"
                  >
                    <span className="truncate font-medium">{credit.category}</span>
                    <span className="text-right text-emerald-400 font-medium">
                      {formatCurrency(credit.gstCredits)}
                    </span>
                    <span className="flex justify-center">
                      {credit.hasInvoice ? (
                        <CheckCircle className="w-4 h-4 text-emerald-400" />
                      ) : needsInvoice ? (
                        <AlertTriangle className="w-4 h-4 text-amber-400" />
                      ) : (
                        <span className="text-xs text-zinc-600">N/A</span>
                      )}
                    </span>
                    <span className="text-right text-secondary">{credit.transactionCount}</span>
                  </div>
                );
              })}
              {/* Total */}
              <div className="grid grid-cols-4 gap-4 pt-3 border-t border-border text-sm font-semibold">
                <span>Total</span>
                <span className="text-right text-cba-gold">{formatCurrency(totalClaimable)}</span>
                <span />
                <span className="text-right text-secondary">
                  {credits.reduce((sum, c) => sum + c.transactionCount, 0)}
                </span>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  Lightbulb,
  Zap,
  AlertCircle,
  Brain,
  Eye,
  CheckCircle,
  X,
  Filter,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { intelligenceApi } from '../../../api';
import { cn } from '../../../lib/utils';

interface InsightFeedProps {
  userId: string;
  dateRange?: { start: string; end: string };
}

interface Insight {
  id: string;
  type: string;
  severity: 'info' | 'suggestion' | 'warning' | 'critical';
  title: string;
  description: string;
  sourceModules: string[];
  confidence: number;
  status: 'new' | 'viewed' | 'acted_on' | 'dismissed';
  createdAt: string;
}

const severityConfig = {
  info: { icon: Lightbulb, color: 'border-blue-500', bg: 'bg-blue-500/10', text: 'text-blue-400' },
  suggestion: {
    icon: Zap,
    color: 'border-emerald-500',
    bg: 'bg-emerald-500/10',
    text: 'text-emerald-400',
  },
  warning: {
    icon: AlertCircle,
    color: 'border-yellow-500',
    bg: 'bg-yellow-500/10',
    text: 'text-yellow-400',
  },
  critical: { icon: Brain, color: 'border-red-500', bg: 'bg-red-500/10', text: 'text-red-400' },
};

const statusStyles: Record<string, string> = {
  new: 'bg-cba-gold/20 text-cba-gold animate-pulse',
  viewed: 'bg-zinc-700/50 text-secondary',
  acted_on: 'bg-emerald-500/20 text-emerald-400',
  dismissed: 'bg-zinc-800/50 text-zinc-600 line-through',
};

export function InsightFeed({ userId, dateRange }: InsightFeedProps) {
  const [insights, setInsights] = useState<Insight[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [showFilters, setShowFilters] = useState(false);
  const [filters, setFilters] = useState({
    severity: '' as string,
    status: '' as string,
    minConfidence: 0,
  });

  useEffect(() => {
    loadInsights();
  }, [userId, dateRange, filters]);

  const loadInsights = async () => {
    try {
      setLoading(true);
      const params: Record<string, string> = {};
      if (dateRange?.start) params.startDate = dateRange.start;
      if (dateRange?.end) params.endDate = dateRange.end;
      if (filters.severity) params.severity = filters.severity;
      if (filters.status) params.status = filters.status;
      if (filters.minConfidence > 0) params.minConfidence = String(filters.minConfidence);
      const data = await intelligenceApi.listInsights(userId, params);
      setInsights(Array.isArray(data) ? data : (data.insights ?? []));
      setError(null);
    } catch {
      setError('Failed to load insights');
    } finally {
      setLoading(false);
    }
  };

  const updateStatus = async (insightId: string, status: string) => {
    try {
      await intelligenceApi.updateInsightStatus(insightId, status);
      setInsights((prev) =>
        prev.map((i) => (i.id === insightId ? { ...i, status: status as Insight['status'] } : i)),
      );
    } catch {
      // silent
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="w-8 h-8 border-2 border-cba-gold border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (error) {
    return <div className="neu-raised p-4 rounded-lg text-red-400 text-center">{error}</div>;
  }

  return (
    <div className="space-y-4">
      {/* Filters Toggle */}
      <button
        onClick={() => setShowFilters(!showFilters)}
        className="flex items-center gap-2 text-sm text-secondary hover:text-cba-gold transition-colors"
      >
        <Filter className="w-4 h-4" />
        Filters
        {showFilters ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
      </button>

      {showFilters && (
        <div className="neu-inset p-4 rounded-lg grid grid-cols-1 sm:grid-cols-3 gap-3">
          <select
            value={filters.severity}
            onChange={(e) => setFilters((f) => ({ ...f, severity: e.target.value }))}
            className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
          >
            <option value="">All Severities</option>
            <option value="info">Info</option>
            <option value="suggestion">Suggestion</option>
            <option value="warning">Warning</option>
            <option value="critical">Critical</option>
          </select>
          <select
            value={filters.status}
            onChange={(e) => setFilters((f) => ({ ...f, status: e.target.value }))}
            className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
          >
            <option value="">All Statuses</option>
            <option value="new">New</option>
            <option value="viewed">Viewed</option>
            <option value="acted_on">Acted On</option>
            <option value="dismissed">Dismissed</option>
          </select>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted">Min Confidence:</span>
            <input
              type="range"
              min={0}
              max={100}
              value={filters.minConfidence}
              onChange={(e) => setFilters((f) => ({ ...f, minConfidence: Number(e.target.value) }))}
              className="flex-1 accent-[#FFCC00]"
            />
            <span className="text-xs text-secondary w-8">{filters.minConfidence}%</span>
          </div>
        </div>
      )}

      {/* Insight Cards */}
      {insights.length === 0 ? (
        <div className="neu-raised p-8 rounded-lg text-center text-muted">
          <Lightbulb className="w-8 h-8 mx-auto mb-2 opacity-50" />
          <p>No insights found. Run a scan to discover new insights.</p>
        </div>
      ) : (
        <div className="space-y-3">
          {insights.map((insight) => {
            const config = severityConfig[insight.severity] || severityConfig.info;
            const Icon = config.icon;
            const isExpanded = expandedId === insight.id;

            return (
              <div
                key={insight.id}
                className={cn(
                  'neu-raised rounded-lg overflow-hidden border-l-4 transition-all',
                  config.color,
                )}
              >
                <div
                  className="p-4 cursor-pointer"
                  onClick={() => setExpandedId(isExpanded ? null : insight.id)}
                >
                  <div className="flex items-start gap-3">
                    <div className={cn('p-2 rounded-lg shrink-0', config.bg)}>
                      <Icon className={cn('w-5 h-5', config.text)} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <h4 className="font-semibold text-zinc-100 truncate">{insight.title}</h4>
                        <span
                          className={cn(
                            'px-2 py-0.5 rounded-full text-[10px] font-bold uppercase',
                            statusStyles[insight.status],
                          )}
                        >
                          {insight.status.replace('_', ' ')}
                        </span>
                      </div>
                      {/* Source modules */}
                      <div className="flex items-center gap-1.5 mt-1.5 flex-wrap">
                        {insight.sourceModules?.map((mod) => (
                          <span
                            key={mod}
                            className="px-2 py-0.5 rounded-full text-[10px] bg-zinc-800 text-secondary border border-zinc-700"
                          >
                            {mod}
                          </span>
                        ))}
                      </div>
                      {/* Confidence bar */}
                      <div className="mt-2 flex items-center gap-2">
                        <div className="flex-1 h-1.5 bg-zinc-800 rounded-full overflow-hidden">
                          <div
                            className="h-full bg-cba-gold rounded-full transition-all"
                            style={{ width: `${insight.confidence}%` }}
                          />
                        </div>
                        <span className="text-[10px] text-muted font-mono">
                          {insight.confidence}%
                        </span>
                      </div>
                    </div>
                    {isExpanded ? (
                      <ChevronUp className="w-4 h-4 text-muted shrink-0" />
                    ) : (
                      <ChevronDown className="w-4 h-4 text-muted shrink-0" />
                    )}
                  </div>
                </div>

                {isExpanded && (
                  <div className="px-4 pb-4 border-t border-border/50">
                    <p className="text-sm text-secondary mt-3 leading-relaxed">
                      {insight.description}
                    </p>
                    <div className="flex items-center gap-2 mt-3">
                      <button
                        onClick={() => updateStatus(insight.id, 'viewed')}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-800 hover:bg-zinc-700 text-primary transition-colors"
                      >
                        <Eye className="w-3.5 h-3.5" /> Mark Viewed
                      </button>
                      <button
                        onClick={() => updateStatus(insight.id, 'acted_on')}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium bg-emerald-900/40 hover:bg-emerald-900/60 text-emerald-400 transition-colors"
                      >
                        <CheckCircle className="w-3.5 h-3.5" /> Act On
                      </button>
                      <button
                        onClick={() => updateStatus(insight.id, 'dismissed')}
                        className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium bg-zinc-800 hover:bg-zinc-700 text-muted transition-colors"
                      >
                        <X className="w-3.5 h-3.5" /> Dismiss
                      </button>
                    </div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  DollarSign,
  TrendingUp,
  ShieldCheck,
  Receipt,
  Calculator,
  Network,
  Clock,
} from 'lucide-react';
import { intelligenceApi } from '../../../api';
import { cn } from '../../../lib/utils';

interface IntelligenceTimelineProps {
  userId: string;
}

interface TimelineEvent {
  id: string;
  module: string;
  eventType: string;
  title: string;
  description: string;
  timestamp: string;
  metadata?: Record<string, unknown>;
}

const moduleConfig: Record<string, { icon: typeof Clock; color: string; bg: string }> = {
  transactions: { icon: DollarSign, color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
  forecasting: { icon: TrendingUp, color: 'text-blue-400', bg: 'bg-blue-500/10' },
  compliance: { icon: ShieldCheck, color: 'text-red-400', bg: 'bg-red-500/10' },
  tax: { icon: Receipt, color: 'text-orange-400', bg: 'bg-orange-500/10' },
  bas: { icon: Calculator, color: 'text-purple-400', bg: 'bg-purple-500/10' },
  knowledge: { icon: Network, color: 'text-cyan-400', bg: 'bg-cyan-500/10' },
};

type Granularity = 'day' | 'week' | 'month';

interface FetchState {
  events: TimelineEvent[];
  loading: boolean;
  error: string | null;
}

export function IntelligenceTimeline({ userId }: IntelligenceTimelineProps) {
  const [fetchState, setFetchState] = useState<FetchState>({
    events: [],
    loading: true,
    error: null,
  });
  const [granularity, setGranularity] = useState<Granularity>('day');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [activeModules, setActiveModules] = useState<Set<string>>(
    new Set(Object.keys(moduleConfig)),
  );

  const loadTimeline = async () => {
    try {
      setFetchState((prev) => ({ ...prev, loading: true, error: null }));
      const params: Record<string, string> = { granularity };
      if (startDate) params.startDate = startDate;
      if (endDate) params.endDate = endDate;
      const data = await intelligenceApi.getTimeline(userId, params);
      setFetchState({
        events: Array.isArray(data) ? data : (data.events ?? []),
        loading: false,
        error: null,
      });
    } catch {
      setFetchState((prev) => ({ ...prev, loading: false, error: 'Failed to load timeline' }));
    }
  };

  useEffect(() => {
    const id = setTimeout(() => void loadTimeline(), 0);
    return () => clearTimeout(id);
  }, [userId, granularity, startDate, endDate]);

  const toggleModule = (mod: string) => {
    setActiveModules((prev) => {
      const next = new Set(prev);
      if (next.has(mod)) next.delete(mod);
      else next.add(mod);
      return next;
    });
  };

  const { events, loading, error } = fetchState;
  const filteredEvents = events.filter((e) => activeModules.has(e.module));

  // Group events by date
  const grouped = filteredEvents.reduce<Record<string, TimelineEvent[]>>((acc, evt) => {
    const dateKey = evt.timestamp.slice(0, 10);
    if (!acc[dateKey]) acc[dateKey] = [];
    acc[dateKey].push(evt);
    return acc;
  }, {});

  const sortedDates = Object.keys(grouped).sort((a, b) => b.localeCompare(a));

  return (
    <div className="space-y-4">
      {/* Controls */}
      <div className="neu-raised p-4 rounded-lg space-y-3">
        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-2">
            <label htmlFor="timeline-start" className="text-xs text-muted font-medium">
              From:
            </label>
            <input
              id="timeline-start"
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-1.5 text-sm text-primary"
            />
          </div>
          <div className="flex items-center gap-2">
            <label htmlFor="timeline-end" className="text-xs text-muted font-medium">
              To:
            </label>
            <input
              id="timeline-end"
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-1.5 text-sm text-primary"
            />
          </div>
          <div className="flex rounded-lg overflow-hidden border border-zinc-700">
            {(['day', 'week', 'month'] as Granularity[]).map((g) => (
              <button
                key={g}
                onClick={() => setGranularity(g)}
                className={cn(
                  'px-3 py-1.5 text-xs font-bold uppercase transition-colors',
                  granularity === g
                    ? 'bg-cba-gold text-base'
                    : 'bg-zinc-800 text-secondary hover:text-primary',
                )}
              >
                {g}
              </button>
            ))}
          </div>
        </div>

        {/* Module filters */}
        <div className="flex flex-wrap gap-2">
          {Object.entries(moduleConfig).map(([mod, cfg]) => (
            <button
              key={mod}
              onClick={() => toggleModule(mod)}
              className={cn(
                'flex items-center gap-1.5 px-2.5 py-1 rounded-full text-[10px] font-bold uppercase border transition-all',
                activeModules.has(mod)
                  ? `${cfg.bg} ${cfg.color} border-current`
                  : 'bg-zinc-800/50 text-zinc-600 border-zinc-700',
              )}
            >
              <cfg.icon className="w-3 h-3" />
              {mod}
            </button>
          ))}
        </div>
      </div>

      {/* Timeline */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <div className="w-8 h-8 border-2 border-cba-gold border-t-transparent rounded-full animate-spin" />
        </div>
      ) : error ? (
        <div className="neu-raised p-4 rounded-lg text-red-400 text-center">{error}</div>
      ) : sortedDates.length === 0 ? (
        <div className="neu-raised p-8 rounded-lg text-center text-muted">
          <Clock className="w-8 h-8 mx-auto mb-2 opacity-50" />
          <p>No timeline events found for this period.</p>
        </div>
      ) : (
        <div className="relative pl-6">
          {/* Vertical line */}
          <div className="absolute left-3 top-0 bottom-0 w-px bg-zinc-700" />

          {sortedDates.map((date) => (
            <div key={date} className="mb-6">
              {/* Date marker */}
              <div className="flex items-center gap-3 mb-3 relative">
                <div className="absolute left-[-12px] w-6 h-6 rounded-full bg-cba-gold flex items-center justify-center">
                  <Clock className="w-3 h-3 text-base" />
                </div>
                <h3 className="text-sm font-bold text-cba-gold ml-4">
                  {new Date(date + 'T00:00:00').toLocaleDateString('en-AU', {
                    weekday: 'short',
                    day: 'numeric',
                    month: 'short',
                    year: 'numeric',
                  })}
                </h3>
              </div>

              {/* Events for this date */}
              <div className="space-y-2 ml-4">
                {grouped[date].map((evt) => {
                  const cfg = moduleConfig[evt.module] || {
                    icon: Clock,
                    color: 'text-secondary',
                    bg: 'bg-zinc-500/10',
                  };
                  const ModIcon = cfg.icon;
                  return (
                    <div key={evt.id} className="neu-raised p-3 rounded-lg flex items-start gap-3">
                      <div className={cn('p-1.5 rounded-lg shrink-0', cfg.bg)}>
                        <ModIcon className={cn('w-4 h-4', cfg.color)} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center gap-2">
                          <span className="text-sm font-medium text-primary">{evt.title}</span>
                          <span
                            className={cn(
                              'px-1.5 py-0.5 rounded text-[9px] font-bold uppercase',
                              cfg.bg,
                              cfg.color,
                            )}
                          >
                            {evt.module}
                          </span>
                        </div>
                        <p className="text-xs text-muted mt-0.5">{evt.description}</p>
                        <span className="text-[10px] text-zinc-600 mt-1 block">
                          {new Date(evt.timestamp).toLocaleTimeString('en-AU', {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </span>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useRef } from 'react';
import { X } from 'lucide-react';
import { intelligenceApi } from '../../../api';

interface ModuleConnectionMapProps {
  connections?: Connection[];
}

interface Connection {
  id: string;
  sourceModule: string;
  targetModule: string;
  connectionType: 'data_flow' | 'trigger' | 'dependency' | 'correlation' | 'enrichment';
  strength: number;
  description: string;
}

const MODULES = [
  'transactions',
  'analytics',
  'tax',
  'bas',
  'gst',
  'knowledge',
  'documents',
  'matching',
  'intelligence',
];

const CONNECTION_COLORS: Record<string, string> = {
  data_flow: '#3b82f6',
  trigger: '#f97316',
  dependency: '#ef4444',
  correlation: '#a855f7',
  enrichment: '#22c55e',
};

const MODULE_COLORS: Record<string, string> = {
  transactions: '#22c55e',
  analytics: '#a855f7',
  tax: '#f97316',
  bas: '#8b5cf6',
  gst: '#10b981',
  knowledge: '#06b6d4',
  documents: '#f43f5e',
  matching: '#eab308',
  intelligence: '#FFCC00',
};

export function ModuleConnectionMap({ connections: propConnections }: ModuleConnectionMapProps) {
  const [connections, setConnections] = useState<Connection[]>(propConnections ?? []);
  const [loading, setLoading] = useState(!propConnections);
  const [error, setError] = useState<string | null>(null);
  const [selectedModule, setSelectedModule] = useState<string | null>(null);
  const [selectedConnection, setSelectedConnection] = useState<Connection | null>(null);
  const svgRef = useRef<SVGSVGElement>(null);

  useEffect(() => {
    if (!propConnections) loadConnections();
  }, []);

  const loadConnections = async () => {
    try {
      setLoading(true);
      const data = await intelligenceApi.getConnections();
      setConnections(Array.isArray(data) ? data : (data.connections ?? []));
      setError(null);
    } catch {
      setError('Failed to load connections');
    } finally {
      setLoading(false);
    }
  };

  // Calculate module positions in a circle
  const width = 600;
  const height = 500;
  const cx = width / 2;
  const cy = height / 2;
  const radius = 180;

  const modulePositions = MODULES.reduce<Record<string, { x: number; y: number }>>(
    (acc, mod, i) => {
      const angle = (2 * Math.PI * i) / MODULES.length - Math.PI / 2;
      acc[mod] = {
        x: cx + radius * Math.cos(angle),
        y: cy + radius * Math.sin(angle),
      };
      return acc;
    },
    {},
  );

  const getModuleConnections = (mod: string) => {
    const incoming = connections.filter((c) => c.targetModule === mod);
    const outgoing = connections.filter((c) => c.sourceModule === mod);
    return { incoming, outgoing };
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="w-8 h-8 border-2 border-cba-gold border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  if (error) {
    return <div className="neu-raised p-4 rounded-lg text-red-400 text-center">{error}</div>;
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col lg:flex-row gap-4">
        {/* SVG Map */}
        <div className="flex-1 neu-raised rounded-lg p-4 overflow-hidden">
          <svg
            ref={svgRef}
            viewBox={`0 0 ${width} ${height}`}
            className="w-full h-auto max-h-[500px]"
          >
            {/* Connections */}
            {connections.map((conn) => {
              const src = modulePositions[conn.sourceModule];
              const tgt = modulePositions[conn.targetModule];
              if (!src || !tgt) return null;
              const color = CONNECTION_COLORS[conn.connectionType] ?? '#666';
              const strokeWidth = Math.max(1, conn.strength * 4);
              const isSelected = selectedConnection?.id === conn.id;

              return (
                <g key={conn.id}>
                  <line
                    x1={src.x}
                    y1={src.y}
                    x2={tgt.x}
                    y2={tgt.y}
                    stroke={color}
                    strokeWidth={isSelected ? strokeWidth + 2 : strokeWidth}
                    strokeOpacity={isSelected ? 1 : 0.4}
                    className="cursor-pointer transition-all"
                    onClick={() => setSelectedConnection(isSelected ? null : conn)}
                  />
                  {/* Arrow head */}
                  <circle
                    cx={tgt.x + (src.x - tgt.x) * 0.15}
                    cy={tgt.y + (src.y - tgt.y) * 0.15}
                    r={3}
                    fill={color}
                    opacity={isSelected ? 1 : 0.6}
                  />
                </g>
              );
            })}

            {/* Module nodes */}
            {MODULES.map((mod) => {
              const pos = modulePositions[mod];
              const color = MODULE_COLORS[mod] ?? '#888';
              const isSelected = selectedModule === mod;

              return (
                <g
                  key={mod}
                  className="cursor-pointer"
                  onClick={() => setSelectedModule(isSelected ? null : mod)}
                >
                  <circle
                    cx={pos.x}
                    cy={pos.y}
                    r={isSelected ? 32 : 28}
                    fill={`${color}20`}
                    stroke={color}
                    strokeWidth={isSelected ? 3 : 1.5}
                    className="transition-all"
                  />
                  <text
                    x={pos.x}
                    y={pos.y + 1}
                    textAnchor="middle"
                    dominantBaseline="middle"
                    fill={color}
                    fontSize="9"
                    fontWeight="bold"
                    className="pointer-events-none uppercase"
                  >
                    {mod.slice(0, 5)}
                  </text>
                </g>
              );
            })}
          </svg>

          {/* Legend */}
          <div className="flex flex-wrap gap-3 mt-3 justify-center">
            {Object.entries(CONNECTION_COLORS).map(([type, color]) => (
              <div key={type} className="flex items-center gap-1.5">
                <div className="w-4 h-1 rounded-full" style={{ backgroundColor: color }} />
                <span className="text-[10px] text-muted uppercase font-medium">
                  {type.replace('_', ' ')}
                </span>
              </div>
            ))}
          </div>
        </div>

        {/* Detail Panel */}
        {(selectedModule || selectedConnection) && (
          <div className="w-full lg:w-72 neu-raised rounded-lg p-4 space-y-3">
            <div className="flex items-center justify-between">
              <h4 className="text-sm font-bold text-cba-gold">
                {selectedModule ? `Module: ${selectedModule}` : 'Connection Detail'}
              </h4>
              <button
                onClick={() => {
                  setSelectedModule(null);
                  setSelectedConnection(null);
                }}
                className="text-muted hover:text-primary"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {selectedModule &&
              (() => {
                const { incoming, outgoing } = getModuleConnections(selectedModule);
                return (
                  <>
                    <div>
                      <p className="text-xs text-muted font-medium mb-1">
                        Incoming ({incoming.length})
                      </p>
                      {incoming.map((c) => (
                        <div key={c.id} className="text-xs text-secondary py-0.5">
                          ← {c.sourceModule}{' '}
                          <span className="text-zinc-600">({c.connectionType})</span>
                        </div>
                      ))}
                      {incoming.length === 0 && <p className="text-xs text-zinc-600">None</p>}
                    </div>
                    <div>
                      <p className="text-xs text-muted font-medium mb-1">
                        Outgoing ({outgoing.length})
                      </p>
                      {outgoing.map((c) => (
                        <div key={c.id} className="text-xs text-secondary py-0.5">
                          → {c.targetModule}{' '}
                          <span className="text-zinc-600">({c.connectionType})</span>
                        </div>
                      ))}
                      {outgoing.length === 0 && <p className="text-xs text-zinc-600">None</p>}
                    </div>
                  </>
                );
              })()}

            {selectedConnection && (
              <>
                <div className="text-sm text-primary">
                  <span className="font-medium">{selectedConnection.sourceModule}</span>
                  <span className="text-zinc-600"> → </span>
                  <span className="font-medium">{selectedConnection.targetModule}</span>
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-muted">Type:</span>
                  <span
                    className="px-2 py-0.5 rounded-full text-[10px] font-bold uppercase"
                    style={{
                      backgroundColor: `${CONNECTION_COLORS[selectedConnection.connectionType]}20`,
                      color: CONNECTION_COLORS[selectedConnection.connectionType],
                    }}
                  >
                    {selectedConnection.connectionType.replace('_', ' ')}
                  </span>
                </div>
                <div>
                  <span className="text-xs text-muted">Strength:</span>
                  <div className="mt-1 h-2 bg-zinc-800 rounded-full overflow-hidden">
                    <div
                      className="h-full rounded-full bg-cba-gold"
                      style={{ width: `${selectedConnection.strength * 100}%` }}
                    />
                  </div>
                </div>
                <p className="text-xs text-secondary">{selectedConnection.description}</p>
              </>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  Bell,
  Mail,
  Radio,
  Globe,
  Plus,
  Trash2,
  X,
} from 'lucide-react';
import { intelligenceApi } from '../../../api';
import { cn } from '../../../lib/utils';

interface SubscriptionManagerProps {
  userId: string;
}

interface Subscription {
  id: string;
  userId: string;
  name: string;
  type: string;
  filterCriteria: Record<string, unknown>;
  channel: 'in_app' | 'email' | 'sse' | 'webhook';
  channelConfig: Record<string, unknown>;
  cooldownMinutes: number;
  isActive: boolean;
  createdAt: string;
}

const channelIcons: Record<string, typeof Bell> = {
  in_app: Bell,
  email: Mail,
  sse: Radio,
  webhook: Globe,
};

const channelLabels: Record<string, string> = {
  in_app: 'In-App',
  email: 'Email',
  sse: 'Real-Time SSE',
  webhook: 'Webhook',
};

export function SubscriptionManager({ userId }: SubscriptionManagerProps) {
  const [subscriptions, setSubscriptions] = useState<Subscription[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);

  // Form state
  const [formName, setFormName] = useState('');
  const [formType, setFormType] = useState('insight');
  const [formChannel, setFormChannel] = useState<Subscription['channel']>('in_app');
  const [formCooldown, setFormCooldown] = useState(30);
  const [formSeverity, setFormSeverity] = useState('');
  const [formModule, setFormModule] = useState('');

  useEffect(() => {
    loadSubscriptions();
  }, [userId]);

  const loadSubscriptions = async () => {
    try {
      setLoading(true);
      const data = await intelligenceApi.listSubscriptions(userId);
      setSubscriptions(Array.isArray(data) ? data : (data.subscriptions ?? []));
      setError(null);
    } catch {
      setError('Failed to load subscriptions');
    } finally {
      setLoading(false);
    }
  };

  const createSubscription = async () => {
    if (!formName.trim()) return;
    try {
      const filterCriteria: Record<string, string> = {};
      if (formSeverity) filterCriteria.severity = formSeverity;
      if (formModule) filterCriteria.module = formModule;

      await intelligenceApi.subscribe({
        userId,
        name: formName,
        type: formType,
        filterCriteria,
        channel: formChannel,
        channelConfig: {},
        cooldownMinutes: formCooldown,
      });
      resetForm();
      loadSubscriptions();
    } catch {
      setError('Failed to create subscription');
    }
  };

  const deleteSubscription = async (id: string) => {
    try {
      await intelligenceApi.deleteSubscription(id);
      setSubscriptions((prev) => prev.filter((s) => s.id !== id));
    } catch {
      // ignore
    }
  };

  const resetForm = () => {
    setShowForm(false);
    setFormName('');
    setFormType('insight');
    setFormChannel('in_app');
    setFormCooldown(30);
    setFormSeverity('');
    setFormModule('');
  };

  // Stats
  const activeSubs = subscriptions.filter((s) => s.isActive).length;
  const channelCounts = subscriptions.reduce<Record<string, number>>((acc, s) => {
    acc[s.channel] = (acc[s.channel] || 0) + 1;
    return acc;
  }, {});

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <div className="w-8 h-8 border-2 border-cba-gold border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Stats Row */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
        <div className="neu-raised p-3 rounded-lg text-center">
          <p className="text-2xl font-bold text-cba-gold">{subscriptions.length}</p>
          <p className="text-[10px] text-muted uppercase font-bold">Total</p>
        </div>
        <div className="neu-raised p-3 rounded-lg text-center">
          <p className="text-2xl font-bold text-emerald-400">{activeSubs}</p>
          <p className="text-[10px] text-muted uppercase font-bold">Active</p>
        </div>
        <div className="neu-raised p-3 rounded-lg text-center">
          <p className="text-2xl font-bold text-blue-400">{channelCounts['in_app'] ?? 0}</p>
          <p className="text-[10px] text-muted uppercase font-bold">In-App</p>
        </div>
        <div className="neu-raised p-3 rounded-lg text-center">
          <p className="text-2xl font-bold text-purple-400">{channelCounts['sse'] ?? 0}</p>
          <p className="text-[10px] text-muted uppercase font-bold">SSE</p>
        </div>
      </div>

      {/* Create Button */}
      <button
        onClick={() => setShowForm(!showForm)}
        className="flex items-center gap-2 px-4 py-2 rounded-lg bg-cba-gold text-base font-bold text-sm hover:bg-cba-gold/90 transition-colors"
      >
        <Plus className="w-4 h-4" />
        New Subscription
      </button>

      {/* Create Form */}
      {showForm && (
        <div className="neu-raised p-4 rounded-lg space-y-3 border border-cba-gold/20">
          <div className="flex items-center justify-between">
            <h4 className="text-sm font-bold text-cba-gold">Create Subscription</h4>
            <button onClick={resetForm} className="text-muted hover:text-primary">
              <X className="w-4 h-4" />
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label htmlFor="intel-f1" className="text-xs text-muted font-medium block mb-1">Name</label>
              <input id="intel-f1"
                type="text"
                value={formName}
                onChange={(e) => setFormName(e.target.value)}
                placeholder="e.g. Critical Alerts"
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary placeholder:text-zinc-600"
              />
            </div>
            <div>
              <label htmlFor="intel-f2" className="text-xs text-muted font-medium block mb-1">Type</label>
              <select id="intel-f2"
                value={formType}
                onChange={(e) => setFormType(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              >
                <option value="insight">Insight</option>
                <option value="anomaly">Anomaly</option>
                <option value="compliance">Compliance</option>
                <option value="forecast">Forecast</option>
              </select>
            </div>
            <div>
              <label htmlFor="intel-f3" className="text-xs text-muted font-medium block mb-1">Channel</label>
              <select id="intel-f3"
                value={formChannel}
                onChange={(e) => setFormChannel(e.target.value as Subscription['channel'])}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              >
                {Object.entries(channelLabels).map(([val, label]) => (
                  <option key={val} value={val}>
                    {label}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label htmlFor="intel-f4" className="text-xs text-muted font-medium block mb-1">Cooldown (min)</label>
              <input id="intel-f4"
                type="number"
                value={formCooldown}
                onChange={(e) => setFormCooldown(Number(e.target.value))}
                min={1}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              />
            </div>
            <div>
              <label htmlFor="intel-f5" className="text-xs text-muted font-medium block mb-1">
                Severity Filter
              </label>
              <select id="intel-f5"
                value={formSeverity}
                onChange={(e) => setFormSeverity(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              >
                <option value="">All</option>
                <option value="info">Info</option>
                <option value="warning">Warning</option>
                <option value="critical">Critical</option>
              </select>
            </div>
            <div>
              <label htmlFor="intel-f6" className="text-xs text-muted font-medium block mb-1">Module Filter</label>
              <select id="intel-f6"
                value={formModule}
                onChange={(e) => setFormModule(e.target.value)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              >
                <option value="">All Modules</option>
                <option value="transactions">Transactions</option>
                <option value="tax">Tax</option>
                <option value="bas">BAS</option>
                <option value="knowledge">Knowledge</option>
                <option value="analytics">Analytics</option>
              </select>
            </div>
          </div>

          <button
            onClick={createSubscription}
            disabled={!formName.trim()}
            className="px-4 py-2 rounded-lg bg-cba-gold text-base font-bold text-sm hover:bg-cba-gold/90 transition-colors disabled:opacity-50"
          >
            Create
          </button>
        </div>
      )}

      {/* Subscription Cards */}
      {error && <div className="neu-raised p-4 rounded-lg text-red-400 text-center">{error}</div>}

      {subscriptions.length === 0 && !showForm ? (
        <div className="neu-raised p-8 rounded-lg text-center text-muted">
          <Bell className="w-8 h-8 mx-auto mb-2 opacity-50" />
          <p>No subscriptions yet. Create one to get notified.</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
          {subscriptions.map((sub) => {
            const ChannelIcon = channelIcons[sub.channel] || Bell;
            return (
              <div
                key={sub.id}
                className={cn(
                  'neu-raised p-4 rounded-lg border-l-4 transition-all',
                  sub.isActive ? 'border-cba-gold' : 'border-zinc-700',
                )}
              >
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-3">
                    <div
                      className={cn(
                        'p-2 rounded-lg',
                        sub.isActive ? 'bg-cba-gold/10' : 'bg-zinc-800',
                      )}
                    >
                      <ChannelIcon
                        className={cn('w-5 h-5', sub.isActive ? 'text-cba-gold' : 'text-zinc-600')}
                      />
                    </div>
                    <div>
                      <h4 className="text-sm font-semibold text-primary">{sub.name}</h4>
                      <p className="text-[10px] text-muted uppercase font-bold mt-0.5">
                        {sub.type} • {channelLabels[sub.channel]} • {sub.cooldownMinutes}m cooldown
                      </p>
                    </div>
                  </div>
                  <button
                    onClick={() => deleteSubscription(sub.id)}
                    className="text-zinc-600 hover:text-red-400 transition-colors"
                  >
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>
                {sub.filterCriteria && Object.keys(sub.filterCriteria).length > 0 && (
                  <div className="flex flex-wrap gap-1 mt-2">
                    {Object.entries(sub.filterCriteria).map(([k, v]) => (
                      <span
                        key={k}
                        className="px-2 py-0.5 rounded-full text-[9px] bg-zinc-800 text-secondary border border-zinc-700"
                      >
                        {k}: {String(v)}
                      </span>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Search, Save, Clock, Database, ChevronRight } from 'lucide-react';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from 'recharts';
import { intelligenceApi } from '../../../api';

interface TemporalQueryBuilderProps {
  userId: string;
}

type QueryType = 'point_in_time' | 'time_range' | 'trend' | 'comparison' | 'evolution';
type EntityType = 'transactions' | 'forecasts' | 'compliance' | 'anomalies' | 'tax' | 'bas';

interface SavedQuery {
  id: string;
  name: string;
  queryType: QueryType;
  entity: EntityType;
  createdAt: string;
}

const queryTypes: { value: QueryType; label: string }[] = [
  { value: 'point_in_time', label: 'Point in Time' },
  { value: 'time_range', label: 'Time Range' },
  { value: 'trend', label: 'Trend Over Time' },
  { value: 'comparison', label: 'Comparison' },
  { value: 'evolution', label: 'Evolution' },
];

const entityTypes: { value: EntityType; label: string }[] = [
  { value: 'transactions', label: 'Transactions' },
  { value: 'forecasts', label: 'Forecasts' },
  { value: 'compliance', label: 'Compliance' },
  { value: 'anomalies', label: 'Anomalies' },
  { value: 'tax', label: 'Tax' },
  { value: 'bas', label: 'BAS' },
];

export function TemporalQueryBuilder({ userId }: TemporalQueryBuilderProps) {
  const [queryType, setQueryType] = useState<QueryType>('point_in_time');
  const [entity, setEntity] = useState<EntityType>('transactions');
  const [pointDate, setPointDate] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [category, setCategory] = useState('');
  const [minAmount, setMinAmount] = useState('');
  const [maxAmount, setMaxAmount] = useState('');
  const [results, setResults] = useState<any>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [savedQueries, setSavedQueries] = useState<SavedQuery[]>([]);
  const [showSaved, setShowSaved] = useState(false);
  const [queryName, setQueryName] = useState('');
  const [cached, setCached] = useState(false);

  useEffect(() => {
    // Defer to avoid sync setState-in-effect lint violation
    const id = setTimeout(() => void loadSavedQueries(), 0);
    return () => clearTimeout(id);
  }, [userId]);

  const loadSavedQueries = async () => {
    try {
      const data = await intelligenceApi.listSavedQueries(userId);
      setSavedQueries(Array.isArray(data) ? data : (data.queries ?? []));
    } catch {
      // ignore
    }
  };

  const buildQueryPayload = () => {
    const payload: Record<string, unknown> = {
      userId,
      queryType,
      entity,
    };
    if (queryType === 'point_in_time') payload.timestamp = pointDate;
    else {
      payload.startDate = startDate;
      payload.endDate = endDate;
    }
    if (category) payload.category = category;
    if (minAmount) payload.minAmount = Number(minAmount);
    if (maxAmount) payload.maxAmount = Number(maxAmount);
    return payload;
  };

  const executeQuery = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await intelligenceApi.executeQuery(buildQueryPayload());
      setResults(data);
      setCached(!!data?.cached);
    } catch {
      setError('Query execution failed');
      setResults(null);
    } finally {
      setLoading(false);
    }
  };

  const saveQuery = async () => {
    if (!queryName.trim()) return;
    try {
      await intelligenceApi.saveQuery({ ...buildQueryPayload(), name: queryName });
      setQueryName('');
      loadSavedQueries();
    } catch {
      // ignore
    }
  };

  const renderTimeInputs = () => {
    if (queryType === 'point_in_time') {
      return (
        <div className="flex items-center gap-2">
          <label htmlFor="intel-f1" className="text-xs text-muted font-medium">Date:</label>
          <input id="intel-f1"
            type="date"
            value={pointDate}
            onChange={(e) => setPointDate(e.target.value)}
            className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary flex-1"
          />
        </div>
      );
    }
    return (
      <div className="flex flex-col sm:flex-row items-start sm:items-center gap-2">
        <div className="flex items-center gap-2 flex-1">
          <label htmlFor="intel-f2" className="text-xs text-muted font-medium">From:</label>
          <input id="intel-f2"
            type="date"
            value={startDate}
            onChange={(e) => setStartDate(e.target.value)}
            className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary flex-1"
          />
        </div>
        <div className="flex items-center gap-2 flex-1">
          <label htmlFor="intel-f3" className="text-xs text-muted font-medium">To:</label>
          <input id="intel-f3"
            type="date"
            value={endDate}
            onChange={(e) => setEndDate(e.target.value)}
            className="bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary flex-1"
          />
        </div>
      </div>
    );
  };

  const renderResults = () => {
    if (!results) return null;

    // Trend data → line chart
    if (queryType === 'trend' && Array.isArray(results.dataPoints)) {
      return (
        <div className="neu-raised p-4 rounded-lg">
          <div className="flex items-center justify-between mb-3">
            <h4 className="text-sm font-bold text-primary">Trend Results</h4>
            {cached && (
              <span className="px-2 py-0.5 rounded-full text-[10px] bg-cba-gold/20 text-cba-gold font-bold">
                <Database className="w-3 h-3 inline mr-1" />
                CACHED
              </span>
            )}
          </div>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={results.dataPoints}>
              <CartesianGrid strokeDasharray="3 3" stroke="#333" />
              <XAxis dataKey="date" tick={{ fill: '#888', fontSize: 11 }} />
              <YAxis tick={{ fill: '#888', fontSize: 11 }} />
              <Tooltip
                contentStyle={{
                  backgroundColor: '#1a1a2e',
                  border: '1px solid #333',
                  borderRadius: 8,
                }}
                labelStyle={{ color: '#FFCC00' }}
              />
              <Line type="monotone" dataKey="value" stroke="#FFCC00" strokeWidth={2} dot={false} />
            </LineChart>
          </ResponsiveContainer>
        </div>
      );
    }

    // Table results
    const rows = results.records ?? results.data ?? (Array.isArray(results) ? results : []);
    if (rows.length > 0) {
      const keys = Object.keys(rows[0]).slice(0, 6);
      return (
        <div className="neu-raised rounded-lg overflow-hidden">
          <div className="flex items-center justify-between p-3 border-b border-border/50">
            <h4 className="text-sm font-bold text-primary">Results ({rows.length})</h4>
            {cached && (
              <span className="px-2 py-0.5 rounded-full text-[10px] bg-cba-gold/20 text-cba-gold font-bold">
                <Database className="w-3 h-3 inline mr-1" />
                CACHED
              </span>
            )}
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border/50">
                  {keys.map((k) => (
                    <th
                      key={k}
                      className="text-left px-3 py-2 text-xs text-muted font-bold uppercase"
                    >
                      {k}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows.slice(0, 50).map((row: Record<string, unknown>, i: number) => (
                  <tr key={`item-${i}`} className="border-b border-border/50 hover:bg-overlay">
                    {keys.map((k) => (
                      <td key={k} className="px-3 py-2 text-primary truncate max-w-[200px]">
                        {String(row[k] ?? '')}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      );
    }

    return (
      <div className="neu-raised p-4 rounded-lg text-center text-muted">
        <p>No results returned.</p>
        {results.message && <p className="text-xs mt-1">{results.message}</p>}
      </div>
    );
  };

  return (
    <div className="flex gap-4">
      {/* Saved queries sidebar */}
      {showSaved && (
        <div className="w-64 shrink-0 neu-raised rounded-lg p-3 space-y-2 hidden lg:block">
          <h4 className="text-xs font-bold text-muted uppercase tracking-wider mb-2">
            Saved Queries
          </h4>
          {savedQueries.length === 0 ? (
            <p className="text-xs text-zinc-600">No saved queries yet.</p>
          ) : (
            savedQueries.map((sq) => (
              <button
                key={sq.id}
                className="w-full text-left p-2 rounded-lg hover:bg-overlay transition-colors group"
              >
                <div className="flex items-center justify-between">
                  <span className="text-sm text-primary truncate">{sq.name}</span>
                  <ChevronRight className="w-3 h-3 text-zinc-600 group-hover:text-cba-gold" />
                </div>
                <span className="text-[10px] text-zinc-600">
                  {sq.queryType} • {sq.entity}
                </span>
              </button>
            ))
          )}
        </div>
      )}

      {/* Main area */}
      <div className="flex-1 space-y-4">
        {/* Query Builder Form */}
        <div className="neu-raised p-4 rounded-lg space-y-4">
          <div className="flex items-center justify-between">
            <h3 className="text-sm font-bold text-cba-gold flex items-center gap-2">
              <Clock className="w-4 h-4" />
              Temporal Query Builder
            </h3>
            <button
              onClick={() => setShowSaved(!showSaved)}
              className="text-xs text-muted hover:text-cba-gold transition-colors hidden lg:block"
            >
              {showSaved ? 'Hide' : 'Show'} Saved
            </button>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label htmlFor="intel-f4" className="text-xs text-muted font-medium block mb-1">Query Type</label>
              <select id="intel-f4"
                value={queryType}
                onChange={(e) => setQueryType(e.target.value as QueryType)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              >
                {queryTypes.map((qt) => (
                  <option key={qt.value} value={qt.value}>
                    {qt.label}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label htmlFor="intel-f5" className="text-xs text-muted font-medium block mb-1">Target Entity</label>
              <select id="intel-f5"
                value={entity}
                onChange={(e) => setEntity(e.target.value as EntityType)}
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary"
              >
                {entityTypes.map((et) => (
                  <option key={et.value} value={et.value}>
                    {et.label}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {renderTimeInputs()}

          {/* Parameters */}
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
            <div>
              <label htmlFor="intel-f6" className="text-xs text-muted font-medium block mb-1">Category</label>
              <input id="intel-f6"
                type="text"
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                placeholder="e.g. Office Expenses"
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary placeholder:text-zinc-600"
              />
            </div>
            <div>
              <label htmlFor="intel-f7" className="text-xs text-muted font-medium block mb-1">Min Amount</label>
              <input id="intel-f7"
                type="number"
                value={minAmount}
                onChange={(e) => setMinAmount(e.target.value)}
                placeholder="0"
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary placeholder:text-zinc-600"
              />
            </div>
            <div>
              <label htmlFor="intel-f8" className="text-xs text-muted font-medium block mb-1">Max Amount</label>
              <input id="intel-f8"
                type="number"
                value={maxAmount}
                onChange={(e) => setMaxAmount(e.target.value)}
                placeholder="10000"
                className="w-full bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary placeholder:text-zinc-600"
              />
            </div>
          </div>

          {/* Actions */}
          <div className="flex items-center gap-3">
            <button
              onClick={executeQuery}
              disabled={loading}
              className="flex items-center gap-2 px-4 py-2 rounded-lg bg-cba-gold text-base font-bold text-sm hover:bg-cba-gold/90 transition-colors disabled:opacity-50"
            >
              <Search className="w-4 h-4" />
              {loading ? 'Executing...' : 'Execute Query'}
            </button>
            <div className="flex items-center gap-2 flex-1">
              <input
                type="text"
                value={queryName}
                onChange={(e) => setQueryName(e.target.value)}
                placeholder="Query name..."
                className="flex-1 bg-zinc-800 border border-zinc-700 rounded-lg px-3 py-2 text-sm text-primary placeholder:text-zinc-600"
              />
              <button
                onClick={saveQuery}
                disabled={!queryName.trim()}
                className="flex items-center gap-1.5 px-3 py-2 rounded-lg text-sm font-medium bg-zinc-800 hover:bg-zinc-700 text-primary transition-colors disabled:opacity-50"
              >
                <Save className="w-4 h-4" /> Save
              </button>
            </div>
          </div>
        </div>

        {/* Error */}
        {error && <div className="neu-raised p-4 rounded-lg text-red-400 text-center">{error}</div>}

        {/* Results */}
        {renderResults()}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { inventoryApi } from '@/api';
import { Search, Plus, Edit2, XCircle, Package, Loader2 } from 'lucide-react';
import { cn } from '@/lib/utils';

interface InventoryItem {
  id: string;
  sku: string;
  name: string;
  category: string;
  unit: string;
  costPriceCents: number;
  salePriceCents: number;
  currentStockQty: number;
  reorderPoint: number;
  isActive: boolean;
}

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

export function InventoryItemList() {
  const [items, setItems] = useState<InventoryItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [editItem, setEditItem] = useState<InventoryItem | null>(null);
  const [formData, setFormData] = useState({
    sku: '',
    name: '',
    category: '',
    unit: 'each',
    costPriceCents: 0,
    salePriceCents: 0,
    reorderPoint: 10,
  });

  const loadItems = async () => {
    setLoading(true);
    try {
      const filters: { search?: string; category?: string } = {};
      if (search) filters.search = search;
      if (categoryFilter) filters.category = categoryFilter;
      const data = await inventoryApi.listItems(filters);
      setItems(Array.isArray(data) ? data : (data.items ?? []));
    } catch (err) {
      console.error('Failed to load items:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadItems();
  }, [search, categoryFilter]);

  const categories = [...new Set(items.map((i) => i.category).filter(Boolean))];

  const handleSubmit = async () => {
    try {
      if (editItem) {
        await inventoryApi.updateItem(editItem.id, formData);
      } else {
        await inventoryApi.createItem(formData);
      }
      setShowForm(false);
      setEditItem(null);
      setFormData({
        sku: '',
        name: '',
        category: '',
        unit: 'each',
        costPriceCents: 0,
        salePriceCents: 0,
        reorderPoint: 10,
      });
      loadItems();
    } catch (err) {
      console.error('Failed to save item:', err);
    }
  };

  const handleDeactivate = async (id: string) => {
    try {
      await inventoryApi.deactivateItem(id);
      loadItems();
    } catch (err) {
      console.error('Failed to deactivate item:', err);
    }
  };

  const openEdit = (item: InventoryItem) => {
    setEditItem(item);
    setFormData({
      sku: item.sku,
      name: item.name,
      category: item.category,
      unit: item.unit,
      costPriceCents: item.costPriceCents,
      salePriceCents: item.salePriceCents,
      reorderPoint: item.reorderPoint,
    });
    setShowForm(true);
  };

  return (
    <div className="space-y-4">
      {/* Toolbar */}
      <div className="flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted" />
          <input
            type="text"
            placeholder="Search by name or SKU..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            className="w-full pl-10 pr-4 py-2.5 rounded-xl neu-inset bg-transparent text-zinc-100 text-sm placeholder:text-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
          />
        </div>
        <select
          value={categoryFilter}
          onChange={(e) => setCategoryFilter(e.target.value)}
          className="px-4 py-2.5 rounded-xl neu-inset bg-transparent text-primary text-sm focus:outline-none"
        >
          <option value="">All Categories</option>
          {categories.map((c) => (
            <option key={c} value={c}>
              {c}
            </option>
          ))}
        </select>
        <button
          onClick={() => {
            setEditItem(null);
            setFormData({
              sku: '',
              name: '',
              category: '',
              unit: 'each',
              costPriceCents: 0,
              salePriceCents: 0,
              reorderPoint: 10,
            });
            setShowForm(true);
          }}
          className="flex items-center gap-2 px-4 py-2.5 rounded-xl bg-cba-gold text-base font-bold text-sm hover:bg-[#FFD633] transition-colors"
        >
          <Plus className="w-4 h-4" /> Add Item
        </button>
      </div>

      {/* Form Modal */}
      {showForm && (
        <div className="neu-raised rounded-2xl p-6 space-y-4 border border-cba-gold/10">
          <h3 className="text-lg font-bold text-zinc-100">{editItem ? 'Edit Item' : 'New Item'}</h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
            <div>
              <label htmlFor="inven-f1" className="text-xs text-muted font-semibold uppercase">SKU</label>
              <input id="inven-f1"
                value={formData.sku}
                onChange={(e) => setFormData((p) => ({ ...p, sku: e.target.value }))}
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
            <div>
              <label htmlFor="inven-f2" className="text-xs text-muted font-semibold uppercase">Name</label>
              <input id="inven-f2"
                value={formData.name}
                onChange={(e) => setFormData((p) => ({ ...p, name: e.target.value }))}
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
            <div>
              <label htmlFor="inven-f3" className="text-xs text-muted font-semibold uppercase">Category</label>
              <input id="inven-f3"
                value={formData.category}
                onChange={(e) => setFormData((p) => ({ ...p, category: e.target.value }))}
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
            <div>
              <label htmlFor="inven-f4" className="text-xs text-muted font-semibold uppercase">Unit</label>
              <input id="inven-f4"
                value={formData.unit}
                onChange={(e) => setFormData((p) => ({ ...p, unit: e.target.value }))}
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
            <div>
              <label htmlFor="inven-f5" className="text-xs text-muted font-semibold uppercase">
                Cost Price (cents)
              </label>
              <input id="inven-f5"
                type="number"
                value={formData.costPriceCents}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, costPriceCents: Number(e.target.value) }))
                }
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
            <div>
              <label htmlFor="inven-f6" className="text-xs text-muted font-semibold uppercase">
                Sale Price (cents)
              </label>
              <input id="inven-f6"
                type="number"
                value={formData.salePriceCents}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, salePriceCents: Number(e.target.value) }))
                }
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
            <div>
              <label htmlFor="inven-f7" className="text-xs text-muted font-semibold uppercase">Reorder Point</label>
              <input id="inven-f7"
                type="number"
                value={formData.reorderPoint}
                onChange={(e) =>
                  setFormData((p) => ({ ...p, reorderPoint: Number(e.target.value) }))
                }
                className="w-full mt-1 px-3 py-2 rounded-lg neu-inset bg-transparent text-zinc-100 text-sm"
              />
            </div>
          </div>
          <div className="flex gap-3">
            <button
              onClick={handleSubmit}
              className="px-5 py-2 rounded-xl bg-cba-gold text-base font-bold text-sm"
            >
              {editItem ? 'Update' : 'Create'}
            </button>
            <button
              onClick={() => {
                setShowForm(false);
                setEditItem(null);
              }}
              className="px-5 py-2 rounded-xl neu-raised text-secondary font-bold text-sm"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Table */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        </div>
      ) : items.length === 0 ? (
        <div className="neu-raised rounded-2xl p-12 text-center">
          <Package className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
          <p className="text-muted">No inventory items found</p>
        </div>
      ) : (
        <div className="neu-raised rounded-2xl overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border/50">
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    SKU
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Name
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Category
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Unit
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Cost
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Sale Price
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Stock
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Reorder
                  </th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-muted uppercase">
                    Status
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => (
                  <tr
                    key={item.id}
                    className={cn(
                      'border-b border-border/50 hover:bg-white/[0.02] transition-colors',
                      item.currentStockQty < item.reorderPoint && 'bg-amber-500/5',
                    )}
                  >
                    <td className="px-4 py-3 font-mono text-secondary">{item.sku}</td>
                    <td className="px-4 py-3 text-zinc-100 font-medium">{item.name}</td>
                    <td className="px-4 py-3 text-secondary">{item.category}</td>
                    <td className="px-4 py-3 text-muted">{item.unit}</td>
                    <td className="px-4 py-3 text-right text-primary">
                      {formatAUD(item.costPriceCents)}
                    </td>
                    <td className="px-4 py-3 text-right text-primary">
                      {formatAUD(item.salePriceCents)}
                    </td>
                    <td
                      className={cn(
                        'px-4 py-3 text-right font-bold',
                        item.currentStockQty < item.reorderPoint
                          ? 'text-amber-400'
                          : 'text-emerald-400',
                      )}
                    >
                      {item.currentStockQty}
                    </td>
                    <td className="px-4 py-3 text-right text-muted">{item.reorderPoint}</td>
                    <td className="px-4 py-3 text-center">
                      <span
                        className={cn(
                          'px-2 py-0.5 rounded-full text-[10px] font-bold uppercase',
                          item.isActive
                            ? 'bg-emerald-500/10 text-emerald-400'
                            : 'bg-zinc-500/10 text-muted',
                        )}
                      >
                        {item.isActive ? 'Active' : 'Inactive'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <div className="flex items-center justify-end gap-1">
                        <button
                          onClick={() => openEdit(item)}
                          className="p-1.5 rounded-lg hover:bg-overlay text-muted hover:text-cba-gold"
                        >
                          <Edit2 className="w-3.5 h-3.5" />
                        </button>
                        <button
                          onClick={() => handleDeactivate(item.id)}
                          className="p-1.5 rounded-lg hover:bg-overlay text-muted hover:text-red-400"
                        >
                          <XCircle className="w-3.5 h-3.5" />
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { inventoryApi } from '@/api';
import { ChevronLeft, ChevronRight, Loader2, ArrowDownUp } from 'lucide-react';
import { cn } from '@/lib/utils';

interface Movement {
  id: string;
  itemId: string;
  itemName: string;
  itemSku: string;
  movementType: 'purchase' | 'sale' | 'adjustment' | 'transfer';
  quantity: number;
  unitCostCents: number;
  totalCostCents: number;
  warehouseId: string;
  warehouseName: string;
  notes: string | null;
  createdAt: string;
}

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const typeColors: Record<string, string> = {
  purchase: 'bg-emerald-500/10 text-emerald-400',
  sale: 'bg-red-500/10 text-red-400',
  transfer: 'bg-blue-500/10 text-blue-400',
  adjustment: 'bg-amber-500/10 text-amber-400',
};

const PAGE_SIZE = 20;

export function MovementHistory() {
  const [movements, setMovements] = useState<Movement[]>([]);
  const [loading, setLoading] = useState(true);
  const [offset, setOffset] = useState(0);
  const [hasMore, setHasMore] = useState(true);
  const [typeFilter, setTypeFilter] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  const loadMovements = async () => {
    setLoading(true);
    try {
      const filters: Record<string, string | number> = { limit: PAGE_SIZE, offset };
      if (typeFilter) filters.movementType = typeFilter;
      if (startDate) filters.startDate = startDate;
      if (endDate) filters.endDate = endDate;
      const data = await inventoryApi.getMovements(filters);
      const items = Array.isArray(data) ? data : (data.movements ?? []);
      setMovements(items);
      setHasMore(items.length === PAGE_SIZE);
    } catch (err) {
      console.error('Failed to load movements:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadMovements();
  }, [offset, typeFilter, startDate, endDate]);

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-col sm:flex-row gap-3">
        <select
          value={typeFilter}
          onChange={(e) => {
            setTypeFilter(e.target.value);
            setOffset(0);
          }}
          className="px-4 py-2.5 rounded-xl neu-inset bg-transparent text-primary text-sm"
        >
          <option value="">All Types</option>
          <option value="purchase">Purchase</option>
          <option value="sale">Sale</option>
          <option value="transfer">Transfer</option>
          <option value="adjustment">Adjustment</option>
        </select>
        <input
          type="date"
          value={startDate}
          onChange={(e) => {
            setStartDate(e.target.value);
            setOffset(0);
          }}
          className="px-4 py-2.5 rounded-xl neu-inset bg-transparent text-primary text-sm"
          placeholder="Start date"
        />
        <input
          type="date"
          value={endDate}
          onChange={(e) => {
            setEndDate(e.target.value);
            setOffset(0);
          }}
          className="px-4 py-2.5 rounded-xl neu-inset bg-transparent text-primary text-sm"
          placeholder="End date"
        />
      </div>

      {/* Table */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        </div>
      ) : movements.length === 0 ? (
        <div className="neu-raised rounded-2xl p-12 text-center">
          <ArrowDownUp className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
          <p className="text-muted">No movements found</p>
        </div>
      ) : (
        <div className="neu-raised rounded-2xl overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-border/50">
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Date
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Item
                  </th>
                  <th className="text-center px-4 py-3 text-xs font-bold text-muted uppercase">
                    Type
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Qty
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Unit Cost
                  </th>
                  <th className="text-right px-4 py-3 text-xs font-bold text-muted uppercase">
                    Total
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Warehouse
                  </th>
                  <th className="text-left px-4 py-3 text-xs font-bold text-muted uppercase">
                    Notes
                  </th>
                </tr>
              </thead>
              <tbody>
                {movements.map((m) => (
                  <tr
                    key={m.id}
                    className="border-b border-border/50 hover:bg-white/[0.02] transition-colors"
                  >
                    <td className="px-4 py-3 text-secondary">
                      {new Date(m.createdAt).toLocaleDateString('en-AU')}
                    </td>
                    <td className="px-4 py-3">
                      <p className="text-zinc-100 font-medium">{m.itemName}</p>
                      <p className="text-xs text-muted">{m.itemSku}</p>
                    </td>
                    <td className="px-4 py-3 text-center">
                      <span
                        className={cn(
                          'px-2 py-0.5 rounded-full text-[10px] font-bold uppercase',
                          typeColors[m.movementType] ?? 'bg-zinc-500/10 text-secondary',
                        )}
                      >
                        {m.movementType}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right font-bold text-primary">{m.quantity}</td>
                    <td className="px-4 py-3 text-right text-secondary">
                      {formatAUD(m.unitCostCents)}
                    </td>
                    <td className="px-4 py-3 text-right text-primary font-medium">
                      {formatAUD(m.totalCostCents)}
                    </td>
                    <td className="px-4 py-3 text-secondary">{m.warehouseName}</td>
                    <td className="px-4 py-3 text-muted text-xs max-w-[200px] truncate">
                      {m.notes || '—'}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Pagination */}
      <div className="flex items-center justify-between">
        <p className="text-xs text-muted">
          Showing {offset + 1}–{offset + movements.length}
        </p>
        <div className="flex gap-2">
          <button
            onClick={() => setOffset(Math.max(0, offset - PAGE_SIZE))}
            disabled={offset === 0}
            className="p-2 rounded-lg neu-raised text-secondary disabled:opacity-30"
          >
            <ChevronLeft className="w-4 h-4" />
          </button>
          <button
            onClick={() => setOffset(offset + PAGE_SIZE)}
            disabled={!hasMore}
            className="p-2 rounded-lg neu-raised text-secondary disabled:opacity-30"
          >
            <ChevronRight className="w-4 h-4" />
          </button>
        </div>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { inventoryApi } from '@/api';
import { AlertTriangle, ArrowRightLeft, Loader2, Warehouse } from 'lucide-react';
import { cn } from '@/lib/utils';

interface StockLevel {
  itemId: string;
  itemName: string;
  sku: string;
  warehouseId: string;
  warehouseName: string;
  quantityOnHand: number;
  quantityAvailable: number;
  reorderPoint: number;
}

export function StockLevelPanel() {
  const [levels, setLevels] = useState<StockLevel[]>([]);
  const [loading, setLoading] = useState(true);
  const [warehouseFilter, setWarehouseFilter] = useState('');

  const loadLevels = async () => {
    setLoading(true);
    try {
      const filters: { warehouseId?: string } = {};
      if (warehouseFilter) filters.warehouseId = warehouseFilter;
      const data = await inventoryApi.getStockLevels(filters);
      setLevels(Array.isArray(data) ? data : (data.levels ?? []));
    } catch (err) {
      console.error('Failed to load stock levels:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadLevels();
  }, [warehouseFilter]);

  const warehouses = [...new Set(levels.map((l) => l.warehouseName).filter(Boolean))];
  const lowStockItems = levels.filter((l) => l.quantityOnHand < l.reorderPoint);
  const grouped = levels.reduce<Record<string, StockLevel[]>>((acc, l) => {
    const key = l.warehouseName || 'Default';
    if (!acc[key]) acc[key] = [];
    acc[key].push(l);
    return acc;
  }, {});

  const getStockPercent = (qty: number, reorder: number) => {
    if (reorder <= 0) return 100;
    return Math.min((qty / (reorder * 2)) * 100, 100);
  };

  const getStockColor = (qty: number, reorder: number) => {
    if (qty <= 0) return 'bg-red-500';
    if (qty < reorder) return 'bg-amber-500';
    return 'bg-emerald-500';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Low Stock Alerts */}
      {lowStockItems.length > 0 && (
        <div className="neu-raised rounded-2xl p-5 border border-amber-500/20">
          <div className="flex items-center gap-2 mb-3">
            <AlertTriangle className="w-5 h-5 text-amber-400" />
            <h3 className="text-sm font-bold text-amber-400 uppercase tracking-wider">
              Low Stock Alerts ({lowStockItems.length})
            </h3>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
            {lowStockItems.map((item) => (
              <div key={`${item.itemId}-${item.warehouseId}`} className="neu-inset rounded-xl p-3">
                <div className="flex justify-between items-start">
                  <div>
                    <p className="text-sm font-medium text-zinc-100">{item.itemName}</p>
                    <p className="text-xs text-muted">
                      {item.sku} • {item.warehouseName}
                    </p>
                  </div>
                  <span className="text-amber-400 font-bold text-sm">{item.quantityOnHand}</span>
                </div>
                <p className="text-[10px] text-zinc-600 mt-1">Reorder at: {item.reorderPoint}</p>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Filter + Actions */}
      <div className="flex flex-col sm:flex-row gap-3">
        <select
          value={warehouseFilter}
          onChange={(e) => setWarehouseFilter(e.target.value)}
          className="px-4 py-2.5 rounded-xl neu-inset bg-transparent text-primary text-sm"
        >
          <option value="">All Warehouses</option>
          {warehouses.map((w) => (
            <option key={w} value={w}>
              {w}
            </option>
          ))}
        </select>
        <div className="flex gap-2 ml-auto">
          <button className="flex items-center gap-2 px-4 py-2 rounded-xl neu-raised text-primary text-sm hover:text-cba-gold">
            <ArrowRightLeft className="w-4 h-4" /> Transfer
          </button>
        </div>
      </div>

      {/* Warehouse Groups */}
      {Object.entries(grouped).map(([warehouse, warehouseItems]) => (
        <div key={warehouse} className="neu-raised rounded-2xl overflow-hidden">
          <div className="px-5 py-3 border-b border-border/50 flex items-center gap-2">
            <Warehouse className="w-4 h-4 text-cba-gold" />
            <h3 className="text-sm font-bold text-primary">{warehouse}</h3>
            <span className="text-xs text-muted ml-auto">{warehouseItems.length} items</span>
          </div>
          <div className="divide-y divide-white/5">
            {warehouseItems.map((item) => (
              <div
                key={`${item.itemId}-${item.warehouseId}`}
                className="px-5 py-3 flex items-center gap-4"
              >
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-zinc-100 truncate">{item.itemName}</p>
                  <p className="text-xs text-muted">{item.sku}</p>
                </div>
                <div className="flex items-center gap-4 shrink-0">
                  <div className="text-right">
                    <p
                      className={cn(
                        'text-sm font-bold',
                        item.quantityOnHand < item.reorderPoint
                          ? 'text-amber-400'
                          : 'text-emerald-400',
                      )}
                    >
                      {item.quantityOnHand}
                    </p>
                    <p className="text-[10px] text-zinc-600">avail: {item.quantityAvailable}</p>
                  </div>
                  <div className="w-24">
                    <div className="w-full h-2 rounded-full bg-zinc-800">
                      <div
                        className={cn(
                          'h-full rounded-full transition-all',
                          getStockColor(item.quantityOnHand, item.reorderPoint),
                        )}
                        style={{
                          width: `${getStockPercent(item.quantityOnHand, item.reorderPoint)}%`,
                        }}
                      />
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      ))}

      {levels.length === 0 && (
        <div className="neu-raised rounded-2xl p-12 text-center">
          <Warehouse className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
          <p className="text-muted">No stock levels data available</p>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { inventoryApi } from '@/api';
import { DollarSign, Loader2, PieChart } from 'lucide-react';
import { cn } from '@/lib/utils';

interface ValuationData {
  totalValueCents: number;
  totalItems: number;
  asOfDate: string;
  categories: Array<{
    category: string;
    itemCount: number;
    totalValueCents: number;
    percentOfTotal: number;
  }>;
}

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

export function ValuationReport() {
  const [data, setData] = useState<ValuationData | null>(null);
  const [loading, setLoading] = useState(true);
  const [asOfDate, setAsOfDate] = useState('');

  const loadValuation = async () => {
    setLoading(true);
    try {
      const result = await inventoryApi.getValuation(asOfDate || undefined);
      setData(result);
    } catch (err) {
      console.error('Failed to load valuation:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadValuation();
  }, [asOfDate]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  if (!data) {
    return (
      <div className="neu-raised rounded-2xl p-12 text-center">
        <PieChart className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
        <p className="text-muted">No valuation data available</p>
      </div>
    );
  }

  const barColors = [
    'bg-cba-gold',
    'bg-emerald-500',
    'bg-blue-500',
    'bg-purple-500',
    'bg-orange-500',
    'bg-cyan-500',
    'bg-rose-500',
    'bg-amber-500',
  ];

  return (
    <div className="space-y-6">
      {/* Date Selector */}
      <div className="flex items-center gap-3">
        <label htmlFor="valuat-f1" className="text-sm text-muted">As of date:</label>
        <input id="valuat-f1"
          type="date"
          value={asOfDate}
          onChange={(e) => setAsOfDate(e.target.value)}
          className="px-4 py-2 rounded-xl neu-inset bg-transparent text-primary text-sm"
        />
        {asOfDate && (
          <button
            onClick={() => setAsOfDate('')}
            className="text-xs text-muted hover:text-primary"
          >
            Clear
          </button>
        )}
      </div>

      {/* Total Value Banner */}
      <div className="neu-raised rounded-2xl p-6 border border-cba-gold/10">
        <div className="flex items-center gap-4">
          <div className="neu-inset p-3 rounded-xl">
            <DollarSign className="w-8 h-8 text-cba-gold" />
          </div>
          <div>
            <p className="text-xs text-muted uppercase font-semibold tracking-wider">
              Total Inventory Value
            </p>
            <p className="text-3xl font-bold text-gradient-gold">
              {formatAUD(data.totalValueCents)}
            </p>
            <p className="text-xs text-muted mt-1">
              {data.totalItems} items •{' '}
              {data.asOfDate
                ? `As of ${new Date(data.asOfDate).toLocaleDateString('en-AU')}`
                : 'Current'}
            </p>
          </div>
        </div>
      </div>

      {/* Category Breakdown */}
      {data.categories && data.categories.length > 0 && (
        <div className="neu-raised rounded-2xl overflow-hidden">
          <div className="px-5 py-3 border-b border-border/50">
            <h3 className="text-sm font-bold text-primary">Category Breakdown</h3>
          </div>

          {/* Horizontal Bar Chart */}
          <div className="px-5 py-4 space-y-3">
            {data.categories.map((cat, i) => (
              <div key={cat.category} className="space-y-1">
                <div className="flex justify-between text-xs">
                  <span className="text-primary font-medium">{cat.category}</span>
                  <span className="text-muted">{cat.percentOfTotal.toFixed(1)}%</span>
                </div>
                <div className="w-full h-3 rounded-full bg-zinc-800">
                  <div
                    className={cn(
                      'h-full rounded-full transition-all',
                      barColors[i % barColors.length],
                    )}
                    style={{ width: `${cat.percentOfTotal}%` }}
                  />
                </div>
              </div>
            ))}
          </div>

          {/* Category Table */}
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-t border-b border-border/50">
                  <th className="text-left px-5 py-3 text-xs font-bold text-muted uppercase">
                    Category
                  </th>
                  <th className="text-right px-5 py-3 text-xs font-bold text-muted uppercase">
                    Items
                  </th>
                  <th className="text-right px-5 py-3 text-xs font-bold text-muted uppercase">
                    Total Value
                  </th>
                  <th className="text-right px-5 py-3 text-xs font-bold text-muted uppercase">
                    % of Total
                  </th>
                </tr>
              </thead>
              <tbody>
                {data.categories.map((cat) => (
                  <tr key={cat.category} className="border-b border-border/50">
                    <td className="px-5 py-3 text-zinc-100 font-medium">{cat.category}</td>
                    <td className="px-5 py-3 text-right text-secondary">{cat.itemCount}</td>
                    <td className="px-5 py-3 text-right text-primary font-medium">
                      {formatAUD(cat.totalValueCents)}
                    </td>
                    <td className="px-5 py-3 text-right text-secondary">
                      {cat.percentOfTotal.toFixed(1)}%
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Export */}
      <div className="flex justify-end">
        <button
          className="px-4 py-2 rounded-xl neu-raised text-secondary text-sm hover:text-primary"
          title="Export available in Professional plan"
          disabled
        >
          Export CSV
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { invoicingApi } from '@/api';
import {
  ArrowLeft,
  Edit2,
  Archive,
  Loader2,
  Building2,
  Mail,
  Phone,
  MapPin,
  FileText,
  Plus,
  UserPlus,
  DollarSign,
  AlertTriangle,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface CustomerDetailProps {
  customerId: string;
  onBack: () => void;
  onEdit: (customer: CustomerRecord) => void;
}

const formatABN = (abn: string | null | undefined): string => {
  if (!abn) return '—';
  const digits = abn.replace(/\D/g, '');
  if (digits.length !== 11) return abn;
  return `${digits.slice(0, 2)} ${digits.slice(2, 5)} ${digits.slice(5, 8)} ${digits.slice(8, 11)}`;
};

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

interface CustomerRecord {
  businessName?: string;
  abn?: string;
  contactName?: string;
  email?: string;
  phone?: string;
  address?: string;
  city?: string;
  state?: string;
  postcode?: string;
  notes?: string;
  paymentTermsDays?: number;
  isActive?: boolean;
  outstandingBalance?: number;
  overdueAmount?: number;
  invoices?: Array<{ id: string; invoiceNumber?: string; issueDate?: string; date?: string; totalCents?: number; total?: number; status?: string }>;
  [key: string]: unknown;
}

interface ContactRecord {
  id?: string;
  name: string;
  email?: string;
  phone?: string;
  role?: string;
}

export function CustomerDetail({ customerId, onBack, onEdit }: CustomerDetailProps) {
  const [customer, setCustomer] = useState<CustomerRecord | null>(null);
  const [contacts, setContacts] = useState<ContactRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [archiving, setArchiving] = useState(false);
  const [showArchiveConfirm, setShowArchiveConfirm] = useState(false);
  const [showAddContact, setShowAddContact] = useState(false);
  const [newContact, setNewContact] = useState({ name: '', email: '', phone: '', role: '' });
  const [addingContact, setAddingContact] = useState(false);

  useEffect(() => {
    const load = async () => {
      setLoading(true);
      try {
        const [cust, contactsRes] = await Promise.all([
          invoicingApi.getCustomer(customerId),
          invoicingApi.listContacts(customerId).catch(() => []),
        ]);
        setCustomer(cust);
        setContacts(Array.isArray(contactsRes) ? contactsRes : (contactsRes?.contacts ?? []));
      } catch (err) {
        console.error('Failed to load customer:', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [customerId]);

  const handleArchive = async () => {
    setArchiving(true);
    try {
      await invoicingApi.archiveCustomer(customerId);
      onBack();
    } catch (err) {
      console.error('Failed to archive customer:', err);
    } finally {
      setArchiving(false);
      setShowArchiveConfirm(false);
    }
  };

  const handleAddContact = async () => {
    if (!newContact.name.trim()) return;
    setAddingContact(true);
    try {
      await invoicingApi.addContact(customerId, newContact);
      const res = await invoicingApi.listContacts(customerId).catch(() => []);
      setContacts(Array.isArray(res) ? res : (res?.contacts ?? []));
      setNewContact({ name: '', email: '', phone: '', role: '' });
      setShowAddContact(false);
    } catch (err) {
      console.error('Failed to add contact:', err);
    } finally {
      setAddingContact(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  if (!customer) {
    return (
      <div className="neu-raised rounded-2xl p-8 text-center">
        <p className="text-secondary">Customer not found.</p>
        <button onClick={onBack} className="mt-4 text-cba-gold text-sm hover:underline">
          Go back
        </button>
      </div>
    );
  }

  const outstanding = customer.outstandingBalance ?? 0;
  const overdue = customer.overdueAmount ?? 0;
  const invoices = customer.invoices ?? [];

  return (
    <div className="space-y-6">
      {/* Back + Actions */}
      <div className="flex items-center justify-between">
        <button
          onClick={onBack}
          className="flex items-center gap-2 text-secondary hover:text-zinc-100 text-sm transition-colors"
        >
          <ArrowLeft className="w-4 h-4" />
          Back to Customers
        </button>
        <div className="flex items-center gap-2">
          <button
            onClick={() => onEdit(customer)}
            className="flex items-center gap-2 px-3 py-1.5 rounded-lg neu-raised text-primary hover:text-zinc-100 text-sm transition-colors"
          >
            <Edit2 className="w-3.5 h-3.5" />
            Edit
          </button>
          <button
            onClick={() => setShowArchiveConfirm(true)}
            className="flex items-center gap-2 px-3 py-1.5 rounded-lg neu-raised text-red-400 hover:text-red-300 text-sm transition-colors"
          >
            <Archive className="w-3.5 h-3.5" />
            Archive
          </button>
        </div>
      </div>

      {/* Archive Confirmation */}
      {showArchiveConfirm && (
        <div className="neu-raised rounded-xl p-4 border border-red-500/20">
          <p className="text-sm text-primary mb-3">
            Are you sure you want to archive <strong>{customer.businessName}</strong>? This will
            hide them from the active list.
          </p>
          <div className="flex gap-2">
            <button
              onClick={handleArchive}
              disabled={archiving}
              className="px-4 py-1.5 rounded-lg bg-red-500/20 text-red-400 text-sm font-semibold hover:bg-red-500/30 disabled:opacity-50"
            >
              {archiving ? 'Archiving...' : 'Confirm Archive'}
            </button>
            <button
              onClick={() => setShowArchiveConfirm(false)}
              className="px-4 py-1.5 rounded-lg neu-raised text-secondary text-sm"
            >
              Cancel
            </button>
          </div>
        </div>
      )}

      {/* Customer Info */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <div className="lg:col-span-2 neu-raised rounded-2xl p-5 space-y-4">
          <div className="flex items-center gap-3">
            <div className="neu-inset p-3 rounded-xl text-cba-gold">
              <Building2 className="w-6 h-6" />
            </div>
            <div>
              <h3 className="text-lg font-bold text-zinc-100">{customer.businessName}</h3>
              {customer.abn && (
                <p className="text-xs text-muted font-mono">ABN: {formatABN(customer.abn)}</p>
              )}
            </div>
            <span
              className={cn(
                'ml-auto inline-flex items-center px-2.5 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider',
                customer.isActive !== false
                  ? 'bg-emerald-500/20 text-emerald-400'
                  : 'bg-zinc-700/50 text-muted',
              )}
            >
              {customer.isActive !== false ? 'Active' : 'Archived'}
            </span>
          </div>

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 text-sm">
            {customer.contactName && (
              <div className="flex items-center gap-2 text-secondary">
                <UserPlus className="w-4 h-4 text-zinc-600 flex-shrink-0" />
                {customer.contactName}
              </div>
            )}
            {customer.email && (
              <div className="flex items-center gap-2 text-secondary">
                <Mail className="w-4 h-4 text-zinc-600 flex-shrink-0" />
                {customer.email}
              </div>
            )}
            {customer.phone && (
              <div className="flex items-center gap-2 text-secondary">
                <Phone className="w-4 h-4 text-zinc-600 flex-shrink-0" />
                {customer.phone}
              </div>
            )}
            {(customer.address || customer.city) && (
              <div className="flex items-center gap-2 text-secondary">
                <MapPin className="w-4 h-4 text-zinc-600 flex-shrink-0" />
                {[customer.address, customer.city, customer.state, customer.postcode]
                  .filter(Boolean)
                  .join(', ')}
              </div>
            )}
          </div>

          {customer.notes && (
            <div className="text-xs text-muted border-t border-zinc-800 pt-3">
              <span className="text-zinc-600 uppercase tracking-wider font-semibold text-[10px]">
                Notes:{' '}
              </span>
              {customer.notes}
            </div>
          )}

          {customer.paymentTermsDays && (
            <p className="text-xs text-muted">
              Payment terms: <span className="text-primary">{customer.paymentTermsDays} days</span>
            </p>
          )}
        </div>

        {/* Balance Summary */}
        <div className="space-y-4">
          <div className="neu-raised rounded-2xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <DollarSign className="w-4 h-4 text-cba-gold" />
              <span className="text-[10px] text-zinc-600 uppercase font-semibold tracking-wider">
                Outstanding
              </span>
            </div>
            <p
              className={cn(
                'text-2xl font-bold',
                outstanding > 0 ? 'text-cba-gold' : 'text-muted',
              )}
            >
              {formatAUD(outstanding)}
            </p>
          </div>
          <div className="neu-raised rounded-2xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <AlertTriangle className="w-4 h-4 text-red-400" />
              <span className="text-[10px] text-zinc-600 uppercase font-semibold tracking-wider">
                Overdue
              </span>
            </div>
            <p className={cn('text-2xl font-bold', overdue > 0 ? 'text-red-400' : 'text-muted')}>
              {formatAUD(overdue)}
            </p>
          </div>
        </div>
      </div>

      {/* Contacts */}
      <div className="neu-raised rounded-2xl p-5 space-y-3">
        <div className="flex items-center justify-between">
          <h4 className="text-sm font-bold text-primary uppercase tracking-wider">Contacts</h4>
          <button
            onClick={() => setShowAddContact(!showAddContact)}
            className="flex items-center gap-1.5 text-cba-gold text-xs font-semibold hover:underline"
          >
            <Plus className="w-3.5 h-3.5" />
            Add Contact
          </button>
        </div>

        {showAddContact && (
          <div className="grid grid-cols-1 sm:grid-cols-4 gap-2 p-3 neu-inset rounded-xl">
            <input
              type="text"
              placeholder="Name *"
              value={newContact.name}
              onChange={(e) => setNewContact((p) => ({ ...p, name: e.target.value }))}
              className="px-3 py-1.5 rounded-lg neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none"
            />
            <input
              type="email"
              placeholder="Email"
              value={newContact.email}
              onChange={(e) => setNewContact((p) => ({ ...p, email: e.target.value }))}
              className="px-3 py-1.5 rounded-lg neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none"
            />
            <input
              type="text"
              placeholder="Phone"
              value={newContact.phone}
              onChange={(e) => setNewContact((p) => ({ ...p, phone: e.target.value }))}
              className="px-3 py-1.5 rounded-lg neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none"
            />
            <div className="flex gap-2">
              <input
                type="text"
                placeholder="Role"
                value={newContact.role}
                onChange={(e) => setNewContact((p) => ({ ...p, role: e.target.value }))}
                className="flex-1 px-3 py-1.5 rounded-lg neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none"
              />
              <button
                onClick={handleAddContact}
                disabled={addingContact || !newContact.name.trim()}
                className="px-3 py-1.5 rounded-lg bg-cba-gold text-base text-xs font-bold disabled:opacity-40"
              >
                {addingContact ? '...' : 'Add'}
              </button>
            </div>
          </div>
        )}

        {contacts.length === 0 ? (
          <p className="text-xs text-zinc-600">No additional contacts.</p>
        ) : (
          <div className="space-y-2">
            {contacts.map((c: ContactRecord, i: number) => (
              <div
                key={c.id ?? i}
                className="flex items-center gap-4 px-3 py-2 rounded-lg hover:bg-zinc-800/30 text-sm"
              >
                <span className="font-medium text-primary">{c.name}</span>
                {c.role && <span className="text-zinc-600 text-xs">({c.role})</span>}
                {c.email && <span className="text-muted">{c.email}</span>}
                {c.phone && <span className="text-muted">{c.phone}</span>}
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Invoice History */}
      <div className="neu-raised rounded-2xl p-5 space-y-3">
        <h4 className="text-sm font-bold text-primary uppercase tracking-wider">
          Invoice History
        </h4>
        {invoices.length === 0 ? (
          <p className="text-xs text-zinc-600">No invoices for this customer yet.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-zinc-800">
                  <th className="text-left px-3 py-2 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Invoice #
                  </th>
                  <th className="text-left px-3 py-2 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Date
                  </th>
                  <th className="text-right px-3 py-2 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Amount
                  </th>
                  <th className="text-center px-3 py-2 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Status
                  </th>
                </tr>
              </thead>
              <tbody>
                {invoices.map((inv: { id: string; invoiceNumber?: string; issueDate?: string; date?: string; totalCents?: number; total?: number; status?: string }) => (
                  <tr key={inv.id} className="border-b border-zinc-800/50 hover:bg-zinc-800/20">
                    <td className="px-3 py-2 text-primary font-mono">
                      {inv.invoiceNumber ?? inv.id}
                    </td>
                    <td className="px-3 py-2 text-secondary">{inv.issueDate ?? inv.date ?? '—'}</td>
                    <td className="px-3 py-2 text-right font-semibold text-cba-gold">
                      {formatAUD(inv.totalCents ?? inv.total ?? 0)}
                    </td>
                    <td className="px-3 py-2 text-center">
                      <span
                        className={cn(
                          'inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider',
                          inv.status === 'paid'
                            ? 'bg-emerald-500/20 text-emerald-400'
                            : inv.status === 'overdue'
                              ? 'bg-red-500/20 text-red-400'
                              : inv.status === 'sent'
                                ? 'bg-blue-500/20 text-blue-400'
                                : 'bg-zinc-700/50 text-muted',
                        )}
                      >
                        {inv.status ?? 'draft'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { invoicingApi } from '@/api';
import { Plus, X, Loader2, Save, Send } from 'lucide-react';
import { cn } from '@/lib/utils';

interface LineItem {
  id: string;
  description: string;
  quantity: number;
  unitPrice: number; // cents
  gstRate: number; // 0.10 for 10%
}

interface InvoiceEditorProps {
  invoiceId?: string;
  onSave: () => void;
  onCancel: () => void;
}

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

let lineIdCounter = 0;
const nextLineId = () => `line-${++lineIdCounter}-${Date.now()}`;

const DEFAULT_TERMS = `Payment is due within the specified terms. Late payments may incur interest at 2% per month on the outstanding balance.`;

export function InvoiceEditor({ invoiceId, onSave, onCancel }: InvoiceEditorProps) {
  const [loading, setLoading] = useState(!!invoiceId);
  const [saving, setSaving] = useState(false);
  const [customers, setCustomers] = useState<any[]>([]);
  const [customerSearch, setCustomerSearch] = useState('');
  const [showCustomerDropdown, setShowCustomerDropdown] = useState(false);
  const [selectedCustomer, setSelectedCustomer] = useState<any>(null);

  const [invoiceNumber, setInvoiceNumber] = useState('');
  const [issueDate, setIssueDate] = useState(() => new Date().toISOString().split('T')[0]);
  const [dueDate, setDueDate] = useState('');
  const [notes, setNotes] = useState('');
  const [terms, setTerms] = useState(DEFAULT_TERMS);
  const [lineItems, setLineItems] = useState<LineItem[]>([
    { id: nextLineId(), description: '', quantity: 1, unitPrice: 0, gstRate: 0.1 },
  ]);

  // Load next invoice number
  useEffect(() => {
    if (!invoiceId) {
      invoicingApi
        .getNextInvoiceNumber()
        .then((num) => setInvoiceNumber(num))
        .catch(() => setInvoiceNumber('INV-000001'));
    }
  }, [invoiceId]);

  // Load existing invoice for editing
  useEffect(() => {
    if (!invoiceId) return;
    const load = async () => {
      setLoading(true);
      try {
        const inv = await invoicingApi.getInvoice(invoiceId);
        setInvoiceNumber(inv.invoiceNumber ?? '');
        setIssueDate(inv.issueDate?.split('T')[0] ?? '');
        setDueDate(inv.dueDate?.split('T')[0] ?? '');
        setNotes(inv.notes ?? '');
        setTerms(inv.terms ?? DEFAULT_TERMS);
        if (inv.customerId) {
          try {
            const cust = await invoicingApi.listCustomers({ search: inv.customerName, limit: 1 });
            if (cust?.customers?.[0]) setSelectedCustomer(cust.customers[0]);
          } catch {
            /* ignore */
          }
        }
        if (inv.lineItems?.length) {
          setLineItems(
            (inv.lineItems as Array<Record<string, unknown>>).map((li) => ({
              id: nextLineId(),
              description: li.description ?? '',
              quantity: li.quantity ?? 1,
              unitPrice: li.unitPrice ?? 0,
              gstRate: li.gstRate ?? 0.1,
            })),
          );
        }
      } catch (err) {
        console.error('Failed to load invoice:', err);
      } finally {
        setLoading(false);
      }
    };
    load();
  }, [invoiceId]);

  // Auto-calc due date from customer payment terms
  useEffect(() => {
    if (selectedCustomer && issueDate) {
      const days = selectedCustomer.paymentTermsDays ?? 30;
      const d = new Date(issueDate);
      d.setDate(d.getDate() + days);
      setDueDate(d.toISOString().split('T')[0]);
    }
  }, [selectedCustomer, issueDate]);

  // Customer search
  const searchCustomers = useCallback(async (query: string) => {
    if (!query || query.length < 2) {
      setCustomers([]);
      return;
    }
    try {
      const res = await invoicingApi.listCustomers({ search: query, limit: 10 });
      setCustomers(res?.customers ?? []);
    } catch {
      setCustomers([]);
    }
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => searchCustomers(customerSearch), 300);
    return () => clearTimeout(timer);
  }, [customerSearch, searchCustomers]);

  // Line item helpers
  const addLine = () => {
    setLineItems((prev) => [
      ...prev,
      { id: nextLineId(), description: '', quantity: 1, unitPrice: 0, gstRate: 0.1 },
    ]);
  };

  const removeLine = (id: string) => {
    setLineItems((prev) => (prev.length > 1 ? prev.filter((li) => li.id !== id) : prev));
  };

  const updateLine = (id: string, field: keyof LineItem, value: string | number) => {
    setLineItems((prev) => prev.map((li) => (li.id === id ? { ...li, [field]: value } : li)));
  };

  // Totals
  const subtotal = lineItems.reduce((sum, li) => sum + li.quantity * li.unitPrice, 0);
  const gstTotal = lineItems.reduce(
    (sum, li) => sum + Math.round(li.quantity * li.unitPrice * li.gstRate),
    0,
  );
  const grandTotal = subtotal + gstTotal;

  const buildPayload = () => ({
    customerId: selectedCustomer?.id,
    invoiceNumber,
    issueDate,
    dueDate,
    notes,
    terms,
    lineItems: lineItems.map((li) => ({
      description: li.description,
      quantity: li.quantity,
      unitPrice: li.unitPrice,
      gstRate: li.gstRate,
      amount: li.quantity * li.unitPrice,
      gstAmount: Math.round(li.quantity * li.unitPrice * li.gstRate),
    })),
    subtotal,
    gstTotal,
    total: grandTotal,
  });

  const handleSave = async (sendAfter = false) => {
    if (!selectedCustomer) return;
    setSaving(true);
    try {
      const payload = buildPayload();
      if (invoiceId) {
        await invoicingApi.updateInvoice(invoiceId, payload);
        if (sendAfter) await invoicingApi.sendInvoice(invoiceId);
      } else {
        const result = await invoicingApi.createInvoice({ ...payload, status: 'draft' });
        if (sendAfter && result?.id) await invoicingApi.sendInvoice(result.id);
      }
      onSave();
    } catch (err) {
      console.error('Failed to save invoice:', err);
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="space-y-6 max-w-4xl">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-bold text-zinc-100">
          {invoiceId ? 'Edit Invoice' : 'New Invoice'}
        </h3>
        <span className="text-sm font-mono text-cba-gold">{invoiceNumber}</span>
      </div>

      {/* Customer Selector */}
      <div className="neu-raised rounded-2xl p-5 space-y-4">
        <h4 className="text-xs font-bold uppercase tracking-wider text-muted">Customer</h4>

        {selectedCustomer ? (
          <div className="flex items-center justify-between neu-inset rounded-xl p-3">
            <div>
              <p className="font-semibold text-zinc-100">{selectedCustomer.businessName}</p>
              <p className="text-xs text-muted">
                {selectedCustomer.contactName ?? ''}{' '}
                {selectedCustomer.abn ? `| ABN: ${selectedCustomer.abn}` : ''}
              </p>
            </div>
            <button
              onClick={() => {
                setSelectedCustomer(null);
                setCustomerSearch('');
              }}
              className="p-1.5 rounded-lg hover:bg-zinc-700/50 text-secondary hover:text-zinc-100 transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        ) : (
          <div className="relative">
            <input
              type="text"
              value={customerSearch}
              onChange={(e) => {
                setCustomerSearch(e.target.value);
                setShowCustomerDropdown(true);
              }}
              onFocus={() => setShowCustomerDropdown(true)}
              placeholder="Search customers by name, ABN, or email..."
              className="w-full px-4 py-2.5 rounded-xl neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            />
            {showCustomerDropdown && customers.length > 0 && (
              <div className="absolute z-20 top-full mt-1 w-full max-h-48 overflow-y-auto rounded-xl bg-[#15161f] border border-zinc-700 shadow-xl">
                {customers.map((c) => (
                  <button
                    key={c.id}
                    onClick={() => {
                      setSelectedCustomer(c);
                      setCustomerSearch('');
                      setShowCustomerDropdown(false);
                    }}
                    className="w-full text-left px-4 py-2.5 hover:bg-zinc-800/50 transition-colors border-b border-zinc-800/50 last:border-0"
                  >
                    <p className="text-sm font-semibold text-primary">{c.businessName}</p>
                    <p className="text-xs text-muted">
                      {c.contactName ?? ''} {c.email ? `| ${c.email}` : ''}
                    </p>
                  </button>
                ))}
              </div>
            )}
          </div>
        )}
      </div>

      {/* Invoice Details */}
      <div className="neu-raised rounded-2xl p-5 space-y-4">
        <h4 className="text-xs font-bold uppercase tracking-wider text-muted">
          Invoice Details
        </h4>
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <div>
            <label htmlFor="invoi-f1" className="block text-xs text-muted mb-1">Issue Date</label>
            <input id="invoi-f1"
              type="date"
              value={issueDate}
              onChange={(e) => setIssueDate(e.target.value)}
              className="w-full px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            />
          </div>
          <div>
            <label htmlFor="invoi-f2" className="block text-xs text-muted mb-1">Due Date</label>
            <input id="invoi-f2"
              type="date"
              value={dueDate}
              onChange={(e) => setDueDate(e.target.value)}
              className="w-full px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            />
          </div>
        </div>
        <div>
          <label htmlFor="invoi-f3" className="block text-xs text-muted mb-1">Notes</label>
          <textarea id="invoi-f3"
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
            rows={2}
            className="w-full px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 resize-none focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            placeholder="Additional notes for this invoice..."
          />
        </div>
        <div>
          <label htmlFor="invoi-f4" className="block text-xs text-muted mb-1">Terms & Conditions</label>
          <textarea id="invoi-f4"
            value={terms}
            onChange={(e) => setTerms(e.target.value)}
            rows={2}
            className="w-full px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 resize-none focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
          />
        </div>
      </div>

      {/* Line Items */}
      <div className="neu-raised rounded-2xl p-5 space-y-4">
        <h4 className="text-xs font-bold uppercase tracking-wider text-muted">Line Items</h4>

        {/* Header */}
        <div className="hidden sm:grid grid-cols-12 gap-2 text-[10px] uppercase tracking-wider text-muted font-semibold px-1">
          <div className="col-span-4">Description</div>
          <div className="col-span-2 text-right">Qty</div>
          <div className="col-span-2 text-right">Unit Price</div>
          <div className="col-span-2 text-right">GST Rate</div>
          <div className="col-span-1 text-right">Amount</div>
          <div className="col-span-1" />
        </div>

        {lineItems.map((li) => {
          const lineAmount = li.quantity * li.unitPrice;
          const lineGst = Math.round(lineAmount * li.gstRate);
          return (
            <div key={li.id} className="grid grid-cols-12 gap-2 items-center">
              <div className="col-span-12 sm:col-span-4">
                <input
                  type="text"
                  value={li.description}
                  onChange={(e) => updateLine(li.id, 'description', e.target.value)}
                  placeholder="Item description"
                  className="w-full px-3 py-2 rounded-lg neu-inset bg-transparent text-sm text-primary placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
                />
              </div>
              <div className="col-span-4 sm:col-span-2">
                <input
                  type="number"
                  value={li.quantity}
                  onChange={(e) =>
                    updateLine(li.id, 'quantity', Math.max(0, parseFloat(e.target.value) || 0))
                  }
                  min="0"
                  step="1"
                  className="w-full px-3 py-2 rounded-lg neu-inset bg-transparent text-sm text-primary text-right focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
                />
              </div>
              <div className="col-span-4 sm:col-span-2">
                <input
                  type="number"
                  value={li.unitPrice ? (li.unitPrice / 100).toFixed(2) : ''}
                  onChange={(e) =>
                    updateLine(
                      li.id,
                      'unitPrice',
                      Math.round((parseFloat(e.target.value) || 0) * 100),
                    )
                  }
                  min="0"
                  step="0.01"
                  placeholder="0.00"
                  className="w-full px-3 py-2 rounded-lg neu-inset bg-transparent text-sm text-primary text-right focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
                />
              </div>
              <div className="col-span-3 sm:col-span-2">
                <select
                  value={li.gstRate}
                  onChange={(e) => updateLine(li.id, 'gstRate', parseFloat(e.target.value))}
                  className="w-full px-3 py-2 rounded-lg neu-inset bg-transparent text-sm text-primary focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
                >
                  <option value={0.1}>10% GST</option>
                  <option value={0}>GST Free</option>
                </select>
              </div>
              <div className="col-span-4 sm:col-span-1 text-right">
                <span className="text-sm font-semibold text-primary">
                  {formatAUD(lineAmount + lineGst)}
                </span>
              </div>
              <div className="col-span-1 text-right">
                <button
                  onClick={() => removeLine(li.id)}
                  disabled={lineItems.length === 1}
                  className="p-1.5 rounded-lg hover:bg-red-500/20 text-muted hover:text-red-400 transition-colors disabled:opacity-20 disabled:cursor-not-allowed"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>
          );
        })}

        <button
          onClick={addLine}
          className="flex items-center gap-2 text-sm text-cba-gold hover:text-[#FFD633] font-semibold transition-colors"
        >
          <Plus className="w-4 h-4" />
          Add Line Item
        </button>
      </div>

      {/* Totals */}
      <div className="neu-raised rounded-2xl p-5">
        <div className="flex flex-col items-end gap-2">
          <div className="flex justify-between w-full sm:w-64">
            <span className="text-sm text-secondary">Subtotal</span>
            <span className="text-sm font-semibold text-primary">{formatAUD(subtotal)}</span>
          </div>
          <div className="flex justify-between w-full sm:w-64">
            <span className="text-sm text-secondary">GST (10%)</span>
            <span className="text-sm font-semibold text-primary">{formatAUD(gstTotal)}</span>
          </div>
          <div className="flex justify-between w-full sm:w-64 pt-2 border-t border-zinc-700">
            <span className="text-base font-bold text-zinc-100">Total</span>
            <span className="text-base font-bold text-gradient-gold">{formatAUD(grandTotal)}</span>
          </div>
        </div>
      </div>

      {/* Actions */}
      <div className="flex flex-wrap gap-3 justify-end">
        <button
          onClick={onCancel}
          className="px-5 py-2.5 rounded-xl neu-raised text-sm font-semibold text-secondary hover:text-zinc-100 transition-colors"
        >
          Cancel
        </button>
        <button
          onClick={() => handleSave(false)}
          disabled={saving || !selectedCustomer}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl neu-raised text-sm font-bold text-zinc-100 hover:bg-zinc-700/30 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
          Save as Draft
        </button>
        <button
          onClick={() => handleSave(true)}
          disabled={saving || !selectedCustomer}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl bg-cba-gold text-base text-sm font-bold hover:bg-[#FFD633] transition-colors shadow-[0_0_15px_rgba(255,204,0,0.15)] disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" />}
          Save & Send
        </button>
      </div>
    </div>
  );
}

import { useState, useEffect, useCallback } from 'react';
import { invoicingApi } from '@/api';
import {
  Search,
  Plus,
  ChevronLeft,
  ChevronRight,
  Loader2,
  FileText,
  Send,
  Download,
  Eye,
} from 'lucide-react';
import { cn } from '@/lib/utils';

interface Invoice {
  id: string;
  invoiceNumber: string;
  customerId: string;
  customerName?: string;
  issueDate: string;
  dueDate: string;
  status: 'draft' | 'sent' | 'paid' | 'overdue' | 'void';
  subtotal: number;
  gstTotal: number;
  total: number;
}

interface InvoiceListProps {
  onSelectInvoice: (id: string) => void;
  onCreateInvoice: () => void;
}

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const formatDate = (iso: string) => {
  if (!iso) return '—';
  const d = new Date(iso);
  return d.toLocaleDateString('en-AU', { day: '2-digit', month: '2-digit', year: 'numeric' });
};

const statusConfig: Record<
  string,
  { bg: string; text: string; label: string; strikethrough?: boolean }
> = {
  draft: { bg: 'bg-zinc-600/20', text: 'text-secondary', label: 'Draft' },
  sent: { bg: 'bg-blue-500/20', text: 'text-blue-400', label: 'Sent' },
  paid: { bg: 'bg-emerald-500/20', text: 'text-emerald-400', label: 'Paid' },
  overdue: { bg: 'bg-red-500/20', text: 'text-red-400', label: 'Overdue' },
  void: { bg: 'bg-zinc-700/50', text: 'text-muted', label: 'Void', strikethrough: true },
};

const PAGE_SIZE = 20;

export function InvoiceList({ onSelectInvoice, onCreateInvoice }: InvoiceListProps) {
  const [invoices, setInvoices] = useState<Invoice[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [statusFilter, setStatusFilterState] = useState<string>('');
  const [customerFilter, setCustomerFilterState] = useState<string>('');
  const [dateFrom, setDateFromState] = useState('');
  const [dateTo, setDateToState] = useState('');
  const [page, setPage] = useState(0);

  // Reset page inline when filters change (avoids useEffect state reset anti-pattern)
  const setStatusFilter = (v: string) => { setStatusFilterState(v); setPage(0); };
  const setCustomerFilter = (v: string) => { setCustomerFilterState(v); setPage(0); };
  const setDateFrom = (v: string) => { setDateFromState(v); setPage(0); };
  const setDateTo = (v: string) => { setDateToState(v); setPage(0); };

  const loadInvoices = useCallback(async () => {
    setLoading(true);
    try {
      const res = await invoicingApi.listInvoices({
        offset: page * PAGE_SIZE,
        limit: PAGE_SIZE,
        status: statusFilter || undefined,
        customerId: customerFilter || undefined,
        dateFrom: dateFrom || undefined,
        dateTo: dateTo || undefined,
      });
      setInvoices(res?.invoices ?? []);
      setTotal(res?.total ?? 0);
    } catch (err) {
      console.error('Failed to load invoices:', err);
      setInvoices([]);
    } finally {
      setLoading(false);
    }
  }, [page, statusFilter, customerFilter, dateFrom, dateTo]);

  useEffect(() => {
    loadInvoices();
  }, [loadInvoices]);

  const handleSend = async (e: React.MouseEvent, invoiceId: string) => {
    e.stopPropagation();
    try {
      await invoicingApi.sendInvoice(invoiceId);
      loadInvoices();
    } catch (err) {
      console.error('Failed to send invoice:', err);
    }
  };

  const handleDownload = async (e: React.MouseEvent, invoiceId: string, invoiceNumber: string) => {
    e.stopPropagation();
    try {
      const blob = await invoicingApi.downloadInvoicePDF(invoiceId);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `${invoiceNumber}.pdf`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Failed to download PDF:', err);
    }
  };

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-col lg:flex-row gap-3 items-start lg:items-center justify-between">
        <div className="flex flex-wrap gap-3 items-center">
          <select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value)}
            className="px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
          >
            <option value="">All Statuses</option>
            <option value="draft">Draft</option>
            <option value="sent">Sent</option>
            <option value="paid">Paid</option>
            <option value="overdue">Overdue</option>
            <option value="void">Void</option>
          </select>

          <input
            type="date"
            value={dateFrom}
            onChange={(e) => setDateFrom(e.target.value)}
            placeholder="From"
            className="px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
          />
          <input
            type="date"
            value={dateTo}
            onChange={(e) => setDateTo(e.target.value)}
            placeholder="To"
            className="px-3 py-2 rounded-xl neu-inset bg-transparent text-sm text-primary focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
          />
        </div>

        <button
          onClick={onCreateInvoice}
          className="flex items-center gap-2 px-4 py-2 rounded-xl bg-cba-gold text-base text-sm font-bold hover:bg-[#FFD633] transition-colors shadow-[0_0_15px_rgba(255,204,0,0.15)]"
        >
          <Plus className="w-4 h-4" />
          New Invoice
        </button>
      </div>

      {/* Table */}
      {loading ? (
        <div className="flex items-center justify-center py-16">
          <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        </div>
      ) : invoices.length === 0 ? (
        <div className="neu-raised rounded-2xl p-8 text-center">
          <FileText className="w-12 h-12 mx-auto text-zinc-600 mb-3" />
          <p className="text-secondary text-sm">
            {statusFilter
              ? 'No invoices match your filter.'
              : 'No invoices yet. Create your first invoice.'}
          </p>
        </div>
      ) : (
        <div className="neu-raised rounded-2xl overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-zinc-800">
                  <th className="text-left px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Invoice #
                  </th>
                  <th className="text-left px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Customer
                  </th>
                  <th className="text-left px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold hidden md:table-cell">
                    Issue Date
                  </th>
                  <th className="text-left px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold hidden md:table-cell">
                    Due Date
                  </th>
                  <th className="text-right px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Total
                  </th>
                  <th className="text-center px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Status
                  </th>
                  <th className="text-right px-4 py-3 text-[10px] uppercase tracking-wider text-muted font-semibold">
                    Actions
                  </th>
                </tr>
              </thead>
              <tbody>
                {invoices.map((inv) => {
                  const sc = statusConfig[inv.status] ?? statusConfig.draft;
                  return (
                    <tr
                      key={inv.id}
                      onClick={() => onSelectInvoice(inv.id)}
                      className="border-b border-zinc-800/50 hover:bg-zinc-800/30 cursor-pointer transition-colors"
                    >
                      <td className="px-4 py-3">
                        <span
                          className={cn(
                            'font-semibold text-cba-gold',
                            sc.strikethrough && 'line-through',
                          )}
                        >
                          {inv.invoiceNumber}
                        </span>
                      </td>
                      <td
                        className={cn(
                          'px-4 py-3 text-primary',
                          sc.strikethrough && 'line-through',
                        )}
                      >
                        {inv.customerName ?? '—'}
                      </td>
                      <td
                        className={cn(
                          'px-4 py-3 text-secondary hidden md:table-cell',
                          sc.strikethrough && 'line-through',
                        )}
                      >
                        {formatDate(inv.issueDate)}
                      </td>
                      <td
                        className={cn(
                          'px-4 py-3 text-secondary hidden md:table-cell',
                          sc.strikethrough && 'line-through',
                        )}
                      >
                        {formatDate(inv.dueDate)}
                      </td>
                      <td className="px-4 py-3 text-right">
                        <span
                          className={cn(
                            'font-semibold',
                            sc.strikethrough ? 'line-through text-muted' : 'text-zinc-100',
                          )}
                        >
                          {formatAUD(inv.total)}
                        </span>
                      </td>
                      <td className="px-4 py-3 text-center">
                        <span
                          className={cn(
                            'inline-flex items-center px-2 py-0.5 rounded-full text-[10px] font-bold uppercase tracking-wider',
                            sc.bg,
                            sc.text,
                          )}
                        >
                          {sc.label}
                        </span>
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-end gap-1">
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              onSelectInvoice(inv.id);
                            }}
                            title="View"
                            className="p-1.5 rounded-lg hover:bg-zinc-700/50 text-secondary hover:text-zinc-100 transition-colors"
                          >
                            <Eye className="w-4 h-4" />
                          </button>
                          <button
                            onClick={(e) => handleDownload(e, inv.id, inv.invoiceNumber)}
                            title="Download PDF"
                            className="p-1.5 rounded-lg hover:bg-zinc-700/50 text-secondary hover:text-zinc-100 transition-colors"
                          >
                            <Download className="w-4 h-4" />
                          </button>
                          {inv.status === 'draft' && (
                            <button
                              onClick={(e) => handleSend(e, inv.id)}
                              title="Send Invoice"
                              className="p-1.5 rounded-lg hover:bg-blue-500/20 text-secondary hover:text-blue-400 transition-colors"
                            >
                              <Send className="w-4 h-4" />
                            </button>
                          )}
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-xs text-muted">
            Showing {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, total)} of {total}
          </p>
          <div className="flex items-center gap-2">
            <button
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              className="p-1.5 rounded-lg neu-raised text-secondary hover:text-zinc-100 disabled:opacity-30 disabled:cursor-not-allowed"
            >
              <ChevronLeft className="w-4 h-4" />
            </button>
            <span className="text-xs text-secondary tabular-nums">
              {page + 1} / {totalPages}
            </span>
            <button
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
              className="p-1.5 rounded-lg neu-raised text-secondary hover:text-zinc-100 disabled:opacity-30 disabled:cursor-not-allowed"
            >
              <ChevronRight className="w-4 h-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { invoicingApi } from '@/api';
import {
  FileText,
  Users,
  PlusCircle,
  DollarSign,
  AlertTriangle,
  TrendingUp,
  Loader2,
  ArrowLeft,
  Eye,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { CustomerList } from './CustomerList';
import { CustomerDetail } from './CustomerDetail';
import { CustomerForm } from './CustomerForm';
import { InvoiceList } from './InvoiceList';
import { InvoiceEditor } from './InvoiceEditor';
import { InvoicePreview } from './InvoicePreview';
import { InvoicePDF } from './InvoicePDF';

type SubTab = 'customers' | 'invoices' | 'create';

const tabs: { id: SubTab; label: string; icon: typeof FileText }[] = [
  { id: 'customers', label: 'Customers', icon: Users },
  { id: 'invoices', label: 'Invoices', icon: FileText },
  { id: 'create', label: 'Create Invoice', icon: PlusCircle },
];

interface SummaryStats {
  totalOutstanding: number;
  overdueCount: number;
  revenueThisMonth: number;
  totalCustomers: number;
}

const formatAUD = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

export function InvoicingDashboard() {
  const [activeTab, setActiveTab] = useState<SubTab>('customers');
  const [stats, setStats] = useState<SummaryStats | null>(null);
  const [statsLoading, setStatsLoading] = useState(true);
  const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
  const [showCustomerForm, setShowCustomerForm] = useState(false);
  const [editingCustomer, setEditingCustomer] = useState<Record<string, unknown> | null>(null);

  // Invoice state
  const [selectedInvoiceId, setSelectedInvoiceId] = useState<string | null>(null);
  const [editingInvoiceId, setEditingInvoiceId] = useState<string | null>(null);
  const [viewingInvoice, setViewingInvoice] = useState<any>(null);
  const [invoiceViewLoading, setInvoiceViewLoading] = useState(false);

  useEffect(() => {
    loadStats();
  }, []);

  const loadStats = async () => {
    setStatsLoading(true);
    try {
      const customersRes = await invoicingApi
        .listCustomers({ limit: 1000 })
        .catch(() => ({ customers: [], total: 0 }));
      const customers = customersRes?.customers ?? [];
      const totalOutstanding = customers.reduce(
        (sum: number, c: Record<string, unknown>) => sum + ((c.outstandingBalance as number) ?? 0),
        0,
      );
      const overdueCount = customers.filter((c: Record<string, unknown>) => ((c.overdueAmount as number) ?? 0) > 0).length;

      setStats({
        totalOutstanding,
        overdueCount,
        revenueThisMonth: 0,
        totalCustomers: customersRes?.total ?? customers.length,
      });
    } catch (err) {
      console.error('Failed to load invoicing stats:', err);
      setStats({ totalOutstanding: 0, overdueCount: 0, revenueThisMonth: 0, totalCustomers: 0 });
    } finally {
      setStatsLoading(false);
    }
  };

  const handleSelectCustomer = (id: string) => {
    setSelectedCustomerId(id);
  };

  const handleBackToList = () => {
    setSelectedCustomerId(null);
    setEditingCustomer(null);
  };

  const handleEditCustomer = (customer: Record<string, unknown>) => {
    setEditingCustomer(customer);
    setShowCustomerForm(true);
  };

  const handleCustomerSaved = () => {
    setShowCustomerForm(false);
    setEditingCustomer(null);
    setSelectedCustomerId(null);
  };

  const handleSelectInvoice = async (id: string) => {
    setSelectedInvoiceId(id);
    setInvoiceViewLoading(true);
    try {
      const inv = await invoicingApi.getInvoice(id);
      setViewingInvoice(inv);
    } catch (err) {
      console.error('Failed to load invoice:', err);
    } finally {
      setInvoiceViewLoading(false);
    }
  };

  const handleBackToInvoices = () => {
    setSelectedInvoiceId(null);
    setEditingInvoiceId(null);
    setViewingInvoice(null);
  };

  const handleInvoiceSaved = () => {
    setEditingInvoiceId(null);
    setActiveTab('invoices');
    loadStats();
  };

  const renderCustomerContent = () => {
    if (showCustomerForm) {
      return (
        <CustomerForm
          customer={editingCustomer}
          onSave={handleCustomerSaved}
          onCancel={() => {
            setShowCustomerForm(false);
            setEditingCustomer(null);
          }}
        />
      );
    }
    if (selectedCustomerId) {
      return (
        <CustomerDetail
          customerId={selectedCustomerId}
          onBack={handleBackToList}
          onEdit={handleEditCustomer}
        />
      );
    }
    return (
      <CustomerList
        onSelectCustomer={handleSelectCustomer}
        onAddCustomer={() => {
          setEditingCustomer(null);
          setShowCustomerForm(true);
        }}
      />
    );
  };

  const renderInvoiceContent = () => {
    // Viewing a specific invoice
    if (selectedInvoiceId && viewingInvoice && !editingInvoiceId) {
      if (invoiceViewLoading) {
        return (
          <div className="flex items-center justify-center py-16">
            <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
          </div>
        );
      }
      return (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <button
              onClick={handleBackToInvoices}
              className="flex items-center gap-2 text-sm text-secondary hover:text-zinc-100 transition-colors"
            >
              <ArrowLeft className="w-4 h-4" />
              Back to Invoices
            </button>
            <div className="flex items-center gap-2">
              <button
                onClick={() => setEditingInvoiceId(selectedInvoiceId)}
                className="flex items-center gap-2 px-3 py-1.5 rounded-lg neu-raised text-xs font-semibold text-primary hover:text-zinc-100 transition-colors"
              >
                Edit
              </button>
            </div>
          </div>
          <InvoicePDF
            invoiceId={viewingInvoice.id}
            invoiceNumber={viewingInvoice.invoiceNumber}
            status={viewingInvoice.status}
            onSent={() => handleSelectInvoice(selectedInvoiceId)}
          />
          <InvoicePreview
            invoice={{
              ...viewingInvoice,
              lineItems: (viewingInvoice.lineItems as Array<Record<string, unknown>> ?? []).map((li) => ({
                description: li.description ?? '',
                quantity: li.quantity ?? 1,
                unitPrice: li.unitPrice ?? 0,
                gstRate: li.gstRate ?? 0.1,
                amount: li.amount ?? 0,
                gstAmount: li.gstAmount ?? 0,
              })),
            }}
          />
        </div>
      );
    }

    // Editing an existing invoice
    if (editingInvoiceId) {
      return (
        <InvoiceEditor
          invoiceId={editingInvoiceId}
          onSave={handleInvoiceSaved}
          onCancel={handleBackToInvoices}
        />
      );
    }

    // Default: invoice list
    return (
      <InvoiceList
        onSelectInvoice={handleSelectInvoice}
        onCreateInvoice={() => setActiveTab('create')}
      />
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold tracking-tight text-gradient-gold">
          Invoicing & Customers
        </h2>
        <p className="text-sm text-muted">
          Manage customers, create invoices, and track payments
        </p>
      </div>

      {/* Summary Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <div className="neu-raised rounded-2xl p-4 flex items-center gap-3">
          <div className="neu-inset p-2.5 rounded-xl text-cba-gold">
            <DollarSign className="w-5 h-5" />
          </div>
          <div>
            <p className="text-[10px] text-zinc-600 uppercase font-semibold tracking-wider">
              Outstanding
            </p>
            {statsLoading ? (
              <Loader2 className="w-4 h-4 animate-spin text-muted mt-1" />
            ) : (
              <p className="text-lg font-bold text-gradient-gold">
                {formatAUD(stats?.totalOutstanding ?? 0)}
              </p>
            )}
          </div>
        </div>

        <div className="neu-raised rounded-2xl p-4 flex items-center gap-3">
          <div
            className={cn(
              'neu-inset p-2.5 rounded-xl',
              stats && stats.overdueCount > 0 ? 'text-red-400' : 'text-muted',
            )}
          >
            <AlertTriangle className="w-5 h-5" />
          </div>
          <div>
            <p className="text-[10px] text-zinc-600 uppercase font-semibold tracking-wider">
              Overdue
            </p>
            {statsLoading ? (
              <Loader2 className="w-4 h-4 animate-spin text-muted mt-1" />
            ) : (
              <p
                className={cn(
                  'text-lg font-bold',
                  stats && stats.overdueCount > 0 ? 'text-red-400' : 'text-primary',
                )}
              >
                {stats?.overdueCount ?? 0}
              </p>
            )}
          </div>
        </div>

        <div className="neu-raised rounded-2xl p-4 flex items-center gap-3">
          <div className="neu-inset p-2.5 rounded-xl text-emerald-400">
            <TrendingUp className="w-5 h-5" />
          </div>
          <div>
            <p className="text-[10px] text-zinc-600 uppercase font-semibold tracking-wider">
              Revenue (Month)
            </p>
            {statsLoading ? (
              <Loader2 className="w-4 h-4 animate-spin text-muted mt-1" />
            ) : (
              <p className="text-lg font-bold text-emerald-400">
                {formatAUD(stats?.revenueThisMonth ?? 0)}
              </p>
            )}
          </div>
        </div>

        <div className="neu-raised rounded-2xl p-4 flex items-center gap-3">
          <div className="neu-inset p-2.5 rounded-xl text-secondary">
            <Users className="w-5 h-5" />
          </div>
          <div>
            <p className="text-[10px] text-zinc-600 uppercase font-semibold tracking-wider">
              Customers
            </p>
            {statsLoading ? (
              <Loader2 className="w-4 h-4 animate-spin text-muted mt-1" />
            ) : (
              <p className="text-lg font-bold text-zinc-100">{stats?.totalCustomers ?? 0}</p>
            )}
          </div>
        </div>
      </div>

      {/* Tab Navigation */}
      <div className="flex flex-wrap gap-1">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => {
              setActiveTab(tab.id);
              setSelectedCustomerId(null);
              setShowCustomerForm(false);
              setEditingCustomer(null);
              setSelectedInvoiceId(null);
              setEditingInvoiceId(null);
              setViewingInvoice(null);
            }}
            className={cn(
              'flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-bold transition-all duration-300',
              activeTab === tab.id
                ? 'bg-cba-gold text-base shadow-[0_0_20px_rgba(255,204,0,0.2)]'
                : 'neu-raised text-secondary hover:text-zinc-100',
            )}
          >
            <tab.icon className="w-4 h-4" />
            <span className="hidden sm:inline">{tab.label}</span>
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="animate-in fade-in duration-300">
        {activeTab === 'customers' && renderCustomerContent()}
        {activeTab === 'invoices' && renderInvoiceContent()}
        {activeTab === 'create' && (
          <InvoiceEditor onSave={handleInvoiceSaved} onCancel={() => setActiveTab('invoices')} />
        )}
      </div>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import {
  Database,
  Plus,
  Shield,
  Power,
  PowerOff,
  Trash2,
  Loader2,
  CheckCircle,
  X,
} from 'lucide-react';
import { knowledgeApi } from '../../../api';

interface DataPointManagerProps {
  userId: string;
}

interface DataPoint {
  id: string;
  name: string;
  description: string;
  datapointType: string;
  datasetName: string;
  isActive: boolean;
  isPredefined: boolean;
  extractionCount: number;
  accuracy: number;
  schemaFields: Record<string, unknown>;
  extractionPrompt: string;
  createdAt: string;
}

const TYPE_OPTIONS = ['entity', 'relationship', 'attribute', 'metric', 'custom'];

export function DataPointManager({ userId }: DataPointManagerProps) {
  const [dataPoints, setDataPoints] = useState<DataPoint[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [toggling, setToggling] = useState<string | null>(null);

  // Create form
  const [form, setForm] = useState({
    name: '',
    description: '',
    datapointType: 'entity',
    datasetName: '',
    extractionPrompt: '',
    schemaFields: '',
  });
  const [creating, setCreating] = useState(false);

  const loadDataPoints = () => {
    setLoading(true);
    setError(null);
    knowledgeApi
      .listDataPoints(userId)
      .then(setDataPoints)
      .catch((e: Error) => setError(e.message))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadDataPoints();
  }, [userId]);

  const handleCreate = async () => {
    if (!form.name.trim()) return;
    setCreating(true);
    try {
      let parsedSchema: Record<string, unknown> = {};
      if (form.schemaFields.trim()) {
        try {
          parsedSchema = JSON.parse(form.schemaFields) as Record<string, unknown>;
        } catch {
          parsedSchema = { raw: form.schemaFields };
        }
      }
      await knowledgeApi.createDataPoint({
        userId,
        name: form.name,
        description: form.description,
        datapointType: form.datapointType,
        datasetName: form.datasetName || undefined,
        extractionPrompt: form.extractionPrompt || undefined,
        schemaFields: parsedSchema,
      });
      setShowCreate(false);
      setForm({
        name: '',
        description: '',
        datapointType: 'entity',
        datasetName: '',
        extractionPrompt: '',
        schemaFields: '',
      });
      loadDataPoints();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to create datapoint');
    } finally {
      setCreating(false);
    }
  };

  const handleToggle = async (dp: DataPoint) => {
    setToggling(dp.id);
    try {
      if (dp.isActive) {
        await knowledgeApi.deactivateDataPoint(dp.id);
      } else {
        await knowledgeApi.activateDataPoint(dp.id);
      }
      loadDataPoints();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to toggle datapoint');
    } finally {
      setToggling(null);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
