}

import React, { useEffect, useState } from 'react';
import {
  MessageSquare,
  TrendingUp,
  TrendingDown,
  Minus,
  Zap,
  Loader2,
  RefreshCw,
} from 'lucide-react';
import { knowledgeApi } from '../../../api';

interface FeedbackPanelProps {
  userId: string;
}

interface FeedbackStats {
  totalCount: number;
  accuracyRate: number;
  trend: 'up' | 'down' | 'stable';
  byType: Record<string, number>;
  recent: Array<{
    id: string;
    entityId: string;
    entityType: string;
    feedbackType: string;
    details: string;
    createdAt: string;
  }>;
}

const FEEDBACK_TYPE_COLORS: Record<string, { bg: string; text: string }> = {
  positive: { bg: 'bg-emerald-500/10', text: 'text-emerald-400' },
  negative: { bg: 'bg-red-500/10', text: 'text-red-400' },
  correction: { bg: 'bg-amber-500/10', text: 'text-amber-400' },
  suggestion: { bg: 'bg-blue-500/10', text: 'text-blue-400' },
};

export function FeedbackPanel({ userId }: FeedbackPanelProps) {
  const [stats, setStats] = useState<FeedbackStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [memifying, setMemifying] = useState(false);
  const [memifyResult, setMemifyResult] = useState<string | null>(null);

  const loadStats = () => {
    setLoading(true);
    setError(null);
    knowledgeApi
      .feedbackStats(userId)
      .then(setStats)
      .catch((e: unknown) => setError(e instanceof Error ? e.message : 'Unknown error'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadStats();
  }, [userId]);

  const handleMemify = async () => {
    setMemifying(true);
    setMemifyResult(null);
    try {
      const result = await knowledgeApi.triggerMemify(userId, {
        minFeedbackCount: 3,
        forceRun: false,
      });
      setMemifyResult(result.message || 'Memify triggered successfully');
      loadStats();
    } catch (e: unknown) {
      setMemifyResult(`Error: ${e instanceof Error ? e.message : 'Unknown error'}`);
    } finally {
      setMemifying(false);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="neu-inset rounded-xl p-6 text-center">
        <p className="text-sm text-red-400">Failed to load feedback: {error}</p>
        <button
          type="button"
          onClick={loadStats}
          className="mt-3 text-xs text-cba-gold hover:underline"
        >
          Retry
        </button>
      </div>
    );
  }

  const TrendIcon =
    stats?.trend === 'up' ? TrendingUp : stats?.trend === 'down' ? TrendingDown : Minus;
  const trendColor =
    stats?.trend === 'up'
      ? 'text-emerald-400'
      : stats?.trend === 'down'
        ? 'text-red-400'
        : 'text-secondary';

  return (
    <div className="space-y-6">
      {/* Summary Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
        <div className="neu-raised rounded-xl p-4 text-center">
          <MessageSquare className="w-5 h-5 mx-auto mb-2 text-cba-gold" />
          <p className="text-2xl font-bold text-zinc-100">{stats?.totalCount ?? 0}</p>
          <p className="text-[10px] font-bold uppercase tracking-wider text-muted">
            Total Feedback
          </p>
        </div>
        <div className="neu-raised rounded-xl p-4 text-center">
          <div className="w-5 h-5 mx-auto mb-2 text-emerald-400 font-bold text-lg">%</div>
          <p className="text-2xl font-bold text-zinc-100">
            {((stats?.accuracyRate ?? 0) * 100).toFixed(1)}%
          </p>
          <p className="text-[10px] font-bold uppercase tracking-wider text-muted">
            Accuracy Rate
          </p>
        </div>
        <div className="neu-raised rounded-xl p-4 text-center">
          <TrendIcon className={`w-5 h-5 mx-auto mb-2 ${trendColor}`} />
          <p className={`text-2xl font-bold ${trendColor}`}>{stats?.trend ?? 'N/A'}</p>
          <p className="text-[10px] font-bold uppercase tracking-wider text-muted">Trend</p>
        </div>
      </div>

      {/* Memify Action */}
      <div className="neu-raised rounded-xl p-4">
        <div className="flex items-center justify-between">
          <div>
            <h4 className="text-sm font-bold text-primary flex items-center gap-2">
              <Zap className="w-4 h-4 text-cba-gold" /> Trigger Memify
            </h4>
            <p className="text-xs text-muted mt-1">
              Consolidate feedback into knowledge graph improvements
            </p>
          </div>
          <button
            type="button"
            onClick={handleMemify}
            disabled={memifying}
            className="flex items-center gap-2 px-4 py-2 rounded-xl text-sm font-bold bg-cba-gold text-base hover:bg-cba-gold/90 disabled:opacity-50 transition-colors"
          >
            {memifying ? <Loader2 className="w-4 h-4 animate-spin" /> : <Zap className="w-4 h-4" />}
            {memifying ? 'Processing...' : 'Run Memify'}
          </button>
        </div>
        {memifyResult && (
          <p
            className={`mt-3 text-xs ${memifyResult.startsWith('Error') ? 'text-red-400' : 'text-emerald-400'}`}
          >
            {memifyResult}
          </p>
        )}
      </div>

      {/* Feedback by Type */}
      {stats?.byType && Object.keys(stats.byType).length > 0 && (
        <div className="neu-raised rounded-xl p-4">
          <h4 className="text-sm font-bold text-primary mb-3">By Type</h4>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            {Object.entries(stats.byType).map(([type, count]) => {
              const colors = FEEDBACK_TYPE_COLORS[type] ?? {
                bg: 'bg-overlay',
                text: 'text-secondary',
              };
              return (
                <div key={type} className={`${colors.bg} rounded-lg p-3 text-center`}>
                  <p className={`text-lg font-bold ${colors.text}`}>{count}</p>
                  <p className="text-[10px] font-bold uppercase tracking-wider text-muted">
                    {type}
                  </p>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {/* Recent Feedback */}
      <div className="neu-raised rounded-xl p-4">
        <div className="flex items-center justify-between mb-3">
          <h4 className="text-sm font-bold text-primary">Recent Feedback</h4>
          <button
            type="button"
            onClick={loadStats}
            className="text-secondary hover:text-cba-gold transition-colors"
            aria-label="Refresh"
          >
            <RefreshCw className="w-4 h-4" />
          </button>
        </div>
        <div className="space-y-2 max-h-80 overflow-y-auto">
          {(stats?.recent ?? []).length === 0 ? (
            <p className="text-xs text-muted text-center py-4">No feedback yet</p>
          ) : (
            stats!.recent.map((item) => {
              const colors = FEEDBACK_TYPE_COLORS[item.feedbackType] ?? {
                bg: 'bg-overlay',
                text: 'text-secondary',
              };
              return (
                <div
                  key={item.id}
                  className="flex items-start gap-3 py-2 border-b border-border/50 last:border-0"
                >
                  <span
                    className={`shrink-0 mt-0.5 inline-block px-2 py-0.5 rounded-full text-[10px] font-bold ${colors.bg} ${colors.text}`}
                  >
                    {item.feedbackType}
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-xs text-primary truncate">
                      {item.details || `Feedback on ${item.entityType}`}
                    </p>
                    <p className="text-[10px] text-zinc-600 mt-0.5">
                      {new Date(item.createdAt).toLocaleDateString()}
                    </p>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>
    </div>
  );
}

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Search, Filter, Loader2, ZoomIn, ZoomOut, Maximize2 } from 'lucide-react';
import { knowledgeApi } from '../../../api';
import { NodeDetailPanel } from './NodeDetailPanel';

interface KnowledgeGraphExplorerProps {
  datasetName: string;
  ontologyId?: string;
}

interface GraphNode {
  id: string;
  label: string;
  type: string;
  x: number;
  y: number;
  vx: number;
  vy: number;
  neighbors?: Array<{ id: string; label: string; edgeType: string }>;
  properties?: Record<string, unknown>;
}

interface GraphEdge {
  source: string;
  target: string;
  type: string;
}

const TYPE_COLORS: Record<string, string> = {
  entity: '#FFCC00',
  relationship: '#60a5fa',
  document: '#34d399',
  chunk: '#a78bfa',
  concept: '#f472b6',
  default: '#94a3b8',
};

export function KnowledgeGraphExplorer({ datasetName, ontologyId }: KnowledgeGraphExplorerProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const animRef = useRef<number>(0);
  const nodesRef = useRef<GraphNode[]>([]);
  const edgesRef = useRef<GraphEdge[]>([]);

  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [selectedNode, setSelectedNode] = useState<GraphNode | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [typeFilters, setTypeFilters] = useState<Set<string>>(new Set());
  const [allTypes, setAllTypes] = useState<string[]>([]);
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [dragging, setDragging] = useState(false);
  const [dragStart, setDragStart] = useState({ x: 0, y: 0 });

  const loadGraph = useCallback(async () => {
    if (!datasetName) return;
    setLoading(true);
    setError(null);
    try {
      const data = await knowledgeApi.getGraph(datasetName, { maxNodes: 200, ontologyId });
      const nodes: GraphNode[] = (data.nodes ?? []).map((n: { id: string; label?: string; type?: string; neighbors?: Array<{ id: string; label: string; edgeType: string }>; properties?: Record<string, unknown> }) => ({
        id: n.id,
        label: n.label || n.id,
        type: n.type || 'default',
        x: Math.random() * 800 - 400,
        y: Math.random() * 600 - 300,
        vx: 0,
        vy: 0,
        neighbors: n.neighbors,
        properties: n.properties,
      }));
      const edges: GraphEdge[] = (data.edges ?? []).map((e: { source: string; target: string; type?: string }) => ({
        source: e.source,
        target: e.target,
        type: e.type || 'related',
      }));
      nodesRef.current = nodes;
      edgesRef.current = edges;

      const types = [...new Set(nodes.map((n) => n.type))];
      setAllTypes(types);
      setTypeFilters(new Set(types));
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to load graph');
    } finally {
      setLoading(false);
    }
  }, [datasetName, ontologyId]);

  useEffect(() => {
    loadGraph();
  }, [loadGraph]);

  // Force-directed layout simulation
  useEffect(() => {
    if (loading || error) return;

    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let running = true;
    let iteration = 0;
    const maxIterations = 300;

    const simulate = () => {
      if (!running) return;
      const nodes = nodesRef.current;
      const edges = edgesRef.current;
      const nodeMap = new Map(nodes.map((n) => [n.id, n]));

      // Cooling factor
      const temp = Math.max(0.1, 1 - iteration / maxIterations);
      const repulsionStrength = 5000 * temp;
      const attractionStrength = 0.01;
      const damping = 0.85;

      // Repulsion (node-node)
      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          const a = nodes[i];
          const b = nodes[j];
          const dx = a.x - b.x;
          const dy = a.y - b.y;
          const dist = Math.sqrt(dx * dx + dy * dy) || 1;
          const force = repulsionStrength / (dist * dist);
          const fx = (dx / dist) * force;
          const fy = (dy / dist) * force;
          a.vx += fx;
          a.vy += fy;
          b.vx -= fx;
          b.vy -= fy;
        }
      }

      // Attraction (edges)
      for (const edge of edges) {
        const src = nodeMap.get(edge.source);
        const tgt = nodeMap.get(edge.target);
        if (!src || !tgt) continue;
        const dx = tgt.x - src.x;
        const dy = tgt.y - src.y;
        const dist = Math.sqrt(dx * dx + dy * dy) || 1;
        const force = dist * attractionStrength;
        const fx = (dx / dist) * force;
        const fy = (dy / dist) * force;
        src.vx += fx;
        src.vy += fy;
        tgt.vx -= fx;
        tgt.vy -= fy;
      }

      // Center gravity
      for (const node of nodes) {
        node.vx -= node.x * 0.001;
        node.vy -= node.y * 0.001;
      }

      // Update positions
      for (const node of nodes) {
        node.vx *= damping;
        node.vy *= damping;
        node.x += node.vx;
        node.y += node.vy;
      }

      // Draw
      draw(ctx, canvas);
      iteration++;

      if (iteration < maxIterations) {
        animRef.current = requestAnimationFrame(simulate);
      } else {
        // Keep drawing for interactions
        const drawLoop = () => {
          if (!running) return;
          draw(ctx, canvas);
          animRef.current = requestAnimationFrame(drawLoop);
        };
        drawLoop();
      }
    };

    const resizeCanvas = () => {
      const container = containerRef.current;
      if (!container || !canvas) return;
      canvas.width = container.clientWidth;
      canvas.height = container.clientHeight;
    };

    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);
    simulate();

    return () => {
      running = false;
      cancelAnimationFrame(animRef.current);
      window.removeEventListener('resize', resizeCanvas);
    };
  }, [loading, error, typeFilters, searchQuery, selectedNode, zoom, pan]);

  const draw = (ctx: CanvasRenderingContext2D, canvas: HTMLCanvasElement) => {
    const nodes = nodesRef.current;
    const edges = edgesRef.current;
    const nodeMap = new Map(nodes.map((n) => [n.id, n]));
    const cx = canvas.width / 2 + pan.x;
    const cy = canvas.height / 2 + pan.y;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(zoom, zoom);

    const filteredIds = new Set(
      nodes
        .filter((n) => typeFilters.has(n.type))
        .filter((n) => !searchQuery || n.label.toLowerCase().includes(searchQuery.toLowerCase()))
        .map((n) => n.id),
    );

    // Draw edges
    ctx.lineWidth = 0.5;
    for (const edge of edges) {
      const src = nodeMap.get(edge.source);
      const tgt = nodeMap.get(edge.target);
      if (!src || !tgt) continue;
      if (!filteredIds.has(src.id) || !filteredIds.has(tgt.id)) continue;

      ctx.strokeStyle = 'rgba(255,255,255,0.08)';
      if (selectedNode && (edge.source === selectedNode.id || edge.target === selectedNode.id)) {
        ctx.strokeStyle = 'rgba(255,204,0,0.4)';
        ctx.lineWidth = 1.5;
      }
      ctx.beginPath();
      ctx.moveTo(src.x, src.y);
      ctx.lineTo(tgt.x, tgt.y);
      ctx.stroke();
      ctx.lineWidth = 0.5;
    }

    // Draw nodes
    for (const node of nodes) {
      if (!filteredIds.has(node.id)) continue;
      const color = TYPE_COLORS[node.type] ?? TYPE_COLORS.default;
      const radius = selectedNode?.id === node.id ? 10 : 6;

      // Glow for selected
      if (selectedNode?.id === node.id) {
        ctx.shadowColor = color;
        ctx.shadowBlur = 15;
      }

      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.arc(node.x, node.y, radius, 0, Math.PI * 2);
      ctx.fill();

      ctx.shadowColor = 'transparent';
      ctx.shadowBlur = 0;

      // Label
      if (zoom > 0.6 || selectedNode?.id === node.id) {
        ctx.font = `${Math.max(9, 11 / zoom)}px sans-serif`;
        ctx.fillStyle = selectedNode?.id === node.id ? '#FFCC00' : 'rgba(255,255,255,0.6)';
        ctx.textAlign = 'center';
        ctx.fillText(node.label.slice(0, 20), node.x, node.y + radius + 12);
      }
    }

    ctx.restore();
  };

  const handleCanvasClick = (e: React.MouseEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const rect = canvas.getBoundingClientRect();
    const mx = (e.clientX - rect.left - canvas.width / 2 - pan.x) / zoom;
    const my = (e.clientY - rect.top - canvas.height / 2 - pan.y) / zoom;

    const clickedNode = nodesRef.current.find((n) => {
      const dx = n.x - mx;
      const dy = n.y - my;
      return Math.sqrt(dx * dx + dy * dy) < 12;
    });

    setSelectedNode(clickedNode ?? null);
  };

  const handleMouseDown = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (e.button === 0 && !e.shiftKey) return; // left click is for node selection
    setDragging(true);
    setDragStart({ x: e.clientX - pan.x, y: e.clientY - pan.y });
  };

  const handleMouseMove = (e: React.MouseEvent<HTMLCanvasElement>) => {
    if (!dragging) return;
    setPan({ x: e.clientX - dragStart.x, y: e.clientY - dragStart.y });
  };

  const handleMouseUp = () => {
    setDragging(false);
  };

  const handleWheel = (e: React.WheelEvent) => {
    e.preventDefault();
    setZoom((z) => Math.max(0.2, Math.min(3, z - e.deltaY * 0.001)));
  };

  const handleNodeNavigate = (nodeId: string) => {
    const node = nodesRef.current.find((n) => n.id === nodeId);
    if (node) {
      setSelectedNode(node);
      setPan({ x: -node.x * zoom, y: -node.y * zoom });
    }
  };

  const handleFeedback = async (nodeId: string, feedbackType: string) => {
    try {
      await knowledgeApi.submitFeedback({
        entityId: nodeId,
        entityType: 'node',
        feedbackType,
        userId: 'current-user',
      });
    } catch {
      // silently fail for non-critical feedback
    }
  };

  const toggleTypeFilter = (type: string) => {
    setTypeFilters((prev) => {
      const next = new Set(prev);
      if (next.has(type)) next.delete(type);
      else next.add(type);
      return next;
    });
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  if (error) {
    return (
      <div className="neu-inset rounded-xl p-6 text-center">
        <p className="text-sm text-red-400">Failed to load graph: {error}</p>
        <button
          type="button"
          onClick={loadGraph}
          className="mt-3 text-xs text-cba-gold hover:underline"
        >
          Retry
        </button>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {/* Controls */}
      <div className="flex flex-wrap items-center gap-3">
        {/* Search */}
        <div className="relative flex-1 min-w-[200px]">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted" />
          <input
            type="text"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            placeholder="Search nodes..."
            className="w-full pl-9 pr-3 py-2 neu-inset rounded-xl text-sm text-primary bg-transparent placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
          />
        </div>

        {/* Type Filters */}
        <div className="flex items-center gap-1.5 flex-wrap">
          <Filter className="w-4 h-4 text-muted" />
          {allTypes.map((type) => (
            <button
              key={type}
              type="button"
              onClick={() => toggleTypeFilter(type)}
              className={`px-2 py-1 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-colors ${
                typeFilters.has(type) ? 'text-zinc-100 ring-1' : 'text-zinc-600 hover:text-secondary'
              }`}
              style={{
                backgroundColor: typeFilters.has(type)
                  ? `${TYPE_COLORS[type] ?? TYPE_COLORS.default}20`
                  : undefined,
                borderColor: typeFilters.has(type)
                  ? `${TYPE_COLORS[type] ?? TYPE_COLORS.default}40`
                  : undefined,
                color: typeFilters.has(type)
                  ? (TYPE_COLORS[type] ?? TYPE_COLORS.default)
                  : undefined,
              }}
            >
              {type}
            </button>
          ))}
        </div>

        {/* Zoom Controls */}
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => setZoom((z) => Math.min(3, z + 0.2))}
            className="neu-raised-sm p-1.5 rounded-lg text-secondary hover:text-primary"
          >
            <ZoomIn className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => setZoom((z) => Math.max(0.2, z - 0.2))}
            className="neu-raised-sm p-1.5 rounded-lg text-secondary hover:text-primary"
          >
            <ZoomOut className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => {
              setZoom(1);
              setPan({ x: 0, y: 0 });
            }}
            className="neu-raised-sm p-1.5 rounded-lg text-secondary hover:text-primary"
          >
            <Maximize2 className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Graph + Detail */}
      <div className="flex gap-4">
        <div
          ref={containerRef}
          className="flex-1 neu-inset rounded-xl overflow-hidden"
          style={{ height: 500 }}
        >
          <canvas
            ref={canvasRef}
            onClick={handleCanvasClick}
            onContextMenu={(e) => {
              e.preventDefault();
              handleMouseDown(e);
            }}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onMouseLeave={handleMouseUp}
            onWheel={handleWheel}
            className="w-full h-full cursor-crosshair"
          />
        </div>
        {selectedNode && (
          <div className="w-72 shrink-0 hidden lg:block">
            <NodeDetailPanel
              node={selectedNode}
              onNavigate={handleNodeNavigate}
              onFeedback={handleFeedback}
              onClose={() => setSelectedNode(null)}
            />
          </div>
        )}
      </div>

      {/* Node count info */}
      <p className="text-[10px] text-zinc-600 text-right">
        {nodesRef.current.length} nodes, {edgesRef.current.length} edges | Zoom:{' '}
        {(zoom * 100).toFixed(0)}%
      </p>
    </div>
  );
}

import React, { useEffect, useState } from 'react';
import { GitBranch, Plus, Loader2, CheckCircle, ArrowRight } from 'lucide-react';
import { knowledgeApi } from '../../../api';

interface OntologyManagerProps {
  userId: string;
}

interface Ontology {
  id: string;
  name: string;
  ontologyType: string;
  description: string;
  nodeCount: number;
  edgeCount: number;
  appliedDatasets: string[];
  version: number;
  createdAt: string;
}

const TYPE_BADGE_COLORS: Record<string, string> = {
  financial: 'bg-cba-gold/10 text-cba-gold',
  generic: 'bg-blue-500/10 text-blue-400',
  custom: 'bg-purple-500/10 text-purple-400',
  domain: 'bg-emerald-500/10 text-emerald-400',
};

export function OntologyManager({ userId }: OntologyManagerProps) {
  const [ontologies, setOntologies] = useState<Ontology[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showCreate, setShowCreate] = useState(false);
  const [applying, setApplying] = useState<string | null>(null);
  const [applyDataset, setApplyDataset] = useState('');

  // Create form state
  const [form, setForm] = useState({
    name: '',
    ontologyType: 'custom',
    description: '',
    nodeTypes: '',
    edgeTypes: '',
  });
  const [creating, setCreating] = useState(false);

  const loadOntologies = () => {
    setLoading(true);
    setError(null);
    knowledgeApi
      .listOntologies(userId)
      .then(setOntologies)
      .catch((e: Error) => setError(e.message))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadOntologies();
  }, [userId]);

  const handleCreate = async () => {
    if (!form.name.trim()) return;
    setCreating(true);
    try {
      await knowledgeApi.createOntology({
        userId,
        name: form.name,
        ontologyType: form.ontologyType,
        description: form.description,
        nodeTypes: form.nodeTypes
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean),
        edgeTypes: form.edgeTypes
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean),
      });
      setShowCreate(false);
      setForm({ name: '', ontologyType: 'custom', description: '', nodeTypes: '', edgeTypes: '' });
      loadOntologies();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to create ontology');
    } finally {
      setCreating(false);
    }
  };

  const handleApply = async (ontologyId: string) => {
    if (!applyDataset.trim()) return;
    setApplying(ontologyId);
    try {
      await knowledgeApi.applyOntology(ontologyId, applyDataset);
      setApplyDataset('');
      setApplying(null);
      loadOntologies();
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to apply ontology');
      setApplying(null);
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h4 className="text-sm font-bold text-primary">Ontologies ({ontologies.length})</h4>
        <button
          type="button"
          onClick={() => setShowCreate(!showCreate)}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl text-xs font-bold bg-cba-gold text-base hover:bg-cba-gold/90 transition-colors"
        >
          <Plus className="w-3.5 h-3.5" /> Create Ontology
        </button>
      </div>

      {error && <div className="neu-inset rounded-xl p-3 text-xs text-red-400">{error}</div>}

      {/* Create Modal */}
      {showCreate && (
        <div className="neu-raised rounded-xl p-4 border border-cba-gold/20 space-y-3">
          <h4 className="text-sm font-bold text-primary">New Ontology</h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label htmlFor="knowl-f1" className="block text-[10px] font-bold uppercase tracking-wider text-muted mb-1">
                Name
              </label>
              <input id="knowl-f1"
                type="text"
                value={form.name}
                onChange={(e) => setForm({ ...form, name: e.target.value })}
                placeholder="Financial Ontology"
                className="w-full neu-inset rounded-lg px-3 py-2 text-sm text-primary bg-transparent placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
              />
            </div>
            <div>
              <label htmlFor="knowl-f2" className="block text-[10px] font-bold uppercase tracking-wider text-muted mb-1">
                Type
              </label>
              <select id="knowl-f2"
                value={form.ontologyType}
                onChange={(e) => setForm({ ...form, ontologyType: e.target.value })}
                className="w-full neu-inset rounded-lg px-3 py-2 text-sm text-primary bg-transparent focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
              >
                <option value="custom">Custom</option>
                <option value="financial">Financial</option>
                <option value="generic">Generic</option>
                <option value="domain">Domain</option>
              </select>
            </div>
          </div>
          <div>
            <label htmlFor="knowl-f3" className="block text-[10px] font-bold uppercase tracking-wider text-muted mb-1">
              Description
            </label>
            <textarea id="knowl-f3"
              value={form.description}
              onChange={(e) => setForm({ ...form, description: e.target.value })}
              placeholder="Describe the ontology purpose..."
              rows={2}
              className="w-full neu-inset rounded-lg px-3 py-2 text-sm text-primary bg-transparent placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30 resize-none"
            />
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <div>
              <label htmlFor="knowl-f4" className="block text-[10px] font-bold uppercase tracking-wider text-muted mb-1">
                Node Types (comma-separated)
              </label>
              <input id="knowl-f4"
                type="text"
                value={form.nodeTypes}
                onChange={(e) => setForm({ ...form, nodeTypes: e.target.value })}
                placeholder="entity, concept, document"
                className="w-full neu-inset rounded-lg px-3 py-2 text-sm text-primary bg-transparent placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
              />
            </div>
            <div>
              <label htmlFor="knowl-f5" className="block text-[10px] font-bold uppercase tracking-wider text-muted mb-1">
                Edge Types (comma-separated)
              </label>
              <input id="knowl-f5"
                type="text"
                value={form.edgeTypes}
                onChange={(e) => setForm({ ...form, edgeTypes: e.target.value })}
                placeholder="related_to, part_of"
                className="w-full neu-inset rounded-lg px-3 py-2 text-sm text-primary bg-transparent placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
              />
            </div>
          </div>
          <div className="flex items-center justify-end gap-2">
            <button
              type="button"
              onClick={() => setShowCreate(false)}
              className="px-3 py-1.5 rounded-xl text-xs font-bold text-secondary hover:text-primary transition-colors"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleCreate}
              disabled={creating || !form.name.trim()}
              className="flex items-center gap-1.5 px-4 py-1.5 rounded-xl text-xs font-bold bg-cba-gold text-base hover:bg-cba-gold/90 disabled:opacity-50 transition-colors"
            >
              {creating ? (
                <Loader2 className="w-3.5 h-3.5 animate-spin" />
              ) : (
                <CheckCircle className="w-3.5 h-3.5" />
              )}
              Create
            </button>
          </div>
        </div>
      )}

      {/* Ontology Cards */}
      {ontologies.length === 0 ? (
        <div className="neu-inset rounded-xl p-8 text-center">
          <GitBranch className="w-8 h-8 mx-auto mb-3 text-zinc-600" />
          <p className="text-sm text-muted">
            No ontologies yet. Create one to structure your knowledge graph.
          </p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {ontologies.map((ont) => {
            const badgeClass = TYPE_BADGE_COLORS[ont.ontologyType] ?? 'bg-overlay text-secondary';
            return (
              <div key={ont.id} className="neu-raised rounded-xl p-4 space-y-3">
                <div className="flex items-start justify-between">
                  <div>
                    <h5 className="text-sm font-bold text-zinc-100">{ont.name}</h5>
                    <span
                      className={`inline-block mt-1 text-[10px] font-bold uppercase tracking-wider px-2 py-0.5 rounded-full ${badgeClass}`}
                    >
                      {ont.ontologyType}
                    </span>
                  </div>
                  <span className="text-[10px] text-zinc-600">v{ont.version}</span>
                </div>
                {ont.description && (
                  <p className="text-xs text-secondary line-clamp-2">{ont.description}</p>
                )}
                <div className="flex items-center gap-4 text-xs text-muted">
                  <span>{ont.nodeCount} nodes</span>
                  <span>{ont.edgeCount} edges</span>
                </div>
                {ont.appliedDatasets.length > 0 && (
                  <div className="flex flex-wrap gap-1">
                    {ont.appliedDatasets.map((ds) => (
                      <span
                        key={ds}
                        className="inline-block px-2 py-0.5 rounded-full text-[10px] font-bold bg-overlay text-secondary"
                      >
                        {ds}
                      </span>
                    ))}
                  </div>
                )}
                {/* Apply to dataset */}
                <div className="flex items-center gap-2">
                  <input
                    type="text"
                    placeholder="Dataset name..."
                    value={applying === ont.id ? applyDataset : ''}
                    onFocus={() => setApplying(ont.id)}
                    onChange={(e) => {
                      setApplying(ont.id);
                      setApplyDataset(e.target.value);
                    }}
                    className="flex-1 neu-inset rounded-lg px-2 py-1 text-xs text-primary bg-transparent placeholder-zinc-600 focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
                  />
                  <button
                    type="button"
                    onClick={() => handleApply(ont.id)}
                    disabled={applying !== ont.id || !applyDataset.trim()}
                    className="flex items-center gap-1 px-2 py-1 rounded-lg text-[10px] font-bold text-cba-gold hover:bg-cba-gold/10 disabled:opacity-30 transition-colors"
                  >
                    <ArrowRight className="w-3 h-3" /> Apply
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import { Loader2, TrendingUp, Plus, Trash2 } from 'lucide-react';
import { BASE_URL, getAuthHeaders } from '@/api';

interface CustomScenario {
  id: number;
  name: string;
  rate: string;
}

interface ScenarioResult {
  scenario: string;
  rate: number;
  monthly_repayment: number;
  total_interest: number;
  total_cost: number;
  difference_monthly: number;
  difference_total: number;
  source: 'cdr' | 'custom' | 'stress';
}

interface ScenariosResponse {
  base_rate: number;
  loan_amount: number;
  term_years: number;
  scenarios: ScenarioResult[];
}

const formatCurrency = (value: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(value);

async function fetchRateScenarios(params: Record<string, unknown>): Promise<ScenariosResponse> {
  const res = await fetch(`${BASE_URL}/api/cdr/loans/rate-scenarios`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getAuthHeaders() },
    body: JSON.stringify(params),
  });
  if (!res.ok) throw new Error('Failed to generate rate scenarios');
  return res.json();
}

let nextScenarioId = 1;

export function RateScenarios() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ScenariosResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [loanAmount, setLoanAmount] = useState('500000');
  const [termYears, setTermYears] = useState('30');
  const [currentRate, setCurrentRate] = useState('6.25');
  const [customScenarios, setCustomScenarios] = useState<CustomScenario[]>([]);

  const addCustomScenario = () => {
    setCustomScenarios((prev) => [...prev, { id: nextScenarioId++, name: '', rate: '' }]);
  };

  const removeCustomScenario = (id: number) => {
    setCustomScenarios((prev) => prev.filter((s) => s.id !== id));
  };

  const updateCustomScenario = (id: number, field: 'name' | 'rate', value: string) => {
    setCustomScenarios((prev) => prev.map((s) => (s.id === id ? { ...s, [field]: value } : s)));
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchRateScenarios({
        loan_amount: Math.round(parseFloat(loanAmount) * 100),
        term_years: parseInt(termYears),
        current_rate: parseFloat(currentRate) / 100,
        custom_scenarios: customScenarios
          .filter((s) => s.name && s.rate)
          .map((s) => ({ name: s.name, rate: parseFloat(s.rate) / 100 })),
      });
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate scenarios');
    } finally {
      setLoading(false);
    }
  };

  const sourceLabel = (source: string) => {
    switch (source) {
      case 'cdr':
        return { text: 'CDR', color: 'bg-cba-gold/10 text-cba-gold border-cba-gold/20' };
      case 'stress':
        return { text: 'Stress', color: 'bg-red-500/10 text-red-400 border-red-500/20' };
      default:
        return { text: 'Custom', color: 'bg-blue-500/10 text-blue-400 border-blue-500/20' };
    }
  };

  // Find the best (lowest monthly) and worst scenarios for highlighting
  const bestIdx =
    result?.scenarios.reduce(
      (best, s, i) =>
        s.monthly_repayment < (result.scenarios[best]?.monthly_repayment ?? Infinity) ? i : best,
      0,
    ) ?? -1;
  const worstIdx =
    result?.scenarios.reduce(
      (worst, s, i) =>
        s.monthly_repayment > (result.scenarios[worst]?.monthly_repayment ?? -Infinity) ? i : worst,
      0,
    ) ?? -1;

  return (
    <div className="space-y-6">
      {/* Input Form */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-cba-gold" />
            Rate Scenario Modeling
          </CardTitle>
          <CardDescription>
            Compare your rate against CDR market best, average, and stress scenarios
          </CardDescription>
        </CardHeader>
