            <Card className="neu-raised border-border/50">
              <CardContent className="pt-6 text-center">
                <p className="text-xs text-muted">Term</p>
                <p className="text-xl font-bold">{result.term_years} years</p>
              </CardContent>
            </Card>
            <Card className="neu-raised border-cba-gold/10">
              <CardContent className="pt-6 text-center">
                <p className="text-xs text-muted">Base Rate</p>
                <p className="text-xl font-bold text-cba-gold">
                  {(result.base_rate * 100).toFixed(2)}%
                </p>
              </CardContent>
            </Card>
          </div>

          {/* Scenarios Table */}
          <Card className="neu-raised border-border/50">
            <CardHeader>
              <CardTitle>Scenario Comparison</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="overflow-x-auto">
                <table className="w-full text-sm">
                  <thead>
                    <tr className="text-xs text-muted uppercase border-b border-border/50">
                      <th className="text-left py-2 pr-3">Scenario</th>
                      <th className="text-right py-2 px-2">Rate</th>
                      <th className="text-right py-2 px-2">Monthly</th>
                      <th className="text-right py-2 px-2">Total Interest</th>
                      <th className="text-right py-2 px-2">Diff (Monthly)</th>
                      <th className="text-right py-2 pl-2">Diff (Total)</th>
                    </tr>
                  </thead>
                  <tbody>
                    {result.scenarios.map((s, i) => {
                      const sl = sourceLabel(s.source);
                      const isBest = i === bestIdx;
                      const isWorst = i === worstIdx;
                      return (
                        <tr
                          key={i}
                          className={`border-b border-border/50 last:border-0 ${
                            isBest ? 'bg-emerald-500/5' : isWorst ? 'bg-red-500/5' : ''
                          }`}
                        >
                          <td className="py-3 pr-3">
                            <div className="flex items-center gap-2">
                              <span className="font-medium">{s.scenario}</span>
                              <Badge className={`${sl.color} text-[10px]`}>{sl.text}</Badge>
                              {isBest && (
                                <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20 text-[10px]">
                                  Best
                                </Badge>
                              )}
                            </div>
                          </td>
                          <td className="text-right py-3 px-2 font-medium">
                            {(s.rate * 100).toFixed(2)}%
                          </td>
                          <td className="text-right py-3 px-2">
                            {formatCurrency(s.monthly_repayment / 100)}
                          </td>
                          <td className="text-right py-3 px-2 text-secondary">
                            {formatCurrency(s.total_interest / 100)}
                          </td>
                          <td
                            className={`text-right py-3 px-2 ${
                              s.difference_monthly < 0
                                ? 'text-emerald-400'
                                : s.difference_monthly > 0
                                  ? 'text-red-400'
                                  : 'text-secondary'
                            }`}
                          >
                            {s.difference_monthly !== 0 && (s.difference_monthly > 0 ? '+' : '')}
                            {s.difference_monthly === 0
                              ? '—'
                              : formatCurrency(s.difference_monthly / 100)}
                          </td>
                          <td
                            className={`text-right py-3 pl-2 ${
                              s.difference_total < 0
                                ? 'text-emerald-400'
                                : s.difference_total > 0
                                  ? 'text-red-400'
                                  : 'text-secondary'
                            }`}
                          >
                            {s.difference_total !== 0 && (s.difference_total > 0 ? '+' : '')}
                            {s.difference_total === 0
                              ? '—'
                              : formatCurrency(s.difference_total / 100)}
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>
              </div>
            </CardContent>
          </Card>

          {/* Visual Rate Bars */}
          <Card className="neu-raised border-border/50">
            <CardHeader>
              <CardTitle className="text-base">Monthly Repayment Comparison</CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {result.scenarios.map((s, i) => {
                  const maxRepayment = Math.max(
                    ...result.scenarios.map((x) => x.monthly_repayment),
                  );
                  const pct = maxRepayment > 0 ? (s.monthly_repayment / maxRepayment) * 100 : 0;
                  const isBest = i === bestIdx;
                  return (
                    <div key={i} className="space-y-1">
                      <div className="flex items-center justify-between text-xs">
                        <span className="text-secondary">{s.scenario}</span>
                        <span className="font-medium">
                          {formatCurrency(s.monthly_repayment / 100)}/mo
                        </span>
                      </div>
                      <div className="h-3 rounded-full bg-overlay overflow-hidden">
                        <div
                          className={`h-full rounded-full transition-all ${
                            isBest
                              ? 'bg-emerald-500'
                              : s.source === 'stress'
                                ? 'bg-red-500'
                                : 'bg-cba-gold'
                          }`}
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  );
                })}
              </div>
            </CardContent>
          </Card>
        </>
      )}
    </div>
  );
}

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';
import {
  Loader2,
  ArrowRightLeft,
  TrendingDown,
  CheckCircle,
  AlertTriangle,
  MinusCircle,
} from 'lucide-react';
import { BASE_URL, getAuthHeaders } from '@/api';

interface RefinanceInput {
  currentLender: string;
  currentRate: string;
  currentBalance: string;
  remainingTermYears: string;
  monthlyRepayment: string;
  loanPurpose: string;
  features: string[];
  switchingCosts: string;
}

interface Alternative {
  lender: string;
  product: string;
  rate: number;
  comparison_rate: number;
  monthly_saving: number;
  annual_saving: number;
  lifetime_saving: number;
  break_even_months: number;
  feature_match: string[];
  recommendation: 'switch' | 'negotiate' | 'stay';
}

interface RefinanceResult {
  summary: {
    potential_annual_saving: number;
    best_rate: number;
    current_rate: number;
    recommendation: 'switch' | 'negotiate' | 'stay';
  };
  alternatives: Alternative[];
}

const formatCurrency = (value: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(value);

const LOAN_FEATURES = [
  'Offset Account',
  'Redraw Facility',
  'Extra Repayments',
  'Split Loan',
  'Fixed Rate Lock',
  'Interest Only Option',
];

const recommendationConfig = {
  switch: {
    label: 'Switch',
    color: 'bg-emerald-500/10 text-emerald-400 border-emerald-500/20',
    icon: CheckCircle,
  },
  negotiate: {
    label: 'Negotiate',
    color: 'bg-yellow-500/10 text-yellow-400 border-yellow-500/20',
    icon: AlertTriangle,
  },
  stay: {
    label: 'Stay',
    color: 'bg-zinc-500/10 text-secondary border-zinc-500/20',
    icon: MinusCircle,
  },
};

async function fetchRefinanceAnalysis(params: Record<string, unknown>): Promise<RefinanceResult> {
  const res = await fetch(`${BASE_URL}/api/cdr/loans/refinance`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getAuthHeaders() },
    body: JSON.stringify(params),
  });
  if (!res.ok) throw new Error('Failed to fetch refinance analysis');
  return res.json();
}

export function RefinanceAnalysis() {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<RefinanceResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  const [input, setInput] = useState<RefinanceInput>({
    currentLender: '',
    currentRate: '6.5',
    currentBalance: '500000',
    remainingTermYears: '25',
    monthlyRepayment: '3500',
    loanPurpose: 'owner_occupied',
    features: [],
    switchingCosts: '1500',
  });

  const updateField = <K extends keyof RefinanceInput>(key: K, value: RefinanceInput[K]) =>
    setInput((prev) => ({ ...prev, [key]: value }));

  const toggleFeature = (feature: string) => {
    setInput((prev) => ({
      ...prev,
      features: prev.features.includes(feature)
        ? prev.features.filter((f) => f !== feature)
        : [...prev.features, feature],
    }));
  };

  const handleAnalyze = async () => {
    setLoading(true);
    setError(null);
    try {
      const data = await fetchRefinanceAnalysis({
        current_lender: input.currentLender,
        current_rate: parseFloat(input.currentRate) / 100,
        current_balance: Math.round(parseFloat(input.currentBalance) * 100),
        remaining_term_months: parseInt(input.remainingTermYears) * 12,
        monthly_repayment: Math.round(parseFloat(input.monthlyRepayment) * 100),
        loan_purpose: input.loanPurpose,
        required_features: input.features,
        switching_costs: Math.round(parseFloat(input.switchingCosts) * 100),
      });
      setResult(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Analysis failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Input Form */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ArrowRightLeft className="w-5 h-5 text-cba-gold" />
