          </CardTitle>
          <CardDescription>
            Compare your current loan against CDR market alternatives
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid gap-4 md:grid-cols-3">
            <div className="space-y-2">
