import { useState, useEffect, useCallback } from 'react';
import { WifiOff, RefreshCw, X } from 'lucide-react';
import { useOffline } from '../../../hooks/useOffline';

export function OfflineIndicator() {
  const { isOnline, pendingChanges, syncStatus } = useOffline();
  const [dismissed, setDismissed] = useState(false);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (!isOnline) {
      setDismissed(false);
      setVisible(true);
    } else if (syncStatus === 'syncing') {
      setVisible(true);
    } else {
      // Fade out after going online
      const timer = setTimeout(() => setVisible(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isOnline, syncStatus]);

  const handleDismiss = useCallback(() => {
    setDismissed(true);
  }, []);

  if (!visible || dismissed) return null;

  return (
    <div
      className={`w-full z-30 transition-all duration-300 ease-in-out ${
        visible ? 'max-h-14 opacity-100' : 'max-h-0 opacity-0'
      }`}
    >
      {!isOnline && (
        <div className="flex items-center justify-between gap-3 px-4 py-2.5 bg-cba-gold/10 border-b border-cba-gold/20">
          <div className="flex items-center gap-2.5 text-cba-gold">
            <WifiOff className="h-4 w-4 shrink-0" />
            <span className="text-xs font-medium">
              You're offline. Changes will sync when connected.
            </span>
          </div>
          <button
            onClick={handleDismiss}
            className="text-cba-gold/60 hover:text-cba-gold p-1 shrink-0"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        </div>
      )}

      {isOnline && syncStatus === 'syncing' && (
        <div className="flex items-center gap-2.5 px-4 py-2.5 bg-cba-gold/10 border-b border-cba-gold/20">
          <RefreshCw className="h-4 w-4 text-cba-gold animate-spin shrink-0" />
          <span className="text-xs font-medium text-cba-gold">
            Syncing {pendingChanges} change{pendingChanges !== 1 ? 's' : ''}...
          </span>
          {/* Progress bar */}
          <div className="flex-1 h-1 rounded-full bg-cba-gold/20 overflow-hidden">
            <div className="h-full bg-cba-gold rounded-full animate-pulse w-2/3" />
          </div>
        </div>
      )}

      {isOnline && syncStatus !== 'syncing' && pendingChanges === 0 && (
        <div className="flex items-center gap-2.5 px-4 py-2 bg-emerald-500/10 border-b border-emerald-500/20">
          <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse" />
          <span className="text-xs font-medium text-emerald-400">Back online</span>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  fetchEmployee,
  updateEmployee,
  fetchBankDetails,
  fetchSuperFund,
  fetchTaxDeclaration,
  fetchPayStructure,
} from '../../../../../api';
import type {
  DetailTab,
  EmployeeRecord,
  BankDetailRecord,
  SuperFundRecord,
  TaxDeclarationRecord,
  PayStructureRecord,
} from '../types.js';

export function useEmployeeData(employeeId: string) {
  const [activeTab, setActiveTab] = useState<DetailTab>('personal');
  const [employee, setEmployee] = useState<EmployeeRecord | null>(null);
  const [bankDetails, setBankDetails] = useState<BankDetailRecord[]>([]);
  const [superFund, setSuperFund] = useState<SuperFundRecord | null>(null);
  const [taxDeclaration, setTaxDeclaration] = useState<TaxDeclarationRecord | null>(null);
  const [payStructure, setPayStructureData] = useState<PayStructureRecord[]>([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState<string | null>(null);
  const [editData, setEditData] = useState<Record<string, string>>({});

  const loadData = async () => {
    setLoading(true);
    try {
      const emp = await fetchEmployee(employeeId);
      setEmployee(emp);

      const [bank, sup, tax, pay] = await Promise.all([
        fetchBankDetails(employeeId).catch(() => ({ data: [] })),
        fetchSuperFund(employeeId).catch(() => ({ data: null })),
        fetchTaxDeclaration(employeeId).catch(() => null),
        fetchPayStructure(employeeId).catch(() => ({ data: [] })),
      ]);

      setBankDetails(bank.data ?? []);
      setSuperFund(sup.data ?? null);
      setTaxDeclaration(tax);
      setPayStructureData(pay.data ?? []);
    } catch (e) {
      console.error('Failed to load employee', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [employeeId]);

  const handleSavePersonal = async () => {
    try {
      await updateEmployee(employeeId, editData);
      setEmployee({ ...employee, ...editData });
      setEditing(null);
      setEditData({});
    } catch (e) {
      console.error('Failed to save', e);
    }
  };

  const handleCancelEdit = () => {
    setEditing(null);
    setEditData({});
  };

  return {
    activeTab,
    setActiveTab,
    employee,
    bankDetails,
    superFund,
    taxDeclaration,
    payStructure,
    loading,
    editing,
    setEditing,
    editData,
    setEditData,
    loadData,
    handleSavePersonal,
    handleCancelEdit,
  };
}

import { useState, useMemo } from 'react';
import { Search, ChevronLeft, ChevronRight, Filter } from 'lucide-react';

interface Employee {
  id: string;
  first_name: string;
  last_name: string;
  email: string;
  employment_type: string;
  employment_status: string;
  start_date: string;
  position?: string;
}

interface EmployeeListProps {
  employees: Employee[];
  loading: boolean;
  onSelect: (id: string) => void;
  onRefresh: () => void;
}

const statusStyles: Record<string, { bg: string; text: string; label: string }> = {
  active: { bg: 'bg-emerald-500/10', text: 'text-emerald-400', label: 'Active' },
  terminated: { bg: 'bg-red-500/10', text: 'text-red-400', label: 'Terminated' },
  on_leave: { bg: 'bg-amber-500/10', text: 'text-amber-400', label: 'On Leave' },
};

const typeLabels: Record<string, string> = {
  full_time: 'Full Time',
  part_time: 'Part Time',
  casual: 'Casual',
  contractor: 'Contractor',
};

const PAGE_SIZE = 10;

export function EmployeeList({ employees, loading, onSelect, onRefresh }: EmployeeListProps) {
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [page, setPage] = useState(0);

  const filtered = useMemo(() => {
    let result = employees;

    if (statusFilter !== 'all') {
      result = result.filter((e) => e.employment_status === statusFilter);
    }

    if (search.trim()) {
      const q = search.toLowerCase();
      result = result.filter(
        (e) =>
          e.first_name.toLowerCase().includes(q) ||
          e.last_name.toLowerCase().includes(q) ||
          e.email.toLowerCase().includes(q),
      );
    }

    return result;
  }, [employees, search, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const pageEmployees = filtered.slice(page * PAGE_SIZE, (page + 1) * PAGE_SIZE);

  if (loading) {
    return (
      <div className="neu-raised rounded-2xl p-6 space-y-4">
        {Array.from({ length: 5 }).map((_, i) => (
          <div key={i} className="flex items-center gap-4 animate-pulse">
            <div className="h-10 w-10 rounded-full bg-overlay" />
            <div className="flex-1 space-y-2">
              <div className="h-4 w-40 bg-overlay rounded" />
              <div className="h-3 w-24 bg-overlay rounded" />
            </div>
            <div className="h-6 w-16 bg-overlay rounded-full" />
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="neu-raised rounded-2xl overflow-hidden">
      {/* Toolbar */}
      <div className="p-4 border-b border-border/50 flex flex-col sm:flex-row gap-3">
        <div className="relative flex-1">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted" />
          <input
            type="text"
            value={search}
            onChange={(e) => {
              setSearch(e.target.value);
              setPage(0);
            }}
            placeholder="Search by name or email..."
            className="w-full pl-9 pr-4 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary placeholder:text-muted focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/40"
          />
        </div>
        <div className="relative">
          <Filter className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted" />
          <select
            value={statusFilter}
            onChange={(e) => {
              setStatusFilter(e.target.value);
              setPage(0);
            }}
            className="pl-9 pr-8 py-2.5 rounded-xl bg-overlay border border-border text-sm text-primary appearance-none focus:outline-none focus:ring-1 focus:ring-[#FFCC00]/40"
          >
            <option value="all">All Statuses</option>
            <option value="active">Active</option>
            <option value="terminated">Terminated</option>
            <option value="on_leave">On Leave</option>
          </select>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <table className="w-full">
          <thead>
            <tr className="border-b border-border/50">
              <th className="text-left text-xs font-medium text-muted uppercase tracking-wider px-4 py-3">
                Employee
              </th>
              <th className="text-left text-xs font-medium text-muted uppercase tracking-wider px-4 py-3 hidden sm:table-cell">
                Type
              </th>
              <th className="text-left text-xs font-medium text-muted uppercase tracking-wider px-4 py-3 hidden md:table-cell">
                Position
              </th>
              <th className="text-left text-xs font-medium text-muted uppercase tracking-wider px-4 py-3 hidden lg:table-cell">
                Start Date
              </th>
              <th className="text-left text-xs font-medium text-muted uppercase tracking-wider px-4 py-3">
                Status
              </th>
            </tr>
          </thead>
          <tbody>
            {pageEmployees.length === 0 ? (
              <tr>
                <td colSpan={5} className="text-center py-12 text-muted text-sm">
                  {search || statusFilter !== 'all'
                    ? 'No employees match your filters'
                    : 'No employees yet. Add your first employee to get started.'}
                </td>
              </tr>
            ) : (
              pageEmployees.map((emp) => {
                const status = statusStyles[emp.employment_status] ?? statusStyles.active;
                return (
                  <tr
                    key={emp.id}
                    onClick={() => onSelect(emp.id)}
                    className="border-b border-border/50 last:border-0 hover:bg-white/[0.02] cursor-pointer transition-colors"
                  >
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        <div className="h-9 w-9 rounded-full bg-cba-gold/10 flex items-center justify-center text-sm font-bold text-cba-gold">
                          {emp.first_name[0]}
                          {emp.last_name[0]}
                        </div>
                        <div>
                          <p className="text-sm font-medium text-primary">
                            {emp.first_name} {emp.last_name}
                          </p>
                          <p className="text-xs text-muted">{emp.email}</p>
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3 hidden sm:table-cell">
                      <span className="text-xs font-medium text-primary bg-overlay px-2 py-1 rounded-md">
                        {typeLabels[emp.employment_type] ?? emp.employment_type}
                      </span>
                    </td>
                    <td className="px-4 py-3 hidden md:table-cell">
                      <span className="text-sm text-secondary">{emp.position ?? '-'}</span>
                    </td>
                    <td className="px-4 py-3 hidden lg:table-cell">
                      <span className="text-sm text-secondary">
                        {new Date(emp.start_date).toLocaleDateString('en-AU')}
                      </span>
                    </td>
                    <td className="px-4 py-3">
                      <span
                        className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${status.bg} ${status.text}`}
                      >
                        {status.label}
                      </span>
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between px-4 py-3 border-t border-border/50">
          <p className="text-xs text-muted">
            Showing {page * PAGE_SIZE + 1}–{Math.min((page + 1) * PAGE_SIZE, filtered.length)} of{' '}
            {filtered.length}
          </p>
          <div className="flex gap-1">
            <button
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              className="p-1.5 rounded-lg text-secondary hover:text-primary hover:bg-overlay disabled:opacity-30 disabled:pointer-events-none transition-colors"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <span className="px-3 py-1.5 text-xs font-medium text-secondary">
              {page + 1} / {totalPages}
            </span>
            <button
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
              className="p-1.5 rounded-lg text-secondary hover:text-primary hover:bg-overlay disabled:opacity-30 disabled:pointer-events-none transition-colors"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import {
  fetchPayCategories,
  fetchPayStructure,
  setPayStructure,
  fetchEmployee,
} from '../../../../../api';
import type { EmployeeSummary, PayCategory, PayStructureItem, PaySummary } from '../types.js';
import { SUPER_RATE } from '../constants.js';
import { today } from '../helpers.js';

export function usePayStructure(employeeId: string) {
  const [employee, setEmployee] = useState<EmployeeSummary | null>(null);
  const [categories, setCategories] = useState<PayCategory[]>([]);
  const [items, setItems] = useState<PayStructureItem[]>([]);
  const [allItems, setAllItems] = useState<PayStructureItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [showHistory, setShowHistory] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [saving, setSaving] = useState(false);

  // Form state
  const [formCategoryId, setFormCategoryId] = useState('');
  const [formRate, setFormRate] = useState('');
  const [formHoursPerWeek, setFormHoursPerWeek] = useState('38');
  const [formAnnualSalary, setFormAnnualSalary] = useState('');
  const [formEffectiveDate, setFormEffectiveDate] = useState(today());

  const loadData = async () => {
    setLoading(true);
    try {
      const [empResult, catResult, structResult] = await Promise.all([
        fetchEmployee(employeeId),
        fetchPayCategories('default'),
        fetchPayStructure(employeeId),
      ]);
      setEmployee(empResult);
      setCategories((catResult.data ?? []).filter((c: PayCategory) => c.isActive));

      const structItems: PayStructureItem[] = structResult?.items ?? structResult?.data ?? [];
      setAllItems(structItems);
      setItems(structItems.filter((it: PayStructureItem) => it.isActive));
    } catch (e) {
      console.error('Failed to load pay structure data', e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, [employeeId]);

  const selectedCategory = useMemo(
    () => categories.find((c) => c.id === formCategoryId),
    [categories, formCategoryId],
  );

  const summary: PaySummary = useMemo(() => {
    let weeklyGross = 0;
    let annualTotal = 0;
    let oteBasis = 0;

    for (const item of items) {
      const rateInDollars = item.rateCents / 100;
      const multiplier = item.multiplier || 1;

      if (item.rateType === 'hourly') {
        const hours = item.hoursPerWeek ?? 38;
        const weeklyItem = rateInDollars * hours * multiplier;
        weeklyGross += weeklyItem;
        annualTotal += weeklyItem * 52;
        if (item.categoryType === 'ordinary' || item.categoryType === 'leave') {
          oteBasis += weeklyItem * 52;
        }
      } else if (item.rateType === 'annual') {
        const annual =
          item.annualSalaryCents != null ? item.annualSalaryCents / 100 : rateInDollars;
        weeklyGross += annual / 52;
        annualTotal += annual;
        if (item.categoryType === 'ordinary') {
          oteBasis += annual;
        }
      } else {
        weeklyGross += rateInDollars * multiplier;
        annualTotal += rateInDollars * multiplier * 52;
      }
    }

    const superAmount = oteBasis * SUPER_RATE;

    return {
      weekly: weeklyGross,
      fortnightly: weeklyGross * 2,
      monthly: annualTotal / 12,
      annual: annualTotal,
      superAnnual: superAmount,
      superMonthly: superAmount / 12,
    };
  }, [items]);

  const resetForm = () => {
    setFormCategoryId('');
    setFormRate('');
    setFormHoursPerWeek('38');
    setFormAnnualSalary('');
    setFormEffectiveDate(today());
    setShowForm(false);
  };

  const handleCategoryChange = (catId: string) => {
    setFormCategoryId(catId);
    const cat = categories.find((c) => c.id === catId);
    if (cat?.defaultRateCents != null) {
      setFormRate((cat.defaultRateCents / 100).toFixed(2));
    }
  };

  const handleAddPayItem = async () => {
    if (!formCategoryId || !formRate) return;

    const cat = categories.find((c) => c.id === formCategoryId);
    if (!cat) return;

    setSaving(true);
    try {
      const rateCents = Math.round(parseFloat(formRate) * 100);
      const hoursPerWeek = cat.rateType === 'hourly' ? parseFloat(formHoursPerWeek) || 38 : null;
      const annualSalaryCents =
        cat.rateType === 'annual' ? Math.round(parseFloat(formAnnualSalary) * 100) : null;

      await setPayStructure(employeeId, {
        payCategoryId: formCategoryId,
        rateCents,
        hoursPerWeek,
        annualSalaryCents,
        multiplier: cat.multiplier ?? 1,
        effectiveDate: formEffectiveDate,
      });
      resetForm();
      await loadData();
    } catch (e) {
      console.error('Failed to add pay item', e);
    } finally {
      setSaving(false);
    }
  };

  const displayItems = showHistory ? allItems : items;

  return {
    employee,
    categories,
    items,
    allItems,
    displayItems,
    loading,
    showHistory,
    setShowHistory,
    showForm,
    setShowForm,
    saving,
    formCategoryId,
    formRate,
    formHoursPerWeek,
    formAnnualSalary,
    formEffectiveDate,
    setFormRate,
    setFormHoursPerWeek,
    setFormAnnualSalary,
    setFormEffectiveDate,
    selectedCategory,
    summary,
    resetForm,
    handleCategoryChange,
    handleAddPayItem,
  };
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import {
  ArrowLeft,
  Loader2,
  Zap,
  CheckCircle2,
  XCircle,
  AlertCircle,
  MinusCircle,
} from 'lucide-react';
import { reconApi } from '@/api';
import { cn } from '@/lib/utils';
import { ReconMatchSuggestions } from './ReconMatchSuggestions';
import type { BankTransaction, MatchSuggestion } from './ReconMatchSuggestions';

interface ReconSession {
  id: string;
  accountId: string;
  accountName: string;
  periodStart: string;
  periodEnd: string;
  status: string;
  statementBalanceCents?: number;
  ledgerBalanceCents?: number;
  matchedCount: number;
  unmatchedCount: number;
  differenceAmount?: number;
  bankTransactions?: BankTransaction[];
  ledgerEntries?: LedgerEntry[];
  matches?: MatchSuggestion[];
}

interface LedgerEntry {
  id: string;
  reference: string;
  date: string;
  amount: number;
  description: string;
  matchStatus: 'confirmed' | 'suggested' | 'rejected' | 'unmatched';
}

interface ReconMatchingWorkspaceProps {
  sessionId: string;
  onBack: () => void;
}

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const statusColors: Record<string, string> = {
  confirmed: 'bg-emerald-500/20 text-emerald-400 border-emerald-500/30',
  suggested: 'bg-amber-500/20 text-amber-400 border-amber-500/30',
  rejected: 'bg-red-500/20 text-red-400 border-red-500/30',
  unmatched: 'bg-zinc-500/20 text-secondary border-zinc-500/30',
};

const statusIcons: Record<string, typeof CheckCircle2> = {
  confirmed: CheckCircle2,
  suggested: AlertCircle,
  rejected: XCircle,
  unmatched: MinusCircle,
};

export function ReconMatchingWorkspace({ sessionId, onBack }: ReconMatchingWorkspaceProps) {
  const [session, setSession] = useState<ReconSession | null>(null);
  const [loading, setLoading] = useState(true);
  const [autoMatching, setAutoMatching] = useState(false);
  const [completing, setCompleting] = useState(false);
  const [selectedBankTx, setSelectedBankTx] = useState<BankTransaction | null>(null);
  const [suggestions, setSuggestions] = useState<MatchSuggestion[]>([]);

  useEffect(() => {
    loadSession();
  }, [sessionId]);

  const loadSession = async () => {
    setLoading(true);
    try {
      const data = await reconApi.getSession(sessionId);
      setSession(data);
    } catch (err) {
      console.error('Failed to load session:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleAutoMatch = async () => {
    setAutoMatching(true);
    try {
      await reconApi.autoMatch(sessionId);
      await loadSession();
    } catch (err) {
      console.error('Auto-match failed:', err);
    } finally {
      setAutoMatching(false);
    }
  };

  const handleComplete = async () => {
    setCompleting(true);
    try {
      await reconApi.completeSession(sessionId);
      onBack();
    } catch (err) {
      console.error('Failed to complete session:', err);
    } finally {
      setCompleting(false);
    }
  };

  const handleSelectBankTx = (tx: BankTransaction) => {
    setSelectedBankTx(tx);
    // Filter suggestions for this transaction
    const txSuggestions = (session?.matches ?? []).filter(
      (m) => m.matchId.includes(tx.id) || true, // Show all available suggestions
    );
    setSuggestions(txSuggestions);
  };

  const handleConfirmMatch = async (_matchId: string) => {
    await loadSession();
    setSelectedBankTx(null);
    setSuggestions([]);
  };

  const handleRejectMatch = async (_matchId: string) => {
    await loadSession();
  };

  const handleManualMatch = async (_bankTxId: string, _ledgerEntryId: string) => {
    await loadSession();
    setSelectedBankTx(null);
    setSuggestions([]);
  };

  const handleMarkNoMatch = (_bankTxId: string) => {
    // Mark as reviewed but unmatched
    setSelectedBankTx(null);
    setSuggestions([]);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-16">
        <Loader2 className="h-6 w-6 animate-spin text-cba-gold" />
      </div>
    );
  }

  if (!session) {
    return (
      <div className="text-center py-16">
        <p className="text-muted">Session not found</p>
        <Button variant="ghost" size="sm" onClick={onBack} className="mt-2">
          <ArrowLeft className="h-4 w-4 mr-1" /> Back
        </Button>
      </div>
    );
  }

  const bankTransactions = session.bankTransactions ?? [];
  const ledgerEntries = session.ledgerEntries ?? [];
  const totalItems = session.matchedCount + session.unmatchedCount;
  const matchPercent = totalItems > 0 ? Math.round((session.matchedCount / totalItems) * 100) : 0;
  const statementBalance = session.statementBalanceCents ?? 0;
  const ledgerBalance = session.ledgerBalanceCents ?? 0;
  const difference = session.differenceAmount ?? statementBalance - ledgerBalance;

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div className="flex items-center gap-3">
          <Button variant="ghost" size="sm" onClick={onBack}>
            <ArrowLeft className="h-4 w-4 mr-1" /> Back
          </Button>
          <div>
            <h3 className="text-lg font-bold text-primary">
              {session.accountName ?? 'Reconciliation'}
            </h3>
            <p className="text-xs text-muted">
              {session.periodStart} to {session.periodEnd}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <Button
            size="sm"
            className="bg-cba-gold text-base hover:bg-cba-gold/90"
            onClick={handleAutoMatch}
            disabled={autoMatching}
          >
            {autoMatching ? (
              <Loader2 className="h-4 w-4 animate-spin mr-1" />
            ) : (
              <Zap className="h-4 w-4 mr-1" />
            )}
            Auto-Match
          </Button>
          <Button
            size="sm"
            variant="outline"
            className="border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/10"
            onClick={handleComplete}
            disabled={completing}
          >
            {completing ? (
              <Loader2 className="h-4 w-4 animate-spin mr-1" />
            ) : (
              <CheckCircle2 className="h-4 w-4 mr-1" />
            )}
            Complete Session
          </Button>
        </div>
      </div>

      {/* Progress & Balance Banner */}
      <div className="neu-raised rounded-xl p-4 border border-border/50">
        <div className="flex items-center justify-between mb-2">
          <span className="text-xs font-bold text-muted uppercase tracking-wider">
            Matched: {session.matchedCount} of {totalItems}
          </span>
          <span className="text-sm font-bold text-cba-gold">{matchPercent}%</span>
        </div>
        <Progress value={matchPercent} className="h-2 mb-3" />
        <div className="grid grid-cols-3 gap-4 text-center text-sm">
          <div>
            <p className="text-muted text-xs mb-1">Statement</p>
            <p className="font-bold text-primary">{formatCurrency(statementBalance)}</p>
          </div>
          <div>
            <p className="text-muted text-xs mb-1">Ledger</p>
            <p className="font-bold text-primary">{formatCurrency(ledgerBalance)}</p>
          </div>
          <div>
            <p className="text-muted text-xs mb-1">Difference</p>
            <p className={cn('font-bold', difference === 0 ? 'text-emerald-400' : 'text-red-400')}>
              {formatCurrency(difference)}
            </p>
          </div>
        </div>
      </div>

      {/* Two-column layout */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Bank Transactions */}
        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-blue-500" />
              Bank Transactions
              <Badge variant="secondary" className="text-[10px] ml-auto">
                {bankTransactions.length}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent>
            {bankTransactions.length === 0 ? (
              <p className="text-xs text-muted text-center py-6">
                No bank transactions for this period
              </p>
            ) : (
              <div className="space-y-1 max-h-[500px] overflow-y-auto scrollbar-gold">
                {bankTransactions.map((tx) => {
                  const StatusIcon = statusIcons[tx.matchStatus] ?? MinusCircle;
                  return (
                    <button
                      key={tx.id}
                      type="button"
                      onClick={() => handleSelectBankTx(tx)}
                      className={cn(
                        'w-full text-left p-2.5 rounded-lg border transition-all text-xs',
                        selectedBankTx?.id === tx.id
                          ? 'border-cba-gold/50 bg-cba-gold/5'
                          : 'border-border/50 hover:border-border',
                      )}
                    >
                      <div className="flex items-center justify-between gap-2">
                        <div className="flex items-center gap-2 flex-1 min-w-0">
                          <StatusIcon
                            className={cn(
                              'h-3.5 w-3.5 shrink-0',
                              tx.matchStatus === 'confirmed' && 'text-emerald-400',
                              tx.matchStatus === 'suggested' && 'text-amber-400',
                              tx.matchStatus === 'rejected' && 'text-red-400',
                              tx.matchStatus === 'unmatched' && 'text-muted',
                            )}
                          />
                          <div className="min-w-0">
                            <p className="text-primary truncate">{tx.description}</p>
                            <p className="text-zinc-600">{tx.date}</p>
                          </div>
                        </div>
                        <span
                          className={cn(
                            'font-bold shrink-0',
                            tx.amount >= 0 ? 'text-emerald-400' : 'text-red-400',
                          )}
                        >
                          {formatCurrency(tx.amount)}
                        </span>
                      </div>
                    </button>
                  );
                })}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Ledger Entries / Suggestions Panel */}
        <div className="space-y-4">
          {selectedBankTx ? (
            <ReconMatchSuggestions
              transaction={selectedBankTx}
              suggestions={suggestions}
              ledgerEntries={ledgerEntries.map((le) => ({
                id: le.id,
                reference: le.reference,
                date: le.date,
                amount: le.amount,
              }))}
              sessionId={sessionId}
              onConfirm={handleConfirmMatch}
              onReject={handleRejectMatch}
              onManualMatch={handleManualMatch}
              onMarkNoMatch={handleMarkNoMatch}
              onClose={() => {
                setSelectedBankTx(null);
                setSuggestions([]);
              }}
            />
          ) : (
            <Card>
              <CardHeader className="pb-2">
                <CardTitle className="text-sm flex items-center gap-2">
                  <div className="w-2 h-2 rounded-full bg-purple-500" />
                  Ledger Entries
                  <Badge variant="secondary" className="text-[10px] ml-auto">
                    {ledgerEntries.length}
                  </Badge>
                </CardTitle>
              </CardHeader>
              <CardContent>
                {ledgerEntries.length === 0 ? (
                  <p className="text-xs text-muted text-center py-6">
                    No ledger entries for this period
                  </p>
                ) : (
                  <div className="space-y-1 max-h-[500px] overflow-y-auto scrollbar-gold">
                    {ledgerEntries.map((le) => {
                      const StatusIcon = statusIcons[le.matchStatus] ?? MinusCircle;
                      return (
                        <div key={le.id} className="p-2.5 rounded-lg border border-border/50 text-xs">
                          <div className="flex items-center justify-between gap-2">
                            <div className="flex items-center gap-2 flex-1 min-w-0">
                              <StatusIcon
                                className={cn(
                                  'h-3.5 w-3.5 shrink-0',
                                  le.matchStatus === 'confirmed' && 'text-emerald-400',
                                  le.matchStatus === 'suggested' && 'text-amber-400',
                                  le.matchStatus === 'rejected' && 'text-red-400',
                                  le.matchStatus === 'unmatched' && 'text-muted',
                                )}
                              />
                              <div className="min-w-0">
                                <p className="text-primary truncate">{le.reference}</p>
                                <p className="text-zinc-600">{le.date}</p>
                              </div>
                            </div>
                            <span
                              className={cn(
                                'font-bold shrink-0',
                                le.amount >= 0 ? 'text-emerald-400' : 'text-red-400',
                              )}
                            >
                              {formatCurrency(le.amount)}
                            </span>
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </CardContent>
            </Card>
          )}
        </div>
      </div>
    </div>
  );
}

