import { useState, useEffect } from 'react';
import {
  FileText,
  BarChart3,
  Wallet,
  ArrowUpDown,
  GitCompareArrows,
  TrendingUp,
} from 'lucide-react';
import { api } from '@/api';
import type { Account } from '@/api';
import { cn } from '@/lib/utils';
import { ProfitAndLoss } from './ProfitAndLoss';
import { BalanceSheet } from './BalanceSheet';
import { CashFlow } from './CashFlow';
import { TrialBalance } from './TrialBalance';
import { PeriodComparison } from './PeriodComparison';
import { KPIDashboard } from './KPIDashboard';

type ReportTab = 'pnl' | 'balance-sheet' | 'cash-flow' | 'trial-balance' | 'comparison' | 'kpis';

const tabs: { id: ReportTab; label: string; icon: typeof FileText }[] = [
  { id: 'pnl', label: 'P&L', icon: FileText },
  { id: 'balance-sheet', label: 'Balance Sheet', icon: BarChart3 },
  { id: 'cash-flow', label: 'Cash Flow', icon: Wallet },
  { id: 'trial-balance', label: 'Trial Balance', icon: ArrowUpDown },
  { id: 'comparison', label: 'Comparison', icon: GitCompareArrows },
  { id: 'kpis', label: 'KPIs', icon: TrendingUp },
];

const generateFinancialYears = () => {
  const currentYear = new Date().getFullYear();
  const years = [];
  for (let i = 0; i < 5; i++) {
    const year = currentYear - i;
    years.push({
      label: `FY${year}`,
      start: `${year - 1}-07-01`,
      end: `${year}-06-30`,
    });
  }
  return years;
};

export function ReportsDashboard() {
  const [activeTab, setActiveTab] = useState<ReportTab>('pnl');
  const [accounts, setAccounts] = useState<Account[]>([]);
  const [selectedAccountId, setSelectedAccountId] = useState<string>('');
  const [selectedFY, setSelectedFY] = useState(0); // index into financialYears

  const financialYears = generateFinancialYears();
  const fy = financialYears[selectedFY];

  const [customStart, setCustomStart] = useState(fy.start);
  const [customEnd, setCustomEnd] = useState(fy.end);

  useEffect(() => {
    api.fetchAccounts().then(setAccounts).catch(console.error);
  }, []);

  // Sync custom dates with FY selection
  useEffect(() => {
    setCustomStart(fy.start);
    setCustomEnd(fy.end);
  }, [selectedFY]);

  // For single-date reports (balance sheet, trial balance): use end date
  const asAtDate = customEnd;
  // For KPI: use FY label
  const kpiPeriod = fy.label;

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gradient-gold">Financial Reports</h2>
          <p className="text-sm text-muted mt-1">
            Comprehensive financial statements and KPI tracking
          </p>
        </div>
      </div>

      {/* Controls Row */}
      <div className="neu-raised rounded-2xl p-4">
        <div className="flex flex-wrap items-center gap-4">
          {/* Financial Year Selector */}
          <div>
            <label htmlFor="repor-f1" className="block text-[10px] text-muted font-bold uppercase tracking-wider mb-1">
              Financial Year
            </label>
            <select id="repor-f1"
              value={selectedFY}
              onChange={(e) => setSelectedFY(Number(e.target.value))}
              className="neu-inset rounded-xl px-3 py-2 text-sm text-primary bg-transparent outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            >
              {financialYears.map((y, i) => (
                <option key={y.label} value={i}>
                  {y.label}
                </option>
              ))}
            </select>
          </div>

          {/* Custom Date Range */}
          <div>
            <label htmlFor="repor-f2" className="block text-[10px] text-muted font-bold uppercase tracking-wider mb-1">
              Period Start
            </label>
            <input id="repor-f2"
              type="date"
              value={customStart}
              onChange={(e) => setCustomStart(e.target.value)}
              className="neu-inset rounded-xl px-3 py-2 text-sm text-primary bg-transparent outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            />
          </div>
          <div>
            <label htmlFor="repor-f3" className="block text-[10px] text-muted font-bold uppercase tracking-wider mb-1">
              Period End
            </label>
            <input id="repor-f3"
              type="date"
              value={customEnd}
              onChange={(e) => setCustomEnd(e.target.value)}
              className="neu-inset rounded-xl px-3 py-2 text-sm text-primary bg-transparent outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            />
          </div>

          {/* Account Filter */}
          <div>
            <label htmlFor="repor-f4" className="block text-[10px] text-muted font-bold uppercase tracking-wider mb-1">
              Account
            </label>
            <select id="repor-f4"
              value={selectedAccountId}
              onChange={(e) => setSelectedAccountId(e.target.value)}
              className="neu-inset rounded-xl px-3 py-2 text-sm text-primary bg-transparent outline-none focus:ring-1 focus:ring-[#FFCC00]/30"
            >
              <option value="">All Accounts</option>
              {accounts.map((acc) => (
                <option key={acc.id} value={acc.id}>
                  {acc.accountName}
                </option>
              ))}
            </select>
          </div>
        </div>
      </div>

      {/* Report Type Tabs */}
      <div className="flex items-center gap-1 overflow-x-auto pb-1">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            type="button"
            onClick={() => setActiveTab(tab.id)}
            className={cn(
              'flex items-center gap-2 px-4 py-2.5 rounded-xl text-sm font-bold transition-all duration-300 whitespace-nowrap',
              activeTab === tab.id
                ? 'bg-cba-gold text-base shadow-[0_0_20px_rgba(255,204,0,0.2)]'
                : 'neu-raised text-secondary hover:text-zinc-100 hover:bg-overlay',
            )}
          >
            <tab.icon className="w-4 h-4" />
            <span>{tab.label}</span>
          </button>
        ))}
      </div>

      {/* Report Content */}
      <div className="animate-in fade-in duration-300">
        {activeTab === 'pnl' && (
          <ProfitAndLoss
            periodStart={customStart}
            periodEnd={customEnd}
            accountId={selectedAccountId || undefined}
          />
        )}
        {activeTab === 'balance-sheet' && <BalanceSheet asAtDate={asAtDate} />}
        {activeTab === 'cash-flow' && <CashFlow periodStart={customStart} periodEnd={customEnd} />}
        {activeTab === 'trial-balance' && <TrialBalance asAtDate={asAtDate} />}
        {activeTab === 'comparison' && <PeriodComparison />}
        {activeTab === 'kpis' && <KPIDashboard period={kpiPeriod} />}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { Check, X, Zap } from 'lucide-react';
import { cn } from '@/lib/utils';

interface PlanComparisonProps {
  currentPlan?: string;
  selectedPlan?: string;
  onSelectPlan?: (planId: string) => void;
  isOnboarding?: boolean;
}

interface Plan {
  id: string;
  name: string;
  monthlyPrice: number;
  annualPrice: number;
  description: string;
  limits: {
    members: number;
    accounts: number;
    transactionsPerMonth: number;
    aiQueries: number;
    storageMB: number;
  };
  features: string[];
  missingFeatures: string[];
}

const PLANS: Plan[] = [
  {
    id: 'starter',
    name: 'Starter',
    monthlyPrice: 0,
    annualPrice: 0,
    description: 'For getting started',
    limits: { members: 1, accounts: 2, transactionsPerMonth: 100, aiQueries: 10, storageMB: 50 },
    features: ['Basic transaction parsing', 'GST classification', 'BAS generation', 'Single user'],
    missingFeatures: [
      'Multi-account',
      'AI insights',
      'Cognee knowledge graph',
      'Team collaboration',
      'Priority support',
    ],
  },
  {
    id: 'professional',
    name: 'Professional',
    monthlyPrice: 29,
    annualPrice: 24,
    description: 'For sole traders',
    limits: { members: 3, accounts: 5, transactionsPerMonth: 1000, aiQueries: 100, storageMB: 500 },
    features: [
      'Everything in Starter',
      'Multi-account support',
      'AI categorization',
      'Tax reports',
      'Transfer detection',
    ],
    missingFeatures: ['Cognee knowledge graph', 'Team collaboration', 'Priority support'],
  },
  {
    id: 'business',
    name: 'Business',
    monthlyPrice: 79,
    annualPrice: 66,
    description: 'For growing teams',
    limits: {
      members: 10,
      accounts: 20,
      transactionsPerMonth: 10000,
      aiQueries: 500,
      storageMB: 2000,
    },
    features: [
      'Everything in Professional',
      'Cognee knowledge graph',
      'Team collaboration',
      'Custom dashboards',
      'Anomaly detection',
    ],
    missingFeatures: ['Priority support'],
  },
  {
    id: 'enterprise',
    name: 'Enterprise',
    monthlyPrice: 199,
    annualPrice: 166,
    description: 'For large organisations',
    limits: { members: -1, accounts: -1, transactionsPerMonth: -1, aiQueries: -1, storageMB: -1 },
    features: [
      'Everything in Business',
      'Unlimited everything',
      'Priority support',
      'Custom integrations',
      'Dedicated account manager',
    ],
    missingFeatures: [],
  },
];

export function PlanComparison({
  currentPlan = '',
  selectedPlan,
  onSelectPlan,
  isOnboarding,
}: PlanComparisonProps) {
  const [annual, setAnnual] = useState(true);

  const activePlan = selectedPlan ?? currentPlan;

  const formatLimit = (val: number) => (val === -1 ? 'Unlimited' : val.toLocaleString());

  return (
    <div className="space-y-5">
      {/* Billing Toggle */}
      <div className="flex items-center justify-center gap-3">
        <span className={cn('text-sm font-bold', !annual ? 'text-primary' : 'text-muted')}>
          Monthly
        </span>
        <button
          type="button"
          onClick={() => setAnnual(!annual)}
          className={cn(
            'relative w-12 h-6 rounded-full transition-colors',
            annual ? 'bg-cba-gold' : 'bg-zinc-700',
          )}
        >
          <div
            className={cn(
              'absolute top-0.5 w-5 h-5 rounded-full bg-base transition-transform',
              annual ? 'translate-x-6' : 'translate-x-0.5',
            )}
          />
        </button>
        <span className={cn('text-sm font-bold', annual ? 'text-primary' : 'text-muted')}>
          Annual
        </span>
        {annual && (
          <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-emerald-500/10 text-emerald-400 uppercase tracking-wider">
            Save 17%
          </span>
        )}
      </div>

      {/* Plan Cards */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {PLANS.map((plan) => {
          const isCurrent = plan.id === currentPlan;
          const isSelected = plan.id === activePlan;
          const price = annual ? plan.annualPrice : plan.monthlyPrice;

          return (
            <div
              key={plan.id}
              className={cn(
                'neu-raised rounded-2xl border p-5 flex flex-col transition-all',
                isSelected
                  ? 'border-cba-gold/50 shadow-[0_0_24px_rgba(255,204,0,0.1)]'
                  : 'border-border/50 hover:border-border',
              )}
            >
              {isCurrent && (
                <span className="text-[10px] font-black px-2 py-0.5 rounded-full bg-cba-gold/10 text-cba-gold uppercase tracking-wider self-start mb-2">
                  Current Plan
                </span>
              )}

              <h4
                className={cn('text-lg font-bold', isSelected ? 'text-cba-gold' : 'text-primary')}
              >
                {plan.name}
              </h4>
              <p className="text-xs text-muted mb-3">{plan.description}</p>

              <div className="mb-4">
                <span className="text-3xl font-black text-zinc-100">
                  {price === 0 ? 'Free' : `$${price}`}
                </span>
                {price > 0 && <span className="text-sm text-muted">/mo</span>}
              </div>

              {/* Limits */}
              <div className="neu-inset rounded-xl p-3 mb-4 space-y-1.5 text-xs">
                <div className="flex justify-between text-secondary">
                  <span>Members</span>
                  <span className="font-bold text-primary">
                    {formatLimit(plan.limits.members)}
                  </span>
                </div>
                <div className="flex justify-between text-secondary">
                  <span>Accounts</span>
                  <span className="font-bold text-primary">
                    {formatLimit(plan.limits.accounts)}
                  </span>
                </div>
                <div className="flex justify-between text-secondary">
                  <span>Transactions/mo</span>
                  <span className="font-bold text-primary">
                    {formatLimit(plan.limits.transactionsPerMonth)}
                  </span>
                </div>
                <div className="flex justify-between text-secondary">
                  <span>AI Queries</span>
                  <span className="font-bold text-primary">
                    {formatLimit(plan.limits.aiQueries)}
                  </span>
                </div>
                <div className="flex justify-between text-secondary">
                  <span>Storage</span>
                  <span className="font-bold text-primary">
                    {plan.limits.storageMB === -1 ? 'Unlimited' : `${plan.limits.storageMB} MB`}
                  </span>
                </div>
              </div>

              {/* Features */}
              <div className="flex-1 space-y-1.5 mb-4">
                {plan.features.map((f) => (
                  <div key={f} className="flex items-start gap-2 text-xs">
                    <Check className="w-3.5 h-3.5 text-emerald-400 shrink-0 mt-0.5" />
                    <span className="text-primary">{f}</span>
                  </div>
                ))}
                {plan.missingFeatures.map((f) => (
                  <div key={f} className="flex items-start gap-2 text-xs">
                    <X className="w-3.5 h-3.5 text-zinc-600 shrink-0 mt-0.5" />
                    <span className="text-zinc-600">{f}</span>
                  </div>
                ))}
              </div>

              {/* CTA */}
              {onSelectPlan ? (
                <button
                  type="button"
                  onClick={() => onSelectPlan(plan.id)}
                  className={cn(
                    'w-full flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-bold transition-colors',
                    isSelected
                      ? 'bg-cba-gold text-base'
                      : 'border border-border text-secondary hover:text-primary hover:border-border',
                  )}
                >
                  {isSelected ? (
                    <>
                      <Check className="w-4 h-4" /> Selected
                    </>
                  ) : (
                    <>
                      <Zap className="w-4 h-4" /> Select
                    </>
                  )}
                </button>
              ) : (
                <button
                  type="button"
                  disabled={isCurrent}
                  className={cn(
                    'w-full flex items-center justify-center gap-2 py-2.5 rounded-xl text-sm font-bold transition-colors',
                    isCurrent
                      ? 'bg-zinc-800 text-muted cursor-not-allowed'
                      : 'bg-cba-gold text-base hover:bg-[#FFD633]',
                  )}
                >
                  {isCurrent ? 'Current' : 'Upgrade'}
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, Building, Landmark, AlertTriangle } from 'lucide-react';
import { taxApi } from '@/api';
import type { TaxReturnResult } from '@/api';
import { TaxReturnSummaryCard } from './TaxReturnSummaryCard';

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const formatPercent = (value: number) => `${(value * 100).toFixed(1)}%`;

export function CompanyReturn({ year }: { year: string }) {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<TaxReturnResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    taxApi
      .fetchCompanyReturn(year)
      .then(setData)
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to load'))
      .finally(() => setLoading(false));
  }, [year]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        <span className="ml-2 text-secondary">Calculating company return...</span>
      </div>
    );
  }

  if (error) {
    return (
      <Card className="border-red-500/20">
        <CardContent className="pt-6">
          <p className="text-red-400">{error}</p>
        </CardContent>
      </Card>
    );
  }

  if (!data) return null;

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <TaxReturnSummaryCard
          title="Revenue"
          value={formatCurrency(data.grossIncomeCents)}
          icon={Building}
          variant="positive"
        />
        <TaxReturnSummaryCard
          title="Expenses"
          value={`-${formatCurrency(data.totalDeductionsCents)}`}
        />
        <TaxReturnSummaryCard
          title="Taxable Income"
          value={formatCurrency(data.taxableIncomeCents)}
          icon={Landmark}
        />
        <TaxReturnSummaryCard
          title="Company Tax (25%)"
          value={formatCurrency(data.netTaxPayableCents)}
          subtitle={`Effective: ${formatPercent(data.effectiveRate)}`}
          variant="negative"
        />
      </div>

      {/* Revenue & Expense Breakdown */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle className="text-gradient-gold">Company P&L</CardTitle>
          <CardDescription>Company Tax Return — FY {year} (Base Rate Entity 25%)</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {Object.entries(data.breakdown).map(([key, value]) => (
              <div
                key={key}
                className="flex justify-between items-center py-2 border-b border-border/50 last:border-0"
              >
                <span className="text-secondary capitalize">{key.replace(/_/g, ' ')}</span>
                <span
                  className={`font-medium ${(value as number) >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                >
                  {formatCurrency(Math.abs(value as number))}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Franking Credits Info */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle>Franking Credits</CardTitle>
          <CardDescription>
            Tax paid generates franking credits for shareholder dividends
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex justify-between">
              <span className="text-secondary">Tax Paid</span>
              <span className="font-medium">{formatCurrency(data.netTaxPayableCents)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-secondary">Franking Credits Generated</span>
              <span className="font-medium text-emerald-400">
                {formatCurrency(data.netTaxPayableCents)}
              </span>
            </div>
            <p className="text-xs text-muted pt-2">
              Franking credits can be distributed to shareholders with dividends, reducing their
              personal tax liability.
            </p>
          </div>
        </CardContent>
      </Card>

      {data.warnings.length > 0 && (
        <Card className="border-amber-500/20 neu-raised">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-amber-400">
              <AlertTriangle className="w-5 h-5" /> Warnings
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2">
              {data.warnings.map((w: string, i: number) => (
                <li key={i} className="flex items-start gap-2 text-sm text-secondary">
                  <Badge
                    variant="outline"
                    className="shrink-0 mt-0.5 border-amber-500/30 text-amber-400"
                  >
                    !
                  </Badge>
                  {w}
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, User, Briefcase, Heart, AlertTriangle } from 'lucide-react';
import { taxApi } from '@/api';
import type { TaxReturnResult } from '@/api';
import { TaxReturnSummaryCard } from './TaxReturnSummaryCard';

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const formatPercent = (value: number) => `${(value * 100).toFixed(1)}%`;

export function PersonalReturn({ year }: { year: string }) {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<TaxReturnResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    taxApi
      .fetchPersonalReturn(year)
      .then(setData)
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to load'))
      .finally(() => setLoading(false));
  }, [year]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        <span className="ml-2 text-secondary">Calculating personal return...</span>
      </div>
    );
  }

  if (error) {
    return (
      <Card className="border-red-500/20">
        <CardContent className="pt-6">
          <p className="text-red-400">{error}</p>
        </CardContent>
      </Card>
    );
  }

  if (!data) return null;

  const refundOrOwing = data.netTaxPayableCents;
  const isRefund = refundOrOwing < 0;

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <TaxReturnSummaryCard
          title="Salary & Wages"
          value={formatCurrency(data.grossIncomeCents)}
          icon={Briefcase}
          variant="positive"
        />
        <TaxReturnSummaryCard
          title="Deductions"
          value={`-${formatCurrency(data.totalDeductionsCents)}`}
          icon={User}
        />
        <TaxReturnSummaryCard
          title="Medicare Levy"
          value={formatCurrency(data.medicareLevyCents)}
          icon={Heart}
          variant="warning"
        />
        <TaxReturnSummaryCard
          title={isRefund ? 'Estimated Refund' : 'Tax Payable'}
          value={formatCurrency(Math.abs(refundOrOwing))}
          subtitle={`Effective rate: ${formatPercent(data.effectiveRate)}`}
          variant={isRefund ? 'positive' : 'negative'}
        />
      </div>

      {/* Income & Deductions Breakdown */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle className="text-gradient-gold">Income & Deductions</CardTitle>
          <CardDescription>Personal Tax Return — FY {year}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {Object.entries(data.breakdown).map(([key, value]) => (
              <div
                key={key}
                className="flex justify-between items-center py-2 border-b border-border/50 last:border-0"
              >
                <span className="text-secondary capitalize">{key.replace(/_/g, ' ')}</span>
                <span
                  className={`font-medium ${(value as number) >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                >
                  {formatCurrency(Math.abs(value as number))}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Tax Calculation */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle>Tax Payable / Refund</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex justify-between">
              <span className="text-secondary">Income Tax on Taxable Income</span>
              <span className="font-medium">{formatCurrency(data.incomeTaxCents)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-secondary">Medicare Levy</span>
              <span className="font-medium">{formatCurrency(data.medicareLevyCents)}</span>
            </div>
            {data.taxOffsetsCents > 0 && (
              <div className="flex justify-between text-emerald-400">
                <span>Tax Offsets (LITO)</span>
                <span className="font-medium">-{formatCurrency(data.taxOffsetsCents)}</span>
              </div>
            )}
            <div className="border-t border-border pt-3 flex justify-between font-bold text-lg">
              <span>{isRefund ? 'Estimated Refund' : 'Amount Owing'}</span>
              <span className={isRefund ? 'text-emerald-400' : 'text-red-400'}>
                {formatCurrency(Math.abs(refundOrOwing))}
              </span>
            </div>
          </div>
        </CardContent>
      </Card>

      {data.warnings.length > 0 && (
        <Card className="border-amber-500/20 neu-raised">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-amber-400">
              <AlertTriangle className="w-5 h-5" />
              Notices
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2">
              {data.warnings.map((w: string, i: number) => (
                <li key={i} className="flex items-start gap-2 text-sm text-secondary">
                  <Badge
                    variant="outline"
                    className="shrink-0 mt-0.5 border-amber-500/30 text-amber-400"
                  >
                    !
                  </Badge>
                  {w}
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

