                className="flex justify-between items-center py-2 border-b border-border/50 last:border-0"
              >
                <span className="text-secondary capitalize">{key.replace(/_/g, ' ')}</span>
                <span
                  className={`font-medium ${(value as number) >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                >
                  {formatCurrency(Math.abs(value as number))}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Tax Calculation */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle>Tax Calculation</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex justify-between">
              <span className="text-secondary">Income Tax</span>
              <span className="font-medium">{formatCurrency(data.incomeTaxCents)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-secondary">Medicare Levy</span>
              <span className="font-medium">{formatCurrency(data.medicareLevyCents)}</span>
            </div>
            {data.taxOffsetsCents > 0 && (
              <div className="flex justify-between text-emerald-400">
                <span>Tax Offsets (SBITO + LITO)</span>
                <span className="font-medium">-{formatCurrency(data.taxOffsetsCents)}</span>
              </div>
            )}
            <div className="border-t border-border pt-3 flex justify-between font-bold text-lg">
              <span>Net Tax Payable</span>
              <span className={data.netTaxPayableCents > 0 ? 'text-red-400' : 'text-emerald-400'}>
                {formatCurrency(data.netTaxPayableCents)}
              </span>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Warnings */}
      {data.warnings.length > 0 && (
        <Card className="border-amber-500/20 neu-raised">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-amber-400">
              <AlertTriangle className="w-5 h-5" />
              Warnings
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2">
              {data.warnings.map((w: string, i: number) => (
                <li key={i} className="flex items-start gap-2 text-sm text-secondary">
                  <Badge
                    variant="outline"
                    className="shrink-0 mt-0.5 border-amber-500/30 text-amber-400"
                  >
                    !
                  </Badge>
                  {w}
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { taxApi } from '@/api';
import type {
  TaxCalculationResult,
  TaxSummary,
  Deduction,
  CGTAsset,
  CGTEvent,
  DepreciableAsset,
} from '@/api';
import { getCurrentTaxYear } from '../helpers.js';

export function useTaxDashboard() {
  const [loading, setLoading] = useState(false);
  const [selectedYear, setSelectedYear] = useState(getCurrentTaxYear());
  const [grossIncome, setGrossIncome] = useState('');
  const [entityType, setEntityType] = useState<'individual' | 'company' | 'trust' | 'super_fund'>(
    'individual',
  );
  const [hasPrivateHealth, setHasPrivateHealth] = useState(false);
  const [taxResult, setTaxResult] = useState<TaxCalculationResult | null>(null);
  const [taxSummary, setTaxSummary] = useState<TaxSummary | null>(null);
  const [deductions, setDeductions] = useState<Deduction[]>([]);
  const [cgtAssets, setCgtAssets] = useState<CGTAsset[]>([]);
  const [cgtEvents, setCgtEvents] = useState<CGTEvent[]>([]);
  const [depreciableAssets, setDepreciableAssets] = useState<DepreciableAsset[]>([]);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    loadTaxData();
  }, [selectedYear]);

  const loadTaxData = async () => {
    setLoading(true);
    try {
      const [summary, deductionsList, assets, events, depreciation] = await Promise.all([
        taxApi.fetchTaxSummary(selectedYear),
        taxApi.fetchDeductions(selectedYear),
        taxApi.fetchCGTAssets(),
        taxApi.fetchCGTEvents(selectedYear),
        taxApi.fetchDepreciableAssets(),
      ]);
      setTaxSummary(summary);
      setDeductions(deductionsList);
      setCgtAssets(assets);
      setCgtEvents(events);
      setDepreciableAssets(depreciation);

      if (summary && summary.grossIncomeCents > 0) {
        const incomeDollars = (summary.grossIncomeCents / 100).toFixed(0);
        setGrossIncome(incomeDollars);
        try {
          const result = await taxApi.calculateTax(
            selectedYear,
            summary.grossIncomeCents,
            entityType,
            hasPrivateHealth,
          );
          setTaxResult(result);
        } catch (calcErr) {
          console.error('Auto tax calc failed:', calcErr);
        }
      }
    } catch (err) {
      console.error('Failed to load tax data:', err);
    } finally {
      setLoading(false);
    }
  };

  const calculateTax = async () => {
    if (!grossIncome) return;
    setLoading(true);
    setError(null);
    try {
      const incomeInCents = Math.round(parseFloat(grossIncome) * 100);
      const result = await taxApi.calculateTax(
        selectedYear,
        incomeInCents,
        entityType,
        hasPrivateHealth,
      );
      setTaxResult(result);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to calculate tax');
    } finally {
      setLoading(false);
    }
  };

  const totalDeductions = deductions.reduce((sum, d) => sum + d.amountCents, 0);
  const totalCGT = cgtEvents.reduce(
    (sum, e) => sum + e.capitalGainNetCents - e.capitalLossCents,
    0,
  );

  return {
    loading,
    selectedYear,
    setSelectedYear,
    grossIncome,
    setGrossIncome,
    entityType,
    setEntityType,
    hasPrivateHealth,
    setHasPrivateHealth,
    taxResult,
    taxSummary,
    deductions,
    cgtAssets,
    cgtEvents,
    depreciableAssets,
    error,
    calculateTax,
    totalDeductions,
    totalCGT,
  };
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Loader2, Lightbulb, Check, X, Sparkles, ExternalLink } from 'lucide-react';
import { taxApi } from '@/api';
import type { TaxStrategyRecord } from '@/api';

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

export function TaxOptimizerPanel({ year }: { year: string }) {
  const [loading, setLoading] = useState(false);
  const [generating, setGenerating] = useState(false);
  const [strategies, setStrategies] = useState<TaxStrategyRecord[]>([]);
  const [error, setError] = useState<string | null>(null);

  const loadStrategies = () => {
    setLoading(true);
    taxApi
      .fetchStrategies(year)
      .then(setStrategies)
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to load'))
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    loadStrategies();
  }, [year]);

  const handleGenerate = async () => {
    setGenerating(true);
    setError(null);
    try {
      await taxApi.generateStrategies(year);
      loadStrategies();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to generate strategies');
    } finally {
      setGenerating(false);
    }
  };

  const handleUpdateStatus = async (id: string, status: 'suggested' | 'applied' | 'dismissed') => {
    try {
      await taxApi.updateStrategyStatus(id, status);
      setStrategies((prev) => prev.map((s) => (s.id === id ? { ...s, status } : s)));
    } catch (err) {
      console.error('Failed to update strategy:', err);
    }
  };

  const suggested = strategies.filter((s) => s.status === 'suggested');
  const applied = strategies.filter((s) => s.status === 'applied');
  const dismissed = strategies.filter((s) => s.status === 'dismissed');
  const totalPotentialSavings = suggested.reduce((sum, s) => sum + s.estimatedSaving, 0);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        <span className="ml-2 text-secondary">Loading strategies...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header with generate button */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-bold">Tax Optimization Strategies</h3>
          {totalPotentialSavings > 0 && (
            <p className="text-sm text-emerald-400">
              Potential savings: {formatCurrency(totalPotentialSavings)}
            </p>
          )}
        </div>
        <Button
          onClick={handleGenerate}
          disabled={generating}
          className="bg-cba-gold text-base hover:bg-[#e6b800]"
        >
          {generating ? (
            <Loader2 className="w-4 h-4 mr-2 animate-spin" />
          ) : (
            <Sparkles className="w-4 h-4 mr-2" />
          )}
          {generating ? 'Analyzing...' : 'Generate Strategies'}
        </Button>
      </div>

      {error && (
        <Card className="border-red-500/20">
          <CardContent className="pt-6">
            <p className="text-red-400">{error}</p>
          </CardContent>
        </Card>
      )}

      {/* Suggested Strategies */}
      {suggested.length > 0 && (
        <div className="space-y-4">
          <h4 className="text-sm font-bold text-secondary uppercase tracking-wider">Suggested</h4>
          {suggested.map((s) => (
            <Card
              key={s.id}
              className="neu-raised border-cba-gold/10 hover:border-cba-gold/30 transition-colors"
            >
              <CardHeader className="pb-3">
                <div className="flex items-start justify-between">
                  <div className="flex items-center gap-2">
                    <Lightbulb className="w-5 h-5 text-cba-gold" />
                    <CardTitle className="text-base">{s.strategyName}</CardTitle>
                  </div>
                  <Badge className="bg-emerald-500/10 text-emerald-400 border-emerald-500/20">
                    Save {formatCurrency(s.estimatedSaving)}
                  </Badge>
                </div>
              </CardHeader>
              <CardContent>
                <p className="text-sm text-secondary mb-3">{s.description}</p>
                <div className="flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <Badge variant="outline" className="text-xs">
                      Confidence: {Math.round(s.confidence * 100)}%
                    </Badge>
                    {s.atoRulingRef && (
                      <Badge variant="outline" className="text-xs flex items-center gap-1">
                        <ExternalLink className="w-3 h-3" /> {s.atoRulingRef}
                      </Badge>
                    )}
                  </div>
                  <div className="flex gap-2">
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={() => handleUpdateStatus(s.id, 'dismissed')}
                      className="text-secondary hover:text-red-400"
                    >
                      <X className="w-4 h-4 mr-1" /> Dismiss
                    </Button>
                    <Button
                      size="sm"
                      onClick={() => handleUpdateStatus(s.id, 'applied')}
                      className="bg-emerald-600 hover:bg-emerald-700 text-primary"
                    >
                      <Check className="w-4 h-4 mr-1" /> Apply
                    </Button>
                  </div>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Applied Strategies */}
      {applied.length > 0 && (
        <div className="space-y-4">
          <h4 className="text-sm font-bold text-secondary uppercase tracking-wider">Applied</h4>
          {applied.map((s) => (
            <Card key={s.id} className="neu-raised border-emerald-500/20 opacity-80">
              <CardContent className="pt-6 flex items-center justify-between">
                <div className="flex items-center gap-3">
                  <Check className="w-5 h-5 text-emerald-400" />
                  <div>
                    <p className="font-medium">{s.strategyName}</p>
                    <p className="text-sm text-muted">
                      Saving: {formatCurrency(s.estimatedSaving)}
                    </p>
                  </div>
                </div>
                <Badge className="bg-emerald-500/10 text-emerald-400">Applied</Badge>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* Dismissed */}
      {dismissed.length > 0 && (
        <details className="group">
          <summary className="text-sm font-bold text-muted uppercase tracking-wider cursor-pointer hover:text-secondary">
            Dismissed ({dismissed.length})
          </summary>
          <div className="mt-3 space-y-2">
            {dismissed.map((s) => (
              <Card key={s.id} className="neu-raised opacity-50">
                <CardContent className="pt-4 pb-4 flex items-center justify-between">
                  <span className="text-sm text-muted line-through">{s.strategyName}</span>
                  <Button
                    size="sm"
                    variant="ghost"
                    onClick={() => handleUpdateStatus(s.id, 'suggested')}
                  >
                    Restore
                  </Button>
                </CardContent>
              </Card>
            ))}
          </div>
        </details>
      )}

      {strategies.length === 0 && !generating && (
        <Card className="neu-raised border-border/50">
          <CardContent className="pt-6 text-center">
            <Lightbulb className="w-12 h-12 text-zinc-600 mx-auto mb-3" />
            <p className="text-secondary">No strategies generated yet.</p>
            <p className="text-sm text-muted mt-1">
              Click "Generate Strategies" to analyze your tax position and find savings.
            </p>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Loader2, Users, AlertTriangle, ShieldAlert } from 'lucide-react';
import { taxApi } from '@/api';
import type { TaxReturnResult } from '@/api';
import { TaxReturnSummaryCard } from './TaxReturnSummaryCard';

const formatCurrency = (cents: number) =>
  new Intl.NumberFormat('en-AU', { style: 'currency', currency: 'AUD' }).format(cents / 100);

const formatPercent = (value: number) => `${(value * 100).toFixed(1)}%`;

export function TrustReturn({ year }: { year: string }) {
  const [loading, setLoading] = useState(false);
  const [data, setData] = useState<TaxReturnResult | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    setLoading(true);
    setError(null);
    taxApi
      .fetchTrustReturn(year)
      .then(setData)
      .catch((err) => setError(err instanceof Error ? err.message : 'Failed to load'))
      .finally(() => setLoading(false));
  }, [year]);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-12">
        <Loader2 className="w-6 h-6 animate-spin text-cba-gold" />
        <span className="ml-2 text-secondary">Calculating trust return...</span>
      </div>
    );
  }

  if (error) {
    return (
      <Card className="border-red-500/20">
        <CardContent className="pt-6">
          <p className="text-red-400">{error}</p>
        </CardContent>
      </Card>
    );
  }

  if (!data) return null;

  const hasSection100AWarning = data.warnings.some((w: string) =>
    w.toLowerCase().includes('section 100a'),
  );

  return (
    <div className="space-y-6">
      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-4">
        <TaxReturnSummaryCard
          title="Trust Income"
          value={formatCurrency(data.grossIncomeCents)}
          icon={Users}
          variant="positive"
        />
        <TaxReturnSummaryCard
          title="Trust Expenses"
          value={`-${formatCurrency(data.totalDeductionsCents)}`}
        />
        <TaxReturnSummaryCard
          title="Net Income"
          value={formatCurrency(data.taxableIncomeCents)}
          subtitle="For distribution"
        />
        <TaxReturnSummaryCard
          title="Tax on Undistributed"
          value={formatCurrency(data.netTaxPayableCents)}
          subtitle={`Rate: ${formatPercent(data.effectiveRate)}`}
          variant={data.netTaxPayableCents > 0 ? 'negative' : 'positive'}
        />
      </div>

      {/* Section 100A Warning Banner */}
      {hasSection100AWarning && (
        <Card className="border-red-500/30 bg-red-500/5 neu-raised">
          <CardContent className="pt-6 flex items-start gap-3">
            <ShieldAlert className="w-6 h-6 text-red-400 shrink-0 mt-0.5" />
            <div>
              <h4 className="font-bold text-red-400">Section 100A Risk</h4>
              <p className="text-sm text-secondary mt-1">
                Trust distributions that involve reimbursement agreements may be assessed at the top
                marginal rate under Section 100A ITAA 1936. Review distribution arrangements with
                your tax adviser.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Trust P&L */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle className="text-gradient-gold">Trust Income & Expenses</CardTitle>
          <CardDescription>Trust Tax Return — FY {year}</CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            {Object.entries(data.breakdown).map(([key, value]) => (
              <div
                key={key}
                className="flex justify-between items-center py-2 border-b border-border/50 last:border-0"
              >
                <span className="text-secondary capitalize">{key.replace(/_/g, ' ')}</span>
                <span
                  className={`font-medium ${(value as number) >= 0 ? 'text-emerald-400' : 'text-red-400'}`}
                >
                  {formatCurrency(Math.abs(value as number))}
                </span>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Distribution Info */}
      <Card className="neu-raised border-border/50">
        <CardHeader>
          <CardTitle>Distribution Summary</CardTitle>
          <CardDescription>
            Net trust income must be distributed to beneficiaries by June 30
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div className="flex justify-between">
              <span className="text-secondary">Distributable Amount</span>
              <span className="font-medium">{formatCurrency(data.taxableIncomeCents)}</span>
            </div>
            <p className="text-xs text-muted pt-2">
              Undistributed income is taxed at the top marginal rate (45% + 2% Medicare). Ensure a
              valid resolution is made before year-end.
            </p>
          </div>
        </CardContent>
      </Card>

      {data.warnings.length > 0 && (
        <Card className="border-amber-500/20 neu-raised">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-amber-400">
              <AlertTriangle className="w-5 h-5" /> Warnings
            </CardTitle>
          </CardHeader>
          <CardContent>
            <ul className="space-y-2">
              {data.warnings.map((w: string, i: number) => (
                <li key={i} className="flex items-start gap-2 text-sm text-secondary">
                  <Badge
                    variant="outline"
                    className="shrink-0 mt-0.5 border-amber-500/30 text-amber-400"
                  >
                    !
                  </Badge>
                  {w}
                </li>
              ))}
            </ul>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { useState, useRef, useEffect, useCallback } from 'react';
import { ChevronDown } from 'lucide-react';
import { cn } from '@/lib/utils';
import { CATEGORY_NAMES_BY_TYPE } from '../constants/categories';
import { getCategoryColor } from '../constants/categoryColors';

interface CategorySelectProps {
  value: string;
  onChange: (value: string) => void;
  includeAll?: boolean;
  className?: string;
  'aria-label'?: string;
  size?: 'sm' | 'md' | 'lg';
}

const GROUP_LABELS: Record<string, string> = {
  revenue: 'Revenue',
  cogs: 'Cost of Goods Sold',
  expense: 'Expenses',
  system: 'System',
};

const GROUP_ORDER = ['revenue', 'cogs', 'expense', 'system'];

export function CategorySelect({
  value,
  onChange,
  includeAll = false,
  className,
  'aria-label': ariaLabel = 'Select category',
  size = 'md',
}: CategorySelectProps) {
  const [open, setOpen] = useState(false);
  const [highlightIndex, setHighlightIndex] = useState(-1);
  const containerRef = useRef<HTMLDivElement>(null);
  const listRef = useRef<HTMLUListElement>(null);

  const sizeClasses = {
    sm: 'py-2 px-3 text-xs',
    md: 'py-3 px-4 text-sm',
    lg: 'py-4 px-5 text-base',
  };

  // Build flat list of all options for keyboard nav
  const allOptions: string[] = [];
  if (includeAll) allOptions.push('All');
  for (const group of GROUP_ORDER) {
    const items = CATEGORY_NAMES_BY_TYPE[group];
    if (items) allOptions.push(...items);
  }

  const selectedColor = value && value !== 'All' ? getCategoryColor(value) : null;

  // Close on click outside
  useEffect(() => {
    if (!open) return;
    const handleClick = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, [open]);

  // Scroll highlighted item into view
  useEffect(() => {
    if (highlightIndex >= 0 && listRef.current) {
      const items = listRef.current.querySelectorAll('[role="option"]');
      items[highlightIndex]?.scrollIntoView({ block: 'nearest' });
    }
  }, [highlightIndex]);

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (!open) {
        if (e.key === 'ArrowDown' || e.key === 'ArrowUp' || e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          setOpen(true);
          setHighlightIndex(allOptions.indexOf(value));
        }
        return;
      }

      switch (e.key) {
        case 'ArrowDown':
          e.preventDefault();
          setHighlightIndex((prev) => Math.min(prev + 1, allOptions.length - 1));
          break;
        case 'ArrowUp':
          e.preventDefault();
          setHighlightIndex((prev) => Math.max(prev - 1, 0));
          break;
        case 'Enter':
        case ' ':
          e.preventDefault();
          if (highlightIndex >= 0 && allOptions[highlightIndex]) {
            onChange(allOptions[highlightIndex]);
            setOpen(false);
          }
          break;
        case 'Escape':
          e.preventDefault();
          setOpen(false);
          break;
      }
    },
    [open, highlightIndex, allOptions, value, onChange],
  );

  return (
    <div ref={containerRef} className="relative">
      <button
        type="button"
        role="combobox"
        aria-label={ariaLabel}
        aria-expanded={open}
        aria-haspopup="listbox"
        aria-controls="category-listbox"
        onClick={() => setOpen(!open)}
        onKeyDown={handleKeyDown}
        className={cn(
          'w-full neu-inset rounded-xl text-cba-gold font-bold bg-transparent border-none focus-gold cursor-pointer pr-10 text-left flex items-center gap-2',
          sizeClasses[size],
          className,
        )}
      >
        {selectedColor && (
          <span className={cn('w-2 h-2 rounded-full shrink-0', selectedColor.dot)} />
        )}
        <span className="truncate">{value || 'Select...'}</span>
        <ChevronDown
          className={cn(
            'absolute right-3 top-1/2 -translate-y-1/2 h-4 w-4 text-cba-gold/50 transition-transform',
            open && 'rotate-180',
          )}
        />
      </button>

      {open && (
        <ul
          id="category-listbox"
          ref={listRef}
          role="listbox"
          aria-label={ariaLabel}
          className="absolute z-50 mt-1 w-full max-h-64 overflow-y-auto neu-raised rounded-xl border border-border bg-surface shadow-2xl scrollbar-thin animate-in fade-in zoom-in-95 duration-150"
          onKeyDown={handleKeyDown}
        >
          {includeAll && (
            <li
              role="option"
              aria-selected={value === 'All'}
              tabIndex={-1}
              className={cn(
                'px-4 py-2.5 text-xs font-bold cursor-pointer transition-colors',
                value === 'All'
                  ? 'text-cba-gold bg-cba-gold/5'
                  : 'text-primary hover:bg-overlay',
                highlightIndex === 0 && 'bg-overlay-hover',
              )}
              onClick={() => { onChange('All'); setOpen(false); }}
              onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onChange('All'); setOpen(false); } }}
            >
              All Categories
            </li>
          )}

          {GROUP_ORDER.map((group) => {
            const items = CATEGORY_NAMES_BY_TYPE[group];
            if (!items || items.length === 0) return null;
            return (
              <li key={group} role="group">
                <div className="px-4 py-1.5 text-[9px] font-black uppercase tracking-[0.2em] text-zinc-600 bg-black/30 sticky top-0">
                  {GROUP_LABELS[group]}
                </div>
                {items.map((cat) => {
                  const color = getCategoryColor(cat);
                  const flatIndex = allOptions.indexOf(cat);
                  return (
                    <div
                      key={cat}
                      role="option"
                      aria-selected={value === cat}
                      tabIndex={-1}
                      className={cn(
                        'px-4 py-2 text-xs font-bold cursor-pointer transition-colors flex items-center gap-2',
                        value === cat
                          ? 'text-cba-gold bg-cba-gold/5'
                          : 'text-primary hover:bg-overlay',
                        highlightIndex === flatIndex && 'bg-overlay-hover',
                      )}
                      onClick={() => { onChange(cat); setOpen(false); }}
                      onKeyDown={(e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); onChange(cat); setOpen(false); } }}
                    >
                      <span className={cn('w-2 h-2 rounded-full shrink-0', color.dot)} />
                      {cat}
                    </div>
                  );
                })}
              </li>
            );
          })}
        </ul>
      )}
    </div>
  );
}

