import { useEffect, useRef, useCallback, useState } from 'react';
import { X, AlertTriangle } from 'lucide-react';
import { cn } from '@/lib/utils';

interface DeleteConfirmDialogProps {
  isOpen: boolean;
  onConfirm: () => void;
  onCancel: () => void;
  title?: string;
  message?: string;
  confirmLabel?: string;
  cancelLabel?: string;
}

/**
 * DeleteConfirmDialog - Accessible modal for delete confirmation
 *
 * Features:
 * - ARIA attributes for screen readers (alertdialog role)
 * - Focus trap (Tab/Shift+Tab contained within modal)
 * - Escape key closes modal
 * - Focus restoration to trigger element
 * - Semi-transparent backdrop with blur
 * - Matches existing design system (neu-raised, cba-gold colors)
 */
export function DeleteConfirmDialog({
  isOpen,
  onConfirm,
  onCancel,
  title = 'Delete Transaction',
  message = 'Are you sure you want to delete this transaction? This action cannot be undone.',
  confirmLabel = 'Delete',
  cancelLabel = 'Cancel',
}: DeleteConfirmDialogProps) {
  const dialogRef = useRef<HTMLDivElement>(null);
  const cancelButtonRef = useRef<HTMLButtonElement>(null);
  const confirmButtonRef = useRef<HTMLButtonElement>(null);
  const previousActiveElement = useRef<HTMLElement | null>(null);

  // Get all focusable elements within the dialog
  const getFocusableElements = useCallback(() => {
    if (!dialogRef.current) return [];
    return Array.from(
      dialogRef.current.querySelectorAll<HTMLElement>(
        'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])',
      ),
    ).filter((el) => !el.hasAttribute('disabled'));
  }, []);

  // Focus trap and keyboard handling
  useEffect(() => {
    if (!isOpen) return;

    // Store the previously focused element
    previousActiveElement.current = document.activeElement as HTMLElement;

    // Focus the cancel button initially (safer default for destructive action)
    cancelButtonRef.current?.focus();

    // Lock body scroll
    const originalOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';

    const handleKeyDown = (e: KeyboardEvent) => {
      // Close on Escape
      if (e.key === 'Escape') {
        e.preventDefault();
        onCancel();
        return;
      }

      // Focus trap on Tab
      if (e.key === 'Tab') {
        const focusableElements = getFocusableElements();
        if (focusableElements.length === 0) return;

        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (!firstElement || !lastElement) return;

        if (e.shiftKey) {
          // Shift+Tab: if on first element, wrap to last
          if (document.activeElement === firstElement) {
            e.preventDefault();
            lastElement.focus();
          }
        } else {
          // Tab: if on last element, wrap to first
          if (document.activeElement === lastElement) {
            e.preventDefault();
            firstElement.focus();
          }
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);

    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = originalOverflow;
      // Restore focus to the previously focused element
      previousActiveElement.current?.focus();
    };
  }, [isOpen, onCancel, getFocusableElements]);

  // Don't render if not open
  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center">
      {/* Backdrop */}
      <div
        className="absolute inset-0 bg-black/60 backdrop-blur-sm"
        onClick={onCancel}
        aria-hidden="true"
      />

      {/* Dialog */}
      <div
        ref={dialogRef}
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="delete-dialog-title"
        aria-describedby="delete-dialog-description"
        className={cn(
          'relative neu-raised rounded-2xl p-6 max-w-md w-full mx-4',
          'border border-border',
          'animate-in zoom-in-95 fade-in duration-200',
        )}
      >
        {/* Close button */}
        <button
          type="button"
          onClick={onCancel}
          className={cn(
            'absolute top-4 right-4 p-1.5 rounded-lg',
            'text-muted hover:text-primary',
            'hover:bg-overlay transition-colors',
            'focus:outline-none focus:ring-2 focus:ring-[#FFCC00]/50',
          )}
          aria-label="Close dialog"
        >
          <X className="h-5 w-5" />
        </button>

        {/* Warning Icon */}
        <div className="flex justify-center mb-4">
          <div className="w-16 h-16 neu-inset rounded-2xl flex items-center justify-center">
            <AlertTriangle className="h-8 w-8 text-red-400" />
          </div>
        </div>

        {/* Title */}
        <h2
          id="delete-dialog-title"
          className="text-xl font-black text-center text-zinc-100 mb-2 uppercase tracking-wide"
        >
          {title}
        </h2>

        {/* Message */}
        <p
          id="delete-dialog-description"
          className="text-sm text-center text-secondary mb-6 leading-relaxed"
        >
          {message}
        </p>

        {/* Action Buttons */}
        <div className="flex gap-3">
          <button
            ref={cancelButtonRef}
            type="button"
            onClick={onCancel}
            className={cn(
              'flex-1 py-3 px-4 rounded-xl',
              'neu-raised-sm border border-border/50',
              'text-primary font-black uppercase text-xs tracking-widest',
              'hover:text-cba-gold hover:border-cba-gold/20',
              'transition-all duration-200',
              'focus:outline-none focus:ring-2 focus:ring-[#FFCC00]/50',
            )}
          >
            {cancelLabel}
          </button>
          <button
            ref={confirmButtonRef}
            type="button"
            onClick={onConfirm}
            className={cn(
              'flex-1 py-3 px-4 rounded-xl',
              'bg-red-500/10 border border-red-500/30',
              'text-red-400 font-black uppercase text-xs tracking-widest',
              'hover:bg-red-500/20 hover:border-red-500/50',
              'transition-all duration-200',
              'focus:outline-none focus:ring-2 focus:ring-red-500/50',
            )}
          >
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

/**
 * Hook for managing delete confirmation dialog state
 *
 * Usage:
 * ```tsx
 * const { isOpen, itemToDelete, openDialog, closeDialog, confirmDelete } = useDeleteConfirm();
 *
 * // When user clicks delete
 * const handleDelete = (id: string) => openDialog(id);
 *
 * // In the dialog's onConfirm
 * const handleConfirm = () => {
 *   if (itemToDelete) {
 *     deleteItem(itemToDelete);
 *   }
 *   confirmDelete();
 * };
 *
 * // Render
 * <DeleteConfirmDialog
 *   isOpen={isOpen}
 *   onConfirm={handleConfirm}
 *   onCancel={closeDialog}
 * />
 * ```
 */
export function useDeleteConfirm<T = string>() {
  const [isOpen, setIsOpen] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<T | null>(null);

  const openDialog = useCallback((item: T) => {
    setItemToDelete(item);
    setIsOpen(true);
  }, []);

  const closeDialog = useCallback(() => {
    setIsOpen(false);
    setItemToDelete(null);
  }, []);

  const confirmDelete = useCallback(() => {
    setIsOpen(false);
    // Keep itemToDelete briefly so consumer can access it in onConfirm
    setTimeout(() => setItemToDelete(null), 100);
  }, []);

  return {
    isOpen,
    itemToDelete,
    openDialog,
    closeDialog,
    confirmDelete,
  };
}

export default DeleteConfirmDialog;

/**
 * LedgerPage - Main orchestrator component for the transaction ledger
 *
 * This component composes all sub-components and coordinates all hooks
 * to provide a complete transaction management interface with:
 * - Responsive mobile/desktop layouts
 * - Filtering and sorting
 * - Inline editing
 * - Transaction splitting
 * - Delete confirmation
 * - CSV/Excel export
 * - Keyboard shortcuts (Ctrl+F for search, Escape for cancel/close)
 */
import { useState, useEffect, useRef, useCallback } from 'react';
import type { VisibilityState } from '@tanstack/react-table';
import type { Transaction, Account } from '../types/ledger';

// Hooks
import { useLedgerFilters } from '../hooks/useLedgerFilters';
import { useLedgerData } from '../hooks/useLedgerData';
import { useInlineEdit } from '../hooks/useInlineEdit';
import { useTransactionSplit } from '../hooks/useTransactionSplit';
import { useBulkSelect } from '../hooks/useBulkSelect';

// Components
import { LedgerSkeleton } from './LedgerSkeleton';
import { LedgerHeader } from './LedgerHeader';
import { LedgerFilters } from './LedgerFilters';
import { LedgerSummaryBar } from './LedgerSummaryBar';
import { LedgerTable } from './LedgerTable';
import { TransactionCardList } from './TransactionCardList';
import { LedgerFooter } from './LedgerFooter';
import { SplitTransactionModal } from './SplitTransactionModal';
import { DeleteConfirmDialog, useDeleteConfirm } from './DeleteConfirmDialog';
import { BulkActionBar } from './BulkActionBar';
import { MobileLayout } from '@/components/layout/MobileLayout';

const EMPTY_ACCOUNTS: Account[] = [];

interface LedgerPageProps {
  transactions: Transaction[];
  accounts?: Account[];
  loading?: boolean;
  onDataChange?: () => void;
  totalTransactions?: number;
  onLoadMore?: () => void;
}

export function LedgerPage({
  transactions,
  accounts = EMPTY_ACCOUNTS,
  loading = false,
  onDataChange,
  totalTransactions,
  onLoadMore,
}: LedgerPageProps) {
  // Filter hook - manages filter state, sorting, and filtered transactions
  const {
    filters,
    setFilters,
    showFilters,
    setShowFilters,
    sorting,
    setSorting,
    filteredTransactions,
    categories,
    hasActiveFilters,
    resetFilters,
  } = useLedgerFilters({ transactions });

  // Data/export hook - handles CSV/Excel export with current filters
  const { handleExport } = useLedgerData({ filters });

  // Edit hook - manages inline editing state and operations
  const {
    editingId,
    editForm,
    setEditForm,
    setEditingId,
    handleEditStart,
    handleSave,
    handleCancel,
    handleDelete: deleteTransaction,
  } = useInlineEdit({ transactions, onDataChange });

  // Split hook - manages transaction split modal state and operations
  const {
    splittingTx,
    splits,
    setSplits,
    handleSplitStart,
    handleSplitSave,
    handleSplitCancel,
    isSaving: isSplitSaving,
  } = useTransactionSplit({ onDataChange });

  // Bulk selection hook
  const {
    selectedIds,
    isSelected,
    toggle: toggleSelect,
    selectAll,
    clearSelection,
    selectedCount,
  } = useBulkSelect();

  // Column visibility state
  const [columnVisibility, setColumnVisibility] = useState<VisibilityState>({});

  // Delete confirmation dialog hook
  const {
    isOpen: isDeleteOpen,
    itemToDelete,
    openDialog: openDeleteDialog,
    closeDialog: closeDeleteDialog,
    confirmDelete,
  } = useDeleteConfirm<string>();

  // Handle delete button click - opens confirmation dialog
  const handleDeleteClick = (id: string) => {
    openDeleteDialog(id);
  };

  // Handle confirmed delete - actually deletes the transaction
  const handleConfirmDelete = async () => {
    if (itemToDelete) {
      await deleteTransaction(itemToDelete);
      confirmDelete();
    }
  };

  // Count active filters for mobile badge
  const activeFiltersCount = [
    filters.startDate,
    filters.endDate,
    filters.selectedCategory !== 'All' ? filters.selectedCategory : '',
    filters.globalFilter,
    filters.selectedAccount !== 'All' ? filters.selectedAccount : '',
    filters.minAmount,
    filters.maxAmount,
  ].filter(Boolean).length;

  // Ref for search input to enable Ctrl+F keyboard shortcut
  const searchInputRef = useRef<HTMLInputElement>(null);

  // Memoize handleCancel for use in keyboard shortcut effect
  const memoizedHandleCancel = useCallback(() => {
    handleCancel();
  }, [handleCancel]);

  // Keyboard shortcuts handler
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl+F or Cmd+F to focus search
      if ((e.ctrlKey || e.metaKey) && e.key === 'f') {
        e.preventDefault();
        searchInputRef.current?.focus();
      }

      // Escape to cancel edit or close filters
      if (e.key === 'Escape') {
        if (editingId) {
          memoizedHandleCancel();
        } else if (showFilters) {
          setShowFilters(false);
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [editingId, showFilters, memoizedHandleCancel, setShowFilters]);

  // Aria-live announcement state for screen readers
  const [announceMessage, setAnnounceMessage] = useState('');

  // Update announcement when filtered count changes
  useEffect(() => {
    setAnnounceMessage(
      `Showing ${filteredTransactions.length} of ${transactions.length} transactions`,
    );
  }, [filteredTransactions.length, transactions.length]);

  // Loading state - show skeleton
  if (loading) {
    return <LedgerSkeleton />;
  }

  return (
    <>
      {/* Screen reader announcement for filter result changes */}
      <div role="status" aria-live="polite" aria-atomic="true" className="sr-only">
        {announceMessage}
      </div>

      {/* Mobile Layout - hidden on md+ screens */}
      <MobileLayout
        title="Ledger"
        subtitle={`${filteredTransactions.length} transactions`}
        onFilterClick={() => setShowFilters(!showFilters)}
        activeFiltersCount={activeFiltersCount}
        summaryStats={<LedgerSummaryBar transactions={filteredTransactions} />}
      >
        {/* Mobile filters - expandable panel */}
        {(showFilters || hasActiveFilters) && (
          <LedgerFilters
            startDate={filters.startDate}
            endDate={filters.endDate}
            selectedCategory={filters.selectedCategory}
            minAmount={filters.minAmount?.toString() ?? ''}
            maxAmount={filters.maxAmount?.toString() ?? ''}
            selectedAccount={filters.selectedAccount}
            accounts={accounts}
            onStartDateChange={setFilters.setStartDate}
            onEndDateChange={setFilters.setEndDate}
            onCategoryChange={setFilters.setSelectedCategory}
            onMinAmountChange={setFilters.setMinAmount}
            onMaxAmountChange={setFilters.setMaxAmount}
            onAccountChange={setFilters.setSelectedAccount}
            onReset={resetFilters}
          />
        )}

        {/* Mobile transaction cards with virtualization */}
        <TransactionCardList
          transactions={filteredTransactions}
          accounts={accounts}
          onEdit={handleEditStart}
          onDelete={handleDeleteClick}
          onSplit={handleSplitStart}
          editingId={editingId}
          editForm={editForm}
          setEditForm={setEditForm}
          onSave={handleSave}
          onCancelEdit={handleCancel}
        />
      </MobileLayout>

      {/* Desktop Layout - hidden on mobile */}
      <div className="hidden md:block space-y-6 p-1">
        {/* Header card with search, filters toggle, export buttons */}
        <div className="neu-raised-sm lg:neu-raised rounded-3xl flex flex-col border border-border shadow-[0_20px_70px_-10px_rgba(0,0,0,0.5)]">
          <LedgerHeader
            filteredCount={filteredTransactions.length}
            globalFilter={filters.globalFilter}
            onGlobalFilterChange={setFilters.setGlobalFilter}
            showFilters={showFilters}
            onToggleFilters={() => setShowFilters(!showFilters)}
            hasActiveFilters={hasActiveFilters}
            onExport={handleExport}
            searchInputRef={searchInputRef}
            columnVisibility={columnVisibility}
            onColumnVisibilityChange={setColumnVisibility}
          />

          {/* Expandable filter panel */}
          {(showFilters || hasActiveFilters) && (
            <div className="p-6 pt-0">
              <LedgerFilters
                startDate={filters.startDate}
                endDate={filters.endDate}
                selectedCategory={filters.selectedCategory}
                minAmount={filters.minAmount?.toString() ?? ''}
                maxAmount={filters.maxAmount?.toString() ?? ''}
                selectedAccount={filters.selectedAccount}
                accounts={accounts}
                onStartDateChange={setFilters.setStartDate}
                onEndDateChange={setFilters.setEndDate}
                onCategoryChange={setFilters.setSelectedCategory}
                onMinAmountChange={setFilters.setMinAmount}
                onMaxAmountChange={setFilters.setMaxAmount}
                onAccountChange={setFilters.setSelectedAccount}
                onReset={resetFilters}
              />
            </div>
          )}
        </div>

        {/* Bulk action bar */}
        <BulkActionBar
          selectedCount={selectedCount}
          selectedIds={selectedIds}
          onClearSelection={clearSelection}
          onDataChange={onDataChange}
        />

        {/* Desktop table with virtualization */}
        <div className="neu-raised-sm lg:neu-raised rounded-3xl overflow-hidden border border-border">
          <LedgerTable
            transactions={filteredTransactions}
            accounts={accounts}
            sorting={sorting}
            onSortingChange={setSorting}
            globalFilter={filters.globalFilter}
            onGlobalFilterChange={setFilters.setGlobalFilter}
            editingId={editingId}
            editForm={editForm}
            setEditForm={setEditForm}
            setEditingId={setEditingId}
            handleEditStart={handleEditStart}
            handleSave={handleSave}
            handleDelete={handleDeleteClick}
            handleSplitStart={handleSplitStart}
            categories={categories}
            bulkSelect={{ isSelected, toggle: toggleSelect }}
            onSelectAll={() => selectAll(filteredTransactions.map((t) => t.id))}
            columnVisibility={columnVisibility}
            onColumnVisibilityChange={setColumnVisibility}
          />

          <LedgerFooter
            totalCount={totalTransactions ?? transactions.length}
            filteredCount={filteredTransactions.length}
            loadedCount={transactions.length}
            onLoadMore={onLoadMore}
          />
        </div>
      </div>

      {/* Split Transaction Modal */}
      {splittingTx && (
        <SplitTransactionModal
          transaction={splittingTx}
          splits={splits}
          onSplitsChange={setSplits}
          onSave={handleSplitSave}
          onCancel={handleSplitCancel}
          isSaving={isSplitSaving}
        />
      )}

      {/* Delete Confirmation Dialog */}
      <DeleteConfirmDialog
        isOpen={isDeleteOpen}
        onConfirm={handleConfirmDelete}
        onCancel={closeDeleteDialog}
      />
    </>
  );
}

