export { LedgerPage as TransactionTable };
export default LedgerPage;

import { useRef, useMemo, useLayoutEffect } from 'react';
import type { SortingState, VisibilityState } from '@tanstack/react-table';
import {
  flexRender,
  getCoreRowModel,
  useReactTable,
  getSortedRowModel,
  getFilteredRowModel,
} from '@tanstack/react-table';
import { useVirtualizer } from '@tanstack/react-virtual';
import type { Transaction, Account } from '../types/ledger';
import { createLedgerColumns } from './LedgerTableColumns';
import { Search } from 'lucide-react';
import { cn } from '@/lib/utils';

// Helper component for dynamic height rows (used for virtual scrolling spacers)
const DynamicHeightRow = ({ height, children }: { height: number; children: React.ReactNode }) => {
  const ref = useRef<HTMLTableRowElement>(null);
  useLayoutEffect(() => {
    if (ref.current) ref.current.style.height = `${height}px`;
  }, [height]);
  return <tr ref={ref}>{children}</tr>;
};

// Helper component for dynamic width header cells
const DynamicTh = ({
  width,
  children,
  className,
  ...props
}: React.ThHTMLAttributes<HTMLTableHeaderCellElement> & { width?: number }) => {
  const ref = useRef<HTMLTableHeaderCellElement>(null);
  useLayoutEffect(() => {
    if (ref.current && width) {
      ref.current.style.setProperty('--column-width', `${width}px`);
    }
  }, [width]);
  return (
    <th ref={ref} className={className} {...props}>
      {children}
    </th>
  );
};

interface BulkSelectActions {
  isSelected: (id: string) => boolean;
  toggle: (id: string) => void;
}

interface LedgerTableProps {
  transactions: Transaction[];
  accounts: Account[];
  sorting: SortingState;
  onSortingChange: (sorting: SortingState) => void;
  globalFilter: string;
  onGlobalFilterChange: (filter: string) => void;
  editingId: string | null;
  editForm: Partial<Transaction>;
  setEditForm: (form: Partial<Transaction>) => void;
  setEditingId: (id: string | null) => void;
  handleEditStart: (tx: Transaction) => void;
  handleSave: (id: string) => void;
  handleDelete: (id: string) => void;
  handleSplitStart: (tx: Transaction) => void;
  categories: string[];
  bulkSelect?: BulkSelectActions;
  onSelectAll?: () => void;
  columnVisibility: VisibilityState;
  onColumnVisibilityChange: (visibility: VisibilityState) => void;
}

export function LedgerTable({
  transactions,
  accounts,
  sorting,
  onSortingChange,
  globalFilter,
  onGlobalFilterChange,
  editingId,
  editForm,
  setEditForm,
  setEditingId,
  handleEditStart,
  handleSave,
  handleDelete,
  handleSplitStart,
  categories,
  bulkSelect,
  onSelectAll,
  columnVisibility,
  onColumnVisibilityChange,
}: LedgerTableProps) {
  const parentRef = useRef<HTMLDivElement>(null);

  // Use ref for edit state to prevent column recreation on every render
  const editStateRef = useRef({ editingId, editForm });
  editStateRef.current = { editingId, editForm };

  const bulkSelectRef = useRef(bulkSelect || null);
  bulkSelectRef.current = bulkSelect || null;

  const columns = useMemo(
    () =>
      createLedgerColumns({
        editStateRef,
        accounts,
        categories,
        setEditForm,
        handleEditStart,
        handleSave,
        handleDelete,
        handleSplitStart,
        setEditingId,
        bulkSelectRef: bulkSelect ? bulkSelectRef : undefined,
        onSelectAll,
      }),
    [
      accounts,
      categories,
      setEditForm,
      handleEditStart,
      handleSave,
      handleDelete,
      handleSplitStart,
      setEditingId,
      !!bulkSelect,
      onSelectAll,
    ],
  );

  const table = useReactTable({
    data: transactions,
    columns,
    getCoreRowModel: getCoreRowModel(),
    onSortingChange: (updater) => {
      const newSorting = typeof updater === 'function' ? updater(sorting) : updater;
      onSortingChange(newSorting);
    },
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    state: { sorting, globalFilter, columnVisibility },
    onColumnVisibilityChange: (updater) => {
      const newVis = typeof updater === 'function' ? updater(columnVisibility) : updater;
      onColumnVisibilityChange(newVis);
    },
    onGlobalFilterChange,
  });

  const { rows } = table.getRowModel();

  const rowVirtualizer = useVirtualizer({
    count: rows.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 60,
    overscan: 10,
  });

  // Empty state
  if (rows.length === 0) {
    return (
      <div className="py-32 text-center">
        <div className="flex flex-col items-center justify-center space-y-4">
          <div className="w-20 h-20 neu-inset rounded-3xl flex items-center justify-center">
            <Search className="h-10 w-10 text-zinc-800" />
          </div>
          <p className="text-sm font-bold text-zinc-600 uppercase tracking-widest">
            No transactions found
          </p>
        </div>
      </div>
    );
  }

  const virtualItems = rowVirtualizer.getVirtualItems();

  return (
    <div className="flex-1 bg-overlay border-t border-border/50 relative group/table">
      {/* Horizontal Scroll Indicators */}
      <div className="absolute left-0 top-0 bottom-0 w-8 bg-linear-to-r from-overlay to-transparent pointer-events-none z-10 opacity-0 group-hover/table:opacity-100 transition-opacity md:hidden" />
      <div className="absolute right-0 top-0 bottom-0 w-8 bg-linear-to-l from-overlay to-transparent pointer-events-none z-10 opacity-0 group-hover/table:opacity-100 transition-opacity md:hidden" />

      <div ref={parentRef} className="overflow-scroll max-h-[70vh]">
        <div className="px-4 py-6 sm:px-6 sm:py-8 lg:px-8 lg:py-10 min-w-max">
          <table
            className="transaction-table w-full border-separate border-spacing-y-2 lg:border-spacing-y-3"
            aria-label="Financial Transactions Ledger"
          >
            <caption className="sr-only">
              List of financial transactions with details including date, description, amount, and
              category.
            </caption>
            <thead className="sticky top-0 z-20 bg-surface">
              {table.getHeaderGroups().map((hg) => (
                <tr key={hg.id} className="text-zinc-600">
                  {hg.headers.map((h) => {
                    const isSticky = h.id === 'actions';
                    const isSorted = h.column.getIsSorted();
                    const ariaSortValue: 'ascending' | 'descending' | 'none' | undefined =
                      !h.column.getCanSort()
                        ? undefined
                        : isSorted === 'asc'
                          ? 'ascending'
                          : isSorted === 'desc'
                            ? 'descending'
                            : 'none';

                    return (
                      <DynamicTh
                        key={h.id}
                        scope="col"
                        aria-sort={ariaSortValue}
                        className={cn(
                          'px-3 lg:px-6 pb-2 text-left whitespace-nowrap dynamic-column-width',
                          h.id === 'gstApplicable' && 'hidden md:table-cell',
                          isSticky &&
                            'lg:sticky lg:right-0 lg:bg-surface lg:z-30 lg:shadow-[-10px_0_20px_-10px_rgba(0,0,0,0.5)]',
                        )}
                        width={h.column.getSize() !== 150 ? h.column.getSize() : undefined}
                      >
                        {h.isPlaceholder
                          ? null
                          : flexRender(h.column.columnDef.header, h.getContext())}
                      </DynamicTh>
                    );
                  })}
                </tr>
              ))}
            </thead>
            <tbody>
              {/* Top spacer for virtual scrolling */}
              {virtualItems.length > 0 && (
                <DynamicHeightRow height={virtualItems[0]?.start || 0}>
                  <td colSpan={columns.length} />
                </DynamicHeightRow>
              )}

              {/* Virtual rows */}
              {virtualItems.map((virtualRow) => {
                const row = rows[virtualRow.index];
                if (!row) return null;

                return (
                  <tr
                    key={row.id}
                    data-index={virtualRow.index}
                    ref={rowVirtualizer.measureElement}
                    className="group transition-all duration-300"
                  >
                    {row.getVisibleCells().map((cell, cellIndex) => {
                      const isSticky = cell.column.id === 'actions';
                      const tx = row.original;
                      const borderColor = tx.isTransfer
                        ? 'border-l-zinc-500/50'
                        : tx.amount > 0
                          ? 'border-l-emerald-500/50'
                          : 'border-l-red-500/50';
                      return (
                        <td
                          key={cell.id}
                          className={cn(
                            'px-3 lg:px-6 py-3 lg:py-5 bg-surface first:rounded-l-xl last:rounded-r-xl border-y border-border/50 first:border-l last:border-r transition-shadow duration-300 group-hover:bg-card group-hover:border-border group-hover:shadow-[0_8px_30px_rgba(0,0,0,0.3)]',
                            editingId === row.original.id && 'bg-card border-cba-gold/20',
                            cell.column.id === 'gstApplicable' && 'hidden md:table-cell',
                            cellIndex === 0 && `border-l-2 ${borderColor}`,
                            isSticky &&
                              'lg:sticky lg:right-0 lg:z-30 lg:shadow-[-10px_0_20px_-10px_rgba(0,0,0,0.5)] lg:border-l lg:border-border/50',
                          )}
                        >
                          {flexRender(cell.column.columnDef.cell, cell.getContext())}
                        </td>
                      );
                    })}
                  </tr>
                );
              })}

              {/* Bottom spacer for virtual scrolling */}
              {virtualItems.length > 0 && (
                <DynamicHeightRow
                  height={
                    rowVirtualizer.getTotalSize() -
                    (virtualItems[virtualItems.length - 1]?.end || 0)
                  }
                >
                  <td colSpan={columns.length} />
                </DynamicHeightRow>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

import { useRef } from 'react';
import { useVirtualizer } from '@tanstack/react-virtual';
import { Search } from 'lucide-react';
import type { Transaction } from '../types/ledger';
import type { Account } from '@/api';
import { TransactionCard } from './TransactionCard';

interface TransactionCardListProps {
  transactions: Transaction[];
  accounts: Account[];
  onEdit: (tx: Transaction) => void;
  onDelete: (id: string) => void;
  onSplit: (tx: Transaction) => void;
  editingId: string | null;
  editForm: Partial<Transaction>;
  setEditForm: (form: Partial<Transaction>) => void;
  onSave: (id: string) => void;
  onCancelEdit: () => void;
}

export function TransactionCardList({
  transactions,
  accounts,
  onEdit,
  onDelete,
  onSplit,
  editingId,
  editForm,
  setEditForm,
  onSave,
  onCancelEdit,
}: TransactionCardListProps) {
  const parentRef = useRef<HTMLDivElement>(null);

  const virtualizer = useVirtualizer({
    count: transactions.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => 120, // Estimated card height including margin
    overscan: 5,
  });

  if (transactions.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center py-12 text-muted">
        <Search className="h-8 w-8 mb-2 opacity-50" />
        <span className="text-xs font-bold uppercase tracking-widest">No transactions found</span>
      </div>
    );
  }

  return (
    <div ref={parentRef} className="h-[calc(100vh-200px)] overflow-auto px-4">
      <div
        style={{
          height: `${virtualizer.getTotalSize()}px`,
          width: '100%',
          position: 'relative',
        }}
      >
        {virtualizer.getVirtualItems().map((virtualItem) => {
          const tx = transactions[virtualItem.index];
          if (!tx) return null;
          return (
            <div
              key={tx.id}
              style={{
                position: 'absolute',
                top: 0,
                left: 0,
                width: '100%',
                transform: `translateY(${virtualItem.start}px)`,
              }}
            >
              <TransactionCard
                transaction={tx}
                accounts={accounts}
                onEdit={onEdit}
                onDelete={onDelete}
                onSplit={onSplit}
                isEditing={editingId === tx?.id}
                editForm={editForm}
                setEditForm={setEditForm}
                onSave={onSave}
                onCancelEdit={onCancelEdit}
              />
            </div>
          );
        })}
      </div>
    </div>
  );
}

import { useState, useEffect, useMemo } from 'react';
import { cn } from '@/lib/utils';
import { Loader2, GitBranch } from 'lucide-react';
import { analyticsApi } from '@/api';
import type { MoneyFlow } from '../types';

const PERIODS = ['1m', '3m', '6m', '12m'] as const;

function formatCurrency(cents: number): string {
  return new Intl.NumberFormat('en-AU', {
    style: 'currency',
    currency: 'AUD',
    maximumFractionDigits: 0,
  }).format(cents / 100);
}

interface AccountNode {
  id: number;
  name: string;
  totalIn: number;
  totalOut: number;
}

export function MoneyFlowDiagram() {
  const [flows, setFlows] = useState<MoneyFlow[]>([]);
  const [loading, setLoading] = useState(true);
  const [period, setPeriod] = useState<string>('3m');
  const [hoveredFlow, setHoveredFlow] = useState<number | null>(null);

  useEffect(() => {
    loadFlows();
  }, [period]);

  const loadFlows = async () => {
    setLoading(true);
    try {
      const data = await analyticsApi.fetchMoneyFlow(period);
      setFlows(data);
    } catch (err) {
      console.error('Failed to fetch money flow:', err);
    } finally {
      setLoading(false);
    }
  };

  const { accounts, maxAmount } = useMemo(() => {
    const accountMap = new Map<number, AccountNode>();
    let max = 0;

    flows.forEach((f) => {
      if (!accountMap.has(f.fromAccountId)) {
        accountMap.set(f.fromAccountId, {
          id: f.fromAccountId,
          name: f.fromAccountName,
          totalIn: 0,
          totalOut: 0,
        });
      }
      if (!accountMap.has(f.toAccountId)) {
        accountMap.set(f.toAccountId, {
          id: f.toAccountId,
          name: f.toAccountName,
          totalIn: 0,
          totalOut: 0,
        });
      }
      accountMap.get(f.fromAccountId)!.totalOut += f.totalAmount;
      accountMap.get(f.toAccountId)!.totalIn += f.totalAmount;
      if (f.totalAmount > max) max = f.totalAmount;
    });

    return { accounts: Array.from(accountMap.values()), maxAmount: max };
  }, [flows]);

  const SVG_WIDTH = 600;
  const SVG_HEIGHT = Math.max(300, accounts.length * 80 + 60);
  const NODE_R = 24;
  const LEFT_X = 80;
  const RIGHT_X = SVG_WIDTH - 80;

  // Build unique left/right account lists
  const leftAccounts = accounts.filter((a) => a.totalOut > 0);
  const rightAccounts = accounts.filter((a) => a.totalIn > 0);

  const getY = (index: number, total: number): number => {
    const spacing = (SVG_HEIGHT - 60) / Math.max(total, 1);
    return 30 + spacing * index + spacing / 2;
  };

  if (loading) {
    return (
      <div className="neu-raised rounded-3xl p-8 border border-border/50 flex items-center justify-center min-h-[300px]">
        <Loader2 className="w-6 h-6 text-cba-gold animate-spin" />
      </div>
    );
  }

  if (flows.length === 0) {
    return (
      <div className="neu-raised rounded-3xl p-10 text-center border border-border/50">
        <div className="neu-inset w-20 h-20 rounded-3xl mx-auto mb-6 flex items-center justify-center">
          <GitBranch className="w-10 h-10 text-zinc-800" />
        </div>
        <h3 className="font-black text-primary uppercase tracking-widest text-sm">No Flow Data</h3>
        <p className="text-xs text-zinc-600 mt-2 font-bold uppercase tracking-tight">
          Transfer data needed to visualize money flow.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Period Selector */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <GitBranch className="w-4 h-4 text-cba-gold" />
          <span className="text-[10px] font-black text-muted uppercase tracking-[0.2em]">
            Money Flow
          </span>
        </div>
        <div className="flex gap-1 neu-inset rounded-xl p-1">
          {PERIODS.map((p) => (
            <button
              key={p}
              type="button"
              onClick={() => setPeriod(p)}
              className={cn(
                'px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all',
                period === p ? 'bg-cba-gold text-base' : 'text-muted hover:text-primary',
              )}
            >
              {p}
            </button>
          ))}
        </div>
      </div>

      {/* SVG Diagram */}
      <div className="neu-raised rounded-2xl border border-border/50 overflow-hidden p-4">
        <svg
          viewBox={`0 0 ${SVG_WIDTH} ${SVG_HEIGHT}`}
          className="w-full h-auto"
          style={{ maxHeight: 500 }}
        >
          {/* Flow arrows */}
          {flows.map((flow, i) => {
            const leftIdx = leftAccounts.findIndex((a) => a.id === flow.fromAccountId);
            const rightIdx = rightAccounts.findIndex((a) => a.id === flow.toAccountId);
            if (leftIdx === -1 || rightIdx === -1) return null;

            const y1 = getY(leftIdx, leftAccounts.length);
            const y2 = getY(rightIdx, rightAccounts.length);
            const thickness = Math.max(2, (flow.totalAmount / maxAmount) * 16);
            const isHovered = hoveredFlow === i;

            return (
              <g
                key={i}
                onMouseEnter={() => setHoveredFlow(i)}
                onMouseLeave={() => setHoveredFlow(null)}
                className="cursor-pointer"
              >
                <path
                  d={`M ${LEFT_X + NODE_R + 4} ${y1} C ${SVG_WIDTH / 2} ${y1}, ${SVG_WIDTH / 2} ${y2}, ${RIGHT_X - NODE_R - 4} ${y2}`}
                  fill="none"
                  stroke={isHovered ? '#FFCC00' : 'rgba(255,204,0,0.2)'}
                  strokeWidth={thickness}
                  strokeLinecap="round"
                  className="transition-all duration-300"
                  opacity={isHovered ? 1 : 0.6}
                />
                {/* Amount label at midpoint */}
                <text
                  x={SVG_WIDTH / 2}
                  y={(y1 + y2) / 2 - thickness / 2 - 4}
                  textAnchor="middle"
                  className={cn(
                    'text-[10px] font-bold transition-opacity duration-200',
                    isHovered ? 'opacity-100' : 'opacity-0',
                  )}
                  fill="#FFCC00"
                >
                  {formatCurrency(flow.totalAmount)} ({flow.transactionCount}x)
                </text>
              </g>
            );
          })}

          {/* Left nodes (senders) */}
          {leftAccounts.map((account, i) => {
            const y = getY(i, leftAccounts.length);
            return (
              <g key={`left-${account.id}`}>
                <circle
                  cx={LEFT_X}
                  cy={y}
                  r={NODE_R}
                  fill="#1a1a24"
                  stroke="rgba(255,204,0,0.3)"
                  strokeWidth={2}
                />
                <text
                  x={LEFT_X}
                  y={y + 1}
                  textAnchor="middle"
                  fill="#f5f5f7"
                  className="text-[9px] font-bold"
                >
                  {account.name.slice(0, 4)}
                </text>
                <text
                  x={LEFT_X - NODE_R - 6}
                  y={y + 1}
                  textAnchor="end"
                  fill="#a1a1aa"
                  className="text-[8px] font-bold"
                >
                  {account.name}
                </text>
              </g>
            );
          })}

          {/* Right nodes (receivers) */}
          {rightAccounts.map((account, i) => {
            const y = getY(i, rightAccounts.length);
            return (
              <g key={`right-${account.id}`}>
                <circle
                  cx={RIGHT_X}
                  cy={y}
                  r={NODE_R}
                  fill="#1a1a24"
                  stroke="rgba(16,185,129,0.3)"
                  strokeWidth={2}
                />
                <text
                  x={RIGHT_X}
                  y={y + 1}
                  textAnchor="middle"
                  fill="#f5f5f7"
                  className="text-[9px] font-bold"
                >
                  {account.name.slice(0, 4)}
                </text>
                <text
                  x={RIGHT_X + NODE_R + 6}
                  y={y + 1}
                  textAnchor="start"
                  fill="#a1a1aa"
                  className="text-[8px] font-bold"
                >
                  {account.name}
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      {/* Flow Summary */}
      <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
        {flows.slice(0, 6).map((flow, i) => (
          <div key={i} className="neu-inset rounded-xl p-3 border border-border/50">
            <p className="text-[8px] font-black text-zinc-600 uppercase tracking-widest truncate">
              {flow.fromAccountName} → {flow.toAccountName}
            </p>
            <p className="text-sm font-black text-cba-gold mt-1">
              {formatCurrency(flow.totalAmount)}
            </p>
            <p className="text-[8px] text-zinc-600 mt-0.5">{flow.transactionCount} transfers</p>
          </div>
        ))}
      </div>
    </div>
  );
}

